int extendOpenSSLWithCiphersAndDigests() {
    // Initialize OpenSSL's crypto library
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();

    int success = 1;
    EVP_PKEY *rsaKeyPair = NULL, *rsaPublicKey = NULL;
