        handleErrors();
        success = 0;
    }

    // Similarly implement the rest of AES, Camellia block ciphers and RSA with SHA1 primitives.

    /* Clean up */
    EVP_CIPHER_CTX_cleanup(&ctx);

    if (rsaKeyPair != NULL) EVP_PKEY_free(rsaKeyPair);
    if (rsaPublicKey != NULL) EVP_PKEY_free(rsaPublicKey);
    if (rsaTmpRsa != NULL) RSA_free(rsaTmpRsa);

    /* Removes all digests and ciphers */
