Here's a JavaScript function implementing an asynchronous reduce method for an array of numbers using callbacks for the reduction operation. The code includes error handling and resource management to prevent potential leaks:

```javascript
/**
 * Implements an asynchronous reduce() method for an array of numbers.
 * @param {Array} array - Array of numbers
 * @param {Function} reducer - Callback function that takes two arguments, the accumulated value and current number.
 * @param {*} initialValue - Initial value for reduction operation.
 * @return {Promise<*>|Promise<Error>} Promise resolves with the final reduced value or rejects with an Error instance in case of error.
 */
async function asyncReduce(array, reducer, initialValue) {
  if (!Array.isArray(array)) return Promise.reject(new Error("Expected array"));
  if (typeof reducer !== 'function') return Promise.reject(new Error("Expected reducer function"));

  let result = initialValue;
  for (let i = 0; i < array.length; i++) {
    try {
      // Check if current value is a number and not NaN
      const currVal = parseFloat(array[i]);
      if (!isNaN(currVal)) {
        result = await reducer(result, currVal);
      } else {
        return Promise.reject(new Error("Non-numeric value encountered at index " + i));
      }
    } catch (error) {
      // If error while executing callback, reject the promise with that error.
      return Promise.reject(error);
    }
  }

  // Finally resolve with reduced result.
  return Promise.resolve(result);
}
```
