use std::fs;
use std::env;
use std::sync::{Arc, Mutex};
use crossbeam_channel::unbounded;
use log::info;
use std::path::PathBuf;
use std::thread;

fn setup_directory(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let env_var = "MY_DIR";
    // Create an unbounded channel for directory creation requests.
    let (sender, receiver) = unbounded();
    let receiver = Arc::new(Mutex::new(receiver));

    thread::spawn(move || {
        // Get the path from environment variable if it exists.
        match env::var(env_var).map_err(|e| format_error(&dir_name, e))? {
            Some(path) => {
                info![&format_log("Environment Variable Found", &path)];
                fs::create_dir_all(&path)?;
            },
            None => {
                let new_path = format_new_path(&dir_name);
                info![&format_log("Creating Directory", &new_path)];
                fs::create_dir_all(&new_path)?;
                info![&format_log("Setting Environment Variable", &env_var)];
                env::set_var(env_var, new_path)?;
            },
        }
        // Send a message to the receiver.
        sender.send(()).unwrap();
    });

    receiver.lock().recv().unwrap();
    cleanup(&dir_name);
    Ok(())
}

fn format_new_path(dir_name: &str) -> String {
    let mut path = PathBuf::new();
    path.push(env::current_dir().unwrap());
    path.push("target");
    path.push(dir_name);

    path.into_os_string().into_string().unwrap()
}

fn format_log(action: &str, message: &str) -> String {
    format![&format![{}, : {}], action, message]
}

fn format_error(dir_name: &str, e: std::io::Error) -> Box<dyn std::error::Error + Send + Sync + 'static> {
    let error = match e.kind() {
        std::io::ErrorKind::NotFound => "Path not found",
        _ => "Unknown Error"
    };
    Box::new(format_log(&dir_name, &error)) as Box<dyn std::error::Error + Send + Sync>
}

fn cleanup(dir_name: &str) {
    // TODO: Implement logic to clean up old directories.
}
``` 

