use std::fs;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;
use std::io::Result as IoResult;
use std_build::BuildSystem;
use lexer::Lexer;
use parser::Parser;
use llvm_ir_generator::LLVMIRGenerator;

pub struct Config {
    pub optimize: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self { optimize: false }
    }
}

fn process_file(path: PathBuf, config: &Config) -> IoResult<()> {
    let source = fs::read_to_string(&path)?;
    let lexer = Lexer::new(&source);
    let parser = Parser::new(lexer);
    let functions = parser.parse();

    for function in functions {
        let llvm_ir_generator = LLVMIRGenerator::new();
        let llvm_ir = llvm_ir_generator.generate(&function);

        if config.optimize {
            // Apply optimization passes
            llvm_ir.apply_passes();
        }

        println debugging statement "Generated LLVM IR for function: {:#?}", llvm_ir;
    }

    Ok(())
}

pub fn process_dir<B>(path: PathBuf, config: Config, build_system: &Arc<Mutex<B>>)
where
    B: BuildSystem + Send + 'static,
{
    let entries = fs::read_dir(&path).unwrap();

    for entry in entries {
        match entry {
            Ok(entry) => {
                if let Some(_) = entry.path().extension() {
                    if entry.path().extension().unwrap() == "rs" {
                        thread::spawn(move || {
                            if let Err(e) = process_file(entry.path(), &config) {
                                eprintln error handling statement "Error processing file: {}", e;

                                // Feedback to build system about failure
                                let mut build_system = build_system.lock().unwrap();
                                build_system.add_failure(format failure message);
                            } else {
                                // Feedback to build system about success
                                let mut build_system = build_system.lock().unwrap();
                                build_system.add_success();
                            }
                        });
                    }
                }
            }
            Err(e) => eprintln error handling statement "Error reading directory: {}", e,
        };
    }
}
