Here is a simple implementation of your requirements using JavaScript and promises for managing async operations:

```javascript
function renderScriptsFooter(scripts, maxConcurrent = 3) {
    let html = ''; // Initialize HTML string to accumulate rendered scripts
    let queue = Promise.resolve(); // Initialize a promise queue
    let numLoading = 0; // Counter for number of loading external scripts

    scripts.forEach(script => {
        if (script.src) { // If the script is an external source
            const loadScriptPromise = new Promise((resolve, reject) => {
                const scriptTag = document.createElement('script');

                // Add error and load handlers to manage script loading and errors
                scriptTag.onerror = () => {
                    console.warn(`Failed to load script ${script.src}`);
                    resolve();
                };
                scriptTag.onload = resolve;

                // Set the source URL of the script and add it to the document head
                scriptTag.setAttribute('src', script.src);
                document.head.appendChild(scriptTag);
            });

            queue = queue.then(() => {
                if (numLoading >= maxConcurrent) { // If too many scripts are loading, wait for some to finish before starting another
                    return new Promise((resolve) => {
                        const intervalId = setInterval(() => {
                            if (numLoading < maxConcurrent) {
                                clearInterval(intervalId);
                                resolve();
                            }
                        }, 100); // Check every 100ms to see if a slot is available in the queue
                    });
                } else {
                    ++numLoading;
                    return loadScriptPromise.finally(() => --numLoading); // Once script has loaded/failed, decrease loading counter
                }
            });
        } else { // If the script is inline code
            queue = queue.then(async () => { // Use an async function to support await for Promise resolution
                const timeoutPromise = new Promise((resolve) => 
                    setTimeout(() => resolve(), 5000) // Set a timeout for external scripts (adjust as necessary)
                );

                try {
                  await Promise.race([eval(script.code), timeoutPromise]); // Execute code or throw after 5s
                } catch (error) {
                  console.warn('Failed to execute inline script', error);
                }
            });
        }
    });

    queue = queue.then(() => html); // Once all scripts have been processed, resolve the final promise with the rendered HTML string

    return queue; // Return a promise for any code that needs to wait for script loading to finish
}
```
Please note: This function uses `eval()` to execute inline scripts. In general, it's not recommended to use `eval()` as it can lead to security issues and makes debugging more difficult. It should be used with caution and preferably replaced with a safer alternative if possible. Also, be aware that it can block the main thread for too long when loading large external scripts or executing inline scripts which may freeze or slow down your webpage.

