use std::ffi::CString;
use std::env;
use std::fs;
use std::path::PathBuf;
use std::os::unix::ffi::OsStrExt;
use libc::{setenv, getenv};

#[no_mangle]
pub extern "C" fn CreateEnvironmentDirectory(directoryName: *const i8) {
    let directory = unsafe { CStr::from_ptr(directoryName) }.to_string_lossy();
    match env::var("MY_ENVIRONMENT_VARIABLE") {
        Ok(_) => (),
        Err(_) => {
            fs::create_dir(&directory).expect("Unable to create directory");
            let path = PathBuf::from(directory);
            let variable_name = CString::new("MY_ENVIRONMENT_VARIABLE").unwrap();
            setenv(variable_name.as_ptr(), path.to_str().unwrap().unwrap_or(""), 1).unwrap();
        }
    };
}
