// Function to fetch word list from external source 
char** wordListFetchAPI(int* size) {
    // Implementation of fetching mechanism should go here
}

void dynamicTrimAndCapitalize(char* str) {
    if (str == NULL) return;

    int size = 0;
    char** wordsToRemove = wordListFetchAPI(&size);

    // Calculate average length of words to remove and adjust limit based on that. 
    // This is a simple example, real implementation may depend on your specific use case.
    double avgLength = 0;
    for (int i = 0; i < size; ++i) {
        avgLength += strlen(wordsToRemove[i]);
    }
    avgLength /= size;

    // Trim and capitalize word function 
    char* result = calloc(strlen(str), sizeof(char));
    if (result == NULL) {
        printf("Insufficient memory\n");
        return;
    }

    char* token = strtok(str, " ");
    while (token != NULL) {
        // Checking if word is in the list of words to remove. 
        bool shouldRemoveWord = false;
        for (int i = 0; i < size; ++i) {
            if (strcmp(wordsToRemove[i], token) == 0) {
                shouldRemoveWord = true;
                break;
            }
        }

        // If the word is not in the list, add it to result and capitalize it. 
        if (!shouldRemoveWord) {
            strcat(result, " ");
            token[0] = toupper((unsigned char)token[0]);
            strncat(result, token, avgLength);
        }

        token = strtok(NULL, " ");
    }

    // If result exceeds limit, return NULL 
    if (strlen(result) > strlen(str)) {
        free(result);
        printf("Result length exceeds limit\n");
        return;
    }

    for (int i = 0; i < size; ++i) {
        free(wordsToRemove[i]);
    }
    free(wordsToRemove);
}
