Here's a code sample in C that performs the required task:

```c
#include <stdio.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <semaphore.h>
#include <unistd.h>
#include <errno.h>

int jpeg_to_pdf(const char *input, const char *output) {
    sem_t *sem;

    // Create a new named semaphore with an initial value of 1
    if ((sem = sem_open("/mysem", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 1)) == SEM_FAILED) {
        perror("sem_open");
        return 1;
    }

    // Wait for the semaphore to be available
    if (sem_wait(sem) < 0) {
        perror("sem_wait");
        sem_close(sem);
        sem_unlink("/mysem");
        return 1;
    }

    // Convert JPEG to PDF using a third-party tool (ImageMagick in this case)
    char command[256];
    sprintf(command, "convert %s %s", input, output);
    int ret = system(command);

    if (ret == -1 || WIFEXITED(ret)) {
        // If the third-party tool fails to execute or exits with nonzero status, ignore it
        sem_post(sem);
        sem_close(sem);
        sem_unlink("/mysem");
        return 0;
    }

    // Post to the semaphore and cleanup resources
    if (sem_post(sem) < 0) {
        perror("sem_post");
        sem_close(sem);
        sem_unlink("/mysem");
        return 1;
    }

    // Semaphore operations complete without issues
    sem_close(sem);
    sem_unlink("/mysem");
    return 0;
}
```
This function creates a named POSIX semaphore with an initial value of 1. It then waits for the semaphore to be available and uses ImageMagick's `convert` command to convert JPEG files to PDF format. If the conversion is successful, it posts to the semaphore and cleans up resources; otherwise, it ignores any potential errors from the third-party tool and cleans up resources without propagating them. 

Please replace `"convert %s %s"` with your own command for converting JPEG to PDF or adjust the code accordingly if you are using a different converter. The function assumes that ImageMagick's `convert` is in the system's PATH; if it's not, you should provide the full path to the `convert` executable.

