const { S3Client, GetObjectCommand } = require("@aws-sdk/client-s3");
const s3Client = new S3Client({ region: "us-west-2"}); // replace with your region

app.post('/login', (req, res) => {
  const username = req.body.username;

  if (!cache.has(username)) {
    fetchImageFromS3AndCache(username);
  } else {
    console.log("Found in cache");
  }

  res.send('Logged In');
});

async function fetchImageFromS3AndCache(key) {
  try {
    const data = await s3Client.send(new GetObjectCommand({Bucket: 'myBucket', Key: key})); // replace with your bucket and image path

    cache.set(key, data);
    console.log("Image cached");
  } catch (err) {
    console.error('Error downloading image from S3', err);
  }
}

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
