using boost::asio::ip::tcp;

class SandeshClient {
public:
    SandeshClient(boost::asio::io_service& io_service, const std::string& server, const std::string& path) 
        : resolver_(io_service), socket_(io_service)
    {
        // Form the request. We specify the "Connection: close" header so that the
        // server will close the socket after transmitting the response. This will
        // allow us to treat all data up until the EOF as the content.
        std::ostream request_stream(&request_);
        request_stream << "GET " << path << " HTTP/1.0\r\n";
        request_stream << "Host: " << server << "\r\n";
        request_stream << "Accept: */*\r\n";
        request_stream << "Connection: close\r\n\r\n";

        // Start an asynchronous resolve to translate the server and service names
        // into a list of endpoints.
        tcp::resolver::query query(server, "http");
        resolver_.async_resolve(query, boost::bind(&SandeshClient::handle_resolve, this, boost::asio::placeholders::error, boost::asio::placeholders::iterator));
    }

private:
    void handle_resolve(const boost::system::error_code& err, tcp::resolver::iterator endpoint_iterator) {
        if (!err) {
            // Attempt a connection to each endpoint in the list until we
            // successfully establish a connection.
            boost::asio::async_connect(socket_, endpoint_iterator, boost::bind(&SandeshClient::handle_connect, this, boost::asio::placeholders::error));
        } else {
            std::cout << "Error: " << err.message() << "\n";
        }
    }

    void handle_connect(const boost::system::error_code& err) {
        if (!err) {
            // The connection was successful. Send the request.
            boost::asio::async_write(socket_, request_, boost::bind(&SandeshClient::handle_write_request, this, boost::asio::placeholders::error));
        } else {
            std::cout << "Error: " << err.message() << "\n";
        }
    }

    void handle_write_request(const boost::system::error_code& err) {
        if (!err) {
            // Read the response status line. The response_ streambuf will
            // automatically grow to accommodate the entire line. The growth may be
            // limited by passing a maximum size to the streambuf constructor.
            boost::asio::async_read_until(socket_, response_, "\r\n", boost::bind(&SandeshClient::handle_read_status_line, this, boost::asio::placeholders::error));
        } else {
            std::cout << "Error: " << err.message() << "\n";
        }
    }

    void handle_read_status_line(const boost::system::error_code& err) {
        if (!err) {
            // Check that response is OK.
            std::istream response_stream(&response_);
            std::string http_version;
            response_stream >> http_version;
            unsigned int status_code;
            response_stream >> status_code;
            std::string status_message;
            std::getline(response_stream, status_message);

            // ...
        } else {
            std::cout << "Error: " << err.message() << "\n";
        }
    }

    tcp::resolver resolver_;
    boost::asio::streambuf request_;
    boost::asio::ip::tcp::socket socket_;
    boost::asio::streambuf response_;
};

