public class JsonService {
    private static Map<String, ServiceFactory> registry = new HashMap<>();
    private static Connection connection;
    private static Channel channel;

    public interface ServiceFactory {
        Object create(JSONObject json);
    }

    static class MessagingSystem {
        public static void sendMessage(String message) throws Exception{
            if (connection == null || !connection.isOpen()) {
                ConnectionFactory factory = new ConnectionFactory();
                factory.setHost("localhost");
                connection = factory.newConnection();
                channel = connection.createChannel();
            }

            channel.queueDeclare(message, false, false, false, null);
        }
    }

    public static class JsonObject<T> {
        private T object;

        public JsonObject(T object) {
            this.object = object;
        }

        public String toJson() {
            return new JSONObject(object).toString();
        }

        public static <T> T fromJson(String json, Class<T> clazz) {
            return new Gson().fromJson(json, clazz);
        }

        @SuppressWarnings("unchecked")
        public static JsonObject<?> createInstanceFromJson(String id, String json){
             ServiceFactory factory = registry.get(id);
             if (factory != null) {
                 return new JsonObject<>(factory.create(new JSONObject(json)));
             }
             throw new IllegalArgumentException("No factory found for id " + id);
        }

        public static void addFactoryToRegistry(String id, ServiceFactory factory){
            registry.put(id, factory);
        }
    }

    public static void startServiceWithRandomDelay() throws Exception{
        Random rand = new Random();
        int delay = rand.nextInt((10 - 5) + 1) + 5; // Delay between 5 and 10 seconds

        Thread.sleep(delay * 1000);

        MessagingSystem.sendMessage("Service Started");
    }

    public static void stopServiceWithRandomDelay() throws Exception{
        Random rand = new Random();
        int delay = rand.nextInt((10 - 5) + 1) + 5; // Delay between 5 and 10 seconds

        Thread.sleep(delay * 1000);

        MessagingSystem.sendMessage("Service Stopped");
    }

    public static void main(String[] args) throws Exception{
        while (true){
            startServiceWithRandomDelay();

            stopServiceWithRandomDelay();
        }
    }
}
