```c
#include <openssl/md5.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

typedef struct record {
    int value;
} record_t;

char *generateMD5Hash(const char* string) {
    unsigned char md[16];
    static char hex_output[(MD5_DIGEST_LENGTH*2)+1];  //+1 for the NULL terminator
    MD5((unsigned char*)string, strlen(string), md);

    int i;
    for (i = 0; i < MD5_DIGEST_LENGTH; i++){
        sprintf(&hex_output[i*2], "%02x", md[i]);
    }

    return hex_output;
}

char *generateRandomValuesAndHash(const char *range, const char *keys) {
    srand(time(NULL));  // Seed for random number generation
    int rangeStart, rangeEnd;
    sscanf(range, "%d-%d", &rangeStart, &rangeEnd);

    // Allocate memory and initialize arrays.
    long *longArray = malloc((rangeEnd - rangeStart + 1) * sizeof(long));
    int *intArray = malloc((rangeEnd - rangeStart + 1) * sizeof(int));
    record_t *recordArray = malloc((rangeEnd - rangeStart + 1) * sizeof(record_t));

    // Fill arrays with random values.
    for (long i = 0; i < (rangeEnd - rangeStart + 1); i++) {
        longArray[i] = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
        intArray[i] = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
        recordArray[i].value = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }

    // Generate and return MD5 hash of keys.
    return generateMD5Hash(keys);
}
```
