#include <stdarg.h>
#include <stdio.h>
#include <time.h>

#define LOG_ERROR 0
#define LOG_WARNING 1
#define LOG_INFO 2

int logCondition(const char *condition, int severity, const char *format, ...) {
    if (!condition) return -1;

    FILE* logFile = NULL;
    va_list args;
    va_start (args, format);

    time_t rawtime;
    struct tm* timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);

    const char* severity_str;
    switch (severity) {
        case LOG_ERROR: 
            severity_str = "Error"; 
            break;
        case LOG_WARNING: 
            severity_str = "Warning"; 
            break;
        default: 
            severity_str = "Info"; 
    }

    logFile = fopen("error.log", "a");
    if (logFile == NULL) {
        printf("Failed to open the error log file.\n");
        return -1;
    }

    char message[500];
    snprintf(message, sizeof(message), "[%s] [%s]: ", buffer, severity_str);

    int len = strlen(message);
    vsnprintf(message + len, sizeof(message) - len, format, args);

    fputs(message, logFile);
    fclose(logFile);

    va_end (args);
    return 0;
}
```

