enum Status {SUCCESS, FAILURE};  // enum to denote the status of conversion

class ImageConverter{
    private:
        std::string inputFilePath;
        std::string outputFilePath;
        std::string formatType;
        Status conversionStatus;

    public:
        ImageConverter(std::string input, std::string output, std::string format) : 
            inputFilePath(input), 
            outputFilePath(output), 
            formatType(format){}

        void convertAndSave(){
            try{
                Magick::Image image;
                image.read(inputFilePath);

                // Conversion Process
                image.magick(formatType);
                image.write(outputFilePath);

                conversionStatus = SUCCESS; 
            } catch (Magick::Exception &error_) {
                std::cerr << "Caught exception: " << error_.what() << std::endl;
                conversionStatus = FAILURE; // Set status to failure in case of error.
            } 
        }

        Status getConversionStatus(){ return conversionStatus; }
};

int main(int argc, char** argv) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <input file> <output file> <format>" << std::endl;
        return 1;
    }

    ImageConverter converter(argv[1], argv[2], argv[3]);
    converter.convertAndSave();

    if (converter.getConversionStatus() == SUCCESS) {
        std::cout << "Image conversion successful" << std::endl;
    } else {
        std::cerr << "Image conversion failed" << std::endl;
    }
    return 0;
}
