using System;
using System.Security.Cryptography;
using System.Text;

public class HashGenerator 
{
    private ILogger _logger;

    public HashGenerator(ILogger logger)
    {
        _logger = logger;
    }

    public string GenerateMd5(string input)
    {
        return GenerateHash<MD5CryptoServiceProvider>(input);
    }

    public string GenerateSha1(string input)
    {
        return GenerateHash<SHA1Managed>(input);
    }

    public string GenerateSha256(string input)
    {
        return GenerateHash<SHA256Managed>(input);
    }

    public string GenerateMd5(byte[] input)
    {
        return GenerateHash<MD5CryptoServiceProvider, byte[]>(input);
    }

    public string GenerateSha1(byte[] input)
    {
        return GenerateHash<SHA1Managed, byte[]>(input);
    }

    public string GenerateSha256(byte[] input)
    {
        return GenerateHash<SHA256Managed, byte[]>(input);
    }

    private string GenerateHash<T, TInputType>(TInputType input) where T : HashAlgorithm, new()
    {
        try 
        {
            using (var provider = new T())
            {
                var hash = provider.ComputeHash(input as byte[] ?? Encoding.UTF8.GetBytes((string)(object)input));
                return ConvertToHexString(hash);
            }
        } 
        catch (Exception ex) 
        {
            _logger.LogError($"Failed to generate hash: {ex}");
            throw;
        }
    }

    private string ConvertToHexString(byte[] bytes)
    {
        StringBuilder sb = new StringBuilder();

        foreach (var b in bytes) 
        {
            sb.Append(b.ToString("x2"));
        }

        return sb.ToString();
    }
}
