Here is an implementation example in Java using NIO Channels, but keep in mind that this is a simplified version. The handling of connection failures, retries, reconnections, and the code structure for handling these cases must be developed according to specific requirements and conditions of your application. 

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.*;

public class ConnectionManager {
    private Map<String, SocketInfo> remoteConnections = new HashMap<>();
    private Selector selector;

    public ConnectionManager() throws IOException {
        this.selector = Selector.open();
    }

    // Add a connection
    public void addConnection(String address, int port) throws IOException {
        SocketChannel socketChannel = SocketChannel.open(new InetSocketAddress(address, port));
        socketChannel.configureBlocking(false);
        SelectionKey key = socketChannel.register(selector, SelectionKey.OP_READ);
        SocketInfo socketInfo = new SocketInfo(socketChannel);
        remoteConnections.put(address + ":" + port, socketInfo);
    }

    // Remove a connection
    public void removeConnection(String address, int port) throws IOException {
        SocketInfo info = remoteConnections.remove(address + ":" + port);
        if (info != null) {
            info.getSocketChannel().close();
        }
    }

    // Listen for connections and process data
    public void listen() throws IOException {
        while (!Thread.interrupted()) {
            selector.select();
            Set<SelectionKey> keys = selector.selectedKeys();
            Iterator<SelectionKey> iterator = keys.iterator();
            while (iterator.hasNext()) {
                SelectionKey key = iterator.next();
                if (key.isReadable()) {
                    readDataFromSocket((SocketChannel) key.channel());
                } else if (key.isWritable()) {
                    // This would be where you'd handle writing data, but that is not implemented here
                }
                iterator.remove();
            }
        }
    }

    private void readDataFromSocket(SocketChannel socketChannel) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(2048);
        int numRead;
        try {
            while ((numRead = socketChannel.read(buffer)) != -1) {
                byte[] data = new byte[numRead];
                System.arraycopy(buffer.array(), 0, data, 0, numRead);
                processData(data); // Process received data here
            }
        } catch (IOException e) {
            // Handle exceptions here, such as a broken pipe or network error
            removeConnection(socketChannel.getRemoteAddress().toString(), socketChannel.socket().getPort());
        }
    }

    private void processData(byte[] data) {
        System.out.println("Received data: " + new String(data));
    }
}
```
