const { blueslip } = require('blueslip');
const { dbConnectionPool, apiClient } = require('./externalDependencies');

async function runModuleTests(moduleLabel, testSuite) {
    console.log(`Starting tests for module: ${moduleLabel}`);

    const startTime = Date.now();
    let totalAssertions = 0;
    let failedTestCount = 0;

    // Use `for...of` instead of `forEach()` to handle async/await
    for (const testCase of testSuite) {
        try {
            console.log(`Running test: ${testCase.name}`);

            const assertionsCount = await testCase();
            totalAssertions += assertionsCount;

            // Reset `blueslip` after each test to avoid side effects across tests
            blueslip.reset();
        } catch (error) {
            console.error(`Error executing test: ${testCase.name}`, error);
            failedTestCount++;
        }
    }

    const endTime = Date.now();
    const totalTests = testSuite.length;
    const executionTime = (endTime - startTime) / 1000; // Convert milliseconds to seconds

    console.log(`Finished tests for module: ${moduleLabel}`);
    console.log(`Executed ${totalTests} tests in ${executionTime} seconds with a total of ${totalAssertions} assertions made, out of which ${failedTestCount} failed.`);

    // Close database connections and clear API calls to prevent leaks
    dbConnectionPool.close();
    apiClient.clearRequestHistory();
}
