#include <string>
#include <vector>
#include <Magick++.h> 

enum class Format {PNG, SVG, JPEG};

class ImageConverter {
public:
    ImageConverter(std::string lib_path) {
        Magick::InitializeMagick(*lib_path.empty() ? nullptr : lib_path.c_str());
    }

    bool convertAndSave(const std::string &inputFile, const std::string &outputFile, Format format) {
        try {
            Magick::Image image;
            image.read(inputFile);

            Magick::Blob outputBlob;
            image.magick(formatToString(format));
            image.write(&outputBlob);

            FILE *output = fopen(outputFile.c_str(), "wb");
            if (!output) {
                return false;
            }

            fwrite(outputBlob.data(), 1, outputBlob.length(), output);
            fclose(output);
        } catch (Magick::Exception &error_) {
            // handle exception
            return false;
        }

        return true;
    }

    bool batchConvertAndSave(const std::vector<std::string> &inputFiles, const std::vector<std::string> &outputFiles, Format format) {
        if (inputFiles.size() != outputFiles.size()) {
            return false;
        }

        bool result = true;
        for(size_t i = 0; i < inputFiles.size(); ++i) {
            if(!convertAndSave(inputFiles[i], outputFiles[i], format)) {
                result = false;  // If one file failed, note it, but continue with others.
            }
        }

        return result;
    }

private:
    std::string formatToString(Format format) {
        switch (format) {
            case Format::PNG:
                return "png";
            case Format::SVG:
                return "svg";
            case Format::JPEG:
                return "jpeg";
            default:
                throw std::invalid_argument("Unsupported format");
        }
    }
};
```
