```Java
import org.apache.kafka.clients.producer.*;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class NIOConnectionHandler {
    private final Logger logger = Logger.getGlobal();
    private final KafkaProducer<String, String> kafkaProducer;
    // Pool of available channels
    private static ConcurrentLinkedQueue<SocketChannel> channelPool = 
        new ConcurrentLinkedQueue<>();

    public NIOConnectionHandler() {
         // Initialise Kafka producer. This would depend on your setup (e.g., bootstrap servers, serializers)
         Properties props = new Properties();
         props.put("bootstrap.servers", "localhost:9092");
         props.put("key.serializer", 
             "org.apache.kafka.common.serialization.StringSerializer");
         props.put("value.serializer", 
             "org.apache.kafka.common.serialization.StringSerializer");
         this.kafkaProducer = new KafkaProducer<>(props);
    }

    public void handleConnections(int port) throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        Selector selector = Selector.open();

        // Bind the server socket channel to localhost and given port
        serverSocketChannel.socket().bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);

        // Register the server socket channel with the selector for ACCEPT event, to accept new connections
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        while (true) {
            // Wait for events on the selector 
            int readyChannels = selector.select();

            if (readyChannels == 0) continue;

            Set<SelectionKey> keys = selector.selectedKeys();
            Iterator<SelectionKey> iterator = keys.iterator();

            while(iterator.hasNext()) {
                SelectionKey key = iterator.next();

                if (key.isAcceptable()) handleAccept(selector, serverSocketChannel);
                else if (key.isReadable()) executor.submit(() -> handleRead(key));

                iterator.remove();
            }
        }
    }

    private void handleAccept(Selector selector, ServerSocketChannel serverSocketChannel) throws IOException {
        SocketChannel client = serverSocketChannel.accept();

        // Configure non-blocking mode for the connected client socket channel
        client.configureBlocking(false);

        // Register the client socket channel with READ event to be notified when data is available
        client.register(selector, SelectionKey.OP_READ);
    }

    private void handleRead(SelectionKey key) {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(256);

        try {
            int read;

            while ((read = client.read(buffer)) > 0) {
                // Process the data from buffer and send it to Kafka
                String message = new String(buffer.array(), 0, read);

                kafkaProducer.send(new ProducerRecord<>("my-topic", UUID.randomUUID().toString(), message));
            }

            if (read < 0) {
                client.close();
                key.cancel();
            }
        } catch(IOException ex) {
            logger.severe("Error: " + ex);
            try {
                client.close();
            } catch (IOException e) {
                logger.severe("Error closing channel: " + e);
            }
        }
    }
}
```
This class will establish a non-blocking server socket with NIO, listen for incoming connections and read data from them. The received messages are then asynchronously sent to an Apache Kafka topic. Please note that this example doesn't include all the optimizations mentioned above like connection pooling or timeouts handling. For more complex scenarios, consider using a framework/library that handles these aspects for you (e.g., Netty).

Here is a possible implementation of `asyncArrayReduce` in JavaScript:

```javascript
class Semaphore {
  constructor(maxConcurrent = 20) {
    this.tasks = [];
    this.counter = 0;
    this.maxConcurrent = maxConcurrent;
  }

  take() {
    if (this.counter < this.maxConcurrent) {
      return new Promise(resolve => resolve());
    } else {
      return new Promise((resolve, reject) => 
        this.tasks.push([resolve, reject]))
    }
  }

  leave() {
    this.counter -= 1;
    if (this.tasks.length > 0) {
      const [resolve] = this.tasks.shift();
      resolve();
    }
  }
}

const asyncArrayReduce = async (array, initialValue, callback) => {
  let accumulator = initialValue;
  let semaphore = new Semaphore(5);

  for (let i = 0; i < array.length; i++) {
    await semaphore.take();

    try {
      const result = await callback(accumulator, array[i]);
      accumulator = result;

      if (result instanceof Error) throw result;  // Throw error if the callback returns an instance of Error class
    } catch (error) {
      semaphore.leave();
      return error;
    }

    semaphore.leave();
  }

  return accumulator;
};
```

This function uses a `Semaphore` class to control the concurrency level by limiting the number of simultaneous asynchronous operations. The `take()` method ensures that only up to a certain limit (5 in this case) can run at once, while `leave()` signals that an operation has completed and allows another task to start.

The function itself uses a for loop to iterate over each element in the array. For each iteration, it waits on the semaphore's take method to ensure there's room for a new asynchronous task before calling the callback function with the current accumulated value and the current number. 

Finally, the `leave()` method of the semaphore is called after each async operation finishes to signal that an available slot has opened up. If the callback throws an error or returns an instance of Error class, it is thrown back to the main function for further handling. Otherwise, the accumulator value is updated with the result from the callback and the process continues with the next number in the array.

