```java
import java.net.InetAddress;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public class PacketFilter {
    private static final int WINDOW_SIZE = 100; // sliding window size

    private BlockingQueue<Packet> packetWindow = new ArrayBlockingQueue<>(WINDOW_SIZE);
    private AtomicInteger totalCount = new AtomicInteger();
    private AtomicReference<Double> averageSize = new AtomicReference<>((double) 0);
    private AtomicInteger filteredCount = new AtomicInteger();

    // packet filter criteria
    Predicate<Packet> condition;

    public PacketFilter(Predicate<Packet> condition) {
        this.condition = condition;
    }

    public synchronized void addPacket(Packet p) {
        totalCount.incrementAndGet();

        // update average size
        double currentAverage = averageSize.get();
        int windowSize = Math.min(totalCount.get(), WINDOW_SIZE);
        averageSize.set((currentAverage * (windowSize - 1) + p.size) / windowSize);

        // add packet to sliding window
        if (!packetWindow.offer(p)) {
            try {
                packetWindow.take(); // remove oldest packet from the window if necessary
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public synchronized Optional<Packet> process(Packet p) {
        addPacket(p); // update sliding window and metrics

        if (!condition.test(p)) {
            filteredCount.incrementAndGet();
            return Optional.empty(); // packet doesn't meet condition, ignore it
        }

        return Optional.of(p); // packet meets condition, process it
    }

    public int getFilteredPackets() {
        return filteredCount.get();
    }

    public double getAverageSize() {
        return averageSize.get();
    }

    public int getTotalPackets() {
        return totalCount.get();
    }

    // Packet class definition
    private static class Packet {
        String id;
        InetAddress sourceIP, destIP;
        int port;
        long arrivalTime;
        int size;

        // constructor and getter methods...
    }
}
```
This is a basic example and may require further customization to handle edge cases specific to your application. For instance, the filtering condition is defined by `Predicate<Packet>`. This could be extended as needed. Please note that the code above is not taking into account network latency issues, which would need more complex logic, possibly involving multithreading and queue handling for incoming packets. Also, this doesn't handle invalid packet data or unexpected input sizes - it depends on how you define these terms in your context.

