def rate_limit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        client_ip = request.remote_addr
        if (now := time()) - LAST_CLEANUP > 1:  # clean up request count every second
            REQUEST_COUNT.clear()
            LAST_CLEANUP = now
        elif client_ip in REQUEST_COUNT and REQUEST_COUNT[client_ip] >= UPDATE_RATE_LIMIT:
            return jsonify({"error": "rate limit exceeded"}), 429
        else:
            REQUEST_COUNT[client_ip] = REQUEST_COUNT.get(client_ip, 0) + 1
        return func(*args, **kwargs)
    return wrapper

