const cache = redis.createClient({
  host: 'localhost',
  port: 6379
});
cache.on('error', function(err) {
  console.log('Error ' + err);
});

// Initialize Stream Cache
let streamCache;
if (cache.status === "ready"){
    streamCache = new StreamCache();
}else{
    cache.once("ready", () => streamCache = new StreamCache());
}

app.post('/process', async function(req, res) {
  let textDataStream = req.body; // Assuming data is sent as JSON in body of the POST request

  const oldTestamentBooks = await db.collection('books').find({"category": "old_testament"}).toArray();
  const booksRegex = new RegExp(oldTestamentBooks.map(book => book.name).join("|"), 'i'); // Case-insensitive search for Old Testament books

  let count = {};

  textDataStream
    .pipe(streamCache)
    .on('data', function(textChunk){
      let match;
      while (match = booksRegex.exec(textChunk)) {
        const bookName = match[0].toLowerCase();

        if(!count[bookName]){
          count[bookName] = 1;
        } else{
          count[bookName] += 1;
        }
      }
    })
    .on('error', function(err) {
      res.status(500).send({message: err});
    })
    .on('end', function() {
      // Send back the result in JSON format
      res.json(count);
    });
});

// Start server
