using System.Security.Cryptography;

public class SecureHashGenerator
{
    // Method to generate MD5 hash
    public async Task<string> GenerateMd5Async(byte[] input)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = await md5.ComputeHashAsync(new MemoryStream(input));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    // Method to generate SHA1 hash
    public async Task<string> GenerateSha1Async(byte[] input)
    {
        using (var sha1 = SHA1.Create())
        {
            var hashBytes = await sha1.ComputeHashAsync(new MemoryStream(input));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    // Method to generate SHA256 hash
    public async Task<string> GenerateSha256Async(byte[] input)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashBytes = await sha256.ComputeHashAsync(new MemoryStream(input));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}
