SSL_CTX* setupSecureConnection(char *password, char *certificatePath, char *privateKeyPath){
    SSL_library_init();
    OpenSSL_add_all_algorithms();  
    SSL_load_error_strings();

    const SSL_METHOD *method = TLSv1_3_method(); // or any other method you want to use
    if(NULL == method){
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    SSL_CTX* ctx = SSL_CTX_new(method);
    if(ctx == NULL) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // set the cipher suite
    SSL_CTX_set_ciphersuites(ctx, "TLS_AES_256_GCM_SHA384"); 

    // set certificate and private key paths
    if (SSL_CTX_use_certificate_file(ctx, certificatePath, SSL_FILETYPE_PEM) <= 0 || 
        SSL_CTX_use_PrivateKey_file(ctx, privateKeyPath, SSL_FILETYPE_PEM) <= 0 ) { 
         ERR_print_errors_fp(stderr);
    }

    return ctx;
}

void destroySecureConnection(SSL_CTX *ctx){
    if (ctx != NULL) {
        SSL_CTX_free(ctx);
    }
}
