#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/conf.h>
#include <stdio.h>

void load_primitives() {
    // Load OpenSSL configuration files
    CONF *configuration = NCONF_new(NCONF_no_malloc());
    if (configuration == NULL) {
        ERR_print_errors_fp(stderr);
        return;
    }

    // Define available cryptographic primitives and their corresponding add functions
    struct primitive {
        const char *name;
        int (*add_function)(const EVP_CIPHER *cipher, void *data, int cb);
    };
    struct primitive primitives[] = {
        {"AES", EVP_add_cipher},
        {"Camellia", EVP_add_cipher},
        {"MD5", EVP_add_digest},
        {"SHA1", EVP_add_digest},
        {"SHA256", EVP_add_digest},
        {"SHA512", EVP_add_digest}
    };

    int num_primitives = sizeof(primitives) / sizeof(struct primitive);

    // Load and manage primitives
    for (int i = 0; i < num_primitives; ++i) {
        const struct primitive *primitive = &primitives[i];

        // Check if the primitive is already loaded
        int index = EVP_get_cipherbyname(primitive->name);
        if (index != -1) {
            printf("Primitive '%s' already loaded\n", primitive->name);
            continue;
        }

        // Add the primitive using the appropriate add function
        int result = (*primitive->add_function)(EVP_get_cipherbyname(primitive->name), NULL, 0);
        if (result != 1) {
            ERR_print_errors_fp(stderr);
            printf("Failed to add primitive '%s'\n", primitive->name);
        } else {
            printf("Primitive '%s' added successfully\n", primitive->name);
        }
    }

    // Cleanup
    NCONF_free(configuration);
}
```
