Below is an example of how you might implement `readDirectoryFiles` using Node.js's built-in `fs` module along with `async/await` for asynchronous handling and error handling. 

```javascript
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const { once } = require('events');
const { createReadStream } = require('fs');
const { createInterface } = readline;

async function readDirectoryFiles(dirPath, extension) {
  let data = '';

  try {
    const dirEntries = await fs.promises.readdir(dirPath);

    for (let entry of dirEntries) {
      if (path.extname(entry) !== `.${extension}`) continue; // Skip if the file does not match extension

      const filePath = path.join(dirPath, entry);
      const stat = await fs.promises.stat(filePath);

      if (stat.isDirectory()) {
        data += await readDirectoryFiles(filePath, extension); // If it's a directory, recurse into it
      } else {
        console.log(`Processing file: ${entry}...`);

        const input = createReadStream(filePath);
        const rl = createInterface({ input });

        rl.on('line', line => {
          data += `${line}\n`; // Add each line to the data string
          console.log(`Content length: ${Buffer.byteLength(data)}`);
        });

        await once(rl, 'close'); // Wait until file is fully read
      }
    }
  } catch (err) {
    console.error('Error reading directory/file', err);
  } finally {
    return data; // Return the accumulated string
  }
}
```

You can use this function like so:

```javascript
readDirectoryFiles('/path/to/directory', 'txt').then(data => console.log(`Final content length: ${Buffer.byteLength(data)}`));
```

Note that the logging system only logs file names and their current content lengths as they are being read, not after all files have been processed. This is due to the fact that such a logging system would result in each line of every single file being logged separately which could slow down your program significantly with large directories or files.

