                importedModule = await import(moduleName);
            } catch (err) {
                console.error(`Failed to import ${moduleName} due to: ${err}`);
                continue; // Skip this test case and proceed with the next one
            }

            // Execute test function
            await fn(importedModule);

            const endTime = performance.now();
            console.log(`Finished ${moduleName}:${label}. Took ${(endTime - startTime).toFixed(2)}ms.`);
        } catch (err) {
            // Handle errors in test function execution
            console.error(`Failed to execute test case due to: ${err}`);
        } finally {
            // Reset the mocking library after each test
            blueslip.reset(); 
        }
    }
}
