                $this->logger->info('User authenticated', ['username' => $username]);
                return $data; // access token & refresh token
            } else {
                $this->logger->error('Authentication failed', ['username' => $username, 'reason' => json_encode($data)]);
                throw new Exception("Invalid response from OAuth server");
            }
        } catch (Exception $e) {
            $this->logger->critical('Unable to authenticate user', ['username' => $username, 'error' => $e->getMessage()]);
            throw $e; // rethrow the exception after logging it
        }
    }

    public function fetchUserInfo($access_token) {
        $cache = $this->redis->get('userinfo:' . md5($access_token));
        if ($cache) {
            return json_decode((string) $cache, true); // cached user data
        } else {
            $response = $this->client->post('me', ['headers' => [ 'Authorization' => 'Bearer '.$access_token ]]);
            $data = json_decode((string) $response->getBody(), true);
            $this->redis->setex('userinfo:' . md5($access_token), 3600, json_encode($data)); // cache for 1 hour
            return $data; // user data
        }
    }

    public function handleAuthRequest($username, $password) {
        $auth = $this->authenticate($username, $password);
        $userinfo = $this->fetchUserInfo($auth['access_token']);

        // Securely store access token in session
        $_SESSION['access_token'] = bin2hex(random_bytes(16));
        return $userinfo;
    }
}
