pub struct CompilationResult {
    pub compilation_time: u128,
    pub memory_usage: usize,
    pub errors: Vec<String>,
}

async fn compile(source_path: &str) -> Result<CompilationResult, String> {
    let start = Instant::now();
    // Fetch latest source file from Git repository using the git2 crate
    match Repository::clone("https://github.com/user/repo", "/tmp/temp_dir").build().unwrap() {
        Ok(_) => println_string("Successfully cloned repo!"),
        Err(Error::FetchHeadNotFound | Error::InvalidSpec(_)) => {
            return Err(format_err_msg(&source_path, "The specified repository does not exist."));
        }
        Err(Error::DetachedHead) => {
            return Err(format_err_msg(&source_path, "The HEAD is in a detached state."));
        }
        Err(_) => return Err(format_err_msg(&source_path, "An error occurred while cloning the repository.")),
    };

    // Measure and log resident set size of process
    let mut sys = sysinfo::System::new();
    let start_mem: usize = sys.reserved().unwrap();

    // Compile with rustc
    catch_with_exit_code(|| {
        compile_source(source_path)
    }).map_err(|error| {
        error.to_string()
    });

    let end = Instant::now();
    let compilation_time = end.duration_since(start).as_millis();
    let end_mem: usize = sys.reserved().unwrap();
    let memory_usage = end_mem - start_mem;

    // Return the compilation result
    Ok(CompilationResult {
        compilation_time,
        memory_usage,
        errors: vec![],
    })
}

