import com.github.dockerjava.api.DockerClient;
import com.github.dockerjava.api.command.CreateContainerResponse;
import com.github.dockerjava.api.model.*;
import com.github.dockerjava.core.DefaultDockerClientConfig;
import com.github.dockerjava.core.DockerClientBuilder;
import com.github.dockerjava.core.DockerClientConfig;

public class DockerManager {
    private DockerClient dockerClient;

    public DockerManager() {
        DockerClientConfig config = DefaultDockerClientConfig.createDefaultConfigBuilder().build();
        this.dockerClient = DockerClientBuilder.getInstance(config).build();
    }

    public void runCommandInContainer(String imageName, String[] commands) throws Exception {
        // Pull image from the repository if not available locally
        dockerClient.pullImageCmd(imageName).exec(new PullImageResultCallback()).awaitCompletion();

        // Create a container spec with shell command and image
        ContainerConfig containerConfig = ContainerConfig.builder()
            .image(imageName)
            .cmd(commands)
            .build();

        // Start the container
        CreateContainerResponse container = dockerClient.createContainerCmd(containerConfig).exec();
        dockerClient.startContainerCmd(container.getId()).exec();

        // Check if the command is running successfully or not
        InspectContainerResponse inspectContainerResponse = dockerClient.inspectContainerCmd(container.getId()).exec();
        if(!inspectContainerResponse.getState().getRunning()) {
            throw new Exception("Failed to execute command in container");
        }
    }
}
