```javascript
const { Suite } = require('blueslip');

async function runTests(moduleLabel, suites, config) {
  const suite = new Suite();

  async function executeTestSuite(suiteName, testCases) {
    for (let i = 0; i < testCases.length; i++) {
      let attempts = 0;

      while (attempts <= config.maxRetryAttempts) {
        try {
          await Promise.resolve() // load module and dependencies here
            .then(() => {
              console.log(`Running ${suiteName} -> ${testCases[i].name}...`);
              return testCases[i]();
            })
            .then((result) => {
              if (result === 'PASS') {
                console.log('Test passed');
              } else {
                console.error(`Test failed: ${result || "unknown error"}`);
              }

              return result;
            })
            .then((result) => suite.addTestResult({ name: testCases[i].name, passed: result === 'PASS'})) // assuming 'PASS'/falsy for fail
            .catch(console.error);

          break;
        } catch (err) {
          console.warn('Retrying', err);
          ++attempts;
        }
      }

      if (attempts > config.maxRetryAttempts) {
        throw new Error(`Test ${testCases[i].name} failed after max retries.`);
      }
    }

    await suite.run(); // execute blueslip tests
  }

  for (let i = 0; i < suites.length; i++) {
    if (!suites[i].skip && !config.onlyTestSuites || config.onlyTestSuites === suites[i].name) {
      await executeTestSuite(moduleLabel, suites[i]);
    }
  }
}
