Here's a basic implementation of `asyncArrayReduce` in JavaScript using Promises, async/await syntax, along with some error handling and edge cases consideration:

```javascript
const MAX_CONCURRENT = 10;
let semaphore = new Semaphore(MAX_CONCURRENT);

// Fetch metadata about the number from an external API
async function fetchMetadata(number) {
  // Simulate a delay or asynchronous processing
  await new Promise((resolve) => setTimeout(resolve, Math.random() * 100));

  if (isNaN(number)) {
    throw Error("Non-numeric value encountered");
  }

  return number; // Placeholder for metadata from external API call
}

async function asyncArrayReduce(array, initialValue = 0, callback) {
  let acc = initialValue;

  for (let i = 0; i < array.length; ++i) {
    await semaphore.use(); // Wait if semaphore count is at MAX_CONCURRENT

    try {
      const number = array[i];

      // Checking for edge cases such as null or undefined values, empty arrays, etc
      if (number === null || number === undefined) {
        throw Error("Encountered a null/undefined value in the array");
      }

      const metadata = await fetchMetadata(number);

      console.log(`Starting operation for ${metadata} at ${new Date().toISOString()}`);

      acc = await callback(acc, number); // Await on the result of the callback before continuing

      console.log(`Finished operation for ${metadata} at ${new Date().toISOString()}`);
    } catch (err) {
      return err;
    } finally {
      semaphore.free(); // Release the semaphore after each async operation
    }
  }

  return acc;
}

// Semaphore class to control concurrency
class Semaphore {
  constructor(max) {
    this.counter = 0;
    this.tasks = [];
    this.max = max;
  }

  use() {
    if (this.counter >= this.max) {
      return new Promise((resolve) => this.tasks.push(resolve));
    }
    ++this.counter;
  }

  free() {
    --this.counter;
    if (this.tasks.length > 0) {
      let task = this.tasks.pop();
      task(() => this.use()); // Call the next function in line to continue execution
    }
  }
}
