```csharp
using System;
using System.Xml;
using System.Xml.XPath;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

public class XmlParser 
{
    private readonly IConfiguration _config;
    private static XPathDocument _docCache = null;
    private static DateTime _cacheTime;

    public XmlParser(IConfiguration config)
    {
        _config = config;
    }

    public string ParseXmlByXpath(string xPath, string namespaceUri)
    {
        // Load XML from the configured path.
        var xmlFilePath = _config["xmlFilePath"];

        if (DateTime.Now - _cacheTime > TimeSpan.FromMinutes(5)) 
        {
            // Cache expired, reload the document.
            _docCache = new XPathDocument(xmlFilePath);
            _cacheTime = DateTime.Now;

            var navigator = _docCache.CreateNavigator();
            if (!string.IsNullOrEmpty(namespaceUri)) 
            {
                // Register the namespace prefix in case it's necessary for the XPath expression.
                var nsManager = new XmlNamespaceManager(navigator.NameTable);
                nsManager.AddNamespace("ns", namespaceUri);
                navigator.MoveToFirst();

                var nodeIterator = navigator.Select(xPath, nsManager);
                if (nodeIterator.MoveNext()) 
                {
                    return nodeIterator.Current.Value;
                }
            }

            throw new Exception("No element found or multiple elements are found with the given name.");
        } 
        else 
        {
            // Use cached document.
            var navigator = _docCache.CreateNavigator();
            if (!string.IsNullOrEmpty(namespaceUri)) 
            {
                var nsManager = new XmlNamespaceManager(navigator.NameTable);
                nsManager.AddNamespace("ns", namespaceUri);
                navigator.MoveToFirst();

                var nodeIterator = navigator.Select(xPath, nsManager);
                if (nodeIterator.MoveNext()) 
                {
                    return nodeIterator.Current.Value;
                }
            }

            throw new Exception("No element found or multiple elements are found with the given name.");
        }
    }
}
```
