```java
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.concurrent.*;

public class MD5HashGenerator {
    private final ExecutorService executor;
    private final LoadingCache<String, String> cache;
    private static final int MAX_STRING_LENGTH = 1000;
    private static final Logger logger = LoggerFactory.getLogger(MD5HashGenerator.class);

    public MD5HashGenerator(int maxThreads, int maxCacheSize) {
        executor = new ThreadPoolExecutor(maxThreads, maxThreads, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        cache = CacheBuilder.newBuilder()
                .maximumSize(maxCacheSize)
                .build(new CacheLoader<String, String>() {
                    @Override
                    public String load(String s) throws Exception {
                        return computeMD5Hash(s);
                    }
                });
    }

    public Future<String> getMd5Async(String input) {
        if (input == null || input.length() > MAX_STRING_LENGTH) {
            throw new IllegalArgumentException("Invalid input");
        }

        return executor.submit(() -> {
            try {
                return cache.get(input);
            } catch (Exception e) {
                logger.error("Error while computing MD5 hash", e);
                return null;
            }
        });
    }

    private String computeMD5Hash(String input) throws Exception {
        MessageDigest md = DigestUtils.getMd5Digest();
        byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));

        // Convert the hash to a hexadecimal string representation
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b & 0xff));
        }

        return sb.toString();
    }
}
```

