const bookNamesRegex = /(Old Testament|New Testament) ?((?:\b\w+\b)[, ]?)*/g; // This regex will find the names of books from both Old and New Testaments.

async function extractBooksFromBibleText(textInput) {
    if (typeof textInput !== 'string') {
        throw new TypeError("Invalid input type. Input should be a string.");
    } else if (!textInput.trim()) {
        throw new Error("Empty string provided as an argument.")
    }

    const bookNames = Array.from(new Set(bookNamesRegex.exec(textInput))); // Extract unique book names from the text input.

    let booksData;

    try {
        booksData = await fetchBibleBooksAPI(); // Call an external API to fetch Bible books data.
    } catch (error) {
        console.log('Error fetching books data:', error);
    }

    const resultObj = bookNames.reduce((acc, currName) => {
        if (booksData[currName]) {
            acc[currName] = booksData[currName]; // If a book is found in the Bible data, increment its count.
        } else {
            acc[currName] = 1; 
        }
        return acc;
    }, {});

    return resultObj;
}
