class asyncArrayReduce {
    constructor(concurrencyLevel = 5) {
        this.semaphore = new Semaphore(concurrencyLevel);
        this.cache = new Cache(); // Implementation of cache class is not provided here for simplicity
        this.token = 'valid_auth_token';
    }

    async reduce(array, initialValue, callback) {
        let result = initialValue;
        try{
            for (const item of array){
                await this.semaphore.wait();
                const apiResultPromise = this.callExternalApi(item);
                apiResultPromise
                    .then((apiResult) => {
                        return callback(result, apiResult);
                    })
                    .catch((err) => console.error('Error in the callback', err))
                    .finally(() => this.semaphore.signal());
            }
        } catch (error){
            throw error;
        }
    }

    callExternalApi(item) {
        // Check if result is cached, if not make an API call
        return new Promise((resolve, reject) => {
            setTimeout(() => {
                resolve({data: item});
            }, 1000);
        });
    }
}
