```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class TripleDesDecryptor
{
    private readonly ConcurrentDictionary<string, Tuple<byte[], byte[]>> keyIVPairs = new ConcurrentDictionary<string, Tuple<byte[], byte[]>>(); // Key is context name and value is a tuple of Key and IV
    private readonly ICspServiceProvider cspService; // Assuming this exists and provides methods for getting the keys and IVs dynamically.

    public TripleDesDecryptor(ICspServiceProvider cspService)
    {
        this.cspService = cspService;
    }

    public string DecryptMessage(string base64EncodedMessage, string contextName)
    {
        try
        {
            // Fetch key and IV if not already available
            if (!keyIVPairs.ContainsKey(contextName))
                keyIVPairs[contextName] = cspService.GetKeysAndIv(contextName);

            byte[] key, iv;
            keyIVPairs.TryGetValue(contextName, out Tuple<byte[], byte[]> value);
            key = value.Item1;
            iv = value.Item2;

            using (TripleDESCryptoServiceProvider tdesAlgorithm = new TripleDESCryptoServiceProvider())
            {
                tdesAlgorithm.Key = key;
                tdesAlgorithm.IV = iv;

                // Create a decrytor to perform the stream transform.
                ICryptoTransform decryptor = tdesAlgorithm.CreateDecryptor(tdesAlgorithm.Key, tdesAlgorithm.IV);

                // Convert Base64 encoded message back into bytes.
                byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

                byte[] decryptedBytes = PerformCryptography(encryptedBytes, decryptor);

                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (Exception ex)
        {
            // Log the exception and throw or handle it as needed in your application.
            Console.WriteLine("Error: " + ex.Message);
            throw;
        }
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using (MemoryStream memoryStream = new MemoryStream())
        {
            using (CryptoStream cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write))
            {
                cryptoStream.Write(data, 0, data.Length);
                cryptoStream.FlushFinalBlock();

                return memoryStream.ToArray();
            }
        }
    }
}
```
