Due to the complexity of this task, it's not feasible to provide an entire code solution here. However, I can outline a basic structure of how you might approach this problem in C using POSIX Threads (pthread) and semaphores. 

```c
#include <stdio.h>
#include <semaphore.h>
#include <pthread.h>

// Define your named semaphore here
typedef struct {
    char *name;
    int value;
    sem_t sem;
} NamedSem;

// Define a hashtable-like structure for managing named semaphores
NamedSem namedSems[100];  // assuming max of 100 semaphores
int numNamedSems = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a named semaphore
void createSem(char *name, int value) {
    // Lock the critical section
    pthread_mutex_lock(&lock);

    if (numNamedSems >= 100) {  // Check for maximum limit
        printf("Error: Maximum semaphores reached.\n");
        return;
    }

    namedSems[numNamedSems].name = name;
    namedSems[numNamedSems].value = value;
    sem_init(&namedSems[numNamedSems++].sem, 0, value); // Initialize the semaphore with provided value

    // Unlock the critical section
    pthread_mutex_unlock(&lock);
}

// Function to delete a named semaphore
void deleteSem(char *name) {
    // Lock the critical section
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numNamedSems; ++i) {
        if (strcmp(namedSems[i].name, name) == 0) {  // Compare names
            sem_destroy(&namedSems[i].sem);  // Destroy the semaphore

            // Shift other elements to fill the gap
            for (int j = i; j < numNamedSems - 1; ++j) {
                namedSems[j] = namedSems[j + 1];
            }
            --numNamedSems;

            break;
        }
    }

    // Unlock the critical section
    pthread_mutex_unlock(&lock);
}

// Function to increment a named semaphore
void incSem(char *name) {
    for (int i = 0; i < numNamedSems; ++i) {
        if (strcmp(namedSems[i].name, name) == 0) {  // Compare names
            sem_post(&namedSems[i].sem);  // Increment the semaphore
            break;
        }
    }
}

// Function to decrement a named semaphore
void decSem(char *name) {
    for (int i = 0; i < numNamedSems; ++i) {
        if (strcmp(namedSems[i].name, name) == 0) {  // Compare names
            sem_wait(&namedSems[i].sem);  // Decrement the semaphore
            break;
        }
    }
}
```
