public class DynamicTripleDesDecryptor
{
    private CspApi cspApi = new CspApi(); // Replace with actual implementation.
    private ConcurrentDictionary<string, Tuple<byte[], byte[]>> cache = 
        new ConcurrentDictionary<string, Tuple<byte[], byte[]>>();

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId)
    {
        var keyAndIv = await FetchKeyAndIvAsync(contextId);

        using (TripleDES tripleDesAlgorithm = TripleDES.Create())
        {
            tripleDesAlgorithm.Mode = CipherMode.CBC;
            tripleDesAlgorithm.Padding = PaddingMode.PKCS7;
            tripleDesAlgorithm.Key = keyAndIv.Item1;
            tripleDesAlgorithm.IV = keyAndIv.Item2;

