            byte[] cipherTextBytes = Convert.FromBase64String(base64EncodedMessage);
            byte[] plainTextBytes = new byte[cipherTextBytes.Length];

            using (MemoryStream memoryStream = new MemoryStream(cipherTextBytes))
            {
                using (CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                {
                    await cryptoStream.CopyToAsync(plainTextBytes);
                }
            }

            return Encoding.UTF8.GetString(plainTextBytes);
        }
    }

    private async Task<Tuple<byte[], byte[]>> FetchKeyAndIvAsync(string contextId)
    {
        if (cache.TryGetValue(contextId, out Tuple<byte[], byte[]> keyAndIv)) return keyAndIv;

        // Replace with actual implementation to interact with the CSP API.
        var keysAndIvs = await cspApi.FetchKeyAndIvAsync(contextId); 

        cache.TryAdd(contextId, Tuple.Create(keysAndIvs.Item1, keysAndIvs.Item2));
