```c
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} DESConfig;

DESConfig* initDes(char* mode, int keyLen, unsigned char* keyData, int ivLen, unsigned char* ivData) {
    EVP_CIPHER *cipher = NULL;
    DESConfig* config = malloc(sizeof(*config));

    if (strcmp("ECB", mode) == 0) cipher = EVP_des_ecb();
    else if (strcmp("EDE", mode) == 0) cipher = EVP_des_ede();
    else if (strcmp("EDE3", mode) == 0) cipher = EVP_des_ede3();
    else if (strcmp("CFB", mode) == 0) cipher = EVP_des_cfb8();  // Or other variants.

    config->ctx = EVP_CIPHER_CTX_new();
    memcpy(config->key, keyData, keyLen);
    memcpy(config->iv, ivData, ivLen);

    return config;
}

void encryptDes(DESConfig* config, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len = 0, ciphertext_len = 0;
    EVP_EncryptInit_ex(config->ctx, EVP_des_ecb(), NULL, config->key, config->iv);
    EVP_EncryptUpdate(config->ctx, ciphertext, &len, plaintext, plaintext_len);
    ciphertext_len = len;
    EVP_EncryptFinal_ex(config->ctx, ciphertext + len, &len);
    ciphertext_len += len;
}

void decryptDes(DESConfig* config, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len = 0, plaintext_len = 0;
    EVP_DecryptInit_ex(config->ctx, EVP_des_ecb(), NULL, config->key, config->iv);
    EVP_DecryptUpdate(config->ctx, plaintext, &len, ciphertext, ciphertext_len);
    plaintext_len = len;
    EVP_DecryptFinal_ex(config->ctx, plaintext + len, &len);
    plaintext_len += len;
}
```

