```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;
using System.Xml.XPath;

public class XmlParserService
{
    private Dictionary<string, IEnumerable<XNode>> _cache = new Dictionary<string, IEnumerable<XNode>>();

    public IEnumerable<XNode> GetNodesByPath(string xmlDoc, string xpathQuery, Action<IEnumerable<XNode>> validationFunc) 
    {
        if (_cache.ContainsKey(xpathQuery))
            return _cache[xpathQuery];

        try
        {
            var doc = XDocument.Parse(xmlDoc);
            var matchedNodes = ((IEnumerable<XNode>)doc.XPathEvaluate(xpathQuery)).ToList();

            if (matchedNodes.Count == 0) 
                Console.WriteLine("No data found for the given XPath query");
            else if (matchedNodes.Count > 1) 
                Console.WriteLine("Multiple matching nodes found for the given XPath query");

            _cache[xpathQuery] = matchedNodes; // cache the result

            validationFunc?.Invoke(matchedNodes);

            return matchedNodes;
        } 
        catch (Exception e)
        {
            Console.WriteLine("Error occurred while parsing XML: " + e.Message);
            return null;
        }
    }
}
```
