#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *input_dir;
    char *output_dir;
} thread_args_t;

void* convert(void *arg) {
    DIR *d;
    struct dirent *dir;
    d = opendir((char*)arg);

    if (d) {
        while ((dir = readdir(d)) != NULL) {
            char extension[5]; // Assuming maximum length of 4 characters for file extensions
            strncpy(extension, &dir->d_name[strlen(dir->d_name)-4], 4); // Fetch last four characters as an extension (including '.')

            if (!strcasecmp(extension, ".jpg") || !strcasecmp(extension, ".jpeg")) { // Case insensitive comparison
                char input_filepath[1024]; // Assuming maximum length of 1024 characters for file path
                sprintf(input_filepath, "%s/%s", (char*)arg, dir->d_name);

                char output_filename[1024]; // Assuming maximum length of 1024 characters for file name
                strncpy(output_filename, &dir->d_name[strlen(dir->d_name)-4], strlen(dir->d_name)-4);
                strcat(output_filename, ".pdf"); // Appending .pdf extension to the output filename

                char output_filepath[1024]; // Assuming maximum length of 1024 characters for file path
                sprintf(output_filepath, "%s/%s", ((thread_args_t*)arg)->output_dir, output_filename);

                char command[2048]; // Assuming maximum length of 2048 characters for the command line string
                sprintf(command, "third-party-tool '%s' '%s'", input_filepath, output_filepath); // Third party tool command to convert JPEG to PDF

                system(command); // Execute third-party tool
            }
        }

        closedir(d);
    }

    return NULL;
}

int main() {
    pthread_t thread;
    char *input_dir = "/path/to/your/jpeg/files";
    char *output_dir = "/path/for/generated/pdf/files";

    thread_args_t args = { input_dir, output_dir };
    pthread_create(&thread, NULL, convert, &args); // Starting a new thread for the conversion process
    pthread_join(thread, NULL); // Waiting for the thread to finish
}
```
