#include <regex>
#include <fstream>
#include <thread>
#include <vector>

// Third-party tool dummy function
int jpegToPdf(const std::string &in, const std::string &out) { return 0; }

std::string renderHtml(std::filesystem::path dir_path, const std::vector<std::string> &scripts)
{
    std::regex jpgRegex("\\.jpg$", std::regex_constants::icase);
    std::string html;
    int failCount = 0;

    for (auto &p : std::filesystem::directory_iterator(dir_path)) {
        if (!std::filesystem::is_regular_file(p.status())) continue;

        std::string fileName = p.path().filename().string();
        std::smatch match;

        // Check for JPEG files only
        if (std::regex_search(fileName, match, jpgRegex)) {
            html += "<script id=\"" + fileName + "\">";  // Create script tag

            // Open each file and append its content to the HTML string
            std::ifstream inFile;
            inFile.open(p.path(), std::ios::in);
            if (inFile.is_open()) {
                std::string line;
                while (!inFile.eof()) {
                    getline(inFile, line);
                    html += line;
                }
            } else {
                failCount++;
            }

            inFile.close();

            html += "</script>\n";  // Close script tag

            std::string pdfFileName = p.path().stem().string() + ".pdf";
            if (jpegToPdf(p.path(), dir_path / pdfFileName)) {
                failCount++;
            }
        }
    }

    return html;
}
