import org.json.*;
import java.util.*;

public class JsonObject {
    private Map<String, Object> data;

    public static JsonObject parse(String jsonString) throws JSONException {
        JSONObject obj = new JSONObject(jsonString);
        Map<String, Object> map = toMap(obj);

        return new JsonObject(map);
    }

    private JsonObject(Map<String, Object> data) {
        this.data = data;
    }

    public static String create(JsonObject object) throws JSONException {
        return new JSONObject(object.data).toString();
    }

    public static Map<String, Object> toMap(JSONObject obj)  throws JSONException {
        Map<String, Object> map = new HashMap<>();

        Iterator<String> keysItr = obj.keys();
        while(keysItr.hasNext()) {
            String key = keysItr.next();
            Object value = obj.get(key);

            if(value instanceof JSONArray) {
                value = toList((JSONArray) value);
            } else if(value instanceof JSONObject) {
                value = toMap((JSONObject) value);
            }   
            map.put(key, value);
        }   
        return map;
    }

    public static List<Object> toList(JSONArray array) throws JSONException {
        List<Object> list = new ArrayList<>();
        for(int i = 0; i < array.length(); i++){
            Object value = array.get(i);
            if(value instanceof JSONArray){
                value = toList((JSONArray) value);
            } else if(value instanceof JSONObject) {
                value = toMap((JSONObject) value);
            }
            list.add(value);
        }   
        return list;
    }
}
```
This class provides the basic methods for parsing and creating JSON strings using the `org.json` library. It also includes helper methods for converting between `Map<String, Object>` and `JSONObject` and `List<Object>` and `JSONArray`. 

