// Resolve a domain name asynchronously.
void resolveAsync(char *name) {
    // Wait for an available slot in the semaphore (if it becomes unavailable, this will block).
    sem_wait(&config.querySem); 

    pthread_t thread;
    char* queryName = malloc(strlen(name));
