```csharp
using System;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using System.Net.Http;

public class ConfigController : ControllerBase
{
    private readonly YourDbContext _context;
    private readonly IMemoryCache _cache;
    private static HttpClient _httpClient = new HttpClient();

    public ConfigController(YourDbContext context, IMemoryCache memoryCache)
    {
        _context = context;
        _cache = memoryCache;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateConfiguration([FromBody]UpdateConfigModel model)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        var cacheKey = $"userconfig_{model.UserId}_{model.Name}";
        string currentValue;

        // Try to get the configuration from the cache
        if (!_cache.TryGetValue(cacheKey, out currentValue))
        {
            // If it's not in the cache or is null, fetch from DB and update the cache
            var config = await _context.UserConfigurations.FindAsync(model.UserId, model.Name);

            if (config == null)
                return NotFound();  // The configuration for this user does not exist

            currentValue = config.Value;

            var cacheEntryOptions = new MemoryCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromSeconds(60));  // Set the expiration time as needed

            _cache.Set(cacheKey, config.Value, cacheEntryOptions);
        }

        if (currentValue == model.NewValue)
            return BadRequest("The new value is same as current one.");

        try
        {
            // Update in database
            var dbConfig = await _context.UserConfigurations.FindAsync(model.UserId, model.Name);

            if (dbConfig != null)
            {
                dbConfig.Value = model.NewValue;

                await _context.SaveChangesAsync();

                // Clear the cache for this configuration after update
                _cache.Remove(cacheKey);
            }
        }
        catch (Exception ex)
        {
            return StatusCode(500, "An error occurred while updating the configuration: " + ex.Message);
        }

        // Integrate with external API for version control and logging
        await _httpClient.PostAsync(VersionApiUrl, new StringContent(""));  // Post to version control API here
        await _httpClient.PostAsync(LoggerApiUrl, new StringContent($"Configuration updated: {model.UserId}, {model.Name}, {currentValue} -> {model.NewValue}"));  // Post to logger API here

        return Ok("Configuration updated successfully.");
    }

    public class UpdateConfigModel
    {
        public int UserId { get; set; }
        public string Name { get; set; }
        public string NewValue { get; set; }
    }
}
```
This controller uses an instance of `IMemoryCache` to cache the configurations fetched from the database, which can improve performance for repeat requests. The cache key is built using the user ID and configuration name, so each user-specific configuration has its own cache entry. If a configuration for a particular user does not exist in the cache or is null, it will be retrieved from the database and stored into the cache to prevent future database hits.

The `UpdateConfiguration` method handles POST requests to update configurations in the database using EF Core's DbContext. It first checks if there's already a cached version of this configuration, and if not, fetches it from the database and caches the result. If the new value is same as current one, or an exception occurs during updating the configuration, appropriate responses are returned.

Finally, after successfully updating the configuration, the code interacts with two external APIs for version control (VersionApiUrl) and logging (LoggerApiUrl). Please replace `""` with actual data you want to post. Make sure that these APIs accept POST requests as needed by your application requirements. 

