        return -3; // Error code for invalid callback
    }

    if (!conn->is_established){
        LogError("validate_and_log", "Connection has not been established");
        return -4; // Error code for unestablished connection
    }

    // If we reach here, the checks have passed
    callback();
    LogInfo("validate_and_log", "Validation and logging procedure completed successfully");
    return 0; // Success code
}
