```java
// Import necessary libraries
import com.jcraft.jsch.*;
import java.io.*;
import java.util.*;

public class SSHManager {
    private static final int MAX_RETRIES = 3;

    private List<String> servers = new ArrayList<>(); // Store server details here
    private Map<String, Session> sessions = new HashMap<>(); // Store SSH sessions by server names
    private String username, password; // Authentication credentials

    public SSHManager(String username, String password) {
        this.username = username;
        this.password = password;
    }

    public void addServer(String ip, int port) throws JSchException {
        servers.add(ip + ":" + port);
        Session session = new JSch().getSession(username, ip, port); // Create a new SSH session
        session.setPassword(password); // Set authentication credentials
        session.connect();
        sessions.put(ip + ":" + port, session); // Store the session for later use
    }

    public void executeCommands(String[] commands) throws JSchException, IOException {
        for (String server : servers) {
            Session session = sessions.get(server);

            for (String command : commands) {
                int attempts = 0;
                while (attempts < MAX_RETRIES) { // Retry the command up to three times with exponential backoff
                    try {
                        ChannelExec channel = (ChannelExec) session.openChannel("exec");

                        channel.setCommand(command);
                        channel.connect();
                        InputStream in = channel.getInputStream();
                        byte[] tmp = new byte[1024];
                        while (true){ // Handle real-time command outputs and log them to console
                            while (in.available() > 0) {
                                int i = in.read(tmp, 0, 1024);
                                if (i < 0) break;
                                System.out.print(new String(tmp, 0, i));
                            }

                            if (channel.isClosed()) {
                                System.out.println("Exit status: " + channel.getExitStatus());
                                break;
                            }
                        }

                        break; // If no exceptions occur during execution, we can exit the loop and move to next command
                    } catch (Exception e) {
                        attempts++;
                        try { Thread.sleep((long) Math.pow(2, attempts)); } 
                        catch (InterruptedException ignored) {} // Exponential backoff: sleep for 2^attempts seconds
                    }
                }
            }
        }
    }
}
```
This is a rudimentary SSH manager in Java which can dynamically connect to remote servers, execute commands on them and handle command execution failures. This tool doesn't yet implement the full features you requested including dynamic server configuration from REST API, logging mechanism, user interface, testing and maintenance plans etc.

