```python
import os
import json
import importlib
from typing import Callable, Dict, Any, Type
from concurrent.futures import ThreadPoolExecutor

class JSONBase:
    _factory_registry = {}

    @staticmethod
    def register_factory(id_: str) -> Callable[[Callable], Callable]:
        def decorator(func: Callable) -> Callable:
            JSONBase._factory_registry[id_] = func
            return func
        return decorator

    @staticmethod
    def get_subclass(cls, id_: str):
        if id_ in cls._factory_registry:
            return cls._factory_registry[id_]()
        else:
            raise ValueError('No factory function registered for the given ID')

    @staticmethod
    def discover_subclasses(directory: str):
        for file in os.listdir(directory):
            if file.endswith('.py'):
                importlib.import_module(file[:-3])

    def to_json(self) -> str:
        return json.dumps(self, default=lambda o: o.__dict__, sort_keys=True, indent=4)

    @staticmethod
    def from_json(cls, json_str: str):
        data = json.loads(json_str)
        return cls(**data)

class JSONRegistry:
    _instance = None
    _executor = ThreadPoolExecutor(max_workers=5)

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super().__new__(cls)
        return cls._instance

    @staticmethod
    def register(id_: str, factory_func: Callable):
        JSONBase.register_factory(id_)()(factory_func)

    @staticmethod
    def get(id_: str) -> Type[JSONBase]:
        return JSONBase.get_subclass(JSONBase, id_)
```

This is a base class for JSON objects and the registry to store them. The subclasses are registered dynamically via decorator `@register_factory`, which ensures they're added to the factory registry. 

The method `discover_subclasses(directory)` scans a specified directory for Python files (assumed to contain classes) and imports them.

