```c
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <semaphore.h>
#include <pthread.h>
#define MAX_WORDS 1024
#define WORD_LEN 64

typedef struct {
    char *data;
    size_t len;
} dynamic_string;

dynamic_string *ds_init(char *str) {
    dynamic_string *s = malloc(sizeof(dynamic_string));
    if (s == NULL) {
        return NULL;
    }

    s->len = strlen(str);
    s->data = malloc((s->len + 1) * sizeof(char));
    if (s->data == NULL) {
        free(s);
        return NULL;
    }

    strncpy(s->data, str, s->len + 1);
    return s;
}

void ds_free(dynamic_string *s) {
    if (s == NULL) {
        return;
    }

    free(s->data);
    free(s);
}

char *ds_str(const dynamic_string *s) {
    char *ret = malloc((s->len + 1) * sizeof(char));
    if (ret == NULL) {
        return NULL;
    }

    strncpy(ret, s->data, s->len + 1);
    return ret;
}

int ds_append(dynamic_string *s, char *str) {
    size_t new_len = s->len + strlen(str);

    s->data = realloc(s->data, (new_len + 1) * sizeof(char));
    if (s->data == NULL) {
        return 0;
    }

    strncat(s->data, str, new_len - s->len);
    s->len = new_len;
    return 1;
}

dynamic_string *ds_capitalize(const dynamic_string *s) {
    char *str = ds_str(s);

    if (str == NULL) {
        return NULL;
    }

    str[0] = toupper((unsigned char) str[0]);

    for (size_t i = 1; i < s->len; ++i) {
        if (isspace(str[i]) && i + 1 < s->len) {
            str[i+1] = toupper((unsigned char) str[i+1]);
            ++i;
        } else if (!isspace(str[i])){
            str[i] = tolower((unsigned char) str[i]);
        }
    }

    dynamic_string *new_s = ds_init(str);
    free(str);
    return new_s;
}
```

