let semaphore = require('semaphore');
let superagent = require('superagent');
let cacheManager = require('cache-manager');

// Initialize caching manager and authentication token
let memCache = cacheManager.caching({ store: 'memory', max: 100, ttl: 60/*seconds*/ });
const AUTH_TOKEN = "YOUR_AUTH_TOKEN";

function asyncArrayReduce(arrNumbers, initialValue, callback) {
    let sem = semaphore(2); // limit to 2 concurrent operations
    return new Promise((resolve, reject) => {
        arrNumbers.reduce((accumulator, currentNumber, index) => {
            sem.take(() => {
                memCache.wrap(index, (err, cacheResult) => {
                    if (cacheResult !== undefined) {
                        accumulator += cacheResult; // Use cached result to optimize performance
                        callback && callback(accumulator, index + 1); // Report progress
                        sem.leave();
                    } else {
                        let api_call = superagent.post('http://example.com/api')
                            .set('auth-token', AUTH_TOKEN) // Secure API call with auth token
                            .send({ accumulator, currentNumber });
                        api_call.timeout(5000); // 5 second timeout for external API calls
                        api_call.end((err, res) => {
                            if (res.ok) {
                                memCache.set(index, res.body.result); // Cache the result
                                accumulator += res.body.result;
                                callback && callback(accumulator, index + 1); // Report progress
                            } else {
                                reject(err || new Error('Request failed'));
                            }
                            sem.leave();
                        });
                    }
                });
            });
        }, initialValue);
    });
}
