```python
from flask import Flask, request, jsonify
import sqlite3
import hashlib
import os
import logging
from functools import wraps

app = Flask(__name__)
logging.basicConfig(filename='record.log', level=logging.DEBUG)
DATABASE = 'database.db'

def connect_db():
    return sqlite3.connect(DATABASE)

@app.route('/update_resource/<id>', methods=['PUT'])
def update_resource(id):
    if request.method == "PUT":
        data = request.get_json()
        db = connect_db()
        try:
            db.execute("UPDATE resources SET data = ? WHERE id = ?", (data, id))
            db.commit()
            logging.info(f"Updated resource with ID {id}")
            return jsonify({'message': 'Resource updated successfully!'}), 200
        except sqlite3.Error as e:
            db.rollback()
            logging.error("Failed to update resource: {}".format(e))
            return jsonify({'message': 'An error occurred while updating the resource.'}), 500
        finally:
            db.close()
    else:
        return jsonify({'message': 'Invalid request method!'}), 405

@app.route('/calculate_hash', methods=['POST'])
def calculate_hash():
    if request.method == "POST":
        file = request.files['file']
        try:
            data = file.stream.read()
            hasher = hashlib.md5(data)
            return jsonify({'message': 'File hash calculated successfully', 'hash': hasher.hexdigest()}), 200
        except (IOError, OSError):
            logging.error("Failed to calculate file hash: {}".format(e))
            return jsonify({'message': 'An error occurred while calculating the file hash.'}), 500
    else:
        return jsonify({'message': 'Invalid request method!'}), 405

if __name__ == "__main__":
    app.run(debug=True)
```
This code creates two endpoints, one for updating a resource and another to calculate the hash of a file sent in the POST request. It also logs all the activity which can be helpful for debugging purposes. 

