public class XmlReducer
{
    private Dictionary<string, TaskCompletionSource<string>> _cache = new Dictionary<string, TaskCompletionSource<string>>();
    private SemaphoreSlim _semaphore = new SemaphoreSlim(5); // limit to 5 concurrent operations

    public async Task<ReducedValue> AsyncXmlReduce(IEnumerable<string> xmls, ReducedValue initialValue, Options options)
    {
        try
        {
            var tasks = new List<Task<string>>();

            foreach (var xml in xmls)
            {
                await _semaphore.WaitAsync().ConfigureAwait(false); // limit concurrent operations

                if (_cache.TryGetValue(xml, out var tcs))
                {
                    tasks.Add(tcs.Task);
                }
                else
                {
                    var task = ReduceXml(xml, options);
                    _cache[xml] = new TaskCompletionSource<string>();
                    tasks.Add(_cache[xml].Task);

                    // start reduction in background and release semaphore after completion
                    task.ContinueWith(t => _semaphore.Release()); 
                }
            }

            var results = await Task.WhenAll(tasks).ConfigureAwait(false);

            foreach (var result in results)
            {
                initialValue = options.Accumulator(initialValue, result); // accumulate results
            }

            _cache.Clear(); // clear cache after use to save memory

