// Mock function for fetching word list from external data source
char** fetchWordList(int *length, char* authToken) {
    // Fetch and return the word list. For the sake of this example, let's assume we have a static list. 
    static const char *words[] = {"the", "and", "in"};
    *length = 3;
    return (char**)words;
}

// Mock function for running command in background
int runInBackground(const char* cmd, int* status) {
    pid_t pid;

    if ((pid = fork()) < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // child process
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        exit(EXIT_FAILURE);
    } else { // parent process
        while (waitpid(pid, status, WNOHANG) == 0) {
            usleep(100000);  // sleep for a short period to prevent busy-waiting
        }
    }

    return 0;
}

// Trim function
char* dynamicTrimAndCapitalize(const char *input, int limit, const char* cmd, void (*callback)(int), char* authToken) {
    // Fetch word list
    int length;
    char** words = fetchWordList(&length, authToken);

    if (words == NULL) return NULL;

    int size = 0;  // size of the resulting string
    for (int i=0; i<length; i++) {
        size += strlen(words[i]);
    }
    int avgSize = length == 0 ? 0 : size / length;

    char* res = malloc(limit * sizeof(char));  // allocate memory for result string
    if (res == NULL) return NULL;

    strcpy(res, input);

    // Trim words and capitalize first letter
    int i = 0;
    while (*input != '\0') {
        char* next = strstr(input, words[i]);
        if (next == NULL) break;

        *next = toupper(*next);  // capitalize the first letter of a word

        callback(++i);  // report progress
    }

    // Run command in background
    int status = 0;
    runInBackground(cmd, &status);

    if (strlen(res) > limit) {
        free(res);
        return NULL;
    }

    return res;
}
