Here's a basic implementation of your requirement using AngularJS. Note that this example does not fully implement pagination or cache functionality as it is quite complex to accomplish these features with given information, you may need additional libraries like lodash or third-party APIs for those functionalities. Moreover, please adjust the URL and resource ID according to your needs. 

```javascript
app.factory('RefreshService', ['$http', '$q', function($http, $q) {

    var cache = {};

    return {
        refreshFields: function (fieldNames, url, resourceId) {
            return $q.all(_.map(fieldNames, function(fieldName){
                if(cache[fieldName] && Date.now() - cache[fieldName].timestamp < 300000 /* 5 mins */) { // data is recent
                    parent.postMessage({ field: fieldName, success: true }, '*');
                    return $q.when(cache[fieldName].data);
                } else {
                  var timestamp = Date.now();
                  return $http.get(url + resourceId + "/" + fieldName)
                      .then(function (response){ 
                        cache[fieldName] = {timestamp: timestamp, data: response.data};
                        parent.postMessage({ field: fieldName, success: true }, '*');
                        return response.data;
                      })
                      .catch(function(err) {
                        console.error("Failed to refresh field " + fieldName);
                        parent.postMessage({ field: fieldName, success: false }, '*');
                        if(cache[fieldName] && Date.now() - cache[fieldName].timestamp < 300000){ // data is recent
                          return $q.when(cache[fieldName].data);
                        } else {
                          return $q.reject("Failed to refresh field " + fieldName);
                        }
