Let's write a simple function that uses the AWS SDK to upload a file from URL to an Amazon S3 bucket:

```javascript
const AWS = require('aws-sdk');
const fs = require('fs');
const https = require('https');
const Promise = require('bluebird');
const Logger = require('logger').createLogger(); //assuming you have a logger library installed, if not replace it with console.log

//configure AWS credentials and region
AWS.config.update({
    accessKeyId: "your-access-key",
    secretAccessKey: "your-secret-key",
    region: "your-region"
});

const s3 = new AWS.S3(); //create S3 instance

async function uploadFile(url, bucketName, filePath) {
    return new Promise((resolve, reject) => {
        const file = fs.createWriteStream(filePath);

        https.get(url, (response) => {
            response.pipe(file);

            file.on('finish', () => {
                file.close(() => {
                    uploadToS3(bucketName, filePath).then(resolve).catch(reject);
                });
            });
        }).on('error', (err) => {
            fs.unlinkSync(filePath); // delete the created file
            reject(err.message);
        });
    });
}

async function uploadToS3(bucketName, filePath) {
    const params = { Bucket: bucketName, Key: '', Body: '' };

    fs.readFileSync(filePath), (error, filedata) => {
        if(error) return Logger.error(`Error reading the file ${filePath}: ${error.message}`);

        params.Body = filedata;
        params.Key = filePath; //use original name if you want to keep it 
    };

    return new Promise((resolve, reject) => {
        s3.upload(params, (err, data) => {
            if (err) return reject(`Error uploading the file ${filePath} to S3: ${err.message}`);

            fs.unlinkSync(filePath); // delete the local file once uploaded successfully

            resolve(data.Location); //return URL of the uploaded file
        });
    });
}
```
Please replace `"your-access-key"`, `"your-secret-key"` and `"your-region"` with your actual AWS credentials. You can also adjust the bucket name and file path according to your requirements.

This function firstly downloads a file from provided URL into local filesystem then uploads it to Amazon S3. After successful upload, it deletes both local copy and uploaded copy in S3. 

