struct rsa_context {
    RSA *private_key;
};

typedef struct rsa_context rsa_context;

// Initialize an RSA encryption/decryption context with a given private key file and password, using the OpenSSL library. 
rsa_context* init_encrypt_context(const char* private_key_file, const char* password) {
    FILE *fp = fopen(private_key_file, "r");
    if (fp == NULL) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    rsa_context *ctx = malloc(sizeof(*ctx));
    if (ctx == NULL) {
        fprintf(stderr, "Failed to allocate memory for RSA context\n");
        return NULL;
    }

    ctx->private_key = PEM_read_RSAPrivateKey(fp, NULL, password_callback, password); // Password callback is a function you'll need to implement.

    if (ctx->private_key == NULL) {
        ERR_print_errors_fp(stderr);
        free(ctx);
        return NULL;
    }

    fclose(fp);

    // Set padding scheme to PKCS1 OAEP. This is necessary for security, as it prevents attacks like Bleichenbacher's attack.
    RSA_set_padding_mode(ctx->private_key, RSA_PKCS1_OAEP_PADDING);

    return ctx;
}

// Function to clean up and disable the RSA context when it is no longer needed. 
void free_context(rsa_context *ctx) {
    if (ctx == NULL) {
        return;
    }

    RSA_free(ctx->private_key);
    free(ctx);
}

// Callback function to provide the password for decryption of private key. You'll need to implement this, as it depends on your particular key management system.
int password_callback(char *buf, int size, int rwflag, void *userdata) {
    // userdata is a pointer to the password string, provided when calling init_encrypt_context().
    const char* password = (const char*)userdata; 

    if ((int)strlen(password) < size) {
        strncpy(buf, password, size);
    } else {
        return 0;
    }

    return strlen(password);
}
