Here's the C code for `loadResourceBundle`:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define error codes
#define ERROR_FILE_NOT_FOUND 1
#define ERROR_INVALID_FORMAT 2
#define ERROR_MEMORY_ALLOCATION 3

typedef struct {
    char* key;
    void* value;
} ResourceItem;

int loadResourceBundle(const char* filepath, ResourceItem** bundle) {
    FILE *file = fopen(filepath, "r");
    if (file == NULL) {
        return ERROR_FILE_NOT_FOUND;
    }

    int size = 0;
    int capacity = 16;
    *bundle = malloc(capacity * sizeof(ResourceItem));
    if (*bundle == NULL) {
        fclose(file);
        return ERROR_MEMORY_ALLOCATION;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Check if bundle size exceeds capacity and reallocate memory
        if (size >= capacity) {
            capacity *= 2;
            ResourceItem* newBundle = realloc(*bundle, capacity * sizeof(ResourceItem));
            if (newBundle == NULL) {
                free(*bundle);
                fclose(file);
                return ERROR_MEMORY_ALLOCATION;
            }
            *bundle = newBundle;
        }

        // Parse key-value pair and add to bundle
        char* equalsSign = strchr(line, '=');
        if (equalsSign == NULL) {
            free(*bundle);
            fclose(file);
            return ERROR_INVALID_FORMAT;
        }

        // Store key without trailing newline character
        *equalsSign = '\0';
        (*bundle)[size].key = malloc(strlen(line) + 1);
        if ((*bundle)[size].key == NULL) {
            free(*bundle);
            fclose(file);
            return ERROR_MEMORY_ALLOCATION;
        }
        strcpy((*bundle)[size].key, line);

        // Parse and store value (assuming integers for simplicity)
        int value = atoi(equalsSign + 1);
        (*bundle)[size].value = malloc(sizeof(int));
        if ((*bundle)[size].value == NULL) {
            free(*bundle);
            fclose(file);
            return ERROR_MEMORY_ALLOCATION;
        }
        *((int*)((*bundle)[size].value)) = value;

        size++;
    }

    // Free excess memory allocated to bundle
    ResourceItem* newBundle = realloc(*bundle, size * sizeof(ResourceItem));
    if (newBundle != NULL) {
        *bundle = newBundle;
    }

    fclose(file);
    return size;
}
```
