public class RandomValueGenerator
{
    private float min;
    private float max;

    public RandomValueGenerator(float min, float max) 
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum");

        this.min = min;
        this.max = max;
    }

    public float GetRandomFloat() => UnityEngine.Random.Range(min, max);

    public int GetRandomInt() => (int)UnityEngine.Random.Range(min, max + 1);

    public List<int> GetNRandomIntegersWithoutDuplicates(int n) 
    {
        if ((max - min + 1) < n) throw new ArgumentException("Requested more unique values than available in range");

        var hashSet = new HashSet<int>();
        while (hashSet.Count != n) 
        {
            hashSet.Add(GetRandomInt());
        }

        return new List<int>(hashSet);
    }

    public override string ToString() => $"Range: [{min}, {max}]";
}
