void expandStateList(int **stateList, int *listSize, fsa_t *fsa, void *externalDataSource) {
    pthread_mutex_lock(&mutex);

    // Retrieve new states count from the external data source (e.g., a file or network request).
    int newStateCount = *(int*)externalDataSource; 

    // Validate and load new states from an external source, handle potential errors.
    void* loadedStates = loadStateFromExternal(fsa, newStateCount);
    if (loadedStates == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Allocate memory for the new state list.
    int *newList = malloc((*listSize + newStateCount) * sizeof(int));
    if (newList == NULL) {
        pthread_mutex_unlock(&mutex);
        return; 
    }

    // Copy the existing states to the new list.
    for (int i = 0; i < *listSize; ++i) {
        newList[i] = (*stateList)[i];
    }

    // Add the loaded states to the end of the new list.
    for (int j = 0; j < newStateCount; ++j) {
        newList[*listSize + j] = ((int*)loadedStates)[j];
    }

    // Update the FSA structure's last pointer and state transition table with loaded states.
    fsa->last->next = &newList[*listSize];
    for (int i = 0; i < newStateCount; ++i) {
        int fromState = ((int*)loadedStates)[i];
        // Update the FSA's state transition table with loaded states.
    }

    // Free up the memory used by old list and update the pointer to new list.
    free(*stateList);
    *listSize += newStateCount;
    *stateList = newList;

    pthread_mutex_unlock(&mutex);
}
