class DynamicNetworkResolver {
private:
    std::vector<std::string> dnsServers;
    int currentServerIndex = 0;
    std::time_t lastUpdateTime = 0;
    std::mutex mtx;
    CURL *curl = nullptr;

public:
    DynamicNetworkResolver() {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
    }

    ~DynamicNetworkResolver() {
        if (curl) curl_easy_cleanup(curl);
        curl_global_cleanup();
    }

    void updateDnsServersFromConfigService() {
        Json::Value jsonResponse;
        std::string readBuffer;

        // replace with your external config service URL
        curl_easy_setopt(curl, CURLOPT_URL, "http://your.config.service/dns-servers");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        // make the request and get the response
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << "\n";
            return;
        }

        // parse the response and update dnsServers vector
        Json::Reader reader;
        bool parsingSuccessful = reader.parse(readBuffer, jsonResponse);
        if (!parsingSuccessful) {
            std::cerr << "Failed to parse JSON configuration: " << reader.getFormattedErrorMessages() << "\n";
            return;
        }

        mtx.lock();
        dnsServers = jsonResponse.getMemberNames();
        currentServerIndex = 0;
        lastUpdateTime = std::time(nullptr);
        mtx.unlock();
    }

    static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
        ((std::string*)userp)->append((char*)contents, size * nmemb);
        return size * nmemb;
    }
};
