#include <pthread.h>
#include <sqlite3.h> // SQLite library, replace with your database API

typedef struct {
    int value; 
} Record;

typedef struct {
    size_t numRecords;
    long* offsets;
    int* keys;
    Record* records;
    sqlite3 *db;
    pthread_mutex_t lock; // mutex for thread-safe operations
} Database;

int initializeDatabase(Database* db) {
    char* errMsg = 0;
    const char* query = "SELECT COUNT(*) FROM table"; // replace 'table' with your actual table name

    if (sqlite3_open("database.db", &db->db)) { // replace 'database.db' with your database file path
        fprintf(stderr, "Unable to open database: %s\n", sqlite3_errmsg(db->db));
        return 1;
    }

    if (sqlite3_exec(db->db, query, NULL, 0, &errMsg) != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", errMsg);
        sqlite3_free(errMsg);
        return 1;
    }

    db->numRecords = sqlite3_column_int(sqlite3_get_table(db->db, query), 0);
    if (db->numRecords <= 0) {
        fprintf(stderr, "No records found\n");
        return 1;
    }

    db->offsets = calloc(db->numRecords, sizeof(long));
    if (!db->offsets) {
        perror("Failed to allocate memory for offsets");
        return 1;
    }

    db->keys = calloc(db->numRecords, sizeof(int));
    if (!db->keys) {
        perror("Failed to allocate memory for keys");
        free(db->offsets);
        return 1;
    }

    db->records = calloc(db->numRecords, sizeof(Record));
    if (!db->records) {
        perror("Failed to allocate memory for records");
        free(db->offsets);
        free(db->keys);
        return 1;
    }

    srand((unsigned int) time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < db->numRecords; ++i) {
        db->records[i].value = rand() % 10001; // Random value between 0 and 10000
    }

    pthread_mutex_init(&db->lock, NULL);

    return 0;
}
