use std::env;
use std::fs::{self, File, create_dir};
use std::path::PathBuf;
use std::time::SystemTime;
use std::io::Write;
use anyhow::Result;

fn main() -> Result<()> {
    let path = PathBuf::from("test");

    // check if directory exists, create if not
    match fs::metadata(&path) {
        Ok(_) => println_dir(),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            fs::create_dir(&path)?;
            println_dir();
        }
        Err(e) => return Err(anyhow::Error::new(e)),
    };

    // set environment variable
    env::set_var("MY_DIR", &path.display().to_string())?;

    // log to file
    let mut file = File::create("my_dirs.log")?;
    write_log(&mut file, "test directory created");

    Ok(())
}

fn println_dir() {
    if let Ok(path) = env::var("MY_DIR") {
        println_dir(path);
    } else {
        eprintln_no_env();
    }
}

fn write_log<W: Write>(writer: &mut W, message: &str) -> std::io::Result<()> {
    let now = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap();
    writeln(writer, "{} -- {}", now.as_secs(), message)?;
    Ok(())
}
