const fs = require('fs-extra');
const path = require('path');
const asyncPool = require('tiny-async-pool');

// Initialize cache
let fileCache = {};

/**
 * Read files in a directory asynchronously, filter by extension and concat into single string.
 * @param {string} dirPath - The path to the directory.
 * @param {string} ext - Extension of file to read (e.g., '.txt').
 * @param {number} bufferSize - Buffer size for reading files.
 */
async function readDirectoryFiles(dirPath, ext, bufferSize = 1024) {
    try {
        let dirContent = await fs.readdir(dirPath);
        let filteredFiles = dirContent.filter((fileName) => path.extname(fileName) === ext).map((fileName) => path.join(dirPath, fileName));

        // Read files in parallel with a limit of 10 concurrent operations (you may change this number according to your needs)
        const result = await asyncPool(10, filteredFiles, async (filePath) => {
            if (!fileCache[filePath]) { // If file not cached
                console.log('Reading file:', filePath);
                let content = await fs.readFile(filePath, { encoding: 'utf-8' }); 
                fileCache[filePath] = content; // Store in cache
            }
            return fileCache[filePath];
        });

        return result.join('');
    } catch (err) {
        console.error(`Error reading directory: ${dirPath}\n${err}`);
        return '';
    }
}
``` 
