// Rust part (in `dir_handler.rs`)
use std::env;
use std::fs::{self, DirEntry, FileType};
use std::path::PathBuf;

pub fn create_directory(name: &str) -> Option<String> {
    let env_var = env::var("DIR_PATH").unwrap();

    // Use existing directory if it is set in environment variables
    if env_var != "" {
        Some(env_var)
    } else {
        // Create a new directory with 755 permissions and get its path
        let dir = fs::create_dir(&format_path(name)).unwrap();
        let path_buf: PathBuf = dir.into();

        Some(format_path(&path_buf.display().to_string()))
    }
}

fn format_path(p: &str) -> String {
    p.trim_end_matches('/').to_owned()
}
