Here is a basic implementation of your requirements in C#. Please note that you would need to add more code to integrate with an external logging system and other features you mentioned like caching mechanism, thread safety etc. Also, this class will throw exceptions if XML document is not found or has syntax errors. You might want to adjust according to the specifics of your project:

```CSharp
using System;
using System.Collections.Generic;
using System.Xml;
using System.Linq;
using System.Threading;
using System.IO;

public class XmlParser
{
    private static ReaderWriterLockSlim cacheLock = new ReaderWriterLockSlim();
    private Dictionary<string, string> elementCache = new Dictionary<string, string>();
    private XmlDocument xmlDoc;

    public XmlParser(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("XML document not found");

        xmlDoc = new XmlDocument();
        try
        {
            xmlDoc.Load(filePath);
        }
        catch (XmlException ex)
        {
            // Log exception here
            throw;
        }
    }

    public string GetSingleElementValue(string xpathExpression)
    {
        cacheLock.EnterReadLock();
        try
        {
            if (elementCache.ContainsKey(xpathExpression))
                return elementCache[xpathExpression];
        }
        finally
        {
            cacheLock.ExitReadLock();
        }

        var nodes = xmlDoc.SelectNodes(xpathExpression);
        if (nodes == null || nodes.Count == 0)
            throw new FileNotFoundException("Element not found");
        else if (nodes.Count > 1)
            throw new MultipleElementException("Multiple elements found");

        string value = nodes[0].InnerText;

        cacheLock.EnterWriteLock();
        try
        {
            elementCache[xpathExpression] = value;
        }
        finally
        {
            cacheLock.ExitWriteLock();
        }

        return value;
    }

    public List<string> GetElementsValues(string xpathExpression)
    {
        var nodes = xmlDoc.SelectNodes(xpathExpression);
        if (nodes == null || nodes.Count == 0)
            return new List<string>();

        return nodes.Cast<XmlNode>().Select(node => node.InnerText).ToList();
    }
}
```

