#include <fstream>
#include <boost/archive/binary_iarchive.hpp>
#include <boost/serialization/map.hpp>
#include <stdexcept>

// Assume you have a class MyClass that you want to deserialize
class MyClass { 
    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive & ar, const unsigned int version) { /*...*/ }
};

MyClass* loadResourceFromFile(std::string filename) {
    std::ifstream file(filename, std::ios::binary);

    if (!file.is_open()) throw std::runtime_error("Cannot open the file.");

    boost::archive::binary_iarchive ia(file);
    MyClass* obj = new MyClass;

    try {
        ia >> *obj;
    } catch (boost::archive::archive_exception& ex) {
        delete obj;
        throw std::runtime_error("Error during deserialization: " + std::string(ex.what()));
    }

    return obj;
}
```
