static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T ***nfalist, int *crc_flag_rules) {
    assert(*nfalist == NULL); // Ensure the pointer is not pointing to an existing list
