    srand(time(NULL)); // Seed for random number generation

    *nfalist = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (*nfalist == NULL) {
        pthread_mutex_unlock(&mutex); 
        return -1; // Failed to allocate memory, return error code
    }

