        (*nfalist)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*nfalist)[i] == NULL) {
            // Failed to allocate memory for a structure, clean up and return error code
            while (--i >= 0) free((*nfalist)[i]); 
            free(*nfalist); *nfalist = NULL; 
            pthread_mutex_unlock(&mutex); 
            return -1;
        }

        // Populate the structure with unique RX_UE_INFORMATION_TAG and RNTI values.
        (*nfalist)[i]->RX_UE_INFORMATION_TAG = /* generate a unique tag */;
        (*nfalist)[i]->RNTI = /* generate a unique rnti */;

        // Set the CRCFLAG based on the corresponding rule in crc_flag_rules.
        (*nfalist)[i]->CRC_INDICATION_REL8_TAG->CRCFLAG = 
            (rand() % 2) ? crc_flag_rules[i] : !crc_flag_rules[i]; // Randomly set or clear CRC flag based on rule.

        log_structure_creation((*nfalist)[i]); // Log the creation of each structure.
    }

    pthread_mutex_unlock(&mutex); 
    return 0; // Successfully populated and logged structures, return success code.
}
