```javascript
function createSemaphore(maxConcurrent) {
    const semaphore = new Promise((resolve) => (semaphore.release = resolve));

    let counter = 0;

    return function () {
      if (++counter < maxConcurrent) {
        return Promise.resolve();
      } else {
        return semaphore.then(() => this());
      }
    };
}

function asyncArrayReduce(arr, initValue, callback, limit = 20, cache = {}, token="auth-token") {
    let throttleLimit = 5;  // Can be adjusted as per requirement
    let throttleCounter = 0;

    const semaphore = createSemaphore(limit);

    return new Promise((resolve, reject) => {
        let accumulator = initValue;

        for (let i = 0; i < arr.length; i++) {
            if (throttleCounter >= throttleLimit) {
