                          semaphore.release();
                      }
                    } catch (e) {
                        reject(e);
                    }
                });
              }, 1000);

              throttleCounter = 0; // Reset the throttle counter after each request.
            } else {
              semaphore().then(async () => {
                  try {
                      const res = cache[arr[i]] || await callback(accumulator, arr[i], token);

                      if (cache[arr[i]] === undefined) {
                          cache[arr[i]] = res;
                      }

                      accumulator = res;

                    // Report the progress.
                    console.log({completed: i+1, currentValue: accumulator});

                      if (i == arr.length - 1) {
                        resolve(accumulator);
                      } else {
                          semaphore.release();
                      }
                  } catch (e) {
                    reject(e);
                  }
              });
            }

            throttleCounter++; // Increase the throttle counter for each request.
        }
    });
}
