typedef struct {
    long value;
    time_t timestamp;
} record;

record* records = NULL;
long *offsets = NULL, *keys = NULL;
int offsetSize = 0, keySize = 0, recordSize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void handleError(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(1);
}

time_t getCurrentTimePlusRandomDelay(int delayRangeSeconds) {
    return time(NULL) + rand() % delayRangeSeconds;
}

void initializeArraysAndRecords(int offsetCount, int keyCount, int recordCount, int delayRangeSeconds) {
    if (offsetCount < 0 || keyCount < 0 || recordCount < 0) {
        handleError("Negative array sizes are not allowed");
    }

    pthread_mutex_lock(&mutex);

    offsetSize = offsetCount;
    keySize = keyCount;
    recordSize = recordCount;

    offsets = malloc(offsetSize * sizeof(*offsets));
    keys = malloc(keySize * sizeof(*keys));
    records = malloc(recordSize * sizeof(*records));

    if (!offsets || !keys || !records) {
        handleError("Memory allocation failed");
    }

    srand((unsigned int) time(NULL));

    for (int i = 0; i < offsetSize; ++i) {
        offsets[i] = rand();
    }

    for (int i = 0; i < keySize; ++i) {
        keys[i] = rand();
    }

    for (int i = 0; i < recordSize; ++i) {
        records[i].value = rand();
        records[i].timestamp = getCurrentTimePlusRandomDelay(delayRangeSeconds);
    }

    pthread_mutex_unlock(&mutex);
}
