Here's a simple implementation of your request using JavaScript's built-in Promise based `fetch` function for file loading and eval function for executing the code.

Please note that in real production environments, you would probably want to use more robust methods such as webpack or requireJS for managing dependencies and execution scripts, but this simplified version shows the principle of what you're asking for:

```javascript
class ScriptLoader {
  constructor() {
    this.scriptQueue = []; // Queue of scripts to be loaded & executed
    this.onLoadComplete = null;
    this.onError = null;
    this.isRunning = false;
  }

  addScript(src) {
    this.scriptQueue.push({ src, status: 'pending' }); // Add new script to queue
    if (!this.isRunning && typeof this.onLoadComplete === 'function') {
      this.start();
    }
  }

  removeScript(src) {
    const index = this.scriptQueue.findIndex(s => s.src === src);
    if (index !== -1) {
      this.scriptQueue.splice(index, 1); // Remove script from queue
    }
  }

  start() {
    this.isRunning = true;
    this._loadNextScript();
  }

  _onLoadComplete() {
    if (typeof this.onLoadComplete === 'function') {
      this.onLoadComplete();
    }
    setTimeout(() => { // Simulate async loading time
      console.log('Load completed');
      this._loadNextScript();
    }, 100);
  }

  _onError(err) {
    if (typeof this.onError === 'function') {
      this.onError(err);
    } else {
      console.error('Failed to load script', err); // Default error handling
      this._loadNextScript();
    }
  }

  _loadNextScript() {
    const nextScript = this.scriptQueue.find(s => s.status === 'pending');

    if (!nextScript) {
      this.isRunning = false;
      console.log('All scripts loaded & executed');
      return;
    }

    fetch(nextScript.src) // Fetch script content
    .then(response => response.text())
    .then(data => { 
      try {
        eval(data); // Execute the fetched data in current context
        nextScript.status = 'loaded';
        this._onLoadComplete();
      } catch (err) {
        this._onError(err);
      }
    })
    .catch(this._onError.bind(this)); // Failover: Load next script on fetch error 
  }
}
```
To use the above class, create an instance and add scripts to it like so:

