import org.apache.commons.exec.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class TestLoader {
    private static final int CACHE_SIZE = 1000; // Configurable maximum size
    private ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private String stateFilePath = "statefile.txt";
    private ExternalStateManagementService service = new ExternalStateManagementService();
    private PythonScriptRunner scriptRunner = new PythonScriptRunner();
    private Logger logger = new Logger(); // Not provided for simplicity, but can be implemented using log4j or similar libraries.

    public MoSTState dynamicTestLoader(String module) throws IOException {
        if (cache.containsKey(module)) return cache.get(module);

        try {
            logger.info("Loading state for " + module);

            // Check the external service first.
            MoSTState freshState = service.checkForUpdatedState(module);
            if (freshState != null) {
                cacheAndReturn(module, freshState);
            } else {
                ObjectInputStream ois = new ObjectInputStream(new FileInputStream(stateFilePath));
                Object readObject = ois.readObject();

                // Check the type of object is as expected.
                if (readObject instanceof MoSTState) {
                    cacheAndReturn(module, (MoSTState) readObject);
                } else {
                    logger.warn("Invalid state file for " + module);
                    return null;  // invalid state file or it's not a MoSTState object.
                }
            }
        } catch (Exception e) {
            logger.error("Failed to load state for " + module, e);
        } finally {
            blueslip.reset(); // Reset the mocking library after each test.
        }

        return null;
    }

    private MoSTState cacheAndReturn(String key, MoSTState value) {
        if (cache.size() >= CACHE_SIZE) {
            logger.info("Cache is full, removing oldest item.");

            // Implement a policy to remove the oldest or least-used items depending on your use case.
            // For simplicity we will just clear the cache.
            cache.clear();
        }

        cache.put(key, value);
        return value;
    }

    public class PythonScriptRunner {
        private CommandLine command = new CommandLine("python");
        private ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        private ExecuteWatchdog watchdog = new ExecuteWatchdog(60 * 1000); // Timeout after one minute.

        public void runScriptWithParams(Map<String, String> params) throws IOException {
            DefaultExecutor executor = new DefaultExecutor();
            executor.setWatchdog(watchdog);
            PumpStreamHandler streamHandler = new PumpStreamHandler(outputStream);

            for (Map.Entry<String, String> entry : params.entrySet()) {
                command.addArgument("-param");
                command.addArgument(entry.getKey());
                command.addArgument(entry.getValue());
            }

            int exitCode = executor.execute(command, streamHandler);
            if (exitCode != 0) {
                throw new RuntimeException("Script failed with exit code " + exitCode + ". Output: " + outputStream.toString());
            }
        }
    }
}
```
