```javascript
const fetch = require('node-fetch'); // For making API calls
let cache = {}; // Caching mechanism

// Function to get Pokemon data from an external API
async function fetchPokemonData(offset) {
  const response = await fetch(`https://pokeapi.co/api/v2/pokemon?limit=10&offset=${offset}`);
  if (!response.ok) throw new Error('Network response was not ok');
  return await response.json();
}

// Function to reduce an array of Pokemon objects and calculate their combined weaknesses
async function calculateWeakness(pokemons, callback) {
  let combinedWeakness = []; // Stores the total combined weaknesses of all pokemon

  for (let i = 0; i < pokemons.length; i++) {
    const name = pokemons[i].name;
    const level = parseInt(pokemons[i].level); // Parse the level to an integer

    let type = cache[name]; 
    if (!type) {
      type = await fetchPokemonData(0).then((data) => data.results[0].url); // Retrieve from API if not in cache
      cache[name] = type; // Cache the type for future use
    }

    let weaknesses;

    switch (type) { // Determine the weakness based on Pokemon's type
      case 'fire':
        weaknesses = ['water'];
        break;
      case 'water':
        weaknesses = ['grass', 'electric'];
        break;
      case 'grass':
        weaknesses = ['fire', 'ice', 'flying', 'bug'];
        break;
      default:
        weaknesses = []; // Default type has no weaknesses for simplicity
    }

    const currentWeakness = callback(name, level, weaknesses); 
    combinedWeakness.push(currentWeakness);
  }

  return combinedWeakness;
}
```
This script assumes a `callback` function that is passed into the `calculateWeakness()` function which can take `name`, `level`, and `weaknesses` as arguments. This callback function should handle how to calculate weakness based on pokemon's level and type. 

