<?php
class ClinicManager {
    // Connection objects for databases and APIs
    private $db;
    private $weatherApi;
    private $patientSchedulerApi;
    private $notificationService;

    public function __construct($database, $weatherApi, $patientSchedulerApi, $notificationService) {
        $this->db = $database;
        $this->weatherApi = $weatherApi;
        $this->patientSchedulerApi = $patientSchedulerApi;
        $this->notificationService = $notificationService;
    }

    public function manageClinicOperations($operation, $clinicData) {
        switch ($operation) {
            case 'create':
                // Validate clinic data and insert into database
                $this->db->insert('clinics', $clinicData);

                break;

            case 'update':
                $clinic = $this->db->select('SELECT * FROM clinics WHERE id = ?', [$clinicData['id']]);

                // Update clinic data in the database
                $this->db->update('clinics', $clinicData, ['id' => $clinicData['id']]);

                if ($clinicData['status'] == 'closed' || $clinicData['status'] == 'emergency') {
                    // Send alert to API and notify staff by email
                    $this->notificationService->sendAlert($clinic, 'Clinic closed due to extreme weather conditions');

                    // Update patient scheduling system 
                    $this->patientSchedulerApi->updateAvailability($clinic['id'], false);
                }

                break;

            case 'delete':
                $clinic = $this->db->select('SELECT * FROM clinics WHERE id = ?', [$clinicData['id']]);

                // Delete clinic from database
                $this->db->delete('clinics', ['id' => $clinicData['id']]);

                // Notify all booked patients with alternative clinic options
                $patients = $this->patientSchedulerApi->getBookings($clinic['id']);
                foreach ($patients as $patient) {
                    $alternatives = $this->db->select('SELECT * FROM clinics WHERE id != ? AND location = ?', [$clinicData['id'], $clinic['location']]);

                    // Send notification to patients with alternative clinic options
                    $this->notificationService->sendNotification($patient, 'Your booking has been cancelled. Here are some alternatives: ', $alternatives);
                }

                $this->patientSchedulerApi->deleteBookings($clinic['id']);

                break;
        }
    }
}
?>
