```rust
use std::env;
use std::fs;
use std::path::PathBuf;
use std::io;
use failure::Fail;

#[derive(Debug, Fail)]
pub enum LogDirectoryError {
    #[fail(display = "Failed to create directory: {}", _0)]
    CreateDirFailure(String),
    #[fail(display = "Failed to set environment variable: {}", _0)]
    SetEnvVarFailure(io::Error),
}

pub fn create_log_directory(log_dir_name: &str) -> Result<(), LogDirectoryError> {
    let mut dir_path = PathBuf::new();
    dir_path.push(env::current_dir()?);
    dir_path.push(log_dir_name);

    if fs::metadata(&*dir_path).is_err() {
        match fs::create_dir(&dir_path) {
            Err(e) => return Err(LogDirectoryError::CreateDirFailure(format_args![e.to_string(),])),
            _ => ()
        } 
    }

    let env_var = "LOG_DIR";
    match env::set_current_dir(&*dir_path) {
        Err(e) => return Err(LogDirectoryError::SetEnvVarFailure(e)),
        _ => env::set_var(env_var, &*dir_path.to_string_lossy())?
    }; 

    Ok(())
}
```

