    time_t lastAttackTime[3];
    const int cooldowns[] = { 3, 5, 7 };
    const int costs[] = { 10, 20, 30 };
    EnergyManagementAPI api;
public:
    Character() : energy(api.getEnergy()) {}

    void selectAttack() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 2); // Random attack number (0-2)

        int chosen = dis(gen);

        if ((time(nullptr) - lastAttackTime[chosen]) < cooldowns[chosen]) {
            std::cout << "The attack cannot be performed due to cooldown.\n";
            return;
        }
        if (energy < costs[chosen]) {
            std::cout << "Not enough energy to perform the attack.\n";
            return;
        }

        // Perform the chosen attack
        lastAttackTime[chosen] = time(nullptr);
        energy -= costs[chosen];
        api.updateEnergy(energy);

        std::cout << "Attack number: " << chosen + 1<< "\n";
    }
};
