        if ($this->validateEmailUniqueness($userData['email']) && 
            $this->matchPasswordAndConfirmPassword($userData['password'], $userData['confirm_password'])) {
            // Additional checks like password complexity can be added here.

            if ($this->db->insert('users', $userData)){
                return ['status' => 'success', 'message'=>'User account created successfully'];
            } else {
                return ['status' => 'error', 'message'=>'Failed to create user account due to database error'];
            }
        } else {
            return ['status' => 'error', 'message'=>'Invalid email or password'];
        }
    }

    public function updateUser($userId, $updatedData){
        if ($this->db->update('users', $updatedData, "id=$userId")){
            return ['status' => 'success', 'message'=>'User account updated successfully'];
        } else {
            return ['status' => 'error', 'message'=>'Failed to update user account due to database error'];
        }
    }

    public function deleteUser($userId){
        if ($this->db->delete('users', "id=$userId")){
            return ['status' => 'success', 'message'=>'User account deleted successfully'];
        } else {
            return ['status' => 'error', 'message'=>'Failed to delete user account due to database error'];
        }
    }

    private function validateEmailUniqueness($email){
        $user = $this->db->select('users', "email='$email'");
        return empty($user);
    }

    private function matchPasswordAndConfirmPassword($password, $confirm_password){
        return $password === $confirm_password;
    }
}
?>
