async function runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
    const module = require(moduleLabel);

    // Fetching Data
    const dataPromises = dataSources.map(source => axios.get(source));
    const dataResults = await Promise.all(dataPromises);

    _.forEach(testFunctions, (func, index) => {
        const testLabel = testLabels[index];
        const cleanupFunc = cleanupFunctions[index];

        try {
            console.time(`Test ${testLabel} took: `);

            // Running Test
            func(dataResults, module);

            console.log(`${testLabel}: Successful`);
        } catch (error) {
            console.log(`${testLabel}: Failed with error: ${error}`);
        } finally {
            console.timeEnd(`Test ${testLabel} took: `);

            // Cleanup Function
            cleanupFunc();

            // Reset blueslip
            blueslip.reset();
        }
    });

    // Report Summary
    const successCount = _.filter(testFunctions, func => {
        try {
            func();
            return true;
        } catch (e) {
            return false;
        }
    }).length;

    console.log(`Successful Tests: ${successCount} out of ${testFunctions.length}`);
}
