std::vector<std::string> getImageFiles(const std::string &directory) {
    std::vector<std::string> files;
    try {
        std::filesystem::recursive_directory_iterator iter(directory);
        for (auto& file : iter) {
            if (!file.is_regular_file()) continue; // Skip directories and other non-regular files

            std::string extension = file.path().extension();
            if (std::regex_match(extension, std::regex(".(jpeg|jpg|png|svg)", std::regex_constants::icase))) {
                files.push_back(file.path());
