typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;

void dynamicTestLoader() {
    logFile = fopen("log.txt", "w"); // open a log file

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(100000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        fprintf(logFile, "Memory allocation failure.\n");
        return; // handle memory failure
    }

    pthread_mutex_lock(&lock); // lock for thread safety

    /* Database interaction */
    int i;
    for (i = 0; i < 100000; i++) {
        list[i].CRCFLAG = getUniqueCrcFlag();
        if (list[i].CRCFLAG == -1) { // unique CRCFLAG generation failed
            fprintf(logFile, "Conflict in CRC flag generation.\n");
            pthread_mutex_unlock(&lock); 
            return;
        }
    }

    blueslip_reset(); // mocking library reset for testing

    /* Database storing */
    if (blueslip_store(list, 100000) != 0) {
        fprintf(logFile, "Failed to store in database.\n");
    } else {
        fprintf(logFile, "Successfully stored in database.\n");
    }

    pthread_mutex_unlock(&lock); // unlock for thread safety

    /* Database retrieval */
    NFAPI_CRC_INDICATION_PDU_T *retrievedList = malloc(100000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (blueslip_get(&retrievedList, 100000) != 0) {
        fprintf(logFile, "Failed to retrieve from database.\n");
    } else {
        fprintf(logFile, "Successfully retrieved from database.\n");
    }

    fclose(logFile); // close the log file
}
