For the first part of your request, let's start with the C function to verify OAuth2 access token response:

```c
#include <stdbool.h>
#include <json-c/json.h>

bool verify_access_token(const char *response) {
    json_object *jobj = json_tokener_parse(response);

    // Check if all required fields are present
    if(!json_object_object_get_ex(jobj, "access_token", &tmp)) return false;
    if(!json_object_object_get_ex(jobj, "expires_in", &tmp)) return false;
    if(!json_object_object_get_ex(jobj, "token_type", &tmp)) return false;

    // Check that token_type is 'Bearer' and expires_in is positive integer
    const char *token_type = json_object_get_string(json_object_object_get(jobj, "token_type"));
    if(strcmp(token_type, "Bearer") != 0) return false;

    int expires_in = json_object_get_int(json_object_object_get(jobj, "expires_in"));
    if(expires_in <= 0) return false;

    // Optional field
    json_object *refresh_token = NULL;
    json_object_object_get_ex(jobj, "refresh_token", &refresh_token);

    // No failed conditions above, so token is valid
    return true;
}
```

The Python function for updating an existing resource via HTTP PUT method and calculating MD5 hash of a file:

```python
import requests
import hashlib
from flask import Flask, request

app = Flask(__name__)

@app.route('/update_resource/<id>', methods=['PUT'])
def update_resource(id):
    url = f"http://api.example.com/resources/{id}"  # replace with your actual API endpoint
    headers = {'Content-Type': 'application/json'}  # replace with the actual content type of your request if needed

    response = requests.put(url, json=request.get_json(), headers=headers)

    return response.json()

def calculate_md5(file_path, block_size=8192):
    hasher = hashlib.md5()
    with open(file_path , 'rb') as f:
        for chunk in iter(lambda: f.read(block_size), b''):
            hasher.update(chunk)

    return hasher.hexdigest()
```

Please replace `"http://api.example.com/resources/{id}"` with your actual API endpoint and adjust headers if needed. Also, make sure that the server supports PUT method for updating resources.

