using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using System.Linq;

public class DynamicTextProcessor {
    private readonly ILogger logger;
    private readonly string userApi;

    public DynamicTextProcessor(ILogger<DynamicTextProcessor> logger, string userApi) {
        this.logger = logger;
        this.userApi = userApi;
    }

    // Synchronous methods:
    public string GenerateMD5Hash(string inputString) => ComputeHash(MD5.Create(), inputString);
    public string GenerateSHA1Hash(string inputString) => ComputeHash(SHA1.Create(), inputString);
    public string GenerateSHA256Hash(string inputString) => ComputeHash(SHA256.Create(), inputString);

    // Asynchronous methods:
    public Task<string> GenerateMD5HashAsync(string inputString) => ComputeHashAsync(MD5.Create(), inputString);
    public Task<string> GenerateSHA1HashAsync(string inputString) => ComputeHashAsync(SHA1.Create(), inputString);
    public Task<string> GenerateSHA256HashAsync(string inputString) => ComputeHashAsync(SHA256.Create(), inputString);

    private string ComputeHash(HashAlgorithm hashAlgorithm, string inputString) {
        var inputBytes = Encoding.UTF8.GetBytes(inputString);
        var sb = new StringBuilder();

        byte[] bytes = hashAlgorithm.ComputeHash(inputBytes);
        foreach (byte b in bytes) {
            sb.Append(b.ToString("X2"));
        }

        return sb.ToString();
    }

    private async Task<string> ComputeHashAsync(HashAlgorithm hashAlgorithm, string inputString) {
        var inputBytes = Encoding.UTF8.GetBytes(inputString);
        var sb = new StringBuilder();

        byte[] bytes;
        await Task.Run(() => {
            bytes = hashAlgorithm.ComputeHash(inputBytes);
        });
        foreach (byte b in bytes) {
            sb.Append(b.ToString("X2"));
        }

        return sb.ToString();
    }

    public async Task<string> ProcessUserInputAsync(string input, int maxLength, bool trimAndUppercase) {
        if (input == null || input.Length > maxLength) {
            throw new ArgumentException("Invalid input");
        }

        // Fetch user settings from API...

        string output = input;
        if (trimAndUppercase) {
            output = output.Trim().ToUpper();
        }

        // Handle any rate limits set by the external service...

        return await Task.FromResult(output);
    }
}
