#include <stdarg.h>
#include <stdio.h>
#include <time.h>

enum SeverityLevel {ERROR = 1, WARNING, INFO};

FILE* openLogFile(const char *logfilePath) {
    FILE *logFile = fopen(logfilePath, "a");
    if (logFile == NULL) {
        printf("Failed to open log file: %s\n", logfilePath);
    }

    return logFile;
}

void closeLogFile(FILE **logFile) {
    fclose(*logFile);
    *logFile = NULL;
}

int writeToLogFile(FILE *logFile, const char* formatStr, va_list args) {
    int charsPrinted = 0;

    if (logFile != NULL) {
        charsPrinted = vfprintf(logFile, formatStr, args);
        fflush(logFile);  // Ensure the message is written immediately.
    }

    return charsPrinted;
}

int logCondition(const char *condition, int severity, const char *format, ...) {
    static const char* LOG_FILE_PATH = "errorLog.log";  // Default path to the error log file.
    FILE *logFile = openLogFile(LOG_FILE_PATH);

    if (logFile != NULL && condition) {
        va_list args;
        va_start(args, format);

        const int MAX_MSG_LEN = 1024;  // Define a maximum message length.
        char msg[MAX_MSG_LEN];

        switch (severity) {
            case ERROR:   snprintf(msg, MAX_MSG_LEN, "ERROR: %s", format);   break;
            case WARNING: snprintf(msg, MAX_MSG_LEN, "WARNING: %s", format); break;
            default:      snprintf(msg, MAX_MSG_LEN, "INFO: %s", format);    break;
        }

        int charsPrinted = writeToLogFile(logFile, msg, args);
        va_end(args);

        closeLogFile(&logFile);  // Clean up.

        return charsPrinted > 0 ? 1 : -1;  // Return success or failure.
    }

    return 0;  // No need to log, return that no message was logged.
}
```
