```java
import com.google.common.cache.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.*;
import java.util.concurrent.TimeUnit;

public class StateCache {
    private static final Logger logger = LoggerFactory.getLogger(StateCache.class);

    // Configuration parameters
    private int maxSize = 10_000;
    private long duration = 3600;
    TimeUnit timeUnit = TimeUnit.SECONDS;

    LoadingCache<String, State> cache = CacheBuilder.newBuilder()
            .maximumSize(maxSize)
            .expireAfterWrite(duration, timeUnit)
            .removalListener((RemovalNotification notification) -> 
                logger.info("State removed due to {}", notification.getCause()))
            .build(new CacheLoader<String, State>() {
                @Override
                public State load(String key) throws Exception {
                    try (InputStream is = new FileInputStream(key)) {
                        return deserializeFromStream(is);
                    } catch (IOException e) {
                        logger.error("Error reading from file", e);
                        // Retry once from external service if failed to read from file
                        return loadStateFromService(); 
                    }
                }
            });

    public State get(String key) throws ExecutionException {
        try {
            return cache.get(key);
        } catch (RuntimeException e) { // Catch and rethrow exceptions thrown from the LoadingCache loader
            logger.error("Failed to retrieve state", e);
            throw e;
        } 
    }

    private State loadStateFromService() {
        try {
            // Implement actual service interaction
            return new State();
        } catch (Exception e) {
            logger.error("Error retrieving state from service", e);
            throw new RuntimeException(e);
        }
    }

    private State deserializeFromStream(InputStream is) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(is)) {
            return (State) ois.readObject();
        } 
    }
}
```
This code sets up a Guava LoadingCache with configurable maximum size and expiration time for cached states. The cache will automatically load state objects from the file or service when they are not in the cache, handling exceptions appropriately.

The deserializeFromStream method reads an object from an InputStream using Java serialization, which requires that the State class implements Serializable. It also handles any IOException that might occur during reading. This method is used to load states from files. 

When an error occurs while attempting to retrieve a state from a file, the cache will automatically attempt to retrieve it from the service instead. If both operations fail, a RuntimeException is thrown and caught by get(). This ensures that callers of the cache are notified when an error has occurred. 

Finally, the code logs information about every removal event (either due to size limit or time expiration), which can be useful for debugging purposes.

```java
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.kafka.common.serialization.StringSerializer;
import org.apache.kafka.streams.*;
import org.apache.kafka.streams.errors.InvalidStateStoreException;
import org.apache.kafka.streams.state.QueryableStoreTypes;
import org.apache.kafka.streams.state.ReadOnlyKeyValueStore;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.*;

public class MetricsProcessor {
    private static ObjectMapper mapper = new ObjectMapper();

    // Create a Kafka Streams configuration
    Properties props = new Properties();
    props.put(StreamsConfig.APPLICATION_ID_CONFIG, "metrics-processor");
    props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
    props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
    props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.String().getClass());

    // Create a StreamBuilder instance
    final StreamsBuilder builder = new StreamsBuilder();

    public MetricsProcessor() { }

    private void startKafkaStream(Set<String> metrics) {
        KStream<String, String> source = builder.stream("input-topic");

        // Transform the input stream into a table that contains only the desired metrics
        KTable<String, JsonNode> metricsTable = 
                source
                    .mapValues(MetricsProcessor::parseJson)
                    .filter((key, value) -> value != null && containsAllFields(value, metrics))
                    .toTable();

        // Write the table to a local state store for efficient querying
        metricsTable.toStream().to("intermediate-topic", Produced.with(Serdes.String(), new JsonNodeSerde()));
    }

    public static JsonNode parseJson(String json) {
        try {
            return mapper.readTree(json);
        } catch (IOException e) {
            // Handle malformed JSON here, possibly logging or throwing an exception
            throw new RuntimeException("Malformed JSON: " + json, e);
        }
    }

    public static boolean containsAllFields(JsonNode node, Set<String> metrics) {
        for (String metric : metrics) {
            if (!node.has(metric)) return false;
        }
        return true;
    }

    private ReadOnlyKeyValueStore<String, JsonNode> getMetricsStore() {
        try {
            // Access the store by using an appropriate state store name and QueryableStoreTypes.keyValueStore()
            return kafkaStreams.store("metrics-table", QueryableStoreTypes.keyValueStore());
        } catch (InvalidStateStoreException e) {
            // The store may not be ready yet
            throw new RuntimeException("Metrics Store is not available yet.", e);
        }
    }

    public Optional<JsonNode> getMetric(String metricId) {
        ReadOnlyKeyValueStore<String, JsonNode> store = getMetricsStore();
        return Optional.ofNullable(store.get(metricId));
    }
}
