use std::fs;
use serde_derive::Deserialize;
use reqwest;
use tokio;
use tokio::sync::Mutex;
use std::path::PathBuf;

#[tokio::main]
async fn main() {
    let config = ConfigManager::new(ConfigParams{ url: String::from("https://api.github.com"), token: "fake-token", repo_name: "myrepo" });
    tokio::spawn(config);
}

pub struct ConfigParams<'a> {
    pub url: &'a str,
    pub token: &'a str,
    pub repo_name: &'a str,
}

struct ConfigManager {
    client: reqwest::Client,
    config: ConfigParams,
}

#[derive(Deserialize)]
pub struct RepoInfo {
    clone_url: String,
}

impl ConfigManager {
    fn new(config: ConfigParams) -> Self {
        let client = reqwest::Client::new();

        ConfigManager {client, config}
    }

    async fn get_repo(&self, repo_name: &str) -> Result<RepoInfo, Box<dyn std::error::Error>> {
        let resp = self.client.get(format !("{}/repos/{}", self.config.url, repo_name)).bearer_auth(self.config.token).send().await?;
        let repo_info: RepoInfo = resp.json().await?;
        Ok(repo_info)
    }

    async fn clone_repo(&self, url: &str, dir: PathBuf) -> Result<(), Box<dyn std::error::Error>> {
        tokio::spawn(async move {
            let output = tokio::process::Command::new("git")
                .arg("clone")
                .arg(&url)
                .arg(&dir.display().to_string())
                .output()
                .await?;

            if !output.status.success() {
                return Err(format !("process failed with error code: {}", output.status).into());
            }
        });
    Ok(())
    }

    async fn init_local(&self) -> Result<PathBuf, Box<dyn std::error::Error>> {
        let dir = PathBuf::from("myrepo");
        fs::create_dir_all(&dir)?;
        Ok(dir)
    }
}
```
