Here's the C++ implementation of inserting string argument in forward list:

```cpp
#include <iostream>
#include <forward_list>
#include <string>
using namespace std;

void insertString(forward_list<string>& flist, const string& firstStr, const string& secondStr) {
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == firstStr) {
            flist.insert_after(it, secondStr);
            return;
        }
        prev = it;
    }

    // If the first string is not found, insert the second at the end of the list
    flist.insert_after(prev, secondStr);
}
```
