Here is a rough example for the expandStateList function with some pseudo-code to give an idea about how it could be structured. This solution does not include all requirements as described but provides a basic framework on which you could build a more complex and robust implementation.

```c
#include <pthread.h> // for threads and mutexes
#include <stdio.h>   // for printf/fopen
#include <stdlib.h>  // for malloc/free

typedef struct { 
    int *state_list;         // current state list
    int num_states;          // number of states in the current list
    FSA fsa;                 // finite state automaton
    void *data_source;       // pointer to external data source
    int last_state;          // integer representing the last state in the current list.
} StateListExpansionParams; 

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* expandStateList(void *params) {
    StateListExpansionParams *expParams = (StateListExpansionParams*) params;

    pthread_mutex_lock(&mutex);   // lock for thread-safe access to shared data

    // 1. Validate new states against the existing FSA structure and current state list
    if (!validateStates(expParams)) {
        printf("State validation failed\n");
        pthread_exit(NULL);      // unlock mutex and exit thread
    }

    // 2. Load new states from external data source (file or network)
    int *new_states = loadNewStates(expParams->data_source);
    if (!new_states) {
        printf("Failed to load new states\n");
        pthread_exit(NULL);      // unlock mutex and exit thread
    }

    // 3. Add new states to the current state list
    expParams->state_list = (int*) realloc(expParams->state_list, sizeof(int) * (expParams->num_states + sizeNewStates));
    for (int i = 0; i < sizeNewStates; ++i) {
        expParams->state_list[expParams->num_states++] = new_states[i];
    }

    // 4. Update last state in the current list
    if (sizeNewStates > 0) {
        expParams->last_state = new_states[sizeNewStates - 1];
    }

    free(new_states);           // cleanup memory

    pthread_mutex_unlock(&mutex); // unlock mutex before exiting thread
    pthread_exit(NULL);
}
```
