This task requires several advanced JavaScript concepts such as dynamically loading modules, managing external APIs, creating and managing semaphores, implementing robust error handling and logging mechanisms, designing a testing framework. Below is a simple outline of how you can start this project:

```javascript
// FileLoader.js - Dynamically load files
class FileLoader {
  constructor() {
    this.files = [];
  }

  async loadFile(url) {
    try {
      const module = await import(url);
      console.log(`Loaded ${url}`);
      this.files.push({ url, module });
      return module;
    } catch (error) {
      console.error(`Failed to load file: ${url}, Reason: ${error}`);
      throw error;
    }
  }

  async reloadFile(url) {
    const index = this.files.findIndex(file => file.url === url);
    if (index !== -1) {
      await this.unloadFile(url);
    }
    return this.loadFile(url);
  }

  unloadFile(url) {
    const index = this.files.findIndex(file => file.url === url);
    if (index !== -1) {
      delete this.files[index].module; // Unset module to let it be garbage collected
      this.files.splice(index, 1);
      console.log(`Unloaded ${url}`);
    } else {
      console.error(`Failed to unload file: ${url}, File not found`);
    }
  }

  // Other methods for managing dependencies and prioritizing files...
}
```
The semaphore implementation would look something like this:

```javascript
// Semaphore.js - Create, delete, acquire and release a named semaphore
class Semaphore {
  constructor(value) {
    // Using Atomics API to ensure thread safety
    this._semaphore = new Int32Array(new SharedArrayBuffer(4));
    Atomics.store(this._semaphore, 0, value);
  }

  acquire() {
    let value;
    // Using compare and swap to ensure atomicity of the operation
    while ((value = Atomics.load(this._semaphore, 0)) > 0) {
      const newValue = Atomics.compareExchange(this._semaphore, 0, value, value - 1);
      if (newValue === value) break; // If the CAS operation succeeded, we've acquired the semaphore
    }
  }

  release() {
    Atomics.add(this._semaphore, 0, 1);
  }

  delete() {
    if (Atomics.load(this._semaphore, 0) > 0) {
      throw new Error("Cannot delete semaphore while it is in use");
    } else {
      Atomics.store(this._semaphore, 0, -1); // Mark the semaphore as deleted
    }
  }
}
```
