    char* client_secret;
    int ageOfTransaction;
    int numTransactionsLast3Seconds;
    double weightedSum;
};

struct FilteredTransactionResult {
    double maxWeightedSum;
    char* transactionId;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
char* accessToken;

CURLcode curl_authenticate(struct TransactionRequest* request) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        char postData[1024];
        sprintf(postData, "client_id=%s&client_secret=%s", request->client_id, request->client_secret);

        curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/oauth2/token");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postData);

        res = curl_easy_perform(curl);
    }

    return res;
}

void* authenticateTransactions(void* arg) {
    struct TransactionRequest* request = (struct TransactionRequest*)arg;
    CURLcode res;
    int retries = 0;

    while ((res = curl_authenticate(request)) != CURLE_OK && retries < 5) {
        retries++;
    }

    if (res == CURLE_OK) {
        pthread_mutex_lock(&lock);
        // Store access token in a global variable for session management.
        accessToken = "placeholder";
        pthread_mutex_unlock(&lock);
    } else {
        printf("Authentication failed after %d retries.\n", retries);
    }

    return NULL;
}

struct FilteredTransactionResult* filterAndAuthenticateTransactions(struct TransactionRequest* request) {
    pthread_t threadId;
    struct FilteredTransactionResult* result = malloc(sizeof(struct FilteredTransactionResult));

    // Authentication process in a separate thread.
    if (pthread_create(&threadId, NULL, &authenticateTransactions, request) != 0) {
        printf("Failed to create authentication thread.\n");
        return NULL;
    }

    pthread_join(threadId, NULL);

    // Fetch transactions and filter based on the criteria.
    /* Implementation of transaction fetching and filtering */

    result->transactionId = "exampleTransactionID";
    result->maxWeightedSum = 100;

    return result;
}
