Here is a code implementation that fulfills all mentioned requirements using a dictionary to dynamically add new hash algorithms and `async/await` pattern for asynchronous operations:

```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Timers;

public class DynamicTextProcessor
{
    private ConcurrentDictionary<string, HashAlgorithm> hashProviders = new ConcurrentDictionary<string, HashAlgorithm>();
    private TimeSpan rateLimit = TimeSpan.FromSeconds(1);  // default rate limit of 1 second
    private DateTime lastOperationTime = DateTime.MinValue;

    public DynamicTextProcessor()
    {
        hashProviders.TryAdd("MD5", MD5.Create());
        hashProviders.TryAdd("SHA1", SHA1.Create());
        hashProviders.TryAdd("SHA256", SHA256.Create());
    }

    public void AddHashAlgorithm(string name, HashAlgorithm provider)
    {
        if (!hashProviders.TryAdd(name, provider))
            throw new ArgumentException("An item with the same key has already been added.");
    }

    // asynchronous operation for large inputs
    public async Task<string> ComputeHashAsync(string algorithmName, string input)
    {
        if (input.Length > 1GB) 
            throw new ArgumentException("Input size is too large.", nameof(input));

        await WaitForRateLimit();

        HashAlgorithm hashProvider = null;
        if (!hashProviders.TryGetValue(algorithmName, out hashProvider))
            throw new InvalidOperationException($"No hash provider named {algorithmName}");

        lastOperationTime = DateTime.UtcNow;

        var inputBytes = Encoding.UTF8.GetBytes(input);
        byte[] result = await Task<byte[]>.Factory.FromAsync(hashProvider.BeginComputeHash, hashProvider.EndComputeHash, inputBytes, null);

        return BitConverter.ToString(result).Replace("-", "");  // return in hexadecimal format
    }

    private async Task WaitForRateLimit()
    {
        var elapsed = DateTime.UtcNow - lastOperationTime;
        if (elapsed < rateLimit)
            await Task.Delay(rateLimit - elapsed);
    }
}
```
