```javascript
const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const rateLimit = require("express-rate-limit");
const redis   = require("redis");
const session = require('express-session');
let RedisStore = require('connect-redis')(session);
let client  = redis.createClient();
const app = express();

app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: false }));

// configure session middleware
app.use(session({
    store: new RedisStore({ client: client }), 
    secret: 'keyboard cat', 
    resave: false, 
    saveUninitialized: true
}));

// apply rate limiting middleware to all requests
const limiter = rateLimit({
    windowMs: 1 * 60 * 1000, // 1 minute
    max: 500, // limit each IP to 500 requests per windowMs
});
app.use(limiter);

// connect to mongodb
mongoose.connect('mongodb://localhost/test', { useNewUrlParser: true });
let db = mongoose.connection;
db.on('error', console.error.bind(console, 'MongoDB connection error:'));

// define schema and model
let ProductSchema = new mongoose.Schema({
    _id: String, 
    name: String, 
    price: Number,
    stockLevel: Number, 
    revenue: Number, 
});
let ProductModel = mongoose.model('Product', ProductSchema );

// update product inventory
app.post('/product/:id/inventory', async (req, res) => {
    try{
        let newStockLevel = req.body.stockLevel;
        let userName = req.session.user || 'Anonymous'; // assume user is already authenticated and stored in session

        let product = await ProductModel.findById(req.params.id);
        if(!product) {
            res.status(404).json({ status: 'error', message: `Product with id ${req.params.id} not found`, data: null });
            return;
        }

        product.stockLevel = newStockLevel;
        let savedProduct = await product.save();

        res.json({ 
            status: 'success', 
            message: 'Inventory updated successfully',
            data: { 
                product_id: req.params.id,
                stock_level: newStockLevel,
                revenue: savedProduct.revenue,
                last_updated_by: userName,
            }
        });
    } catch(error) {
        res.status(500).json({ status: 'error', message: `Failed to update inventory due to ${error}`, data: null });
    }
});

// handle 404 - keep this as a last route
app.use((req, res) => {
    res.status(404).json({ status: 'error', message: `Resource not found`, data: null });
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server running on ${port}, http://localhost:${port}`));
```
