```cpp
#include <chrono>
#include <mutex>
#include <iostream>

class Character {
public:
    int health;
    int energy;
    float distanceToEnemy;
};

// A global mutex used to ensure thread safety when choosing attacks.
std::mutex mtx;

void chooseAttack(Character& character) {
    // Lock the mutex before choosing an attack to prevent race conditions.
    const std::lock_guard<std::mutex> lock(mtx);

    auto now = std::chrono::steady_clock::now();

    if (character.health > 70 && character.energy >= 15 && character.distanceToEnemy <= 2) {
        // Attack 1 has a cooldown of 5 seconds, so it can be used if 5 seconds have passed since the last attack.
        static auto lastAttack = now - std::chrono::seconds(5);
        if (now - lastAttack >= std::chrono::seconds(5)) {
            std::cout << "Chose Attack 1" << std::endl;
            // Reset the cooldown timer.
            lastAttack = now;
        } else {
            auto remainingTime = std::chrono::duration_cast<std::chrono::seconds>(lastAttack + std::chrono::seconds(5) - now).count();
            std::cout << "Cannot use attack. Cooldown period not over. Remaining cooldown: " << remainingTime << " seconds" << std::endl;
        }
    } else if (character.health > 30 && character.energy >= 10) {
        // Attack 2 has a cooldown of 7 seconds, so it can be used if 7 seconds have passed since the last attack.
        static auto lastAttack = now - std::chrono::seconds(7);
        if (now - lastAttack >= std::chrono::seconds(7)) {
            std::cout << "Chose Attack 2" << std::endl;
            // Reset the cooldown timer.
            lastAttack = now;
        } else {
            auto remainingTime = std::chrono::duration_cast<std::chrono::seconds>(lastAttack + std::chrono::seconds(7) - now).count();
            std::cout << "Cannot use attack. Cooldown period not over. Remaining cooldown: " << remainingTime << " seconds" << std::endl;
        }
    } else if (character.energy >= 20 && character.distanceToEnemy <= 5) {
        // Attack 3 has a cooldown of 10 seconds, so it can be used if 10 seconds have passed since the last attack.
        static auto lastAttack = now - std::chrono::seconds(10);
        if (now - lastAttack >= std::chrono::seconds(10)) {
            std::cout << "Chose Attack 3" << std::endl;
            // Reset the cooldown timer.
            lastAttack = now;
        } else {
            auto remainingTime = std::chrono::duration_cast<std::chrono::seconds>(lastAttack + std::chrono::seconds(10) - now).count();
            std::cout << "Cannot use attack. Cooldown period not over. Remaining cooldown: " << remainingTime << " seconds" << std::endl;
        }
    } else {
        // If no attacks can be used, perform a default action (e.g., walk forward).
        std::cout << "Performed default action" << std::endl;
    }
}
```
This function checks the state of the character and chooses an attack based on these criteria. It uses `std::chrono` to measure time intervals, which can be used for cooldown purposes. The lock_guard is used to ensure thread safety in a multi-threaded context.

Here's a basic implementation in C that meets your requirements. This is a simplified version, assuming some functions (`create_semaphore`, `acquire_semaphore`, `release_semaphore`) are available from an external library or toolkit and are working correctly. This code does not include the asynchronous aggregation callback function since its implementation would depend on your specific use case.

```C
#include <stdlib.h>
#include <unistd.h> // For sleep
#include <string.h> // For strcpy

// Assuming this external API is implemented
void acquire_semaphore();
void release_semaphore();
void async_await(int, void (*callback)(void*), int);

typedef struct {
    char key[256];  // Assuming keys are string identifiers of max length 255
    void *value;
} Source;

typedef struct {
    int count;
    Source **sources;
} Sources;

int aggregate_data(Sources sources, char* initial_dict,
                   void (*aggregation_callback)(Source*, char*), 
                   int retry_count, int delay) {

    acquire_semaphore(); // Acquire semaphore

    for (int i = 0; i < sources.count; ++i) {
        Source *source = sources.sources[i];

        async_await(retry_count, aggregation_callback, source);

        if(retry_count > 0){
            sleep(delay); // delay before next retry
        }
    }

    release_semaphore(); // Release semaphore

    return 0;
}
```
In the example above, `async_await` function is responsible for asynchronous waiting and calling aggregation callback on each source. The semaphore mechanism ensures that only one task can access critical sections of code at a time to avoid race conditions or inconsistencies. However, this version doesn't handle potential errors from the third-party tool. You would need to add error handling based on your specific use case and design.
