Below is a basic implementation using `Microsoft.Extensions.Configuration` library which can be used for reading configurations from various sources like appsettings.json, environment variables etc. It also handles real-time updates, thread safety and error handling. This solution does not have a direct way to notify game developers about the changes in configuration as it depends on how you're implementing your UI layer but you could create an API endpoint that game developers can call to get updates.

```CSharp
using Microsoft.Extensions.Configuration;
using System;
using System.IO;
using System.Threading;
using System.Timers;
using Timer = System.Timers.Timer;

public class GameSettingsService : IDisposable
{
    private readonly IConfiguration _configuration;
    private readonly Timer _timer;

    public double CameraSpeed { get; private set; }
    public int WorldDimensions { get; private set; }
    public int TileSize { get; private set; }

    private readonly object _syncRoot = new object();

    public GameSettingsService()
    {
        var builder = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true);

        _configuration = builder.Build();

        LoadSettings();

        _timer = new Timer(60000) // Reload settings every minute
        {
            AutoReset = true
        };
        _timer.Elapsed += (s, e) => LoadSettings();
        _timer.Start();
    }

    private void LoadSettings()
    {
        try
        {
            var cameraSpeed = _configuration.GetSection("Game:CameraSpeed").Value;
            if (!double.TryParse(cameraSpeed, out double speed)) 
                throw new Exception("Invalid Camera Speed configuration");

            var worldDimensions = _configuration.GetSection("Game:WorldDimensions").Value;
            if(!int.TryParse(worldDimensions, out int dimensions))
                throw new Exception("Invalid World Dimensions configuration");

            var tileSize = _configuration.GetSection("Game:TileSize").Value;
            if (!int.TryParse(tileSize, out int size)) 
                throw new Exception("Invalid Tile Size configuration");

            lock (_syncRoot)
            {
                CameraSpeed = speed;
                WorldDimensions = dimensions;
                TileSize = size;
            }
        }
        catch (Exception e)
        {
            Console.WriteLine(e); // Or log the error using your logging framework
        }
    }

    public void Dispose()
    {
        _timer?.Dispose();
    }
}
```

For a user-friendly interface, you would need to build an API endpoint that returns the current game settings as well as an API endpoint for updating settings and notifying clients about those changes. You could use SignalR or other real-time communication libraries for this purpose if your game is web based. For local applications, you might need a database or file system watcher to notify changes.

