const Queue = require('promise-queue'); // Assuming we're using a Promise queue library.
let queue;
let concurrencyLimit = 5; // Default semaphore value.

// A simple LRU Cache implementation for caching API results.
const cache = new Map();
const cacheSize = 100;

function setAuthToken() {
    return process.env.AUTH_TOKEN || keyManager.getKey('auth-token'); // Placeholder for fetching Auth Token
}

// An example of a throttled external API call function with caching support.
const externalPromiseFunc = async (input) => {
    if(cache.has(input)) return cache.get(input);

    const result = await fetch('http://external-api-url', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${setAuthToken()}`,
        },
        body: JSON.stringify({ input }),
    });

    if (cache.size === cacheSize) { // Remove the oldest item from cache
      const key = cache.keys().next().value;
      cache.delete(key);
    }
    cache.set(input, result);

    return result;
};

const asyncArrayReduce = async (array, initialValue, callback, accumulator, onProgress) => {
  const authToken = setAuthToken(); // Fetching token before processing the array reduces overheads.
  if(!authToken) throw new Error('Authentication failed');

  let result = initialValue;
  queue = new Queue(concurrencyLimit);

  for (let i = 0, n = array.length; i < n; ++i) {
    await queue.add(async () => { // Enqueues each task into the queue in order to respect concurrency limits.
      try {
        if (!accumulator) {
          result = await callback(result, array[i]);
        } else {
          result = await accumulator(result, array[i], externalPromiseFunc);
        }

        if (typeof onProgress === 'function') { // Report progress.
            await onProgress({ completed: i + 1, currentValue: result }); 
        }
      } catch (error) {
        console.log('Error while processing the array', error);
      }
    });
  }

  return new Promise((resolve, reject) => {
    queue.start().then(resolve).catch(reject); // Resolves once all tasks have been executed.
  });
};
```
