This solution will be constructed using Java NIO Channels which provides efficient support for non-blocking I/O operations.

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.Iterator;
import java.util.Set;

public class LoadBalancer {
    private Selector selector;
    private Server[] servers;
    private Iterator<SelectionKey> keyIter;

    public LoadBalancer(int port, int poolSize) throws IOException {
        this.selector = Selector.open();
        this.servers = new Server[poolSize];

        // Initializing the load balancing server pool
        for (int i = 0; i < servers.length; i++) {
            servers[i] = new Server(port + i);
            servers[i].registerChannel(selector);
        }
    }

    public void start() throws IOException {
        while (!Thread.interrupted()) {
            selector.select();
            Set<SelectionKey> keys = selector.selectedKeys();
            keyIter = keys.iterator();

            // Looping through each ready channel for I/O operations
            while (keyIter.hasNext()){
                SelectionKey key = keyIter.next();

                if(key.isAcceptable()) {
                    Server currentServer = (Server) key.attachment();
                    SocketChannel client = ((ServerSocketChannel) key.channel()).accept();

                    // Applying load balancing strategy
                    int index = (int)(System.currentTimeMillis() % servers.length);

                    if(!servers[index].equals(currentServer)) {
                        servers[index].registerClient(client);
                        keyIter.remove();
                    } 
                } else if(key.isReadable()) {
                    ((SocketChannel) key.channel()).read(buffer);
                    // Processing data...
                }

                keyIter.remove();
            }
        }
    }
}

public class Server {
    private ServerSocketChannel server;

    public Server(int port) throws IOException{
        this.server = ServerSocketChannel.open();
        this.server.configureBlocking(false);
        this.server.socket().bind(new InetSocketAddress(port));
    }

    public void registerClient(SocketChannel client) throws IOException {
        client.configureBlocking(false);
        client.register(selector, SelectionKey.OP_READ, this);
    }

    public void registerChannel(Selector selector) throws ClosedChannelException{
        server.register(selector, SelectionKey.OP_ACCEPT, this);
    }
}
```

