const axios = require('axios');
const jwt = require('jwt-simple');
const rateLimit = require("express-rate-limit");
let limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

class PaymentGateway {
    constructor(clientId, clientSecret) {
        this.accessToken = null;
        this.baseURL = 'https://api.paymentgateway.com';
        this.authData = {
            grant_type: 'client_credentials',
            client_id: clientId,
            client_secret: clientSecret,
        };
    }

    async authenticate() {
        try {
            const response = await axios.post(`${this.baseURL}/oauth/token`, this.authData);
            this.accessToken = jwt.decode(response.data.access_token, process.env.JWT_SECRET);
        } catch (error) {
            console.log('Authentication error', error);
        }
    }

    async verifyTransaction(transactionId) {
        if (!this.accessToken) await this.authenticate();
        try {
            const config = {
                headers: { Authorization: `Bearer ${this.accessToken}` }
            };
            return axios.get(`${this.baseURL}/transactions/${transactionId}`, config);
        } catch (error) {
            console.log('Transaction verification error', error);
        }
    }

    applyMiddleware() {
        const express = require('express');
        const app = express();
        app.use(limiter);

        // Your routes here

        return app;
    }
}
