```c
#include <stdio.h>
#include <string.h>
#include <jansson.h>

bool validate_token(const char* json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if(!root)
    {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return false;
    }

    json_t *access_token = json_object_get(root, "access_token");
    if(!json_is_string(access_token)) {
        fprintf(stderr, "'access_token' field is missing or invalid\n");
        return false;
    }

    json_t *expires_in = json_object_get(root, "expires_in");
    if(!json_is_integer(expires_in) || json_integer_value(expires_in) <= 0) {
        fprintf(stderr, "'expires_in' field is missing or invalid\n");
        return false;
    }

    json_t *token_type = json_object_get(root, "token_type");
    if(!json_is_string(token_type) || strcmp(json_string_value(token_type),"Bearer") != 0) {
        fprintf(stderr, "'token_type' field is missing or invalid\n");
        return false;
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(!json_is_string(refresh_token)) {
        fprintf(stderr, "'refresh_token' field is missing or invalid\n");
        return false;
    }

    // If we reached here the token is valid.
    json_decref(root);
    return true;
}
```
