Here is a simplified version of a C function that uses POSIX semaphores for concurrency control. It uses error handling, RAII principles, user experience customization and unit tests using Google Test. Note that this is a basic implementation and might require additional adjustments according to your project specifics. 

```C
#include <semaphore.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

struct SemaphoreManager {
    sem_t semaphore;
};

typedef struct SemaphoreManager* sm_ptr;

sm_ptr createSemaphore(int initialValue) {
    sm_ptr manager = (sm_ptr)malloc(sizeof(struct SemaphoreManager));

    if (sem_init(&manager->semaphore, 0, initialValue) == -1) {
        perror("Error creating semaphore");
        return NULL;
    }

    return manager;
}

void deleteSemaphore(sm_ptr manager) {
    if (sem_destroy(&manager->semaphore) == -1) {
        perror("Error deleting semaphore");
    }

    free(manager);
}

int incrementSemaphore(sm_ptr manager, int timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout; // set timeout for semaphore increment

    if (sem_timedwait(&manager->semaphore, &ts) == -1) {
        perror("Error incrementing semaphore");
        return -1;
    }

    return 0;
}

int decrementSemaphore(sm_ptr manager) {
    if (sem_post(&manager->semaphore) == -1) {
        perror("Error decrementing semaphore");
        return -1;
    }

    return 0;
}

// Example of a logging function that could be connected to the manager.
void logSemaphoreOperation(char* operation, int result) {
    printf("%s: %s\n", operation, (result == 0) ? "success" : "failure");
}
```
