public class SecureDataProcessor
{
    private readonly ILog _log = LogManager.GetLogger();
    private const int BufferSize = 4096; // Use 4KB buffer for memory efficiency when dealing with large files

    public async Task<string> GenerateMd5Async(byte[] input) => await ComputeHashAsync(input, MD5.Create);

    public async Task<string> GenerateSha1Async(byte[] input) => await ComputeHashAsync(input, SHA1.Create);

    public async Task<string> GenerateSha256Async(byte[] input) => await ComputeHashAsync(input, SHA256.Create);

    private async Task<string> ComputeHashAsync(byte[] data, Func<HashAlgorithm> algorithmFactory)
    {
        using (var hash = algorithmFactory())
        {
            return BitConverter.ToString(await hash.ComputeHashAsync(data)).Replace("-", "").ToLower();
        }
    }
}
