```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Web;
using RestSharp;

public class DecryptionService
{
    private readonly byte[] key;
    private readonly byte[] iv;
    private readonly string hmacKey;
    private readonly IRestClient restClient;

    public DecryptionService(byte[] key, byte[] iv, string hmacKey, string apiUrl)
    {
        this.key = key;
        this.iv = iv;
        this.hmacKey = hmacKey;
        this.restClient = new RestClient(apiUrl);
    }

    public string DecryptAndValidateMessage(string encryptedBase64)
    {
        byte[] cipherTextWithHMAC;

        try
        {
            // decode the base64 encoded message to bytes
            cipherTextWithHMAC = Convert.FromBase64String(encryptedBase64);
        }
        catch (FormatException ex)
        {
            throw new ArgumentException("Invalid Base64 encoding", ex);
        }

        // split the decoded message into cipher text and HMAC
        var hmacLength = Encoding.UTF8.GetByteCount(hmacKey);
        byte[] cipherText = new byte[cipherTextWithHMAC.Length - hmacLength];
        Array.Copy(cipherTextWithHMAC, 0, cipherText, 0, cipherText.Length);

        byte[] receivedHMAC = new byte[hmacLength];
        Array.Copy(cipherTextWithHMAC, cipherText.Length, receivedHMAC, 0, hmacLength);

        // create an HMAC using the same key and compute it from the decrypted message
        var hmacToCheck = new HMACSHA256(Encoding.UTF8.GetBytes(hmacKey));
        byte[] computedHMAC = hmacToCheck.ComputeHash(cipherText);

        // compare the received and computed HMACs, if they don't match throw an exception
        if (!CompareByteArrays(receivedHMAC, computedHMAC))
            throw new AuthenticationException("Message authentication failed");

        using (TripleDES tripleDes = TripleDES.Create())
        {
            ICryptoTransform decryptor = tripleDes.CreateDecryptor(key, iv);

            // decrypt the cipher text to plain text bytes
            byte[] plainTextBytes;

            using (MemoryStream msDecrypt = new MemoryStream(cipherText))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (BinaryReader brDecrypt = new BinaryReader(csDecrypt))
                    {
                        plainTextBytes = brDecrypt.ReadBytes(cipherText.Length);

                        // convert the decrypted bytes back to a string and return it
                        return Encoding.UTF8.GetString(plainTextBytes);
                    }
                }
            }
        }
    }

    private bool CompareByteArrays(byte[] array1, byte[] array2)
    {
        if (array1.Length != array2.Length) 
            return false;

        for (int i = 0; i < array1.Length; i++)
            if (array1[i] != array2[i]) 
                return false;

        return true;
    }

    private void LogMessage(string message, string status)
    {
        var request = new RestRequest("/log", Method.POST);

        request.AddJsonBody(new
        {
            Message = message,
            Status = status
        });

        restClient.ExecuteAsync(request, response => {});
    }
}
```
