  // Validate and assign default values for options
  const { extensions, bufferSize = 1024 * 64, maxConcurrency = 5, retryBackoff = 3000, maxRetries = 3 } = options;

  // Setup logging system or hook into existing system
  const logger = console;

  // Create a cache object to store file contents
  const cache = {};

  try {
    // Get all files in the directory recursively if option is set
    let files = await getFilesRecursive(dirPath);

    // Filter out files with undesired extensions and large files
    files = files.filter((file) => extensions.includes(path.extname(file)) && fs.statSync(file).size <= options.maxFileSize);

    let totalContentLength = 0;

    const readFilesInParallel = async (files, maxConcurrency) => {
      // Use p-limit package to control concurrency and backpressure
      const limit = pLimit(maxConcurrency);

      for (const file of files) {
        if (!cache[file]) {  // Check cache before reading from disk
          await limit(() => readFileWithRetry(file, retryBackoff, maxRetries));

          totalContentLength += fs.statSync(file).size;
          logger.log(`Read file: ${file}, size: ${fs.statSync(file).size}`);
        } else {
          // If the file is in cache, no need to read from disk
          totalContentLength += fs.statSync(file).size;
          logger.log(`Read file from cache: ${file}, size: ${fs.statSync(file).size}`);
        }
      }
    };

    await readFilesInParallel(files, maxConcurrency);  // Read files in parallel

    logger.log('Total content length: ', totalContentLength);
  } catch (err) {
    logger.error(`Error reading directory ${dirPath}: `, err);
    throw err;
  }
};
