use std::time::Duration;
use reqwest;
use clap::{Parser, ValueHint};
use serde_json::Value;
use tokio::time::delay_for;
use log::*;

#[derive(Parser, Debug)]
#[clap(author, version, about, long_about = None)]
struct Args {
    /// City for which the weather is to be fetched.
    #[clap(value_hint=ValueHint::DirPath)]
    city: String,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    let client = reqwest::Client::new();

    // Fetch current weather data.
    tokio::spawn(fetch_weather(&args.city, &client));

    // Simulate doing other work here...
    delay_for(Duration::from_secs(1)).await;

    Ok(())
}

async fn fetch_weather(city: &str, client: &reqwest::Client) {
    let url = format![https://api.example.com/weather?city={city}];
    match client.get(url).send().await {
        Ok(res) => match res.json::<Value>().await {
            Ok(value) => info_spanned_http_tracing::info(&format![Fetched weather data for city={city}], value),
            Err(e) => error_spanned_http_tracing::error(&format![Failed to parse JSON: {}], e),
        },
        Err(e) => error_spanned_http_tracing::error(&format![Failed to fetch weather data: {}], e),
    }
}
