long countLines(FILE *file, bool compressed);
void closeFile(FILE *file, bool compressed);
FILE* redirectOutput(char *outputFileName);

int main(int argc, char **argv) {
    if (argc < 2) {
        printUsage();
        return 1;
    }

    bool compress = false, decompress = false;
    FILE *outputFile = NULL;
    char *outputFileName = NULL;

    for(int i = 1; i < argc - 1; ++i) {
        if (strcmp(argv[i], "-o") == 0) {
            outputFileName = argv[++i];
        } else if (strcmp(argv[i], "-c") == 0) {
            compress = true;
        } else if (strcmp(argv[i], "-d") == 0) {
            decompress = true;
        } 
    }

    long totalLines = 0;
    for (int i = optind; i < argc; ++i) {
        FILE *file = openFile(argv[i]);
        if (!file) return 1; // Error handling could be improved here.

        totalLines += countLines(file, compress);
        closeFile(file, compress);
    }

    if (outputFileName != NULL) {
        outputFile = redirectOutput(outputFileName);
        if (!outputFile) return 1; // Error handling could be improved here.

        fprintf(outputFile, "Total lines: %ld\n", totalLines);
        fclose(outputFile);
    } else {
        printf("Total lines: %ld\n", totalLines);
    }

    return 0;
}

