def modify_kickstart(file_path):
    for placeholder, value in config_dict.items():
        sed_command = f"sed -i \'s/{placeholder}/{value}/g\' {file_path}"  # replace each placeholder with its corresponding actual value.

        try:
            subprocess.run(sed_command, shell=True, check=True)  # execute sed command and raise an exception if it fails.
