```java
import org.apache.commons.codec.digest.DigestUtils;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.math.BigInteger;
import org.slf4j.LoggerFactory;
import org.apache.commons.io.FileUtils;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import javax.servlet.*;
import java.nio.file.*;

public class MD5HashCalculator {

    // Configuration properties
    private final int maxFileSize = 1024 * 1024; // Max file size in bytes (e.g., 1MB)
    private final int cacheSize = 1000; // Cache size
    private final int threadPoolSize = 5; // Thread pool size

    // Logger instance
    private static org.slf4j.Logger logger = LoggerFactory.getLogger(MD5HashCalculator.class);

    // ExecutorService for the non-blocking thread pool
    private ExecutorService executor = Executors.newFixedThreadPool(threadPoolSize);

    // Cache to store previously computed MD5 hashes
    private LoadingCache<String, String> cache;

    public MD5HashCalculator() {
        cache = CacheBuilder.newBuilder().maximumSize(cacheSize).removalListener(
                notification -> logger.info("Entry " + notification.getKey() + " removed")
        ).build(new CacheLoader<String, String>() {
            @Override
            public String load(String key) throws Exception {
                return calculateMD5Hash(key);
            }
        });
    }

    private String calculateMD5Hash(String filePath) throws IOException {
        File file = new File(filePath);

        // Validate the input file path
        if (!file.isFile() || file.length() > maxFileSize) {
            logger.error("Invalid file: " + filePath);
            return null;
        }

        MessageDigest md = null;
        try (InputStream is = new FileInputStream(file)) {
            md = DigestUtils.getMd5Digest(); // Use a standard library function to compute the MD5 hash

            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead); // Only read a portion of the file into memory at once to handle large files efficiently
            }
        } catch (IOException e) {
            logger.error("Error reading file: " + filePath, e);
            return null;
        }

        byte[] digest = md.digest();
        String hashString = new BigInteger(1, digest).toString(16); // Convert the byte array to a hexadecimal string
        logger.info("Computed MD5 hash: " + hashString);
        return hashString;
    }

    public Future<String> getMD5Hash(String filePath) {
        try {
            return executor.submit(() -> cache.getUnchecked(filePath)); // Use a non-blocking thread pool to compute the hash in a separate thread
        } catch (ExecutionException e) {
            logger.error("Error computing MD5 hash: " + filePath, e);
            return null;
        }
    }
}
```
The above class provides a method `getMD5Hash(String filePath)` which takes a file path as input and returns the MD5 hash of the file. It uses a non-blocking thread pool to compute the hash in a separate thread, a cache to store previously computed hashes, and logging for error handling.

The caching mechanism is implemented using Google's Guava library's `LoadingCache` class which automatically evicts entries when the cache size limit is reached. The file path serves as the key to the cache, with the MD5 hash as the value. 

The thread pool size and cache size can be configured by modifying the `threadPoolSize` and `cacheSize` variables respectively. The max file size in bytes for validation can be modified via the `maxFileSize` variable.

