import org.slf4j.*;
import java.util.concurrent.*;

public class NetworkPacketFilter extends Application {
    private static final Logger logger = LogManager.getLogger(NetworkPacketFilter.class);
    private JDBCDatabaseConnection connection;
    // LinkedList for storing sliding window packets, HashMap to maintain packet count per source IP.
    private LinkedList<Packet> packetWindow;
    private Map<String, Integer> ipCount;

    public static void main(String[] args) {
        launch();
    }

    @Override
    public void start(Stage primaryStage) throws Exception {
        BorderPane root = new BorderPane();
        Scene scene = new Scene(root, 600, 400);

        Label filteredPacketsLabel = new Label("Filtered Packets:");
        Label totalPacketCountLabel = new Label("Total Packet Count:");
        Label averagePacketSizeLabel = new Label("Average Packet Size:");
        Button startButton = new Button("Start Filtering");

        root.setTop(filteredPacketsLabel);
        root.setLeft(totalPacketCountLabel);
        root.setRight(averagePacketSizeLabel);
        root.setBottom(startButton);
        primaryStage.setScene(scene);

        startButton.setOnAction(event -> {
            connection = new JDBCDatabaseConnection();
            packetWindow = new LinkedList<>();
            ipCount = new HashMap<>();

            // Start filtering packets in a separate thread to ensure GUI is not blocked
            ExecutorService executorService = Executors.newSingleThreadExecutor();
            executorService.execute(this::filterPackets);
        });

        primaryStage.show();
    }

    public void filterPackets() {
        while (true) {  // Infinite loop for real-time packet filtering, replace with actual incoming packets
            Packet p = getNextIncomingPacket();

            try {
                if (!isValid(p)) {
                    logger.info("Invalid packet: " + p);
                    continue;
                }

                connection.storeMetadata(p);
                ipCount.put(p.getSourceIP(), ipCount.getOrDefault(p.getSourceIP(), 0) + 1);

                // Maintain sliding window of most recent packets
                packetWindow.addLast(p);
                while (packetWindow.size() > MAX_WINDOW_SIZE) {
                    Packet oldestPacket = packetWindow.removeFirst();
                    ipCount.put(oldestPacket.getSourceIP(), ipCount.getOrDefault(oldestPacket.getSourceIP(), 0) - 1);
                }

            } catch (SQLException e) {
                logger.error("Database error: ", e);
            } catch (OutOfMemoryError e) {
                System.gc(); // Attempt to free some memory if necessary
            }
        }
    }

    private boolean isValid(Packet p) throws SQLException {
        return p != null && p.getSize() >= MIN_SIZE && p.getSourcePort() == DESTINATION_PORT 
                && ipCount.getOrDefault(p.getSourceIP(), 0) <= MAX_COUNT;
    }

    private Packet getNextIncomingPacket() {
        // Simulate network latency and packet arrival time
        try { Thread.sleep((long)(Math.random() * AVG_LATENCY)); } catch (InterruptedException e) {}

        // In reality, replace this with actual code to get next incoming packet
        return new Packet(1024 /* size */, "192.168.0.1" /* source IP */, 80 /* source port */);
    }

    private class JDBCDatabaseConnection {
        private Connection connection;

        public JDBCDatabaseConnection() {
            // Replace with actual JDBC URL, username and password for your database.
            try { 
                Class.forName("com.mysql.jdbc.Driver");
                connection = DriverManager.getConnection(
                        "jdbc:mysql://localhost/testdb", "username", "password");
            } catch (Exception e) { logger.error("Database error: ", e); }
        }

        public void storeMetadata(Packet p) throws SQLException {
            // In reality, replace this with actual code to insert packet metadata into your database.
            PreparedStatement statement = connection.prepareStatement(
                    "INSERT INTO packets VALUES (?, ?, ?)");

            statement.setInt(1, p.getSize());
            statement.setString(2, p.getSourceIP());
            statement.setLong(3, p.getArrivalTime().getTime());
        }
    }

    private class Packet {
        int size;
        String sourceIP;
        long arrivalTime;

        public Packet(int size, String sourceIP) {
            this.size = size;
            this.sourceIP = sourceIP;
            this.arrivalTime = System.currentTimeMillis();
        }

