import org.springframework.stereotype.Component;

import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import java.io.IOException;
import java.util.concurrent.CopyOnWriteArrayList;

@ServerEndpoint(value = "/chat")
@Component
public class WebSocketServer {
    private static final CopyOnWriteArrayList<Session> sessions = new CopyOnWriteArrayList<>();

    @OnOpen
    public void onOpen(Session session) throws IOException, EncodeException {
        // Add the new session to our list of active sessions
        sessions.add(session);

        // Log connection event
        log("Connection opened.");
    }

    @OnMessage
    public void onMessage(Session session, String message) throws IOException, EncodeException {
        // Handle incoming messages from clients and broadcast to all other active sessions
        for (Session openSession : sessions) {
            if (openSession.equals(session)) continue;

            openSession.getBasicRemote().sendText(message);
        }
    }

    @OnClose
    public void onClose(Session session) throws IOException, EncodeException {
        // Remove the disconnected session from our list of active sessions
        sessions.remove(session);

        // Log disconnection event
        log("Connection closed.");
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        // Handle connection timeouts or other errors here

        // Log error event
        log("An error occurred: " + throwable.getMessage());
    }
}
```
