use tokio::sync::Mutex;

#[derive(Debug)]
struct Drone {
    id: String,
    latitude: f64,
    longitude: f64,
}

async fn fetch_weather(drone: &Drone, redis_client: RedisClient, config: Value) -> Option<Value> {
    let request_url = format_request_url(drone, &config);
    if let Ok(cache_data) = redis_client.get(request_url).await {
        return Some(cache_data.unwrap());
    } else {
        match reqwest::get(&request_url).await {
            Ok(response) => {
                if let Ok(json) = response.json::<Value>().await {
                    redis_client.set_ex(request_url, json.to_string(), get_cache_duration(&config)).await;
                    return Some(json);
                } else {
                    // Handle parsing failure
                    println_err("Error parsing response from weather API");
                }
            },
            Err(_) => {
                // Handle connection timeout, API rate limits and other errors
                eprintln_err("Error fetching weather data");
            },
        };
    }
}

async fn main() -> std::io::Result<()> {
    let config_file = File::open("config.json")?;
    let mut buffer = String::new();
    config_file.read_to_string(&mut buffer)?;
    let config: Value = serde_json::from_str(&buffer).unwrap();

    let redis_client = RedisClient::open(ConnectionManager::get()?).unwrap();

    // Assume you have a list of drones to fetch weather data for
    let drones: Vec<Drone> = vec![/* your drones here */];

    let mut handles = Vec::new();
    for drone in drones {
        let client_clone = redis_client.clone();
        handles.push(tokio::spawn(async move {
            match fetch_weather(&drone, client_clone, config).await {
                Some(data) => println_data(drone, data),
                None => eprintln_err("Error fetching weather data"),
            }
        }));
    }

    for handle in handles {
        handle.await.unwrap();
    }

    Ok(())
}
