            return Unauthorized();

        // Update the element's HTML content in the database
        using (var transaction = new TransactionScope(TransactionScopeAsyncFlowOption.Enabled)) 
        {
            var existingElement = await _dbContext.Elements
                .FirstOrDefaultAsync(x => x.PageSectionId == model.PageSectionId && x.ElementId == model.ElementId);

            if (existingElement != null) 
            {
                existingElement.HtmlContent = model.HtmlContent;

                // Optimistic concurrency check using RowVersion property
                _dbContext.Elements.Update(existingElement);

                await _dbContext.SaveChangesAsync();

                // Notify clients via SignalR to refresh the page
                await _hubContext.Clients.All.SendAsync("RefreshPage", model.PageSectionId, model.ElementId);
            }

            transaction.Complete();
        }

        return Ok(new { success = true });
    } 
    catch (DbUpdateConcurrencyException ex) 
    {
        // Handle concurrent updates by retrying or notifying the user
        return Conflict("The element has been updated by another user, please refresh.");
