public class HashingService {
    private static final Logger logger = LoggerFactory.getLogger(HashingService.class);
    private final ExecutorService executorService;
    private final int maxThreads;
    private Map<String, String> cache;
    private Jedis jedis;
    private int maxCacheSize;

    public HashingService(int maxThreads, int maxCacheSize) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.cache = new LinkedHashMap<String, String>() {
            @Override
            protected boolean removeEldestEntry(Map.Entry eldest) {
                return size() > maxCacheSize;
            }
        };
        this.jedis = new Jedis("localhost"); // Redis host and port
        this.maxThreads = maxThreads;
        this.maxCacheSize = maxCacheSize;
    }

    public String getMD5Hash(String input) {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Input string is invalid.");
        }

        // Check cache first
        String cachedValue = cache.get(input);
        if (cachedValue != null) {
            return cachedValue;
        }

        // Then check Redis cache
        String redisCachedValue = jedis.get(input);
        if (redisCachedValue != null) {
            cache.put(input, redisCachedValue);
            return redisCachedValue;
        }

        // If not found in either cache, compute hash asynchronously
        executorService.execute(() -> {
            try (InputStream stream = new ByteArrayInputStream(input.getBytes())) {
                String md5Hash = DigestUtils.md5Hex(stream);
                cache.put(input, md5Hash);

                // Also save in Redis for fast retrieval next time
                jedis.set(input, md5Hash);
            } catch (IOException e) {
                logger.error("Failed to compute hash", e);
            }
        });

        return null; // Returning null means the task is still running or an exception occurred
    }

