            sha256HMAC = Mac.getInstance("HmacSHA256");
            sha256HMAC.init(secretKey);
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            throw new RuntimeException(e);
        }
    }

    private final KafkaProducer<String, String> kafkaProducer = new KafkaProducer<>(getKafkaProperties()); // Replace with actual properties
    private static final ObjectMapper mapper = new ObjectMapper();

    public List<DecryptedMessage> decryptAndValidateMessages(List<EncryptedMessage> encryptedMessages) {
        List<DecryptedMessage> decryptedMessages = new ArrayList<>();
        for (EncryptedMessage message : encryptedMessages) {
            DecryptedMessage decryptedMessage;
            try {
                String decryptedText = decrypt(message.getCiphertext(), message.getKey(), message.getIv());
                boolean isValid = validateHMAC(decryptedText, message.getHmac());
                decryptedMessage = new DecryptedMessage(message, decryptedText, isValid ? "success" : "failed");
            } catch (Exception e) {
                decryptedMessage = new DecryptedMessage(message, "", "error: " + e.getMessage());
            }
            decryptedMessages.add(decryptedMessage);
            kafkaProducer.send(new ProducerRecord<>("topic", mapper.writeValueAsString(decryptedMessage)));
        }
        return decryptedMessages;
    }

    private String decrypt(String ciphertext, String key, String iv) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");
        IvParameterSpec ivParameterSpec1 = new IvParameterSpec(iv.getBytes());
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivParameterSpec1);
        byte[] original = cipher.doFinal(Base64.getDecoder().decode(ciphertext));
        return new String(original);
    }

    private boolean validateHMAC(String message, String hmac) {
        String computedHmac = Base64.getEncoder().encodeToString(sha256HMAC.doFinal(message.getBytes()));
        return computedHmac.equals(hmac);
    }

    //... other methods and classes needed to run the code, such as getKafkaProperties(), EncryptedMessage and DecryptedMessage. 
}
