    int digitsCount;
} FileTypeOptions;

FileTypeOptions supportedTypes[] = {
    { ".txt", 5 },
    { ".jpg", 3 },
    { ".png", 3 },
    { ".pdf", 4 }
};

#define SUPPORTED_TYPES_SIZE (sizeof(supportedTypes) / sizeof(FileTypeOptions))
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to get the file type and digit count options from command line arguments or a configuration file
