int modifyFileExtension(const char* filename, const FileTypeOptions* options) {
    if (!filename || !strlen(filename)) {
        fprintf(stderr, "Error: Empty filename\n");
        return -1;
    }

    // Lock the mutex for thread safety
    pthread_mutex_lock(&mutex);

    char* dotPos = strrchr(filename, '.');

    if (!dotPos) {
        fprintf(stderr, "Error: Filename has no extension\n");
        // Unlock the mutex and return error code
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Get the file type from filename
    const char* fileType = dotPos + 1;
    size_t fileTypeLen = strlen(fileType);
    int found = 0;

    for (int i = 0; i < SUPPORTED_TYPES_SIZE; ++i) {
        if (!strcmp(options[i].extension, fileType)) {
            found = 1;
            break;
        }
    }

    // If the file type is not supported, return error code
    if (!found) {
        fprintf(stderr, "Error: Unsupported file type\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    char* newFilename = malloc((strlen(filename) + options->digitsCount + 2) * sizeof(char));

    // Create the new filename using sprintf and strcat functions
    sprintf(newFilename, "%.*s.%0*d%s", (int)(dotPos - filename), filename, 
        options->digitsCount, rand() % (int)pow(10, options->digitsCount), fileType);

    // TODO: Implement the function to rename or move the file based on your requirements
    printf("New filename: %s\n", newFilename);

    free(newFilename);

    // Unlock the mutex after modifying the filename
    pthread_mutex_unlock(&mutex);

    return 0;
}
```
