    private $supplyChainManagementSystem;
    private $rateLimiter;

    public function __construct(WeatherAPIClient $weatherAPI, PatientSchedulingClient $patientSchedulingSystem, NotificationServiceClient $notificationService, SupplyChainManagementClient $supplyChainManagementSystem, RateLimiter $rateLimiter) {
        $this->weatherAPI = $weatherAPI;
        $this->patientSchedulingSystem = $patientSchedulingSystem;
        $this->notificationService = $notificationService;
        $this->supplyChainManagementSystem = $supplyChainManagementSystem;
        $this->rateLimiter = $rateLimiter;
    }

    public function handleClinicOperations($operation, $data) {
        // Rate limiting
        if (!$this->rateLimiter->isWithinLimit()) {
            throw new Exception('Rate limit exceeded.');
        }

        $clinic = Clinic::findOrFail($data['id']);

        switch ($operation) {
            case 'create':
                $this->validateAndCreateClinic($clinic, $data);
                break;

            case 'update':
                $this->updateStatus($clinic, $data['status']);
                break;

            case 'delete':
                $this->deleteIfNotInUse($clinic);
                break;
        }
    }

    private function validateAndCreateClinic($clinic, $data) {
        $prohibitedNames = ['bad', 'evil']; // Just an example. Should be replaced with the actual list of prohibited terms.

        if (strlen($clinic->name) > 50 || in_array($clinic->name, $prohibitedNames)) {
            throw new Exception('Invalid clinic name.');
        }

        $supplies = $this->supplyChainManagementSystem->getSuppliesByClinicId($clinic->id);
        if (count($supplies) == 0) {
            throw new Exception('Insufficient supplies for clinic creation.');
        }

        $clinic->save();
    }

    private function updateStatus($clinic, $status) {
        if ($status == 'closed' || $status == 'emergency') {
            $this->weatherAPI->checkClosureRisk($clinic);
            $this->patientSchedulingSystem->clearAndRescheduleAppointmentsForClinic($clinic);
            $this->notificationService->notifyPatientsWithAlternatives($clinic);
        }

        $clinic->status = $status;
        $clinic->last_modified_ip = getenv('REMOTE_ADDR');
        $clinic->save();

        $this->supplyChainManagementSystem->adjustSuppliesBasedOnStatus($clinic);
    }

    private function deleteIfNotInUse($clinic) {
        if ($this->patientSchedulingSystem->isClinicInUse($clinic)) {
            throw new Exception('Cannot delete clinic while it is in use.');
        }

        $supplies = $this->supplyChainManagementSystem->getSuppliesByClinicId($clinic->id);
        if (count($supplies) > 0) {
            throw new Exception('Cannot delete clinic with pending supplies.');
        }

        $clinic->delete();
    }
}
