```python
import threading
from collections import defaultdict

class LoadBalancerConfigManager:
    def __init__(self):
        self._configs = {}  # {(ServerID, PortNumber): Weight}
        self._lock = threading.Lock()

    def _is_valid(self, server_id, port_number, weight):
        if (server_id, port_number) in self._configs:
            raise ValueError("Duplicate ServerID and PortNumber combination")
        if not 1 <= weight <= 100:
            raise ValueError("Weight must be within the range of 1-100")

    def add(self, server_id, port_number, weight):
        with self._lock:
            self._is_valid(server_id, port_number, weight)
            self._configs[(server_id, port_number)] = weight

    def remove(self, server_id, port_number):
        with self._lock:
            if (server_id, port_number) in self._configs:
                del self._configs[(server_id, port_number)]

    def get(self, server_id=None, port_number=None):
        with self._lock:
            if server_id is None and port_number is None:  # Get all configs
                return [{'ServerID': k[0], 'PortNumber': k[1], 'Weight': v} for k, v in self._configs.items()]
            elif server_id is not None and port_number is None:  # Get by ServerID
                return [{'ServerID': k[0], 'PortNumber': k[1], 'Weight': v} for k, v in self._configs.items() if k[0] == server_id]
            elif server_id is None and port_number is not None:  # Get by PortNumber
                return [{'ServerID': k[0], 'PortNumber': k[1], 'Weight': v} for k, v in self._configs.items() if k[1] == port_number]
            else:  # Get by ServerID and PortNumber
                try:
                    return {'ServerID': server_id, 'PortNumber': port_number, 'Weight': self._configs[(server_id, port_number)]}
                except KeyError:
