```php
<?php
class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cache = [];
    private $failedAttempts = [];

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length]) && time() - $this->cache[$length]['time'] < 3600) {
            return $this->cache[$length]['string'];
        } else {
            $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!"#$%&\'()*+,-./:;<=>?@[\]^_`{|}~';
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $characters[rand(0, strlen($characters) - 1)];
            }

            $this->cache[$length] = ['string' => $randomString, 'time' => time()];
            return $randomString;
        }
    }

    public function hashPassword($password) {
        $limit = 100;
        $interval = 60; // seconds

        if (count($this->failedAttempts) >= $limit && time() - end($this->failedAttempts) < $interval) {
            throw new Exception('Rate limit exceeded. Please wait before trying again.');
        }

        $hash = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);

        if (password_needs_rehash($hash, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount])) {
            $this->failedAttempts[] = time();
            throw new Exception('Password hashing failed.');
        } else {
            $this->hashedPassword = $hash;
        }
    }

    public function checkPassword($password) {
        $result = password_verify($password, $this->hashedPassword);

        if (!$result) {
            array_push($this->failedAttempts, time());

            $startTime = time() - 60; // 1 minute ago
            $recentFailedAttempts = array_filter($this->failedAttempts, function ($time) use ($startTime) {
                return $time >= $startTime;
            });

            if (count($recentFailedAttempts) > count($this->failedAttempts)) {
                $this->failedAttempts = $recentFailedAttempts;
            }
        }

        return $result;
    }

    public function validateCharacterSet($characterSet) {
        $pattern = '/^.*(?=.*\d)(?=.*[a-z])(?=.*[A-Z])(?=.*\W).*$/';

        if (!preg_match($pattern, $characterSet)) {
            return false;
        } else {
            return true;
        }
    }

    public function setSaltRoundCount($rounds) {
        $this->saltRoundCount = max(min($rounds, 31), 12);
    }

    public function resetPassword() {
        $this->hashedPassword = null;

        foreach ($this->cache as $length => $data) {
            unset($this->cache[$length]);
        }

        $this->failedAttempts = [];
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Logging code here. Depending on your database setup you might want to use PDO or MySQLi and SQL queries for this part.
    }
}
?>
```
