```cpp
#include <iostream>
#include <string>
#include <algorithm>
#include <memory>
#include <forward_list>

template<typename Predicate>
void insert_after(std::forward_list<std::string>& list, const std::string& toFind, 
                   const std::string& toInsert, Predicate p) {
    auto prev = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it, ++prev){
        if(p(*it, toFind)) {
            list.insert_after(it, toInsert);
            return;
        }
    }
    list.insert_after(prev, toInsert);
}

// Comparison function for case insensitive search
bool equal_caseinsensitive(const std::string& a, const std::string& b) {
    if (a.length() != b.length()) return false;

    for (auto i = 0u; i < a.length(); ++i){
        if (tolower(a[i]) != tolower(b[i])) return false;
    }

    return true;
}

int main() {
    std::forward_list<std::string> list = {"hello", "world"};
    insert_after(list, "hello", "beautiful", equal_caseinsensitive);

    for (const auto& str : list) {
        std::cout << str << ' ';
    }
}
```

