public class JSONLogAnalyzer {
    private final int MAX_ENTRIES = 5000;
    private Queue<LogEntry> logsWindow = new LinkedList<>();
    private RateLimiter rateLimiter = RateLimiter.create(1.0 / 5); // 1 call per 5 seconds

    public LogEntry analyzeAndFilterLogs(String jsonString, String moduleName, String severityLevel) {
        JSONObject obj = new JSONObject(jsonString);

        try {
            if (logsWindow.size() == MAX_ENTRIES) logsWindow.remove();

            LogEntry entry = new LogEntry();
            entry.module = obj.getString("module");
            entry.severityLevel = obj.getString("severityLevel");
            entry.userId = obj.getString("userId");
            entry.requestId = obj.getString("requestId");
            entry.timestamp = LocalDateTime.parse(obj.getString("timestamp"));

            if (entry.module.equals(moduleName) && entry.severityLevel.equals(severityLevel)) {
                logsWindow.add(entry);

                Optional<LogEntry> maxSeverityLog = getMaxSeverityLog();
                maxSeverityLog.ifPresent((log) -> sendToMonitoringAPI(log));
            }

        } catch (JSONException e) {
            System.out.println("Malformed JSON: " + jsonString);
        }
    }

    private Optional<LogEntry> getMaxSeverityLog() {
        return logsWindow.stream().max(Comparator.comparing(log -> log.severityLevel));
    }

    private void sendToMonitoringAPI(LogEntry entry) {
        if (rateLimiter.tryAcquire()) {
            // Call external API to send log data
        }
    }
}
