using System.Threading;
using NLog; // You might need to install this package first using NuGet Package Manager

public class CustomDataStructure { /* Define your data structure here */ }

public interface IRepository<T> where T : class
{
    void Save(T item);
    T Load();
}

public class BinaryFileRepository<T> : IRepository<T> where T : class
{
    private static Logger logger = LogManager.GetCurrentClassLogger(); // NLog for logging
    private readonly string _filePath;
    private readonly object _lockObj = new object();

    public BinaryFileRepository(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("Invalid file path", nameof(filePath));

        _filePath = filePath;
    }

    public T Load()
    {
        try
        {
            Monitor.Enter(_lockObj); // Locking to prevent concurrent access and corruption
            using (var stream = File.OpenRead(_filePath))
            {
                var formatter = new BinaryFormatter();
                return (T)formatter.Deserialize(stream);
            }
        }
        catch (Exception e)
        {
            logger.Error(e, "Failed to load data from file");
            throw;
        }
        finally
        {
            Monitor.Exit(_lockObj); // Unlocking after deserialization
        }
    }

    public void Save(T item)
    {
        try
        {
            Monitor.Enter(_lockObj); // Locking to prevent concurrent access and corruption
            using (var stream = File.OpenWrite(_filePath))
            {
                var formatter = new BinaryFormatter();
                formatter.Serialize(stream, item);
            }
        }
        catch (Exception e)
        {
            logger.Error(e, "Failed to save data to file");
            throw;
        }
        finally
        {
            Monitor.Exit(_lockObj); // Unlocking after serialization
        }
    }
}
```
