```php
class AdvancedPasswordManager {
    private $hashed_password;
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789~`@#$%^&*()-_+={}[]|\\;:"<>,.?';
    private $cachedStrings = [];

    public function generateSecureRandomString($length) {
        if (!isset($this->cachedStrings[$length])) {
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $index = random_int(0, strlen($this->characterSet) - 1);
                $randomString .= $this->characterSet[$index];
            }
            $this->cachedStrings[$length] = $randomString;
        }
        return $this->cachedStrings[$length];
    }

    public function hashPassword($password) {
        $this->hashed_password = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        return $this; // for method chaining
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashed_password);
    }

    public function validateCharacterSet($characterSet) {
        $errors = [];
        if (!preg_match('/[A-Z]/', $characterSet)) {
            $errors[] = 'At least one uppercase letter is required';
        }
        // add more validation here...

        return $errors;
    }

    public function setSaltRoundCount($rounds) {
        $this->saltRoundCount = $rounds >= 12 && $rounds <= 31 ? $rounds : 12; // minimum and maximum round counts
        return $this; // for method chaining
    }

    public function resetPassword() {
        $newRandomString = $this->generateSecureRandomString(strlen($this->hashed_password));
        $this->hashPassword($newRandomString);

        unset($this->cachedStrings[strlen($this->hashed_password)]); // invalidate cached strings of previous password length
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement a database logging system here
    }
}
