        logMessage("Failed to initialize semaphore");
        return -1;
    }

    const char* input = "Hello world";
    char* words[MAX_WORDS];
    int numWords = fetchWordList(words); // replace with actual function call

    char* result = adaptiveStringProcessor(input, words, numWords);
    if (result != NULL) {
        printf("%s\n", result);
    } else {
        logMessage("Result exceeded limit");
    }

    sem_destroy(&semaphore); // clean up
    return 0;
}

char *adaptiveStringProcessor(const char* input, const char* words[], int numWords) {
    if (input == NULL || words == NULL) {
        logMessage("Invalid input pointer");
        return NULL;
    }

    // Lock semaphore to control concurrency level
    if (sem_wait(&semaphore) != 0) {
        logMessage("Failed to wait on semaphore");
        return NULL;
    }

    size_t availableMemory = getAvailableSystemMemory();
    double loadAverage = getCurrentLoadAverage();

    // Calculate adjusted size limit based on system resources and word list
    int maxLength = (availableMemory / loadAverage) - numWords;
    if (maxLength < 0) {
        logMessage("Insufficient memory");
        sem_post(&semaphore); // Unlock semaphore
        return NULL;
    }

    char* result = malloc(maxLength + 1); // Allocate memory for result
    if (result == NULL) {
        logMessage("Failed to allocate memory");
        sem_post(&semaphore); // Unlock semaphore
        return NULL;
    }

    strcpy(result, input); // Copy input string
    int i;
    for (i = 0; i < numWords; ++i) {
        char* word = words[i];

        // Remove word from the beginning and end of result
        while (strncmp(result, word, strlen(word)) == 0) {
            strcpy(result, result + strlen(word));
        }
        int len = strlen(result);
        while (strncmp(result + len - strlen(word), word, strlen(word)) == 0 && len > strlen(word)) {
            result[len - strlen(word)] = '\0';
            len--;
        }
    }

    toUpperCase(result); // Capitalize first letter of each remaining word

    if (strlen(result) > maxLength) {
        logMessage("Result exceeded limit");
        free(result); // Deallocate memory for result
        sem_post(&semaphore); // Unlock semaphore
        return NULL;
    }

    sem_post(&semaphore); // Unlock semaphore
    return result;
}

int fetchWordList(char* dest[]) {
    // Replace with actual API call to external data source
    dest[0] = "Hello";
    dest[1] = "world";

    return 2; // number of words fetched
}

void toUpperCase(char* str) {
    int i = 0;
    while (str[i]) {
        if (isalpha(str[i])) {
            str[i] = toupper((unsigned char) str[i]);
            break; // Only capitalize the first word
        }
        ++i;
    }
}

size_t getAvailableSystemMemory() {
