```java
public class ImageLoader {
    private final MemoryCache memoryCache;
    private final DiskCache diskCache;
    private final CloudStorage cloudStorage;
    private final ExecutorService executorService;

    public ImageLoader(Context context) {
        this.memoryCache = new MemoryCache();
        this.diskCache = new DiskCache(context);
        this.cloudStorage = new CloudStorage();
        this.executorService = Executors.newFixedThreadPool(5); // Five threads
    }

    public void loadImage(final String imageUrl, final ImageView imageView) {
        Bitmap bitmap = memoryCache.getBitmapFromMemCache(imageUrl);

        if (bitmap == null) {
            bitmap = diskCache.getBitmapFromDiskCache(imageUrl);

            if (bitmap != null) {
                imageView.setImageBitmap(bitmap);
            } else {
                executorService.execute(new Runnable() {
                    public void run() {
                        try {
                            bitmap = cloudStorage.downloadImage(imageUrl);

                            if (bitmap != null) {
                                memoryCache.addBitmapToMemoryCache(imageUrl, bitmap);
                                diskCache.addBitmapToDiskCache(imageUrl, bitmap);

                                new Handler(Looper.getMainLooper()).post(new Runnable() {
                                    public void run() {
                                        imageView.setImageBitmap(bitmap);
                                    }
                                });
                            }
                        } catch (IOException e) {
                            // Handle download error
                        }
                    }
                });
            }
        } else {
            imageView.setImageBitmap(bitmap);
        }
    }
}
```
