```java
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.lang3.RandomUtils;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class DynamicServiceManager {
    private final ConcurrentHashMap<String, ServiceFactory> serviceRegistry = new ConcurrentHashMap<>();
    private final ObjectMapper objectMapper;
    private final ScheduledExecutorService executorService;
    private static final Logger logger = Logger.getLogger(DynamicServiceManager.class.getName());

    public DynamicServiceManager() {
        this.objectMapper = new ObjectMapper();
        this.executorService = Executors.newScheduledThreadPool(10);
    }

    // register a new service factory function for the specified id
    public void registerServiceFactory(String id, ServiceFactory serviceFactory) {
        if (serviceRegistry.putIfAbsent(id, serviceFactory) != null) {
            throw new IllegalArgumentException("Duplicate service ID");
        }
    }

    // unregister a service factory function for the specified id
    public void unregisterServiceFactory(String id) {
        if (serviceRegistry.remove(id) == null) {
            throw new IllegalArgumentException("No such service ID exists");
        }
    }

    // create a new service instance from JSON configuration
    public Service createServiceInstance(String jsonConfig) throws JsonProcessingException {
        Map<?, ?> configMap = objectMapper.readValue(jsonConfig, Map.class);
        String id = (String) configMap.get("id");
        if (id == null || !serviceRegistry.containsKey(id)) {
            throw new IllegalArgumentException("Invalid service ID");
        }
        ServiceFactory factory = serviceRegistry.get(id);
        return factory.createServiceInstance(configMap);
    }

    // start a new thread and run the service, with random delay
    public void runServiceWithDelay(Service service) {
        int delay = RandomUtils.nextInt(1, 10);
        executorService.schedule(() -> {
            try {
                service.start();
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Failed to start service", e);
            }
        }, delay, TimeUnit.SECONDS);
    }
}

interface ServiceFactory {
    // create a new service instance from the given configuration map
    Service createServiceInstance(Map<?, ?> config);
}

interface Service {
    void start();
    void stop();
}
```
This code uses Jackson's `ObjectMapper` to convert JSON configurations into maps, Apache Commons Lang's `RandomUtils.nextInt` for random delays in service starts, and Java's built-in concurrency utilities (`ConcurrentHashMap`, `ScheduledExecutorService`) to manage the registry of factories and running services asynchronously with consistent state management.

Each service must implement a `start()` method to begin execution and a `stop()` method to end execution. A `ServiceFactory` interface is used for registration/unregistration and creation of new service instances from JSON configurations. The code uses Java's built-in logging utility (`java.util.logging.Logger`) for logging, which can be replaced with other logging frameworks if desired.

