void processNFALogStream(FILE *stream) {
    /* Initialize variables and load initial configuration */
    char line[256];
    int numEntries = 0;

    while (fgets(line, sizeof(line), stream)) {
        NFAPI_CRC_INDICATION_PDU_T entry = parseNFALogEntry(line);

        /* Check if config needs to be updated */
        char *modTime = getLastModifiedTimeOfConfigFile();
        if (strcmp(lastConfigUpdateTime, modTime) != 0) {
            pthread_mutex_lock(&db_lock); // lock database for update

            /* Load new configuration */
            config = json_load_file("config.json");
            lastConfigUpdateTime = modTime;

            pthread_mutex_unlock(&db_lock); // unlock database after update
        }

        /* Check if entry matches CRC rules in current config */
        int isValidEntry = validateCRC(entry, config);

        pthread_mutex_lock(&db_lock); 

        /* Store log entry and validation result into database */
        storeLogInDatabase(db, entry, isValidEntry);

        pthread_mutex_unlock(&db_lock);

        numEntries++;
    }

    printf("Processed %d entries\n", numEntries);
}
