```java
import com.amazonaws.AmazonServiceException;
import com.amazonaws.SdkClientException;
import com.amazonaws.auth.AWSStaticCredentialsProvider;
import com.amazonaws.auth.BasicAWSCredentials;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3ClientBuilder;
import com.amazonaws.services.s3.model.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class S3StorageService {
    private static final Logger logger = LogManager.getLogger(S3StorageService.class);

    AmazonS3 s3Client;

    public S3StorageService(String accessKey, String secretKey, String region) {
        this.s3Client = AmazonS3ClientBuilder.standard()
                .withRegion(region)
                .withCredentials(new AWSStaticCredentialsProvider(new BasicAWSCredentials(accessKey, secretKey)))
                .build();
    }

    public void uploadFile(String bucketName, String keyName, String filePath) {
        try {
            PutObjectRequest request = new PutObjectRequest(bucketName, keyName, filePath);

            s3Client.putObject(request);

        } catch (AmazonServiceException e) {
            logger.error("Error uploading to S3: " + e.getErrorMessage(), e);
        } catch (SdkClientException e) {
            logger.error("Internal error occurred while uploading to S3", e);
        }
    }

    public void downloadFile(String bucketName, String keyName, String filePath) {
        try {
            GetObjectRequest request = new GetObjectRequest(bucketName, keyName);

            s3Client.getObject(request).transferTo(filePath);

        } catch (AmazonServiceException e) {
            logger.error("Error downloading from S3: " + e.getErrorMessage(), e);
        } catch (SdkClientException e) {
            logger.error("Internal error occurred while downloading from S3", e);
        }
    }
}
```
