```C
void LoadCipher(Cipher *cipher, const char* name) {
    char path[1024];
    sprintf(path, "./lib/%s.so", name);  // Path to your shared libraries

    cipher->handle = dlopen(path, RTLD_LAZY);
    if (!cipher->handle) {
        fprintf(stderr, "Failed to load %s: %s\n", path, dlerror());
        return;
    }

    cipher->encrypt = dlsym(cipher->handle, "Encrypt");  // Assuming the symbol is 'Encrypt'
    cipher->decrypt = dlsym(cipher->handle, "Decrypt");  // Assuming the symbol is 'Decrypt'

    char* error = dlerror();
    if (error) {
        fprintf(stderr, "%s\n", error);
        return;
    }
}
