private:
    NetworkClient* client;
    std::unordered_map<std::pair<double, double>, std::string, PairHash> cache;
    const int CACHE_TTL = 60 * 5; // Cache time-to-live is 5 minutes

    struct PairHash {
        template <typename T, typename U>
        std::size_t operator()(const std::pair<T, U> &x) const
        {
            return std::hash<T>()(x.first) ^ std::hash<U>()(x.second);
        }
    };

public:
