    std::string GetWeatherData(double latitude, double longitude) {
        auto now = std::chrono::system_clock::now();
        auto timestampedUrl = std::make_pair(latitude, longitude);

        if (cache.find(timestampedUrl) != cache.end() && 
            now - cache[timestampedUrl].first < CACHE_TTL) {
            BOOST_LOG_TRIVIAL(info) << "Cache hit for coordinates: (" << latitude << ", " << longitude << ")";
            return cache[timestampedUrl].second;
        } 

        std::string data = client->FetchDataFromApi("https://api.openweathermap.org/..."); // replace with your actual API call

        if (!data.empty()) {
            BOOST_LOG_TRIVIAL(info) << "API call successful for coordinates: (" << latitude << ", " << longitude << ")";
            cache[timestampedUrl] = std::make_pair(now, data);
        } else {
            BOOST_LOG_TRIVIAL(error) << "API call failed for coordinates: (" << latitude << ", " << longitude << ")";
        }

        return data;
    }
};

