Here is a simplified version of your requirements in Java. Please note that this is just an example and may need modifications according to your specific use case and requirements.

```java
import java.util.*;

public class ServiceManager {
    private static final int MAX_FAILURES = 5;

    private Random random = new Random();
    private volatile boolean isRunning = false;
    private Service service;
    private ConfigurationManager configManager;
    private MessagingSystem messagingSystem;
    private Logger logger;

    public void start() {
        if (isRunning) {
            return;
        }

        int consecutiveFailures = 0;
        while(consecutiveFailures < MAX_FAILURES) {
            try {
                isRunning = true;

                // Get delay from config manager
                int delay = configManager.getDelay();
                Thread.sleep(delay);

                service = new Service();
                service.performTask();
                consecutiveFailures = 0;
            } catch (Exception e) {
                logger.error("Failed to start service", e);
                consecutiveFailures++;

                // If too many failures, send a message and exit the loop
                if(consecutiveFailures >= MAX_FAILURES) {
                    messagingSystem.sendMessage("Service failed to start after " + consecutiveFailures + " attempts");
                    isRunning = false;
                }
            } finally {
                service.cleanup();
                isRunning = false;
            }
        }
    }

    public void stop() {
        if (!isRunning) {
            return;
        }

        try {
            service.stopService();
        } catch (Exception e) {
            logger.error("Failed to stop service", e);
        } finally {
            isRunning = false;

            // Send message when stopped successfully
            messagingSystem.sendMessage("Service stopped");
        }
    }

    public void configure(int delay) {
        configManager.setDelay(delay);
    }
}
```
