<?php 
require 'vendor/autoload.php';
use Psr\Http\Message\ServerRequestInterface as Request;
use Psr\Http\Message\ResponseInterface as Response;
use \Firebase\JWT\JWT;

$app = new \Slim\App;
// Fetch the JWKS from OAuth 2.0 client and store it in $jwks array
$jwks = [];

function authenticateUser($request, $response) {
    global $jwks;
    $token = $request->getHeader('Authorization')[0];

    try {
        $decoded_JWT = JWT::decode($token, $jwks, array('RS256'));
        // If token is decodable and valid then continue to next step
        return true;
    } catch (Exception $e) {
        // Log the authentication failure for auditing purposes
        error_log("Authentication failed: ".$e->getMessage());
        throw new Exception('Invalid Access Token');
    }
}

function updateDatabase($clinicId, $status, $ipAddress, $db) {
    $query = $db->prepare('UPDATE clinic SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id');

    try {
        $result = $query->execute([':status' => $status, ':ip' => $ipAddress, ':id' => $clinicId]);

        if($result) {
            // If update is successful then return the unique identifier for logging
            $log_id = uniqid('', true);
            error_log("Update successful. Log ID: ".$log_id);
            return $log_id;
        } else {
            throw new Exception('Database Update Failed');
        }
    } catch (Exception $e) {
        // Log the database update failure for auditing purposes
        error_log("Update failed: ".$e->getMessage());
        throw $e;
    }
}

$app->post('/update', function(Request $request, Response $response) use ($jwks){
    $clinicId = $request->getParam('id');
    $status = $request->getParam('status');
    $ipAddress = $_SERVER['REMOTE_ADDR'];

    // Connect to the database using PDO extension
    $db = new PDO('mysql:host=localhost;dbname=test', 'user', 'pass');

    try {
        authenticateUser($request, $response);
        $logId = updateDatabase($clinicId, $status, $ipAddress, $db);

        // Return a success message only after authentication and database update are successful
        return $response->withJson(['success' => true, 'message' => $logId]);
    } catch (Exception $e) {
        return $response->withJson(['success' => false, 'message' => $e->getMessage()]);
    }
});
$app->run();
?>
