    {EVP_des_cfb64},
};
#define NUM_MODES (sizeof(supported_modes) / sizeof(CipherConfig))

const EVP_CIPHER *initialize_cipher(int mode, unsigned char* key, size_t keylen, unsigned char* iv, size_t ivlen, int use_null) {
    if (mode < 0 || mode >= NUM_MODES) {
        fprintf(stderr, "Invalid cipher mode %d\n", mode);
        return NULL;
    }

    EVP_CIPHER *cipher = supported_modes[mode].init();
    if (cipher == NULL) {
        fprintf(stderr, "Failed to initialize cipher for mode %s\n", supported_modes[mode].name);
        return NULL;
    }

    // Validate key and IV length here. Note that this will vary by cipher type.
    if (EVP_CIPHER_key_length(cipher) != keylen || EVP_CIPHER_iv_length(cipher) != ivlen) {
        fprintf(stderr, "Invalid key or IV length\n");
        return NULL;
    }

    // Set the key and IV in your context. Note that this will vary by cipher type.
    /* ... */

    if (use_null) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);

        return ctx;
    } else {
        // Handle other encryption modes here.
        /* ... */
        return cipher;
    }
}
