        self.name = name
        self.category = category
        self.price = price
        self.quantity = quantity

def get_product_risk(product: Product) -> Dict[str, Any]:
    risk_dict = {
        "Clothing": {"high": [], "medium": ["oversize"], "low": []},
        "Electronics": {"high": ["fragile"], "medium": [], "low": []},
        # Add more product categories and their associated risks here...
    }

    risk_level = "Unknown"
    detailed_risk_info = ""

    if product.category in risk_dict:
        if product.price > 100 or product.quantity > 100:
            risk_level = "High"
        elif product.price < 25 or product.quantity < 10:
            risk_level = "Low"
        else:
            risk_level = "Medium"

        try:
            # Assuming an external API that returns JSON data
            response = requests.get(f'https://external-api.com/product/{product.category}')

            if response.status_code == 200:
                detailed_risk_info = response.json()["detailed_risk"]
        except requests.exceptions.RequestException as e:
            print(f"Failed to fetch risk information from external API: {e}")

            # Fallback options
            if product.category in risk_dict and product.name in risk_dict[product.category][risk_level]:
                detailed_risk_info = f"The product '{product.name}' is considered a high-risk item."
    else:
        print("Product category not found in the risk dictionary.")

    return {"risk_level": risk_level, "detailed_risk_information": detailed_risk_info}
