    private $hashedPassword;
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789~`!"@#$%^&*()-_=+[]{};:,.<>/?|';
    private $cachedStrings = [];

    public function generateSecureRandomString($length) {
        if (!isset($this->cachedStrings[$length])) {
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomKey = mt_rand(0, strlen($this->characterSet) - 1);
                $randomString .= $this->characterSet[$randomKey];
            }
            $this->cachedStrings[$length] = $randomString;
        }
        return $this->cachedStrings[$length];
    }

    public function hashPassword($password) {
        $options = [
            'cost' => $this->saltRoundCount,
        ];
        $hashed_password = password_hash($password, PASSWORD_BCRYPT, $options);
        $this->hashedPassword = $hashed_password;
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        $patterns = ["/[A-Z]/", "/[a-z]/", "/[0-9]/", "/[\W_]/"];
        foreach ($patterns as $pattern){
            if (!preg_match($pattern, $characterSet)){
                return false; // Character set is invalid.
            } 
        }
        return true;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            $this->saltRoundCount = 12; // Fallback value.
            return false;
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $newRandomString = $this->generateSecureRandomString(strlen($this->cachedStrings[0]));
