```java
import com.jcraft.jsch.*;

public class SshClient {
    private final String username;
    private final String password;
    private final String host;
    private Session session;

    public SshClient(String username, String password, String host) {
        this.username = username;
        this.password = password;
        this.host = host;
    }

    public void connect() throws JSchException {
        final JSch jsch = new JSch();

        session = jsch.getSession(username, host, 22);
        session.setPassword(password);

        // set other properties like StrictHostKeyChecking, ConnectTimeout, etc. as per requirement

        session.connect();
    }

    public String executeCommand(String command) throws JSchException {
        if (session == null || !session.isConnected()) {
            connect();
        }

        ChannelExec channel = (ChannelExec) session.openChannel("exec");

        channel.setCommand(command);
        channel.connect();

        StringBuilder outputBuffer = new StringBuilder();

        try (InputStream inputStream = channel.getInputStream()) {
            byte[] tmp = new byte[1024];

            while (true) {
                while (inputStream.available() > 0) {
                    int i = inputStream.read(tmp, 0, 1024);

                    if (i < 0) break;

                    outputBuffer.append(new String(tmp, 0, i));
                }

                if (channel.isClosed()) {
                    break;
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Error occurred while reading the command's output", e);
        }

        return outputBuffer.toString();
    }

    public void disconnect() {
        if (session != null && session.isConnected()) {
            session.disconnect();
        }
    }
}
```

