use std::env;
use tokio::fs;
use log::{info};
use serde_json::Value as JsonValue;
use config::Config;
use anyhow::Result;
use once_cell::sync::Lazy;
use std::time::Duration;

static APP: Lazy<App> = Lazy::new(|| App::init().unwrap());

struct App {
    config: Config,
}

impl App {
    pub fn init() -> Result<Self> {
        // Loading and parsing configuration files.
        let s = fs::read_to_string("Config.toml")?;
        let mut config = Config::default();
        config.merge(Config::try_from(&s)?)?;

        Ok(Self { config })
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize the logger (in production, you'd want to use a more advanced configuration).
    env_logger::init();

    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        info_log("No command line arguments provided");
        return Ok(());
    }

    match &args[1][..] {
        "load" => load_env_vars().await?,
        "autoload" => autoloader().await?,
        _ => {
            info_log("Invalid command line argument")?;
        },
    }

    Ok(())
}

async fn load_env_vars() -> Result<()> {
    let value: JsonValue = reqwest::get("http://example.com/api/config")?
        .await?.json().await?;

    for (key, &value) in value["data"].as_object().unwrap() {
        set_env(key, &value);
    }

    Ok(())
}

async fn autoloader() -> Result<()> {
    // Loading vendor autoload file...

    Ok(())
}

fn info_log(msg: &str) -> Result<()> {
    info.log(&format![msg]);
    Ok(())
}

fn set_env(key: &str, value: &JsonValue) -> Result<()> {
    std::env::set_var(key, match value {
        JsonValue::String(s) => s,
        _ => return Err(anyhow::anyhow_format![
            "Expected string for env var {} but found: {:?}",
            key, value
        ]),
    });

    Ok(())
}
