using System;
using System.Text;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;
using System.Data;
using System.Linq;
using System.Collections.Generic;

public class DataService
{
    private readonly HttpClient _httpClient = new HttpClient();

    // Assuming the API has a route that accepts POST requests to fetch word list
    private const string ApiUrl = "https://example.com/wordlist";

    public async Task<string> SendByteArrayToDatabaseAndTrimCapitalize(byte[] data, string token, Action<int, int> callback)
    {
        if (data == null || token == null)
            throw new ArgumentNullException("Data and token cannot be null.");

        // Send byte array to database server. This would depend on how the external system is set up.
        var json = JsonConvert.SerializeObject(data);
        var content = new StringContent(json, Encoding.UTF8, "application/json");
        var response = await _httpClient.PostAsync(ApiUrl, content);

        if (!response.IsSuccessStatusCode)
            throw new Exception("Failed to fetch data from database.");

        // Convert the fetched word list into a DataTable
        var jsonString = await response.Content.ReadAsStringAsync();
        var table = (DataTable)JsonConvert.DeserializeObject(jsonString, typeof(DataTable));

        using (var reader = table.CreateDataReader())
        {
            List<string> wordList = new List<string>();

            while (reader.Read())
                wordList.Add((string)reader[0]); // Assuming the first column contains the words

            var totalWordLength = wordList.Sum(word => word.Length);
            var avgWordLength = totalWordLength / wordList.Count;

            int limit = 10000 - avgWordLength;  // Adjust based on your needs
            StringBuilder sb = new StringBuilder();

            foreach (string word in wordList)
            {
                if (sb.Length + word.Length > limit)
                    return null;

                sb.Append(word);
                callback?.Invoke(wordList.IndexOf(word), sb.Length);  // Report progress
            }

            var result = sb.ToString();

            if (result.Length > limit)
                return null;

            char[] a = result.ToCharArray();
            a[0] = char.ToUpper(a[0]);  // Capitalize the first letter of each word

            for (int i = 1; i < a.Length; i++)
                if ((char.IsWhiteSpace(a[i - 1])) && (char.IsLetter(a[i])))
                    a[i] = char.ToUpper(a[i]);

            return new string(a);
        }
    }
}
```
