# Cache mechanism class
class ProfileImageCache(object):
    def __init__(self, storage_service, expiration_time):
        self.storage_service = storage_service
        self.expiration_time = expiration_time
        self.cache = {}

    def get(self, image_id):
        if image_id in self.cache:
            if time.time() - self.cache[image_id]['timestamp'] < self.expiration_time:
                return self.cache[image_id]['data']
            else:
                del self.cache[image_id]
        try:
            data = self.storage_service.download(image_id)
        except Exception as e:  # Network error handling
            logging.error("Downloading image failed due to {}".format(e))
            return None
        else:
            self.cache[image_id] = {'timestamp': time.time(), 'data': data}
            return data

    def invalidate(self, image_id):
        if image_id in self.cache:
            del self.cache[image_id]

# User login handler
def on_login(user):
    user.profile_images = ProfileImageCache(S3StorageService(), EXPIRATION_TIME)
