Here is a simplified code structure as per your requirements:

```java
import com.auth0.jwt.*;
import com.auth0.jwt.interfaces.*;

public class JWTProcessor {
    private ConfigurationLoader configurationLoader;
    private JWTCache jwtCache;
    private ExternalAPI externalApi;

    public JWTProcessor(ConfigurationLoader configurationLoader, JWTCache jwtCache, ExternalAPI externalApi) {
        this.configurationLoader = configurationLoader;
        this.jwtCache = jwtCache;
        this.externalApi = externalApi;
    }

    public DecodedJWT process(String token){
        // Check the cache first for performance improvement
        if (jwtCache.contains(token)){
            return jwtCache.get(token);
        }

        // Load configuration from external file or database
        JWTConfiguration config = configurationLoader.load();
        try {
            // Validate the token with configuration claims 
            Algorithm algorithm = Algorithm.HMAC256(config.secret);
            JWTVerifier verifier = JWT.require(algorithm)
                    .withIssuer(config.issuer)
                    .acceptExpiresAt(config.expirationTimeInSeconds)
                    .build(); 

            // Check the token with external API for revocation status
            if (externalApi.isRevoked(token)) {
                throw new JWTVerificationException("The provided token is revoked");
            }

            DecodedJWT jwt = verifier.verify(token);

            // Cache validated tokens for performance improvement 
            jwtCache.put(token, jwt);

            return jwt;
        } catch (Exception exception){
            throw new JWTVerificationException("Invalid token", exception);
        }
    }
}

interface ConfigurationLoader {
    JWTConfiguration load();
}

class JWTCache {
    boolean contains(String key) {...};
    DecodedJWT get(String key) {...};
    void put(String key, DecodedJWT value) {...};
}

interface ExternalAPI {
    boolean isRevoked(String token);
}
``` 

