Here's a basic outline for `DynamicFileProcessor` implementation using C++17 features:

```cpp
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <future>
#include <string>
#include <vector>

namespace fs = std::filesystem;
using path_t = fs::path;

class DynamicFileProcessor {
public:
  using MetadataKeys = std::vector<std::string>;
  using FileList = std::vector<std::pair<path_t, MetadataKeys>>;

private:
  path_t configPath_;
  int maxParallelOps_{10}; // Default maximum number of parallel operations.
  bool followSymlinks_{true}; // Follow symbolic links by default.
  fs::file_time_type timestamp_; // Timestamp for the operation.
  FileList files_; // List of file paths and their metadata keys.

public:
  DynamicFileProcessor(const path_t &configPath) : configPath_(configPath) {
    timestamp_ = fs::file_time_type::clock::now();
    readConfigFile(configPath);
  }

  void processFiles() {
    std::vector<std::future<void>> futures;

    for (const auto& [path, metadataKeys] : files_) {
      if (fs::is_symlink(path) && !followSymlinks_) continue; // Skip symbolic link.

      while (futures.size() >= maxParallelOps_) {
        std::for_each(begin(futures), end(futures), [](auto& fut){ fut.wait(); });

        futures.erase(std::remove_if(begin(futures), end(futures), [](auto& fut){ return fut.wait_for(std::chrono::seconds(0)) == std::future_status::ready; }), end(futures));
      }

      futures.push_back(std::async([this, path, metadataKeys](){ this->processFile(path, metadataKeys); }));
    }

    for (auto& fut : futures) {
      fut.get(); // Wait until all tasks are done.
    }
  }

private:
  void readConfigFile(const path_t &configPath) {
    std::ifstream file(configPath);

    if (file.is_open()) {
      path_t filePath;
      MetadataKeys metadataKeys;

      while (std::getline(file, filePath)) {
        std::string line;

        if (std::getline(file, line)) {
          std::istringstream iss(line);
          std::copy(std::istream_iterator<std::string>(iss), 
                    std::istream_iterator<std::string>(),
                    std::back_inserter(metadataKeys));
        }

        files_.emplace_back(filePath, metadataKeys);
      }
    } else {
      throw std::runtime_error("Unable to open config file");
    }
  }

  void processFile(const path_t &path, const MetadataKeys &metadataKeys) {
    // Fetch metadata from external service.

    // Process the fetched metadata and perform operations such as renaming, moving or deleting files based on it.

    // If the file is a symbolic link and 'followSymlinks_' flag is set to false, skip processing this file.
  }
};
```
