```C
#include <stdio.h>
#include <pthread.h>

// Structure to hold cryptographic functions details
typedef struct {
    char name[20];
    int status; // indicates if addition was successful or not
} Algorithm;

Algorithm algorithms_cache[100];
int cache_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to load configuration files and add cryptographic functions
void initializeCryptoLibrary(char** configFiles, int fileCount) {
    for (int i=0; i < fileCount; i++) {
        FILE *file = fopen(configFiles[i], "r"); // open each config file

        if (file == NULL) {
            printf("Failed to load configuration file %s\n", configFiles[i]);
            continue;
        }

        char algorithmName[20];
        int result = fscanf(file, "%s", algorithmName); // read cryptographic function name from each file

        if (result == EOF) {
            printf("Unsupported configuration in %s\n", configFiles[i]);
            continue;
        }

        pthread_mutex_lock(&lock); // lock before adding to cache

        // check for duplicates
        int duplicate = 0;
        for (int j=0; j < cache_count; j++) {
            if(strcmp(algorithmName, algorithms_cache[j].name) == 0){
                printf("Duplicate algorithm name in %s\n", configFiles[i]);
                duplicate = 1;
                break;
            }
        }

        // if not a duplicate, add to cache and set status as successful
        if (!duplicate) {
            strcpy(algorithms_cache[cache_count].name, algorithmName);
            algorithms_cache[cache_count].status = 1; 
            cache_count++;
        } else {
            algorithms_cache[cache_count].status = 0; // if a duplicate, set status as unsuccessful
        }

        pthread_mutex_unlock(&lock); // unlock after adding to cache
    }
}
```
