#include <semaphore.h>
#include <stdio.h>

sem_t sem;

int create_sem(int initial) {
    if (sem_init(&sem, 0, initial) == -1) {
        perror("Semaphore Initialization failed");
        return -1;
    }
    printf("Semaphore Initialize successfully\n");
    return 0;
}

int delete_sem() {
    if (sem_destroy(&sem) == -1) {
        perror("Semaphore Deletion failed");
        return -1;
    }
    printf("Semaphore Delete successfully\n");
    return 0;
}

int increment_sem() {
    if (sem_post(&sem) == -1) {
        perror("Semaphore Increment failed");
        return -1;
    }
    return 0;
}

int decrement_sem() {
    if (sem_wait(&sem) == -1) {
        perror("Semaphore Decrement failed");
        return -1;
    }
    return 0;
}
