async function asyncArrayReduce(array, initialValue, callback) {
    let accumulator = initialValue;
    for (let i = 0; i < array.length; i++) {
        try {
            const value = await callback(accumulator, array[i], i, array);
            accumulator = value;
        } catch (error) {
            console.log("An error occurred during reduction:", error);
            return error;
        }
    }
    return accumulator;
}
