    private IMemoryCache _cache;
    private readonly ExternalApiClient _apiClient;

    public AesCbcInitiateService(IMemoryCache memoryCache, ExternalApiClient apiClient)
    {
        _cache = memoryCache;
        _apiClient = apiClient;
