    // Simplified for brevity. 
    private async Task<List<string>> ParseXmlDocuments(IEnumerable<IXPathNavigable> documents, string xpathQuery)
    {
        var results = new List<string>();

        foreach (var document in documents)
        {
            if (_cache.TryGetValue(xpathQuery, out List<string> cachedResult))
                return cachedResult;

            var navigator = document.CreateNavigator();
            var iterator = navigator.Select(xpathQuery);

            while (iterator.MoveNext())
            {
                results.Add(iterator.Current?.Value);
            }
        }

        _cache.Set(xpathQuery, results, TimeSpan.FromMinutes(1)); // Cache result for 1 minute
        return results;
    }

