import org.junit.*;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.ArrayList;
import static junit.framework.TestCase.assertEquals;

public class MicroserviceTestRunner {
    private List<Class<?>> testClasses;
    private Method[] testMethods;
    private TestConfiguration config;
    ExecutorService executorService = Executors.newFixedThreadPool(config.getConcurrencyLimit());

    public MicroserviceTestRunner(List<Class<?>> testClasses, Method[] testMethods, TestConfiguration config) {
        this.testClasses = testClasses;
        this.testMethods = testMethods;
        this.config = config;
    }

    public void executeTests() throws Exception {
        List<Future<String>> futures = new ArrayList<>();

        for (Class<?> testClass : testClasses) {
            Object instance = testClass.getDeclaredConstructor().newInstance();

            for (Method method : testMethods) {
                futures.add(executorService.submit(() -> {
                    // Log test start
                    System.out.println("Test " + method.getName() + " started");

                    try {
                        // Execute test with timeout and retry mechanism here

                        method.invoke(instance);
                        return "Passed: " + method.getName();
                    } catch (Exception e) {
                        return "Failed: " + method.getName() + ", reason: " + e.getMessage();
                    }
                });
            }
        }

        for (Future<String> future : futures) {
            System.out.println(future.get());
        }

        executorService.shutdown();
    }
}
