    public static Object loadAndValidate(String filePath) {
        Object objToReturn = null;
        FileInputStream fis = null;
        ObjectInputStream ois = null;

        try {
            fis = new FileInputStream(filePath);
            ois = new ObjectInputStream(fis);
            objToReturn = ois.readObject();

            if (objToReturn instanceof MoSTState) {
                MoSTState stateObj = (MoSTState) objToReturn;

                // Validate the object here, you may need to adjust according to your needs
                if(stateObj.validate() && stateObj.getVersionCompatibility()) {
                    LOGGER.info("Object loaded and validated successfully");
                } else {
                    LOGGER.error("Loaded object is not valid or compatible with the current version");
                    objToReturn = null;
                }
            } else {
                LOGGER.error("Loaded object is not an instance of MoSTState class");
            }
        } catch (Exception ex) {
            LOGGER.error("Error while loading and validating object", ex);
        } finally {
            try {
                if(ois != null) ois.close();
                if(fis != null) fis.close();
            } catch (IOException ioe) {
                // Handle exception as needed
            }
        }

        return objToReturn;
    }
}
``` 

