```javascript
class DomTraverser {
    constructor() {
        this.cachedStyles = {};
    }

    async applyStyleToMatches(selector, styles) {
        let elements;

        // 如果缓存中存在样式，则使用它，否则从外部库加载
        if (this.cachedStyles[selector]) {
            elements = this.getElementsBySelector(selector);
            await this.applyCssToElementAsync(elements, styles);
            return;
        }

        try {
            const externalStyleSheet = await loadExternalLibrary();

            // 从外部库中加载样式并将其缓存以备将来使用
            this.cachedStyles[selector] = externalStyleSheet[selector];
            elements = this.getElementsBySelector(selector);
            await this.applyCssToElementAsync(elements, styles || this.cachedStyles[selector]);
        } catch (error) {
            // 处理样式库加载失败的情况
            console.error('无法加载外部样式库：', error);
        }
    }

    getElementsBySelector(selector) {
        return Array.from(document.querySelectorAll(selector));
    }

    async applyCssToElementAsync(elements, styles) {
        for (const element of elements) {
            for (const style in styles) {
                element.style[style] = styles[style];
            }
        }
    }
}
```

