    public static PokemonWeaknessResult getWeaknesses(Pokemon pokemon, String directoryPath) {
        try {
            // check if web.config exists in the provided directory path 
            File file = new File(directoryPath + "/web.config");
            boolean webConfigExists = Files.exists(file.toPath());

            // determine the weaknesses of the pokemon based on its type using a library function
            List<String> weaknesses;
            switch (pokemon.getType()) {
                case "Fire":
                    weaknesses = Arrays.asList("Water", "Rock", "Dragon");
                    break;
                // other cases here...
                default:
                    weaknesses = Collections.emptyList();
            }

            // check if Process class is available, and if so start the directory using it
            Method processBuilderMethod = ProcessBuilder.class.getDeclaredMethod("start");
            try {
                // start the directory here... 
                logger.info("Starting directory at " + directoryPath);
            } catch (Exception e) {
                logger.error("Cannot use Process class to start directory", e);
            }

            return new PokemonWeaknessResult(webConfigExists, weaknesses, null);
        } catch (NoSuchMethodException nsme) {
            // log the error and return an instance with only the error message
            logger.error("Cannot use Process class due to OS limitations", nsme);
            return new PokemonWeaknessResult(false, Collections.emptyList(), "Cannot use Process class due to OS limitations");
        } catch (Exception e) {
            // log the error and return an instance with only the error message
            logger.error("Unexpected error", e);
            return new PokemonWeaknessResult(false, Collections.emptyList(), "Unexpected error: " + e.getMessage());
        }
    }
}
