```java
import java.io.*;
import java.util.logging.Logger;

public class CompressDirectory {
    private static final Logger LOGGER = Logger.getLogger(CompressDirectory.class.getName());
    private static int MAX_RETRIES = 5;

    public static void main(String[] args) {
        if (args.length < 3) {
            System.out.println("Usage: java CompressDirectory <input directory> <output zip file> <compression level>");
            return;
        }

        String inputDir = args[0];
        String outputZip = args[1];
        int compressionLevel = Integer.parseInt(args[2]);

        compressDirectory(inputDir, outputZip, compressionLevel);
    }

    private static void compressDirectory(String inputDir, String outputZip, int compressionLevel) {
        File dir = new File(inputDir);
        if (!dir.exists() || !dir.isDirectory()) {
            LOGGER.severe("Input directory does not exist or is not a directory: " + inputDir);
            return;
        }

        deleteIfExists(outputZip);

        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                Process process = Runtime.getRuntime().exec("zip -r" + compressionLevel + " \"" + outputZip + "\" " + inputDir);

                BufferedReader in = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = in.readLine()) != null) {
                    System.out.println(line); // Feedback to user
                }

                int exitVal = process.waitFor();
                if (exitVal == 0) {
                    LOGGER.info("Directory compressed successfully: " + inputDir);
                    return;
                } else {
                    LOGGER.severe("Failed to compress directory, exit value: " + exitVal);
                }
            } catch (Exception e) {
                LOGGER.severe("Error while compressing directory: " + e.getMessage());
                if(i == MAX_RETRIES - 1){ // Last retry failed
                    throw new RuntimeException(e.getMessage(), e);
                }
            } finally {
                deleteIfExists(outputZip);
            }
        }
    }

    private static void deleteIfExists(String filePath) {
        File file = new File(filePath);

        if (file.exists()) {
