import com.fasterxml.jackson.databind.JsonNode;
import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;

public class JsonParser {
    private Cache<String, JsonNode> cache;

    public JsonParser() {
        this.cache = Caffeine.newBuilder().build();
    }

    public JsonNode parse(String json) throws Exception {
        if (this.cache.asMap().containsKey(json)) {
            return this.cache.getIfPresent(json);
        } else {
            try {
                ObjectMapper objectMapper = new ObjectMapper();
                JsonNode rootNode = objectMapper.readTree(new File(json));
                this.cache.put(json, rootNode);
                return rootNode;
            } catch (Exception e) {
                throw new Exception("Failed to parse JSON: " + e.getMessage());
            }
        }
    }
}
```

