const LRU = require('lru-cache');
const keyManager = require('key-manager');
let cache = new LRU({ maxAge: 1000 * 60 * 60 }); // Cache for one hour

async function asyncArrayReduce(arr, initialVal, callback) {
    let accumulator = initialVal;

    for (let i = 0; i < arr.length; i++) {
        if (cache.has(accumulator)) {
            // Retrieve result from cache
            console.log('Retrieved value from cache:', cache.get(accumulator));
        } else {
            let token = await keyManager.fetchTokenSecurely();

            try {
                const res = await fetch('https://api-url.com/resource', { 
                    method: 'POST',
                    headers: { 
                        Authorization: `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(arr[i])
                });

                if (!res.ok) throw new Error('Network response was not ok');

                let data = await res.json();
                accumulator = callback(accumulator, parseInt(data));
                cache.set(accumulator, data);
            } catch (error) {
                console.log("Error: ", error);
            }
        }
    }

    return accumulator;
}
