```python
import json
from abc import ABC, abstractmethod
from collections import defaultdict
from functools import partial
from threading import Lock

class ConfigSerializer(ABC):
    @abstractmethod
    def serialize(self, data): pass

    @abstractmethod
    def deserialize(self, raw_data): pass

class JsonConfigSerializer(ConfigSerializer):
    def serialize(self, data):
        return json.dumps(data)

    def deserialize(self, raw_data):
        return json.loads(raw_data)

class ConfigManager:
    def __init__(self, loader=JsonConfigSerializer()):
        self._configurations = defaultdict(partial(defaultdict, dict))
        self._parsers = {}
        self._loader = loader
        self._lock = Lock()

    def register_parser(self, config_type, parser):
        with self._lock:
            self._parsers[config_type] = parser

    def add_configuration(self, type_, version, config_data):
        with self._lock:
            if type_ not in self._parsers:
                raise ValueError('No parser registered for this configuration type')

            serialized_config = self._loader.serialize(config_data)
            parsed_config = self._parsers[type_].parse(serialized_config)
            self._configurations[type_][version] = parsed_config

    def get_configuration(self, type_, version):
        with self._lock:
            if version not in self._configurations[type_]:
                raise ValueError('No configuration of this version exists')

            return self._loader.deserialize(self._configurations[type_][version])
```
This code creates two classes, `ConfigSerializer` and its subclass `JsonConfigSerializer`, which define the serialization methods for configurations. It also defines a class `ConfigManager` that handles all of the functionality described in the problem. The `add_configuration` function is used to add new configuration settings to the manager, while the `get_configuration` function retrieves them. The configurations are stored as dictionaries with types as primary keys and versions as secondary keys.

