using System;
using System.Collections.Concurrent;
using System.IO;
using System.Xml;
using Microsoft.Extensions.Configuration;

public class XmlParserService : IDisposable
{
    private readonly IConfiguration configuration;
    private readonly ConcurrentDictionary<string, (XmlDocument Document, string Version)> cache = new();

    public XmlParserService(IConfiguration configuration)
    {
        this.configuration = configuration;
    }

    public XmlNode ParseElement(string documentName, string elementName)
    {
        var (document, version) = LoadDocument(documentName);

        XmlNamespaceManager nsmanager = new XmlNamespaceManager(new NameTable());
        nsmanager.AddNamespace("ns", document.FirstChild?.Attributes?["xmlns"]?.Value ?? "");

        XmlNodeList nodeList = document.SelectNodes($"//ns:{elementName}", nsmanager);

        if (nodeList == null || nodeList.Count == 0)
            throw new Exception("Element not found.");

        if (nodeList.Count > 1)
            throw new Exception("Multiple elements with the given name found.");

        return nodeList[0];
    }

    private (XmlDocument Document, string Version) LoadDocument(string documentName)
    {
        var version = configuration[$"documents:{documentName}:version"];

        if (!cache.TryGetValue(documentName, out var cached) || cached.Version != version)
        {
            var path = Path.Combine(AppContext.BaseDirectory, configuration[$"documents:{documentName}:path"]);

            XmlDocument doc = new XmlDocument();
            doc.Load(path);

            if (cache.Count > 100) // Manage cache size
                while (cache.Count != 90) 
                    cache.TryRemove(cache.Keys.GetEnumerator().Current, out _);

            cache[documentName] = (doc, version);
        }

        return cache[documentName];
    }

    public void Dispose() => cache?.Clear();
}
```

This class loads XML documents and uses an in-memory LRU cache for efficient reuse. It uses the IConfiguration interface for loading document paths and versions from a configuration file, which can be changed to support any external system or database. Note that this is a basic implementation and may require additional error handling and optimization depending on your specific requirements.

