            self.cache[url] = (headers, content_length)

    def fetch_and_process(self, url):
        data = self.fetch_from_cache(url)

        if not data:
            try:
                response = requests.get(url, timeout=5)  # Timeout can be configured with env variables or config file

                if response.status_code == 200:
                    headers = response.headers
                    content_length = len(response.content)

                    self.save_to_cache(url, headers, content_length)
                    data = (headers, content_length)
            except requests.exceptions.RequestException as e:
                print(f"Error occurred while fetching {url}: {e}")  # Can integrate with logging system

        return data

