import java.io.*;
import java.util.logging.Logger;

public MoSTState loadStateFromFile(String filePath) throws DFSClientNotAvailableException, NetworkConnectivityException {
    ObjectInputStream in = null;

    try{
        // Establish connection to DFS
        DFSClient dfsClient = new DFSClient();
        dfsClient.connect();

        InputStream fileContent = dfsClient.readFile(filePath);
        if (fileContent == null) {
            System.out.println("The requested file is not available or empty.");
            return null;
        }

        in = new ObjectInputStream(fileContent);

        // Read object from the stream and check instance type
        Object obj = in.readObject();
        if (obj instanceof MoSTState) {
            return (MoSTState) obj;
        } else {
            System.out.println("The file does not contain a valid MoSTState.");
            return null;
        }
    } catch(FileNotFoundException e){
        System.out.println("The requested file was not found: " + e);
        return null;
    } catch (EOFException e) {
        System.out.println("End of file reached prematurely: " + e);
        return null;
    } catch(IOException | ClassNotFoundException e){
        System.out.println("I/O error occurred during read operation or object was not found in classpath: "+e);
        return null;
    } finally {
        // Close the connection and release resources
        try{
            if (in != null) {
                in.close();
            }
            dfsClient.disconnect();
        } catch(IOException e){
            System.out.println("Failed to close DFS client: "+e);
        }
    }
}
