class RiskAssessmentModule:
    def __init__(self, apis):
        self.apis = deque(apis)
        self.cache = {}
        self._lock = Lock()

    def evaluate_risk(self, product):
        with self._lock:  # Thread-safe access to the cache and api list
            if (product.category, product.price, product.quantity) in self.cache:
                return self.cache[(product.category, product.price, product.quantity)]

            while len(self.apis):
                try:
                    response = requests.post(self.apis[0], data={  # Assume API takes category, price and quantity as input
                        'category': product.category,
                        'price': product.price,
                        'quantity': product.quantity,
                    })
                except Exception:
                    self.apis.rotate(-1)  # Move to next API on failure
                else:
                    risk_score = response.json()['risk_score']  # Assuming api returns a json with 'risk_score' key
                    self.cache[(product.category, product.price, product.quantity)] = risk_score
                    return risk_score
            raise RuntimeError("All APIs failed")

# This is the actual route that will use your module for evaluating risks
