```cpp
#include <forward_list>
#include <string>

std::forward_list<std::string>& insertString(std::forward_list<std::string> &list, const std::string &toInsert, const std::string &afterThis) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == afterThis) {
            break;
        }
        ++it;
    }

    if (it != list.end()) {
        // If the string is found, insert 'toInsert' right after it
        list.insert_after(it, toInsert);
    } else {
        // Otherwise, insert at the end of the list
        list.insert_after(list.before_begin(), toInsert);
    }

    return list;
}
```
