                throw new ArgumentException("Invalid User ID");
            }

            currentConfig[configName] = newValue;

            _database.UpdateUserConfiguration(userId, currentConfig); // assuming method exists

            Log.Information("Updated configuration for user: {@userId}", userId);

            ThreadPool.QueueUserWorkItem((_) => _versionControlApi.CommitChanges()); // assuming CommitChanges is async and doesn't need to be awaited
