    with engine.begin() as connection:
        if version is not None:
            result = connection.execute(text("""
                UPDATE resources 
                SET data=:data, version=version+1 
                WHERE id=:id AND version=:version RETURNING *;
                """), dict(id=str(resource_id), data=data, version=version))
        else:
            result = connection.execute(text("""
                UPDATE resources 
                SET data=:data, version=1 
                WHERE id=:id AND (version IS NULL OR :version IS NULL) RETURNING *;
                """), dict(id=str(resource_id), data=data, version=version))
