def calculate_md5(file_name):
    if not os.path.isfile(file_name):
        raise NotFound('File not found')

    md5 = md5()
    with open(file_name, 'rb') as f:
        for chunk in chunk_reader(f):
            md5.update(chunk)

    return {'hash': md5.hexdigest()}

