#include <jansson.h>

// Structure to hold API response
typedef struct api_response {
    char *data;
    int status_code;
} api_response_t;

static size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->data = realloc(s->data, new_len + 1);

  if (s->data == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }

  memcpy(s->data + s->len, ptr, size*nmemb);
  s->data[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

api_response_t *fetch(const char *url) {
    api_response_t *result = malloc(sizeof(api_response_t));
    struct string s = {0};

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        result->status_code = -1;
        return result;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

    CURLcode res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform request: %s\n", curl_easy_strerror(res));
        result->status_code = -1;
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

        result->data = s.data;
        result->status_code = (int)http_code;
    }

    curl_easy_cleanup(curl);

    return result;
}

void *threadFunc(void *arg) {
    char url[256];
    sprintf(url, "https://api.example.com/users/%s/settings", (char*) arg);

    api_response_t *res = fetch(url);

    if (res->status_code == 200) {
        // Parse JSON response here...
    } else {
        fprintf(stderr, "Failed to fetch settings for %s: HTTP %d\n", (char*) arg, res->status_code);
    }

    free(res->data);
    free(res);
}

void dynamicTextProcessor(const char *user) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, &threadFunc, user)) {
        fprintf(stderr, "Failed to create thread\n");
        return;
    }

    if (pthread_join(thread, NULL)) {
        fprintf(stderr, "Error joining thread\n");
        return;
    }
}
