from threading import Semaphore, BoundedSemaphore
from multiprocessing import Pool

# Initialize the semaphores
sem_dict = {}
sem_pool = BoundedSemaphore(100)

def create_sem(name: str):
    if name in sem_dict:
        raise Exception('Semaphore already exists')
    sem_dict[name] = Semaphore()

def delete_sem(name: str):
    if name not in sem_dict:
        raise Exception('Semaphore does not exist')
    del sem_dict[name]

def increment_sem(name: str, val=1):
    if name not in sem_dict:
        raise Exception('Semaphore does not exist')
    for _ in range(val):
        sem_pool.acquire()
        with sem_dict[name]:
            pass

def decrement_sem(name: str, val=1):
    if name not in sem_dict:
        raise Exception('Semaphore does not exist')
    for _ in range(val):
        sem_pool.release()
        with sem_dict[name]:
            pass

@lru_cache(maxsize=50)  # Assuming a cache size of 50
