```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import javax.xml.bind.DatatypeConverter;
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileHashUtil {
    private static final Logger logger = LoggerFactory.getLogger(FileHashUtil.class);
    private int cacheSize;
    private ExecutorService executorService;

    public FileHashUtil(int threadPoolSize, int cacheSize) {
        this.cacheSize = cacheSize;
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void calculateFileHash(String filePath) {
        if (filePath == null || filePath.isEmpty() || filePath.length() > 1000) {
            logger.error("Invalid file path");
            return;
        }

        Path path = Paths.get(filePath);
        try (FileChannel channel = FileChannel.open(path, StandardOpenOption.READ)) {
            final MessageDigest[] digests = prepareDigests();

            // Read and update the hash computation in a separate thread
            executorService.submit(() -> {
                try (ReadableByteChannel readableChannel = Channels.newChannel(new FileInputStream(path.toFile()))) {
                    final ByteBuffer buffer = ByteBuffer.allocateDirect(16 * 1024);

                    while (readableChannel.read(buffer) != -1) {
                        buffer.flip();

                        for (MessageDigest digest : digests) {
                            digest.update(buffer);
                        }

                        buffer.clear();
                    }
                } catch (IOException e) {
                    logger.error("Error reading file", e);
                }
            });

            // Print the hash values once completed
            executorService.submit(() -> {
                for (MessageDigest digest : digests) {
                    System.out.println(DatatypeConverter.printHexBinary(digest.digest()));
                }
            });
        } catch (IOException e) {
            logger.error("Error opening file", e);
        }
    }

    private MessageDigest[] prepareDigests() throws NoSuchAlgorithmException {
        final MessageDigest md5 = MessageDigest.getInstance("MD5");
        final MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

        return new MessageDigest[]{md5, sha256};
    }

    // Other methods to handle caching, logging, and other features like rate limiting can be added as per the requirements.
}
```
