using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;

public class SecureDataProcessor 
{
    private readonly Dictionary<string, Func<byte[], Task<byte[]>>> hashAlgorithms = new()
    {
        {"md5", ComputeHashAsync<MD5CryptoServiceProvider>},
        {"sha1", ComputeHashAsync<SHA1Managed>},
        {"sha256", ComputeHashAsync<SHA256Managed>}
    };

    public Task<string> GenerateMd5Async(string input) => GenerateHash("md5", input);

    public Task<string> GenerateSha1Async(string input) => GenerateHash("sha1", input);

    public Task<string> GenerateSha256Async(string input) => GenerateHash("sha256", input);

    private async Task<string> GenerateHash(string algorithm, string input)
    {
        var bytes = Encoding.UTF8.GetBytes(input);
        return await ComputeAndFormatHash(hashAlgorithms[algorithm], bytes);
    }

    // other methods similar to the above

    private static async Task<string> ComputeAndFormatHash(Func<byte[], Task<byte[]>> algorithm, byte[] data)
    {
        var hashBytes = await algorithm(data);
        return string.Join("", hashBytes.Select(x => x.ToString("X2")));  // to hexadecimal format
    }

    private static async Task<byte[]> ComputeHashAsync<T>(byte[] data) where T : HashAlgorithm, new()
    {
        using var crypt = new T();
        return await crypt.ComputeHashAsync(new MemoryStream(data));
    }
}
