import json

class TokenValidator:
    def __init__(self):
        self._required_fields = {"access_token", "expires_in", "token_type"}

    def validate(self, token: str) -> bool:
        try:
            data = json.loads(token)
        except json.JSONDecodeError:
            return False  # not a JSON string

        if not self._required_fields.issubset(data.keys()):
            return False  # missing fields

        if data['token_type'] != 'Bearer':
            return False  # invalid token type

        if not isinstance(data['expires_in'], int) or data['expires_in'] < 0:
            return False  # invalid expires in value

        return True
