        // Fetch the filename from the array and append digits if needed
        char* filename = (char*) js_files[i];

        int num_digits = 0;
        int naming_convention_status = get_naming_convention(filename, &num_digits);

        // Handle errors from the naming convention service
        if (naming_convention_status != 0) {
            printf("Error fetching naming convention for %s\n", filename);
            continue;
        }

        char* unique_filename = malloc(strlen(base_filename) + num_digits + 1); // +1 for null terminator
        if (unique_filename == NULL) {
            printf("Memory allocation failed\n");
            return NULL; // Error handling
        }

        sprintf(unique_filename, "%s%d", base_filename, i);  // Append index as digit

        int load_and_execute_status = load_and_execute(unique_filename);

        // Handle errors from file loading and execution
        if (load_and_execute_status != 0) {
            printf("Error loading or executing %s\n", unique_filename);
            free(unique_filename);
            return NULL; // Error handling
        }

        result = unique_filename;
    }

    return result;  // Return the last processed filename for simplicity
}
