void expandStateList(int** currentStates, int* numOfCurrentStates, 
                    const FSA* fsa, void** externalDataSources, 
                    int lastState) {
    pthread_mutex_lock(&mutex); // Lock for thread safety

    // Validate and expand states...
    int* newStates = NULL;
    size_t numNewStates = 0;

