        if ((*currentStates)[i] == lastState) {
            // Transition to new states based on FSA definition and external data...
            int numTransitions = getNumTransitions((*currentStates)[i], fsa, externalDataSources);

            for (int j = 0; j < numTransitions; ++j) {
                if (!stateAlreadyInList(newStates, numNewStates, getNextState((*currentStates)[i], j, fsa, externalDataSources))) {
                    newStates = realloc(newStates, sizeof(*newStates) * (numNewStates + 1));
                    if (!newStates) {
                        // Handle memory allocation error...
                    }
                    newStates[numNewStates++] = getNextState((*currentStates)[i], j, fsa, externalDataSources);
                }
            }
        }
    }

    *currentStates = realloc(*currentStates, sizeof(**currentStates) * (numNewStates));
    if (!*currentStates) {
        // Handle memory allocation error...
    }

    memcpy(*currentStates, newStates, sizeof(int) * numNewStates);
    free(newStates);
    *numOfCurrentStates = numNewStates;

    pthread_mutex_unlock(&mutex); // Unlock for thread safety
}
