    broadcast_receiver: broadcast::Receiver<()>,
}

impl WeatherService {
    async fn fetch_weather(&self, location: &str) -> Result<Value, ReqwestError> {
        let client = reqwest::Client::new();
        let url = format![API_ENDPOINT, location];
        let response = client.get(url).send().await?;
        let value = response.json().await?;

        // Store the fetched data in cache before returning it
        self.cache.write().await.insert(location.to_string(), value.clone());
        Ok(value)
    }

    async fn cleanup(&self, interval: u64){
        loop {
            // Wait for the interval duration and then send a notification to all waiting tasks
            broadcast::channel(1).0.recv().await;
            tokio::time::sleep(Duration::from_secs(interval)).await;

            let mut cache = self.cache.write().await;
            for (location, weather) in cache.iter() {
                if should_expire(&weather){
                    cache.remove(location);
                }
            }
        }
    }
}

#[tokio::main]
async fn main(){
    let config: Value = read_config(); // Read configuration from a JSON file

    let (broadcast_sender, broadcast_receiver) = broadcast::channel(1);
    let cache = RwLock::new(HashMap::<String, String>::new());

    let service = WeatherService { 
        cache: cache.clone(), 
        broadcast_receiver: broadcast_receiver,
    };

    // Start the background cleanup task
    tokio::spawn(async move {
        loop{
            service.cleanup(&config["cache_expiration"]).await;
            broadcast_sender.send(()).unwrap();
        } 
    });

    let location = "New York"; // Example location
    match service.fetch_weather(&location).await {
       Ok(data) => println![&format![Weather in {} is: {}", location, data],
       Err(e) => eprintln![&format![Fetching weather for {} failed with error: {}", location, e]
    }
}
```

This code provides a basic outline of the system. However, it's important to note that this is only a start and many improvements could be made. For example, you might want to add authentication tokens to your requests to the weather API if necessary. You should also handle API rate limits and ensure that your Redis server is configured correctly for caching weather data effectively.

