class ImageLoader {
    private val cache = Cache() // Custom implementation of an LRU cache, storing Bitmaps

    fun loadImage(url: String): Bitmap? {
        // Look for the image in cache first
        var bitmap = cache.get(url)

        if (bitmap == null) {
            // If not found in cache, download it from cloud storage
            val futureBitmap = CloudStorageService.downloadImageAsync(url) 

            try {
                // Wait for the image to finish downloading
                bitmap = futureBitmap.get()

                if (bitmap != null) {
                    cache.put(url, bitmap)
                }
            } catch (e: ExecutionException) {
                e.printStackTrace()
            }
        }

        return bitmap
    }
}
