        this.oldTestamentRegex = /(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1\sSamuel|2\sSamuel|1\sKings|2\sKings|Isaiah|Jeremiah|Ezekiel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/gi;
        this.newTestamentRegex = /(Matthew|Mark|Luke|John|Acts|Romans|1\sCorinthians|2\sCorinthians|Galatians|Ephesians|Philippians|Colossians|1\sThessalonians|2\sThessalonians|1\sTimothy|2\sTimothy|Titus|Philemon|Hebrews|James|1\sPeter|2\sPeter|1\sJohn|2\sJohn|3\sJohn|Jude)/gi;
        this.books = {};
    }

    analyzeText(text) {
        if (typeof text !== 'string' || text === '') throw new Error('Invalid input');
        let oldTestamentBooks = Array.from(text.matchAll(this.oldTestamentRegex)).map(a => a[0]);
        let newTestamentBooks = Array.from(text.matchAll(this.newTestamentRegex)).map(a => a[0]);

        oldTestamentBooks.concat(newTestamentBooks).forEach(book => {
            if (this.books[book]) this.books[book]++;
            else this.books[book] = 1;
        });

        // Verify with external API here... 
    }

    categorizeBooks() {
        let categories = { oldTestament: [], newTestament: [] };
        for (let book in this.books) {
            if (this.oldTestamentRegex.test(book)) categories['oldTestament'].push(book);
            else if (this.newTestamentRegex.test(book)) categories['newTestament'].push(book);
        }
        return categories;
    }

    report() {
        let booksSorted = Object.entries(this.books).sort((a, b) => b[1] - a[1]);
        console.log('Most frequently mentioned books:');
        booksSorted.slice(0, 5).forEach(book => console.log(`${book[0]} (${book[1]} times)`));
    }
}

module.exports = BibleTextAnalyzer;
