const shortid = require('shortid');
const mongoose = require('mongoose');
const ProductModel = mongoose.model('Product');

// Helper function to generate unique product identifier
async function getUniqueId(collection) {
    let id;
    do {
        id = shortid.generate();
    } while (await collection.findById(id));

    return id;
}

const ProductService = {

    // Add product asynchronously with unique identifier
    async addProductAsync: async function(product) {
        const newProduct = new ProductModel({ _id: await getUniqueId(ProductModel), ...product });

        return await newProduct.save();
    },

    // Delete product by id asynchronously, returns false if not found
    deleteProductAsync: async function(id) {
        const result = await ProductModel.deleteOne({ _id: id });

        return result.deletedCount > 0;
    },

    // Update product details asynchronously, returns false if not found
    updateProductAsync: async function(id, newDetails) {
        const result = await ProductModel.updateOne({ _id: id }, newDetails);

        return result.nModified > 0;
    }
};

module.exports = ProductService;
```
