```python
import threading
import queue
from functools import wraps
from time import sleep
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def retry_on_failure(max_retries, backoff):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(max_retries+1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logger.error(f"Failed with exception {e} on attempt number {i+1}. Retrying...")
                    sleep(backoff * i)
            raise Exception("Maximum retries exceeded.")
        return wrapper
    return decorator

def merge_files(file_list, dest_path, buffer_size=4096, max_retries=5, backoff=1):

    # Create a thread-safe queue for files
    file_queue = queue.Queue()
    for file in file_list:
        file_queue.put(file)

    @retry_on_failure(max_retries, backoff)
    def read_from_file():
        with open(file_queue.get(), 'rb') as f:
            while True:
                chunk = f.read(buffer_size)
                if not chunk:
                    break
                yield chunk

    # Use thread-safe counter for progress indicator
    file_counter = threading.Lock()
    total_files = len(file_list)

    def write_to_destination():
        nonlocal total_files
        with open(dest_path, 'wb') as f:
            while not file_queue.empty():
                for chunk in read_from_file():
                    f.write(chunk)

                # Update progress indicator
                with file_counter:
                    total_files -= 1
                    logger.info(f"Merged {total_files} files out of {len(file_list)}")

    threads = []
    for _ in range(min(32, len(file_list))): # Use no more than 32 threads
        thread = threading.Thread(target=write_to_destination)
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    logger.info("All files merged successfully.")
```
This code defines a function `merge_files` that accepts a list of file paths, a destination path and several optional parameters. It reads each file concurrently using multiple threads, writes to the destination in chunks for optimal disk I/O performance, implements retry mechanism with configurable maximum retries and backoff strategy for handling potential IO errors. It also logs detailed information about the merging process. For handling large files it breaks them into smaller segments before merging and reassembles them correctly at the destination.

