import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import java.io.*;
import java.util.*;
import java.lang.ref.*;

public class JsonParser {
    private static final int MAX_CACHE_SIZE = 1000; // Adjust as needed
    private ObjectMapper objectMapper = new ObjectMapper();
    private Map<String, WeakReference<JsonNode>> cacheMap = Collections.synchronizedMap(new LinkedHashMap<String, WeakReference<JsonNode>>() {
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > MAX_CACHE_SIZE;
        }
    });

    public JsonNode parseAndCache(String jsonPath, String jsonDocument) throws IOException {
        WeakReference<JsonNode> cached = cacheMap.get(jsonPath);
        if (cached != null && cached.get() != null) {
            return cached.get(); // Return from the cache if available
        }

        JsonNode jsonNode = objectMapper.readTree(new File(jsonDocument)); 
        cacheMap.put(jsonPath, new WeakReference<>(jsonNode)); // Add to the cache

        return jsonNode;
    }
}
```
