void* convertImageThread(void* params) {
    ConversionParameters* p = (ConversionParameters*)params;

    // Lock semaphore before starting conversion
    sem_wait(&semaphore);
    ++numThreads;
    sem_post(&semaphore);

    convertImageToPdf(p);

    // Decrement thread count and post semaphore to allow next thread to start
    sem_wait(&semaphore);
    --numThreads;
    sem_post(&semaphore);

    pthread_exit(NULL);
}

int convertImagesToPdf(ConversionParameters* params) {
