    results = malloc(sizeof(ConversionResult)*numFiles);

    char** fileList = listFilesInDir(params->dirPath, params->pattern);

    sem_init(&semaphore, 0, 10); // Initialize semaphore with maximum of 10 threads

    pthread_t threads[numFiles];
    for (int i = 0; i < numFiles; ++i) {
        ConversionParameters* p = malloc(sizeof(ConversionParameters));
        p->dirPath = params->dirPath; // Set other parameters as required

        int rc = pthread_create(&threads[i], NULL, convertImageThread, (void*)p);
        if (rc) {
            handleError("Failed to create thread");
            return 1;
        }
    }

    // Wait for all threads to finish and clean up
    for (int i = 0; i < numFiles; ++i) {
        pthread_join(threads[i], NULL);
    }
    sem_destroy(&semaphore);

    int failedConversions = 0;
    for (int i = 0; i < numFiles; ++i) {
        if (!results[i].success) {
            ++failedConversions;
            handleError(strcat("Failed to convert ", results[i].filename));
        }
    }

    // Cleanup
    free(fileList);
    free(results);

    return failedConversions;
}
