public class AsyncDbQueryService 
{
    private readonly string _connectionString;

    public AsyncDbQueryService(IConfiguration config)
    {
        _connectionString = config.GetConnectionString("MyDatabase");
        Log.Logger = new LoggerConfiguration()
            .WriteTo.File("log.txt")  // local file logging 
            .WriteTo.ElasticsearchEvents("http://localhost:9200/", "{my-index}")  // logstash endpoint  
            .CreateLogger();
    }

    public async Task<SqlDataReader> ExecuteQueryAsync(byte[] byteArray)
    {
        var sqlCommand = GenerateSQLFromByteArray(byteArray);

        using (var connection = new SqlConnection(_connectionString)) 
        {
            await connection.OpenAsync();

            var command = new SqlCommand(sqlCommand, connection);

            // Apply the retry policy here:
            var policy = Policy
                .Handle<SqlException>()
                .WaitAndRetryAsync(3, 
                    attempt => TimeSpan.FromMilliseconds(100 * Math.Pow(2, attempt))); 

            SqlDataReader reader = null;

            try
            {
                await policy.ExecuteAsync(async () => 
                {
                   reader = await command.ExecuteReaderAsync();
                });  

                return reader;    // assuming you want to handle the data in your method
            } 
            catch (Exception e) 
            {
               Log.Error("Failed to execute SQL query: " + e);
               throw; // if needed, rethrow the exception after logging it
            }
        }  
    }

    private string GenerateSQLFromByteArray(byte[] byteArray)
    {
        // convert byte array into a readable format 
        var input = Encoding.UTF8.GetString(byteArray);

        // parse the input to generate SQL dynamically. This is upto you how you want to do it 
        return $"SELECT * FROM Table WHERE Column = {input}";
    }
}
