using System;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class SerializerFactory
{
    private readonly ILogger<SerializerFactory> logger;
    private readonly IConfiguration configuration;

    public SerializerFactory(ILogger<SerializerFactory> logger, IConfiguration configuration)
    {
        this.logger = logger;
        this.configuration = configuration;
    }

    public object DeserializeFromFile(string filePath)
    {
        var serializationFormat = configuration["Serialization:Format"]; // configurable format e.g., "BinaryFormatter", "Json"

        if (serializationFormat == "BinaryFormatter")
            return DeserializeWithBinaryFormatter(filePath);
        else if (serializationFormat == "Json")
            return DeserializeWithJsonNet(filePath);
        else throw new NotSupportedException("Unsupported serialization format");
    }

    private object DeserializeWithBinaryFormatter(string filePath)
    {
        // BinaryFormatter implementation goes here...
    }

    private object DeserializeWithJsonNet(string filePath)
    {
        try
        {
            using (Stream stream = File.Open(filePath, FileMode.Open))
            {
                var binaryFormatter = new BinaryFormatter();

                return binaryFormatter.Deserialize(stream);
            }
        }
        catch (SerializationException ex)
        {
            logger.LogError("Failed to deserialize. Reason: " + ex.Message);
        }
        catch (FileNotFoundException ex)
        {
            logger.LogError("The file cannot be found. Message: " + ex.Message);
        }

        return null;
    }
}
