```python
import time
from threading import Thread
import requests
from queue import Queue
# Assuming these are your email providers and their respective classes
from sendgrid_provider import SendGridProvider
from amazon_ses_provider import AmazonSESProvider
from mailgun_provider import MailGunProvider

class EmailNotificationService:
    def __init__(self, provider):
        self.rate_limit = {} # IP -> (last timestamp, token count)
        self.provider = provider 
        self.queue = Queue()
        self._start_worker()

    def sendNotificationEmail(self, email, content, ip):
        if not self._validate_email(email):
            return False, "Invalid Email"

        current_time = time.time()
        if ip in self.rate_limit and (current_time - self.rate_limit[ip][0]) < 1: # 1 second cooldown
            if self.rate_limit[ip][1] <= 0:
                return False, "Rate Limit Exceeded"

            self.rate_limit[ip] = (self.rate_limit[ip][0], self.rate_limit[ip][1]-1) 
        else: # Refill bucket
            self.rate_limit[ip] = (current_time, 100) 

        self._enqueue_email(email, content)
        return True, "Email queued for sending"

    def _start_worker(self):
        Thread(target=self.process_emails).start()

    def process_emails(self):
        while True: # run forever
            email, content = self.queue.get() 

            for retry in range(5):
                try:
                    if not self._send_email(email, content):
                        time.sleep((2**retry) * 0.1) # exponential backoff
                    else:
                        break
                except Exception as e:
                    print("Error sending email:", str(e))

    def _validate_email(self, email):
        try:
            # Regex to validate email format
            if not re.match(r"[^@]+@[^@]+\.[^@]+", email): 
                return False

            host = email.split('@')[-1]

            # Checking domain name availability using requests module
            if not self._check_domain(host):
                return False
        except Exception:
            return False

        return True

    def _check_domain(self, hostname):
        url = "http://" + hostname # assuming http
        try: 
            requests.get(url)
            return True
        except requests.ConnectionError:
            return False

    def _enqueue_email(self, email, content):
        self.queue.put((email, content))

    def _send_email(self, email, content):
        try:
            # Using the chosen provider to send emails
            self.provider.send(email, content) 
            return True
        except Exception as e:
            print("Error sending using selected provider:", str(e))

        return False
