    // Validate non-null and non-empty nature of database URL, username and password.
    if (config.databaseUrl == nullptr || config.username == nullptr || config.password == nullptr 
        || config.databaseUrl->empty() || config.username->empty() || config.password->empty()) {
        config.logger(ERROR, "Database URL, Username or Password is empty.");
