int count = 0;

void listFilesRecursively(char *basePath, char *pattern) {
    char path[1000];
    struct dirent *dp;
    DIR *dir = opendir(basePath);
    if (!dir) return;
    while ((dp = readdir(dir)) != NULL) {
        // Skipping files with '.' as the starting character
        if (strcmp(dp->d_name, ".") == 0 || strcmp(dp->d_name, "..") == 0) continue;
        // Construct new path from our base path
        strcpy(path, basePath);
        strcat(path, "/");
        strcat(path, dp->d_name);
        if (dp->d_type != DT_DIR) {
            /* Check for supported image formats */
            if (strcasestr(dp->d_name, pattern) != NULL) {
                pthread_mutex_lock(&lock);
                ImageFile *node = malloc(sizeof(ImageFile));
                node->filename = strdup(path);
                node->next = head;
                head = node;
                count++;
                pthread_mutex_unlock(&lock);
            }
        } else {
            /* Recursively search in subdirectories */
            listFilesRecursively(path, pattern);
        }
    }
    closedir(dir);
}

