```python
import os
from Crypto.Cipher import AES
from Crypto.Hash import SHA256
from base64 import b64encode, b64decode
from threading import Lock

class SecureFileStorage:
    def __init__(self):
        self.lock = Lock()

    def pad(self, s):
        return s + "\0" * (AES.block_size - len(s) % AES.block_size) 

    def encrypt(self, message, key):
        cipher = AES.new(key)
        padded_message = self.pad(message)
        return b64encode(cipher.encrypt(padded_message))

    def decrypt(self, encrypted, key):
        cipher = AES.new(key)
        message = cipher.decrypt(b64decode(encrypted))
        return message.rstrip("\0")

    def storeFile(self, filename, data, key):
        with self.lock:
            encrypted_data = self.encrypt(data, key)
            with open(filename, 'wb') as file:
                file.write(encrypted_data)

    def loadFile(self, filename, key):
        with self.lock:
            with open(filename, 'rb') as file:
                encrypted_data = file.read()
                decrypted_data = self.decrypt(encrypted_data, key)
                return decrypted_data
```

In this example, we use AES for simplicity but it can be extended to support multiple encryption algorithms by adding a mapping of algorithm names and functions in the SecureFileStorage class:

