```python
import hashlib
from flask import Flask, request, make_response
app = Flask(__name__)

class Script:
    def __init__(self, src, integrity=None):
        self.src = src
        if integrity is None:
            data = open(src, 'rb').read()  # in real scenario this might be a request to another server
            self.integrity = hashlib.sha256(data).hexdigest()
        else:
            self.integrity = integrity
        self.hits = 0
        self.misses = 0

scripts = []  # populate this list with Script objects
cache = {}  # cache for scripts content

@app.route('/script/<path:src>')
def script(src):
    if src in cache:  # cache hit
        script = cache[src]
        script.hits += 1
    else:  # cache miss
        try:
            script = next((x for x in scripts if x.src == src), None)
            script.misses += 1
            cache[script.src] = open(script.src, 'r').read()  # same as above
        except FileNotFoundError:
            return "Script not found", 404

    resp = make_response(cache[src], 200)
    resp.headers['Content-Type'] = 'application/javascript'
    resp.set_etag(script.integrity)
    if request.if_none_match == script.integrity:  # client has this version of the script
        return "Not Modified", 304

    return resp
```
