```rust
use hyper::service::{make_service, service_fn};
use hyper::client::{Client as HyperHttpClient, HttpConnector, Endpoint};
use futures::future;
use std::time::Duration;
use std::net::ToSocketAddrs;
use hyper::header::HeaderValue;

pub struct HttpClient {
    inner: HyperHttpClient<HttpsConnector>,
}

impl HttpClient {
    pub fn new(disable_certificate_validation: bool) -> Self {
        let https_connector = HttpsConnector::new(disable_certificate_validation);
        Self {
            inner: HyperHttpClient::new(https_connector),
        }
    }

    pub fn request(&self, url: &str) -> RequestBuilder {
        RequestBuilder::new(url, self.clone())
    }
}

pub struct HttpsConnector {
    inner: hyper::client::HttpConnector,
}

impl HttpsConnector {
    pub fn new(disable_certificate_validation: bool) -> Self {
        let https = hyper::server::conn::unencrypted_connector();
        Self { inner: https }
    }
}

impl HttpConnector for HttpsConnector {
    type Transport = hyper::client::Http;
    type Endpoint = Endpoint<Self::Transport>;

    fn connect(&self, url: hyper::Uri) -> future::FutureObj<Self::Transport, Self::Endpoint> {
        self.inner.connect(url)
    }
}

pub struct RequestBuilder {
    client: HttpClient,
    url: String,
    headers: Vec<(String, HeaderValue)>,
    timeout_duration: Option<Duration>,
    follow_redirects: bool,
}

impl RequestBuilder {
    fn new(url: &str, client: HttpClient) -> Self {
        Self {
            url: url.to_string(),
            headers: vec![],
            timeout_duration: None,
            follow_redirects: true,
            client,
        }
    }

    pub fn with_header(mut self, name: &str, value: HeaderValue) -> Self {
        self.headers.push((name.to_string(), value));
        self
    }

    pub fn with_timeout(mut self, duration: Duration) -> Self {
        self.timeout_duration = Some(duration);
        self
    }

    pub async fn send(&self) -> Result<hyper::Response, hyper::Error> {
        let mut request = client.get(uri).unwrap();

        for (name, value) in &self.headers {
            request.header_mut(name, *value);
        }

        if let Some(timeout) = self.timeout_duration {
            request.timeout(timeout);
        }

        if !self.follow_redirects {
            request.redirects(0);
        }

        match client.execute_request(request).await {
            Ok((response, _)) => Ok(response),
            Err(err) => Err(err.into())
        }
    }
}
```
This is a basic and incomplete implementation of an HTTP client in Rust using the `hyper` library. It supports creating requests with headers, timeouts and disabling redirects. The client also supports disabling certificate validation when creating a new instance via `HttpClient::new(disable_certificate_validation: bool)`.

