void* dynamicTrimAndCapitalize(void* arg) {
    char* inputString = (char*)arg;
    int wordListLength = 0;
    double avgWordLen = 0.0;

    // Fetch the list of words to be trimmed
    char** wordList = fetchWords(&wordListLength);

    // Calculate the average length of the fetched words
    for (int i = 0; i < wordListLength; i++) {
        avgWordLen += strlen(wordList[i]);
    }
    avgWordLen /= wordListLength;

    // Adjust the size limit based on the average word length
    int adjustedSizeLimit = (int)(strlen(inputString) - (avgWordLen * wordListLength));

    if (adjustedSizeLimit <= 0) {
        return NULL;  // Exit early if the string is too short to be trimmed and capitalized
    }

    char* result = malloc(sizeof(char) * adjustedSizeLimit);

    // Trim and Capitalize the first letter of each word in the resulting string
    for (int i = 0; i < wordListLength; i++) {
        if (!strncmp(inputString, wordList[i], strlen(wordList[i]))) {
            inputString += strlen(wordList[i]);  // Trim the beginning of the string
        }
    }

    int resultIndex = 0;
    while (*inputString != '\0' && resultIndex < adjustedSizeLimit) {
        result[resultIndex++] = toupper(*inputString++);  // Capitalize and copy each character

        if (strchr(wordList, *inputString) != NULL) {  // If the current character starts a word to be trimmed...
            while (*inputString != '\0' && strchr(wordList, *inputString)) {
                inputString++;  // ...skip over that word
            }
        }
    }

    for (int i = 0; i < wordListLength; i++) {
        free(wordList[i]);  // Free memory allocated to the fetched words
    }
    free(wordList);

    return result;
}
