async function asyncArrayReduce(array, initialValue, accumulator, config) {
  const { maxParallelOperations, throttleInterval, authToken, progressCallback } = config;

  // Check for invalid inputs or missing configuration parameters
  if (!array || !accumulator || !config) throw new Error('Invalid input');

  let accumulatedValue = initialValue;
  let completedOperations = 0;

  const semaphore = async (fn, ...args) => {
    // Implement a simple semaphore to control concurrency
    const queue = [];

    const runner = async () => {
      if (queue.length === 0 || queue[queue.length - 1].expires > Date.now()) {
        queue.push({ fn, args });
      }

      await new Promise(resolve => setTimeout(resolve, throttleInterval));

      const { fn: taskFn, args: taskArgs } = queue.shift();
      accumulatedValue = await taskFn(...taskArgs);
      completedOperations++;

      if (progressCallback) progressCallback({ value: accumulatedValue, operationsCompleted: completedOperations });
    };

    while (queue.length < maxParallelOperations) runner();
  };

  for (let i = 0; i < array.length; i++) {
    if (semaphore(accumulator, accumulatedValue, array[i], i, array)) break;
  }

  return accumulatedValue;
}
