#include <vector>
#include <mutex>
#include <ctime>

struct AttackProfile {
    int damage;
    int cost;
    // other attributes...

    time_t lastUsed = 0;
    int cooldown;
};

class Character {
public:
    std::vector<AttackProfile> attackProfiles;
    int health, energy;
    float distanceToEnemy;

    void updateState(int newHealth, int newEnergy, float newDistance) {
        health = newHealth;
        energy = newEnergy;
        distanceToEnemy = newDistance;
    }
};

class AttackSystem {
public:
    static AttackProfile chooseAttack(Character& character) {
        std::lock_guard<std::mutex> lock(m); // Ensuring thread-safe access.

        time_t currentTime = std::time(nullptr);
        for (auto &attack : character.attackProfiles) {
            if (character.health > 0 && 
                attack.lastUsed + attack.cooldown <= currentTime && 
                character.energy >= attack.cost) {

                // Attempting the attack
                character.energy -= attack.cost;
                attack.lastUsed = currentTime;
                return attack;
            }
        }

        // No valid attacks found, performing default action
        character.health--;
        return {};
    }
private:
    static std::mutex m; // Mutex for thread safety.
};
``` 
In this example, `chooseAttack()` is the main function that decides which attack to perform based on the character's state and available resources. If no valid attacks are found due to cooldown or resource limitations, a default action such as reducing health is performed. Note: In real-world scenarios, this decision would be more complex involving factors like enemy proximity, type of enemies etc. Also, it would take into account other conditions such as whether there are nearby allies, enemy's state, and so on.

