import com.fasterxml.jackson.databind.JsonNode;
import org.apache.kafka.clients.consumer.*;
import redis.clients.jedis.*;

public class MetricExtractor {
    private KafkaConsumer<String, String> consumer;
    private Jedis jedis;

    public MetricExtractor() {
        Properties props = new Properties();
        // Setup Kafka properties here...

        this.consumer = new KafkaConsumer<>(props);
        this.jedis = new Jedis("localhost");
    }

    public void extractMetricsFromKafka(List<String> metricsToExtract) throws IOException {
        consumer.subscribe(Collections.singletonList("input-topic"));

        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                try {
                    JsonNode rootNode = new ObjectMapper().readTree(record.value());
                    extractMetricsFromJson(rootNode, metricsToExtract);
                } catch (IOException e) {
                    handleError(e); // Handle errors here...
                }
            }
        }
    }

    private void extractMetricsFromJson(JsonNode rootNode, List<String> metricsToExtract) {
        for (String metric : metricsToExtract) {
            JsonNode node = rootNode.path(metric);

            // Handle missing fields here...
            if (!node.isMissingNode()) {
                jedis.set(metric, node.asText());
            } else {
                handleError("Missing field: " + metric); // Handle errors here...
            }
        }
    }
}
```
This class subscribes to a Kafka topic and extracts metrics from the consumed records. It uses Jackson for parsing JSON, and Jedis for interfacing with Redis.

