// A map to store supported file types and their corresponding digit counts
int digitCountMap[256] = {0};
pthread_mutex_t mapLock;

void initFileType(char *fileType, int digitCount) {
    pthread_mutex_lock(&mapLock);
    for (size_t i = 0; i < strlen(fileType); ++i) 
        digitCountMap[(int)toupper(fileType[i])] = digitCount;

    pthread_mutex_unlock(&mapLock);
}

// Remove file type from the map
void removeFileType(char *fileType) {
    pthread_mutex_lock(&mapLock);
    for (size_t i = 0; i < strlen(fileType); ++i) 
        digitCountMap[(int)toupper(fileType[i])] = 0;

    pthread_mutex_unlock(&mapLock);
}

// The main function that changes the filename's extension
void modifyExtension(char *filename, int newDigits) {
    if (newDigits < 1 || newDigits > 999) {
        printf("Error: Invalid digit count\n");
        return;
    }

    char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) {
        printf("Error: Missing or incorrect extension\n");
        return;
    }

    int digitCount = digitCountMap[(int)*++dot];
    if (digitCount == 0) {
        printf("Error: Unsupported file type\n");
        return;
    }

    char newExt[256] = "";
    sprintf(newExt, "%.*s.%0*d%s", dot - filename, filename, digitCount, newDigits, dot);

    strcpy(filename, newExt);
}

int main() {
    // Initialize the map lock
    pthread_mutex_init(&mapLock, NULL);

    // Add supported file types and their corresponding digit counts
    initFileType("TXT", 3);
    initFileType("JPG", 4);
    initFileType("PDF", 5);

    char filename[256] = "sample.txt";
    modifyExtension(filename, 10); // Modify the extension to "sample.010.txt"

    printf("%s\n", filename);

    return 0;
}
```

