```c
#include <openssl/ssl.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <dlfcn.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_NAME_LEN 2048
#define MAX_DIGESTS 16

typedef void* (*CryptoOperationFunc)(const EVP_MD*, const unsigned char*, size_t, unsigned char*, unsigned int*);

typedef struct Digest {
    const EVP_MD *(*getMDDigestFunc)();
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digestLen;
} Digest;

pthread_mutex_t mutexes[MAX_DIGESTS] = { PTHREAD_MUTEX_INITIALIZER };
Digest digests[MAX_DIGESTS];
int currentIndex = 0;

void* dlLoadFunction(const char *funcName) {
    void *handle = dlopen("libcrypto.so", RTLD_LAZY);
    if (!handle) return NULL;
    dlerror(); // clear any existing error
    void *funcAddr = dlsym(handle, funcName);
    char *error = dlerror();
    if (error != NULL) return NULL;
    return funcAddr;
}

int addDigest(const EVP_MD* (*getMDDigestFunc)()) {
    pthread_mutex_lock(&mutexes[currentIndex]);
    digests[currentIndex].getMDDigestFunc = getMDDigestFunc;
    currentIndex = (currentIndex + 1) % MAX_DIGESTS;
    pthread_mutex_unlock(&mutexes[currentIndex]);
}

Digest* performCryptoOperation(const EVP_MD* (*getMDDigestFunc)(), const unsigned char *data, size_t dataLen) {
    int digestIndex = -1;

    for (int i = 0; i < MAX_DIGESTS; ++i) {
        pthread_mutex_lock(&mutexes[i]);

        if (digests[i].getMDDigestFunc == getMDDigestFunc) {
            digestIndex = i;
            break;
        }

        pthread_mutex_unlock(&mutexes[i]);
    }

    if (digestIndex < 0) {
        CryptoOperationFunc funcAddr = dlLoadFunction("EVP_DigestInit"); // replace with actual function name
        if (!funcAddr) return NULL; // Handle error

        digestIndex = addDigest(getMDDigestFunc);
    }

    Digest *digest = &digests[digestIndex];
    (*funcAddr)(getMDDigestFunc(), data, dataLen, digest->digest, &digest->digestLen); // replace with actual function call

    pthread_mutex_unlock(&mutexes[digestIndex]);

    return digest;
}
```

