class ImageProcessor {
public:
    enum class Status {
        SUCCESS,
        FAILURE
    };

private:
    std::string inputPath;
    std::string outputDir;
    std::string formatType;
    Status status = Status::FAILURE;  // default to failure until successful conversion

public:
    ImageProcessor(const std::string& in, const std::string& out, const std::string& fmt) : inputPath(in), outputDir(out), formatType(fmt){}

    void processImage() {
        Magick::InitializeMagick(*argv);  // initialize ImageMagick library
        Magick::Image image;

        try {
            image.read(inputPath);
            image.magick(formatType);

            std::string outputPath = outputDir + "/output." + formatType;
            image.write(outputPath);  // save the processed image to specified directory

            status = Status::SUCCESS;
        } catch (Magick::Exception &error_) {
            status = Status::FAILURE;
            std::cerr << "Caught exception: " << error_.what() << std::endl;  // log the detailed information about each conversion attempt
        }
    }

    Status getProcessingStatus() const{
        return status;
    }
};
