#include <sys/stat.h>
#include <errno.h>
#include <string.h>

int create_log_file(const char *filename, const char *format) {
    // Creating a timestamp for log file name
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);

    // Creating a log file name with timestamp and format
    char log_file[1024];
    snprintf(log_file, 1024, "%s_%s.txt", filename, buffer);

    int fd = open(log_file, O_RDWR | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);

    if (fd == -1) {
        printf("open failed: %s\n", strerror(errno));
        return -1;
    }

    // Writing to the log file
    char message[50];
    snprintf(message, 50, "Log created at: %s with format: %s\n", buffer, format);

    if (write(fd, message, strlen(message)) != strlen(message)) {
        printf("write failed: %s\n", strerror(errno));
        return -1;
    }

    close(fd);
    return 0;
}
```
