#include <curl/curl.h>
#include <string>
#include <fstream>

class ImageCrawler {
public:
    enum RecorderType  { DATABASE, FILE };

    int recordTransaction(bool shouldRecord, RecorderType type, const std::string& details) {
        if (!shouldRecord) return 0;

        try {
            switch (type){
                case DATABASE:
                    // Implement database connection here
                    break;

                case FILE:
                    std::ofstream logFile("log.txt", std::ios_base::app | std::ios_base::out);
                    if(!logFile) {
                        return -1;  // Error code for file open failure
                    }
                    logFile << details << std::endl;
                    break;
            }
        } catch(const std::exception& e){
            return -2; // Error code for database write failure
        }

        return 0;  // Success
    }

    void crawlWebpage(const std::string &url) {
        CURL *curl = curl_easy_init();
        if(!curl){
            recordTransaction(true, FILE, "Failed to initialize libcurl");
            return;
        }

        // Set url and other curl options here...

        CURLcode res = curl_easy_perform(curl);

        /* Check for errors */ 
        if(res != CURLE_OK){
            recordTransaction(true, FILE, std::string("libcurl Error: ") + curl_easy_strerror(res));
        }

        /* always cleanup */ 
        curl_easy_cleanup(curl);
    }
};
```

