    delete vm_args.options;

    return env;
}

OctreeNode* initializeSerializableOctree(int featureSize, int initialLeafNodes, int maxDataCapacity) {
    OctreeNode *root = new OctreeNode();

    // Create a java virtual machine and environment for serialization 
    JavaVM *jvm;
    JNIEnv *env = create_vm(&jvm);

    ExternalApiWrapper api;
    std::string className = "com.example.MyClass";

    jobject cachedObj = NULL;
    auto itr = serializedClassCache.find(className);

    // Check if the class already exists in cache
    if (itr != serializedClassCache.end()) {
        cachedObj = itr->second;
    } else {
        jclass cls = env->FindClass(className.c_str()); 
        if (cls == NULL) {
            std::cerr << "Could not find class: " << className;
            return nullptr;
        }

        // Assume the API has method to serialize a java object and deserialize it back
        jbyteArray bytes = api.serialize(className); 
        if (bytes == NULL) {
            std::cerr << "Serialization failed for class: " << className;
            return nullptr;
        }

        cachedObj = env->NewObject(cls, bytes); // Deserialize the byte array to an object
        serializedClassCache[className] = cachedObj; 
    }

    // Continue with building the octree based on the cached object...

    return root;
}
