Here is a basic implementation of a `DynamicNetworkResolver` class in C++ using the Asio library for network I/O, JSON for configuration files, Boost Log for logging, and an unordered_map to store DNS servers:

```cpp
#include <boost/asio.hpp>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/log/core.hpp>
#include <boost/log/trivial.hpp>
#include <unordered_map>

using namespace boost::asio;
using namespace boost::property_tree;
namespace logging = boost::log;

class DynamicNetworkResolver {
public:
    void readConfig(const std::string& filename) {
        ptree pt;
        read_json(filename, pt);
        for (auto& server : pt.get_child("servers")) {
            dnsServers[server.second.data()] = server.first;  // Store servers in order of priority
        }
    }

    std::string resolveHostname(const std::string& hostname, const int timeout) {
        boost::unique_lock<boost::mutex> lock(mtx);   // Lock for thread safety

        if (dnsServers.empty()) {
            throw std::runtime_error("No DNS servers configured");
        }

        io_service service;
        ip::tcp::resolver resolver(service);
        boost::system::error_code ec;

        for (const auto& server : dnsServers) {
            BOOST_LOG_TRIVIAL(info) << "Resolving hostname " << hostname << " with DNS server " << server.first;
            resolver.async_resolve({hostname, ""}, [&](const boost::system::error_code &ec, ip::tcp::resolver::iterator it){ });

            service.reset(); // Reset IO Service to cancel any ongoing operations
            if (timeout > 0) {
                service.run_for(std::chrono::seconds(timeout)); 
            } else {
                service.run(); // Run until all async operations complete or timeout occurs
            }

            if (!ec && it != ip::tcp::resolver::iterator()) {
                BOOST_LOG_TRIVIAL(info) << "Hostname resolution successful with IP: " << it->endpoint().address();
                return it->endpoint().address().to_string();
            } else if (ec != boost::asio::error::operation_aborted) {
                BOOST_LOG_TRIVIAL(info) << "Hostname resolution failed: " << ec.message();
            }
        }

        throw std::runtime_error("Failed to resolve hostname");
    }

    void updateDNSServers(const std::string& filename) {
        boost::unique_lock<boost::mutex> lock(mtx);   // Lock for thread safety
        readConfig(filename);  // Read new configurations and store them in dnsServers map
    }

private:
    std::unordered_map<std::string, int> dnsServers; // Map to hold DNS servers with priorities
    boost::mutex mtx;   // Mutex for thread safety 
};
```
