public class ValueGenerator
{
    private readonly float minValueFloat;
    private readonly float maxValueFloat;

    private readonly int minValueInt;
    private readonly int maxValueInt;

    private static readonly Random rnd = new Random();

    public ValueGenerator(float min, float max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max");

        this.minValueFloat = min;
        this.maxValueFloat = max;

        this.minValueInt = (int)Math.Ceiling(min); // inclusive minimum
        this.maxValueInt = (int)Math.Floor(max);   // inclusive maximum
    }

