public interface StateManagementService {
    boolean isStateOutdated(String id);
    MoSTState getUpdatedStateFromExternalService(String id);
}

// Cache management and sync logic are abstracted into a separate module
@Slf4j
public class StateCacheManager {

    private final ConcurrentHashMap<String, MoSTState> stateCache = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();
    private final StateManagementService externalService;

    public StateCacheManager(StateManagementService externalService) {
        this.externalService = externalService;
    }

    public MoSTState getCachedStateOrLoadFromExternalService(String id, String filePath) throws IOException, ClassNotFoundException {
        if (stateCache.containsKey(id)) {
            return stateCache.get(id);
        } else {
            try(ObjectInputStream objectStream = new ObjectInputStream(new FileInputStream(filePath))) {
                MoSTState state = (MoSTState) objectStream.readObject();
                if (state != null && externalService.isStateOutdated(id)) {
                    MoSTState updatedState = externalService.getUpdatedStateFromExternalService(id);
                    // If there is any network error while syncing, 
                    // the program will catch this and handle it gracefully
                    lock.lock();
                    try {
                        stateCache.put(id, updatedState);
                    } finally {
                        lock.unlock();
                    }
                }
                return state;
            }
        }
    }

    // ... other methods for cache invalidation and periodic sync with external service
}
