```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

#define MAX_QUEUE_SIZE 100
#define FILE_URLS_LEN 20

typedef struct {
    char *fileUrls[FILE_URLS_LEN]; // queue of file URLs
    sem_t mutex;                  // binary semaphore for locking access to the queue
    sem_t slots;                  // counting semaphore, initially 0; producer increments this when adding an item to the queue.
    sem_t items;                  // counting semaphore, initially capacity of the queue; consumer decrements this when removing an item from the queue.
} Queue;

Queue *queue;
pthread_t producers[MAX_QUEUE_SIZE];
pthread_t consumers[MAX_QUEUE_SIZE];
int producerCount;
int consumerCount;

void initialize(int capacity) {
    if (capacity > MAX_QUEUE_SIZE) {
        fprintf(stderr, "Error: Queue size too large.\n");
        exit(1);
    }

    queue = malloc(sizeof *queue);
    sem_init(&queue->mutex, 0, 1);
    sem_init(&queue->slots, 0, capacity);
    sem_init(&queue->items, 0, 0);
}

void enqueue(char *fileUrl) {
    sem_wait(&queue->slots); // wait on available slots
    sem_wait(&queue->mutex); // lock access to the queue

    // add fileUrl to the queue

    sem_post(&queue->mutex); // unlock access to the queue
    sem_post(&queue->items); // signal that there is an item in the queue
}

char *dequeue() {
    char *fileUrl;

    sem_wait(&queue->items); // wait for items in the queue
    sem_wait(&queue->mutex); // lock access to the queue

    // remove and get fileUrl from the queue

    sem_post(&queue->mutex); // unlock access to the queue
    sem_post(&queue->slots); // signal that there is a free slot in the queue

    return fileUrl;
}

int isQueueEmpty() {
    int empty = 0;

    sem_wait(&queue->mutex); // lock access to the queue

    // check if the queue is empty

    sem_post(&queue->mutex); // unlock access to the queue

    return empty;
}

void *producer(void *param) {
    char fileUrl[FILE_URLS_LEN];

    while (1) {
        sprintf(fileUrl, "http://example.com/%d", rand()); // generate a random URL
        enqueue(fileUrl); // add it to the queue

        // check for stop condition and break if true
    }

    return NULL;
}

char *uploadFile(char *fileUrl) {
    // upload file using appropriate library or function

    return fileUrl; // returning the URL of uploaded file
}

void *consumer(void *param) {
    while (1) {
        if (!isQueueEmpty()) {
            char *fileUrl = dequeue(); // get an item from the queue

            uploadFile(fileUrl); // upload the file
        } else {
            printf("The queue is empty.\n");
        }

        // check for stop condition and break if true
    }

    return NULL;
}
```
