```java
import java.io.*;
import java.util.*;
import java.util.regex.*;
import javax.imageio.ImageIO;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.JPEGFactory;
import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.concurrent.*;

public class Converter {
    private ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public int convertImagesToPdf(String inputDir, String outputPath) throws IOException, InterruptedException, ExecutionException {
        File dir = new File(inputDir);
        if (!dir.exists() || !dir.isDirectory()) throw new IllegalArgumentException("Input directory does not exist or is not a directory");

        Pattern pattern = Pattern.compile(".+\\.(jpg|jpeg|png)$", Pattern.CASE_INSENSITIVE);

        // List all matching image files in the input directory
        File[] images = dir.listFiles(file -> pattern.matcher(file.getName()).find());
        Arrays.sort(images, Comparator.comparing(File::getName));

        PDDocument document = new PDDocument();
        int failures = 0;

        List<Future<BufferedImage>> futureImages = new ArrayList<>();

        for (File image : images) {
            Future<BufferedImage> futureImage = executor.submit(() -> ImageIO.read(image));
            futureImages.add(futureImage);
        }

        for (Future<BufferedImage> futureImage : futureImages) {
            BufferedImage buffImg = futureImage.get();

            PDPage page = new PDPage(new PDRectangle((float)(buffImg.getWidth() / 72 * buffImg.getHeight()), (float)(buffImg.getHeight() / 72 * buffImg.getWidth())));

            document.addPage(page);

            try (PDPageContentStream contentStream = new PDPageContentStream(document, page)) {
                AffineTransform at = AffineTransform.getScaleInstance((float) page.getMediaBox().getWidth() / buffImg.getWidth(), (float) page.getMediaBox().getHeight() / buffImg.getHeight());

                BufferedImage img = new BufferedImage(page.getMediaBox().width, page.getMediaBox().height, BufferedImage.TYPE_INT_RGB);
                Graphics2D g2d = img.createGraphics();

                g2d.drawRenderedImage(buffImg, at);
                g2d.dispose();

                contentStream.drawImage(JPEGFactory.createFromImage(document, img), 0f, 0f);
            } catch (Exception e) {
                failures++;
                System.err.println("Failed to convert image " + image.getName() + ". Reason: " + e.getMessage());
            }
        }

        document.save(outputPath);
        executor.shutdown();

        return failures;
    }
}
```
