import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.regex.Pattern;

public class EmailValidator {
    private final Lock lock = new ReentrantLock();
    private Map<String, Pattern> domainRules = new HashMap<>();
    private ApiService apiService;

    public void loadDomainRule(String domain, String rule) {
        // Validate domain and rule
        domainRules.put(domain, Pattern.compile(rule));
    }

    public boolean validateEmail(String email) throws InterruptedException {
        try {
            lock.lock();
            int atIndex = email.indexOf('@');

            if (atIndex == -1 || atIndex == 0 || atIndex == email.length() - 1) return false;

            String domain = email.substring(atIndex + 1);
            Pattern rule = domainRules.get(domain);

            if (rule != null && rule.matcher(email).find()) {
                try {
                    // Call API to check additional rules
                    return apiService.validateEmail(email);
                } catch (ApiException e) {
                    throw new RuntimeException("API exception", e);
                }
            }

            return false;
        } finally {
            lock.unlock();
        }
    }

    public void runTests(List<String> emails) {
        for (String email : emails) {
            try {
                boolean isValid = validateEmail(email);
                System.out.println("Email: " + email + ", Result: " + (isValid ? "Pass" : "Fail"));
            } catch (InterruptedException e) {
                // Handle exception and log information to the console
                System.out.println("Interrupted while validating email: " + email);
                Thread.currentThread().interrupt();
            } catch (RuntimeException e) {
                System.out.println("Validation failed for email: " + email);
                e.printStackTrace();
            } finally {
                // Cleanup and isolation between tests by resetting mocking library 
                Mockito.reset(apiService);
            }
        }
    }

    public interface ApiService {
        boolean validateEmail(String email) throws InterruptedException, ApiException;
    }
}
```
This code uses a `HashMap` to store domain-specific regular expressions as values and domains as keys. 

The method `validateEmail` checks if an email address matches the defined rules for its domain. If no rule is found or the validation fails, it calls a remote API service (represented by the `ApiService` interface) to perform additional checks against a remote service. The method throws `InterruptedException` when the thread executing this code is interrupted while waiting, such as during shutdown.

The `runTests` function runs through an array of emails and validates them one by one, logging the results and handling potential exceptions in a graceful manner. After each test, it resets the mocking library to maintain isolation between tests. 

