```C++
#include <memory>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <libpq-fe.h> // PostgreSQL driver

class ConnectionPool {
public:
    using Connection = std::unique_ptr<PGconn, std::function<void(PGconn*)>>;

    struct Config {
        int maxSize = 10; // maximum connection pool size
        int timeout = 5; // connection timeout in seconds
        std::string connInfo = "dbname=test user=postgres password=secret"; // PostgreSQL connection string

        std::function<void(const std::string&)> onLog = [](auto){}; // callback for logging to external service
    };

private:
    std::queue<Connection> pool_;
    int maxSize_, timeout_;
    std::mutex mutex_;
    std::condition_variable cv_;
    Config config_;

public:
    ConnectionPool(Config config) : config_(std::move(config)), maxSize_(config_.maxSize), timeout_(config_.timeout) {
        for (int i = 0; i < maxSize_; ++i) pool_.emplace(createConnection());
    }

    // Acquire a connection from the pool. Blocks if there are no available connections.
    Connection acquire() {
        std::unique_lock<std::mutex> lock(mutex_);

        cv_.wait(lock, [this](){ return !pool_.empty(); });

        auto conn = std::move(pool_.front());
        pool_.pop();

        config_.onLog("Connection acquired");
        return conn;
    }

    // Release a connection back to the pool. If no connections are available, blocks until one becomes free.
    void release(Connection&& conn) {
        if (!conn) {
            config_.onLog("Invalid connection released");
            return;
        }

        std::unique_lock<std::mutex> lock(mutex_);

        cv_.wait(lock, [this](){ return pool_.size() < maxSize_; });

        pool_.push(std::move(conn));
        config_.onLog("Connection released");
    }

private:
    Connection createConnection() {
        auto conn = PQconnectdb(config_.connInfo.c_str());
        if (PQstatus(conn) != CONNECTION_OK) throw std::runtime_error(PQerrorMessage(conn));

        return {conn, [this](PGconn* p){ config_.onLog("Connection closed"); PQfinish(p); }};
    }
};
```
This is a basic example of how you could structure the connection pool in C++. Please remember that you will need to handle race conditions and error handling scenarios according to your use case. You might also want to improve this code by adding better logging, customizable parameters, etc. For instance, it's common to use an external library like Boost or POCO for PostgreSQL connection pooling in C++.

