using System.Threading.Tasks;
using ThirdPartyCSP; // replace this with actual namespace of third-party CSP

public interface ICryptoProviderAdapter
{
    Task<string> DecryptAsync(string base64EncodedMessage, string contextId);
}

public class SecureMessageHandler
{
    private readonly Dictionary<string, ICryptoProviderAdapter> _cryptoProviders;

    public SecureMessageHandler()
    {
        _cryptoProviders = new Dictionary<string, ICryptoProviderAdapter>();
    }

    public void RegisterCSP(string name, ICryptoProviderAdapter cryptoProvider)
    {
        if (!_cryptoProviders.ContainsKey(name))
            _cryptoProviders.Add(name, cryptoProvider);
    }

    public string DecryptMessage(string base64EncodedMessage, string contextId)
    {
        return Task.Run(() => DecryptMessageAsync(base64EncodedMessage, contextId)).Result;
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId)
    {
        if (!_cryptoProviders.ContainsKey(contextId))
            throw new Exception("Context not registered");

        return await _cryptoProviders[contextId].DecryptAsync(base64EncodedMessage, contextId);
    }
}
```

