```python
import json, uuid, datetime
from decimal import Decimal

class JSONSerializable(object):
    _registry = {}

    def __init__(self, id=None):
        self.id = id if id else str(uuid.uuid4())

    @staticmethod
    def add_factory_function(id, func):
        JSONSerializable._registry[id] = func

    @staticmethod
    def create_instance_from_id(id):
        if id not in JSONSerializable._registry:
            raise ValueError('Factory function for the ID does not exist')

        return JSONSerializable._registry[id]()

    def to_json(self):
        data = {k: v for k, v in self.__dict__.items() if not callable(v) and not k.startswith('__')}

        # Convert datetime and Decimal objects into ISO format and string respectively
        for key, value in data.items():
            if isinstance(value, (datetime.datetime, datetime.date)):
                data[key] = value.isoformat()
            elif isinstance(value, Decimal):
                data[key] = str(value)

        return json.dumps({**data, '__id': self.id})

    @classmethod
    def from_json(cls, json_string):
        data = json.loads(json_string)

        # Check if ID is present in the data and create instance using it
        if '__id' in data:
            return cls.create_instance_from_id(data['__id'])(**{k: v for k, v in data.items() if k != '__id'})

        # If ID is not present, create instance of the class itself
        else:
            return cls(**data)
``` 

This code works by storing a registry of factory functions that are used to create new instances based on their associated ID. The `to_json` method converts the object's attributes into a JSON string, and `from_json` does the reverse. For datetime and Decimal objects, it uses ISO formatting and string representation respectively when serializing and deserializing.

