```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.kafka.clients.producer.*;

public class NonBlockingConnectionPool {

    private final Selector selector;
    private final Map<String, Connection> connections = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public NonBlockingConnectionPool() throws IOException {
        this.selector = Selector.open();
    }

    public void addAddresses(List<String> addresses) {
        for (String address : addresses) {
            String[] hostAndPort = address.split(":");
            InetSocketAddress socketAddress = new InetSocketAddress(hostAndPort[0], Integer.parseInt(hostAndPort[1]));
            addConnection(new Connection(socketAddress));
        }
    }

    public void addConnection(Connection connection) {
        connections.put(connection.getHost(), connection);
        selector.wakeup(); // Wakes up the selector for new connections
    }

    public void processConnections() throws IOException {
        while (!Thread.currentThread().isInterrupted()) {
            int selected = selector.selectNow(); // non-blocking select
            if (selected == 0) continue;
            Set<SelectionKey> keys = selector.selectedKeys();
            for (SelectionKey key : keys) {
                Connection connection = (Connection) key.attachment();
                if (!key.isValid()) {
                    connections.remove(connection.getHost());
                    continue;
                }
                if (key.isConnectable()) {
                    SocketChannel socketChannel = (SocketChannel) key.channel();
                    boolean isConnected = socketChannel.finishConnect();
                    connection.setIsConnected(isConnected);
                    System.out.println("Connection " + (isConnected ? "established" : "failed"));
                } else if (key.isReadable()) {
                    ByteBuffer buffer = ByteBuffer.allocate(1024);
                    SocketChannel socketChannel = (SocketChannel) key.channel();
                    int readBytes = socketChannel.read(buffer);
                    System.out.println("Received " + readBytes + " bytes");
                }
            }
            keys.clear(); // clears selected keys for next iteration
        }
    }

    public void sendMessageToKafka(String topic, String message) {
        Producer<String, String> producer = new KafkaProducer<>(createProperties());
        producer.send(new ProducerRecord<>(topic, message), (metadata, exception) -> {
            if (exception != null) {
                System.out.println("Failed to send message: " + exception);
            } else {
                System.out.println("Message sent to topic: " + metadata.topic());
            }
        });
    }

    // Helper methods and classes
}
```
This code provides a basic structure for the non-blocking connection pool that is managed by a selector. It utilizes a `ConcurrentHashMap` to store all connections. The `addAddresses()` method adds multiple addresses, each of which creates a new `Connection` object and adds it to the map. If no new connections arrive, the `processConnections()` method simply returns immediately, avoiding blocking. Once a connection is ready for reading or writing, appropriate logic is executed to handle the event.

A separate thread is responsible for sending messages to Apache Kafka. This method sends the message asynchronously using the Kafka Producer's `send()` method, which provides a callback mechanism to handle successful and failed send operations. The `createProperties()` method creates a new Properties object with the necessary Kafka producer properties, such as bootstrap servers, serializers, etc.

Remember to close all channels and sessions in the finally block or use try-with-resources statement for automatic resource management. For testing, mock objects can be used instead of real ones. For maintainability, keep the code modular, follow good practices like writing unit tests, and remember that a good design allows easy updates and modifications in the future.

