```csharp
using System;
using System.Text;
using System.IO;
using System.Security.Cryptography;

public class AuthenticationException : Exception
{
    public AuthenticationException(string message) : base(message){}
}

public class DecryptionService 
{
    private readonly byte[] key; // This should be securely managed and cleaned up after use
    private readonly byte[] iv;  // Same as above

    public DecryptionService(byte[] key, byte[] iv)
    {
        this.key = key;
        this.iv = iv;
    }

    public string DecryptAndValidateMessage(string encryptedBase64String, byte[] hmacKey) 
    {
        try 
        {
            // Convert Base64 to bytes
            var encryptedBytes = Convert.FromBase64String(encryptedBase64String);

            // Decrypt using Triple DES
            using (var tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;

                var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

                using (var msDecrypt = new MemoryStream(encryptedBytes)) 
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) 
                    {
                        using (var srDecrypt = new StreamReader(csDecrypt)) 
                        {                            
                            var plaintext = srDecrypt.ReadToEnd();

                            // Validate HMAC
                            if (!IsValidHmac(encryptedBytes, hmacKey, Convert.FromBase64String(plaintext)))
                                throw new AuthenticationException("Message failed to authenticate");

                            return plaintext;
                        }
                    }
                }
            }
        } 
        catch (CryptographicException e) 
        {
            Console.WriteLine("Failed to decrypt: " + e.Message);
            throw new AuthenticationException(e.Message);
        }
    }

    private bool IsValidHmac(byte[] encryptedBytes, byte[] hmacKey, byte[] plaintext) 
    {
        using (var hmacsha256 = new HMACSHA256(hmacKey)) 
        {
            var hash = hmacsha256.ComputeHash(encryptedBytes);

            return hash == plaintext;
        }
    }
}
```
