```python
import csv 
import argparse

def process_csv(files, columns, separator=',', output=None):

    # Read command line arguments
    parser = argparse.ArgumentParser()
    parser.add_argument('files', nargs='+')
    parser.add_argument('--columns', required=True)
    parser.add_argument('--separator', default=',')
    parser.add_argument('--output')

    args = parser.parse_args()

    files = args.files
    columns = args.columns.split(',')
    separator = args.separator
    output = args.output

    for file in files:
        with open(file, 'r') as csv_file:
            reader = csv.DictReader(csv_file, delimiter=separator)

            if output is None:
                print('\t'.join([column for column in columns]))
            else:
                with open(output, 'w') as out_file:
                    out_file.write('\t'.join([column for column in columns]) + '\n')

            for row in reader:
                if not all(col in row for col in columns):
                    raise Exception("Incorrect column names")

                data = [row[column] for column in columns]

                # Output data 
                if output is None:
                    print('\t'.join(data))
                else:
                    with open(output, 'a') as out_file:
                        out_file.write('\t'.join(data) + '\n')
```
