Next we will create a registry of factory functions keyed by ID:
```rust
use std::collections::HashMap;
use std::fmt;

struct FactoryRegistry<T> {
    factories: HashMap<String, Box<dyn Fn(&str) -> T>>,
}

impl<T> FactoryRegistry<T> {
    fn new() -> Self {
        FactoryRegistry {
            factories: HashMap::new(),
        }
    }

    fn add_factory<F>(&mut self, id: &str, factory: F)
    where
        F: 'static + Send + Sync + fmt::Debug + (Fn(&str) -> T),
    {
        let _ = self.factories.insert(id.to_string(), Box::new(factory));
    }

    fn create(&self, id: &str, data: &str) -> Option<T> {
        if let Some(f) = self.factories.get(id) {
            Some((*f)(data))
        } else {
            None
        }
    }
}
```
