    std::chrono::seconds cooldown;
    bool onCooldown = false;
};

class Character {
public:
    explicit Character(int health) : health_(health) {}

    void updateHealth(int health) {
        std::lock_guard<std::mutex> lock(mtx_);
        health_ = health;
    }
private:
    int health_;
    std::array<Attack, 5> attacks_;
    mutable std::mutex mtx_;
};

void attackCharacter(Character& character) {
    while (true) {
        auto currentHealth = [&character]() -> int {
            std::lock_guard<std::mutex> lock(character.mtx_);
            return character.getHealth();
        }();

        if (currentHealth == 0) {
            // perform default action
            continue;
        }

        bool attackSelected = false;
        Attack selectedAttack;
        for (const auto& attack : character.attacks_) {
            if (!attack.onCooldown && currentHealth >= attack.damage) {
                attackSelected = true;
                selectedAttack = attack;
                break;
            }
        }

        if (!attackSelected) {
            // perform default action
            continue;
        }

        selectedAttack.onCooldown = true;

        std::this_thread::sleep_for(selectedAttack.cooldown); 
        selectedAttack.onCooldown = false;
    }
}

int main() {
    Character character(100);

    // simulate the game loop running in a separate thread
    std::thread gameThread(attackCharacter, std::ref(character));

    while (true) {
        int health;
        std::cin >> health;

        if (health < 0) {
            break;
        }

        character.updateHealth(health);  // update the Character's state through an API call
    }

    gameThread.join();

    return 0;
}
```
