```cpp
#include <Magick++.h>
#include <json/json.h>
#include <fstream>
#include <mutex>
#include <thread>
#include <atomic>
#include <vector>
#include <exception>

enum class Status {
  SUCCESS,
  FAILURE,
};

class ImageConverter {
public:
  ImageConverter(std::string inputPath, std::string outputPath, std::string format) :
    m_inputPath{inputPath},
    m_outputPath{outputPath},
    m_format{format} {}

  void convertAndSave() {
    // Lock the mutex before accessing conversionCount
    std::lock_guard<std::mutex> lock(m_conversionMutex);
    ++m_ongoingConversions;

    try {
      Magick::Image image{m_inputPath};
      image.magick(m_format);

      // Check if the maximum number of concurrent conversions has been reached
      while (m_ongoingConversions > m_maxConcurrentConversions) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
      }

      image.write(m_outputPath);
    } catch (const std::exception& e) {
      // Handle exception and log the error
      m_errorLog << "Exception caught: " << e.what() << ". File path: " << m_inputPath << "\n";

      if(m_retryOnFail) {
        --m_ongoingConversions;
        convertAndSave(); // Retry the conversion on failure
      } else {
        --m_ongoingConversions;
        return reportProgress(0, Status::FAILURE); 
      }
    }

    --m_ongoingConversions;
    reportProgress(100, Status::SUCCESS);
  }

  void setMaxConcurrentConversions(int max) { m_maxConcurrentConversions = max;}

  void cancelOngoingConversion() {m_cancelRequested = true;}

  // Additional methods omitted for brevity. Please refer to the full code.
private:
  std::string m_inputPath;
  std::string m_outputPath;
  std::string m_format;

  int m_ongoingConversions{0};
  int m_maxConcurrentConversions{1}; // Default to single threaded conversion.
  bool m_retryOnFail = false;
  std::atomic<bool> m_cancelRequested{false};

  mutable std::mutex m_conversionMutex; // For synchronizing access to ongoingConversions

  std::ofstream m_errorLog{"imageConverterError.log"};
};
