Here is an example of how you could implement such a configuration management system in C++ using nlohmann/json, boost::variant for type checking and range constraints, shared_ptr for memory management, observer pattern for notifications, and exception handling for I/O errors.

```cpp
#include <nlohmann/json.hpp>
#include <boost/variant.hpp>
#include <fstream>
#include <iostream>
#include <map>
#include <vector>
#include <memory>

class ConfigObserver {
public:
    virtual void update() = 0;
};

class ConfigSettings {
private:
    using SettingsVariant = boost::variant<int, double, bool, std::string>;

    std::map<std::string, SettingsVariant> m_settings;
    std::vector<ConfigObserver*> m_observers;

public:
    void loadFromFile(const std::string& filePath) {
        try {
            std::ifstream ifs(filePath);

            if (!ifs.good()) throw std::runtime_error("Failed to open the file.");

            nlohmann::json j;
            ifs >> j;
            for (nlohmann::json::iterator it = j.begin(); it != j.end(); ++it) {
                m_settings[it.key()] = it.value();
            }

            notifyObservers();
        } catch(const std::exception& e) {
            std::cerr << "An exception occurred: " << e.what() << '\n';
        } catch(...) {
            std::cerr << "An unknown error occurred\n";
        }
    }

    void saveToFile(const std::string& filePath) const {
        nlohmann::json j;
        for (const auto& pair : m_settings) {
            j[pair.first] = pair.second;
        }

        std::ofstream ofs(filePath);
        if (!ofs.good()) throw std::runtime_error("Failed to open the file.");

        ofs << j;
    }

    template<typename T>
    const T& getSetting(const std::string& key) const {
        auto it = m_settings.find(key);
        if (it != m_settings.end()) {
            return boost::get<T>(it->second);
        } else {
            throw std::out_of_range("No setting with key '" + key + "' found.");
        }
    }

    void addObserver(ConfigObserver* observer) {
        m_observers.push_back(observer);
    }

    void removeObserver(ConfigObserver* observer) {
        auto it = std::find(m_observers.begin(), m_observers.end(), observer);
        if (it != m_observers.end()) {
            m_observers.erase(it);
        }
    }

    void notifyObservers() const {
        for (auto observer : m_observers) {
            observer->update();
        }
    }
};

std::shared_ptr<ConfigSettings> getSettingsFromFile(const std::string& filePath){
    auto settings = std::make_shared<ConfigSettings>();
    settings->loadFromFile(filePath);

    return settings;
}
```
This code is not complete and will only compile if the required libraries (nlohmann/json, boost) are installed and included. It also requires C++14 or newer due to usage of std::shared_ptr. This is a simple starting point for such a system with no validation checks on range constraints or types. You could implement these checks by checking the type before casting it in the getSetting() function.

