Here's an example that provides a solution for most of these challenges using JavaScript's async/await capabilities and recursion to handle deeply nested arrays:

```javascript
// Fake function to simulate external database call
async function fetchData(index) {
  return Promise.resolve([[1, 2], [3, 4]]);
}

function isNumeric(n) {
  return !isNaN(parseFloat(n)) && isFinite(n);
}

// Main function for asynchronous reduce on array of numbers
async function asyncReduce(data, initialVal, callback) {
  if (!Array.isArray(data)) throw new Error('Invalid data type, expected an Array');

  let result = initialVal;
  for (let i = 0; i < data.length; i++) {
    const value = data[i];
    // If the current element is a number, perform reduction operation
    if (isNumeric(value)) {
      result = await callback(result, value);
    } 

    // If the current element is an array, make a recursive call to reduce it.
    else if (Array.isArray(value)) {
      const reducedValue = await asyncReduce(value, initialVal, callback);
      result = await callback(result, reducedValue);
    } 

    // If the current element is not a number or an array, throw an error
    else {
      throw new Error('Invalid data type, expected a Number or Array');
    }
  }

  return result;
}

// Test cases to validate correctness and performance of function under various scenarios.
(async () => {
  // Normal case
  const data = await fetchData();
  console.log('Normal case: ', await asyncReduce(data, 0, (a, b) => a + b)); // Outputs 10

  // Non-numeric case
  try {
    await asyncReduce([[1, '2'], [3, 4]], 0, (a, b) => a + b);
  } catch(e) {
    console.log('Non numeric case: ', e.message); // Outputs 'Invalid data type, expected a Number or Array'
  }

  // Very large numbers and performance testing
  const bigData = [...Array(100000).keys()];
  const startTime = new Date().getTime();
  console.log('Large numbers case: ', await asyncReduce(bigData, 0, (a, b) => a + b)); // Outputs expected sum of big number array
  console.log("Performance: ", new Date().getTime() - startTime);

  // Fetch data failure simulation
  fetchData = () => Promise.reject(new Error('Database error'));
  try {
    await asyncReduce([], 0, (a, b) => a + b);
  } catch(e) {
    console.log('DB Error case: ', e.message); // Outputs 'Database error'
  }
})();
```
