// This is an example code snippet that doesn't cover everything as mentioned in the problem, but will give you some idea how it can be handled.
let cache = {};
const lruCacheSize = 10;
let aggregationResult = null;

function callback(accumulatedValue, currentItem, index) {
  let valueToAdd = isNaN(Number(currentItem)) ? 0 : Number(currentItem);

  // Error handling for division by zero and undefined values
  if (valueToAdd === 0 && accumulatedValue === Infinity) {
    throw new Error("Division by zero error");
  } else if (!valueToAdd || !accumulatedValue) {
    throw new Error("Undefined value detected");
  }

  return accumulatedValue + valueToAdd;
}

async function asyncArrayAggregate(array, callback) {
  let result = array.reduce((previousValue, currentItem, index) => {
      try {
        previousValue = callback(previousValue, currentItem, index);
      } catch (error) {
        console.log("Error: ", error.message);
      }
    return previousValue;
  }, aggregationResult || 0);

  // LRU cache implementation for external API calls
  const key = JSON.stringify(array);
  if (!cache[key]) {
    if (Object.keys(cache).length >= lruCacheSize) {
      delete cache[Object.keys(cache)[0]];
    }

    cache[key] = result;
  } else {
    // Fetch from cache instead of external API call when available
    result = cache[key];
  }

  aggregationResult = result;
  return Promise.resolve(result);
}
```
This simplified version uses the JavaScript built-in `reduce` function for array aggregation, and implements a simple LRU cache to store the results of external API calls. The error handling is done by using a try-catch block in the callback function which catches any errors thrown during computation. 

