```C#
using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;

public class DecryptionService
{
    private readonly byte[] key;
    private readonly byte[] iv;

    public DecryptionService(byte[] key, byte[] iv)
    {
        this.key = key;
        this.iv = iv;
    }

    public string DecryptAndValidateMessage(string encryptedBase64String, byte[] hmacKey, byte[] expectedHMACBytes)
    {
        // Decode Base64 encoded message
        var cipherText = Convert.FromBase64String(encryptedBase64String);

        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            // Initialize the decryption process
            tripleDes.Mode = CipherMode.CBC;
            tripleDes.Key = key;
            tripleDes.IV = iv;

            var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

            // Decrypt the cipher text to plaintext
            using (var memoryStream = new MemoryStream(cipherText))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                {
                    var buffer = new byte[cipherText.Length];
                    var decryptedByteCount = cryptoStream.Read(buffer, 0, buffer.Length);

                    // Validate HMAC
                    using (var hmacsha256 = new HMACSHA256(hmacKey))
                    {
                        byte[] computedHashBytes = hmacsha256.ComputeHash(buffer, 0, decryptedByteCount);

                        if (!ConstantTimeComparison(computedHashBytes, expectedHMACBytes))
                        {
                            throw new AuthenticationException("Invalid HMAC");
                        }
                    }

                    // Convert the plaintext bytes to string and return it
                    return Encoding.UTF8.GetString(buffer, 0, decryptedByteCount);
                }
            }
        }
    }

    private static bool ConstantTimeComparison(byte[] a, byte[] b)
    {
        if (a.Length != b.Length)
        {
            return false;
        }

        var areEqual = true;

        for (var i = 0; i < a.Length; i++)
        {
            areEqual &= (a[i] == b[i]);
        }

        return areEqual;
    }
}
```

The `ConstantTimeComparison` method is used to avoid timing attacks by always executing the same number of operations regardless of whether or not the byte arrays are equal. 

This function decrypts a message using Triple DES with CBC mode and validate the integrity of the message by computing an HMAC SHA256 hash over the decrypted message and comparing it to the expected hash. If they don't match, an `AuthenticationException` is thrown.

