// Simple cache implementation using LRU strategy
class Cache {
  constructor(max = 5) {
    this.cache = new Map();
    this.maxSize = max;
  }

  get(key) {
    let item = this.cache.get(key);
    if (item) {
      // refresh key for LRU strategy
      this.cache.delete(key);
      this.cache.set(key, item);
    }
    return item;
  }

  set(key, val) {
    // remove oldest entry when reaching max size
    if (this.cache.size === this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
    this.cache.set(key, val);
  }
}

const cache = new Cache();
let pendingPromises = 0;
// Function to fetch and return content from URL
async function fetchScriptContent(src) {
  if (cache.get(src)) {
    console.log('From cache');
    return Promise.resolve(cache.get(src));
  } else if (pendingPromises >= 5) { // Throttle concurrent requests to no more than 5 at a time
    await new Promise((resolve) => setTimeout(resolve, 100));
    return fetchScriptContent(src);
  } else {
    pendingPromises++;
    try {
      const res = await fetchFromCDN(src); // Pseudo-code for fetching from CDNs
      cache.set(src, res);
      console.log('Fetched');
      return Promise.resolve(res);
    } catch (err) {
      console.error(err);
      return '';
    } finally {
      pendingPromises--;
    }
  }
}

async function renderFooterScripts(scripts) {
