  const sortedScripts = scripts.sort((a, b) => a.priority - b.priority);

  for (let script of sortedScripts) {
    if (!script || !script.src || !script.type) {
      console.error('Invalid script object: ', script);
      continue;
    }

    const content = await fetchScriptContent(script.src);
    // If content is empty string, it means there was an error fetching the script, so don't include this in rendered HTML
    if (content) {
      html += `<script src="${script.src}" type="${script.type}"></script>\n`;
    }
  }

  return html;
}
