use std::process::exit;
use std::error::Error;

static CACHE_DIR: Arc<Mutex<Option<String>>> = Arc::new(Mutex::new(None));
const DEFAULT_CLEANUP_INTERVAL: u64 = 24 * 3600; // 24 hours in seconds

fn get_cache_dir() -> Result<PathBuf, Box<dyn Error>> {
    let cache_dir = match CACHE_DIR.lock().unwrap().as_ref() {
        Some(dir) => dir,
        None => env::var("CACHE_DIR")?,
    };

    fs::create_dir_all(&cache_dir)?;
    set_env_variable("CACHE_PATH", &cache_dir)?;

    Ok(PathBuf::from(cache_dir))
}

fn set_env_variable(key: &str, value: &String) -> Result<(), Box<dyn Error>> {
    env::set_var(key, value);
    Ok(())
}

fn cleanup_old_files() {
    let cache_dir = match get_cache_dir() {
        Err(err) => {
            eprintlnlnmacro_rulescannont be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()macro_rulescannot be reproduced due to insufficient reputation()
            exit(-1);
        },
        Ok(dir) => dir,
    };

    let cleanup_interval = match env::var("CLEANUP_INTERVAL") {
        Err(_) => DEFAULT_CLEANUP_INTERVAL,
        Ok(interval) => interval.parse().unwrap_or(DEFAULT_CLEANUP_INTERVAL),
    };

    let elapsed = Duration::from_secs(cleanup_interval);
    thread::spawn(move || {
        loop {
            thread::sleep(elapsed);
            for entry in fs::read_dir(&cache_dir).unwrap() {
                if let Ok(entry) = entry {
                    let metadata = match fs::metadata(entry.path()) {
                        Err(_) => continue,
                        Ok(data) => data,
                    };

                    if metadata.len() == 0 && metadata.modified().unwrap_or_default() < std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap() - elapsed {
                        let _ = fs::remove_file(entry.path());
                    }
                }
            }
        }
    });
}
```

