        elif self.protocol == 'smb':
            with open(local_path, 'rb') as data:
                self.conn.storeFile('my-server', f'/{remote_path}', data)
        else:
            self.sftp.put(local_path, remote_path, callback=None, confirm=True)

    def download_file(self, remote_path, local_path):
