            self.client.download_file('mybucket', remote_path, local_path)
        elif self.protocol == 'smb':
            with open(local_path, 'wb') as data:
                self.conn.retrieveFile('my-server', f'/{remote_path}', data)
        else:
            self.sftp.get(remote_path, local_path, callback=None)

