Here is a skeleton code for the function that could fulfill your requirements. This is a simplified version of an async hierarchical reduce method with error handling. The actual implementation may vary based on external libraries used to connect to the database or how parallel processing can be achieved depending on the environment and available resources.

```javascript
const {performance} = require('perf_hooks');
const fetchFromDB = require('./dbService'); // imaginary function

/**
 * Asynchronous hierarchical reduce method for arrays, including nested arrays. 
 * @param {Array} arr - Array to be reduced.
 * @param {Function} reducer - Reduction operation.
 * @param {Number} initialValue - Initial value for the reduction.
 * @returns {Promise<any>} Promise that resolves to the final reduced value or an error object if one occurs.
 */
async function hierarchicalReduce(arr, reducer, initialValue) {
    let result = initialValue;
    const startTime = performance.now();

    try {
        for (let i = 0; i < arr.length; ++i) {
            if (Array.isArray(arr[i])) { // nested array
                result = await hierarchicalReduce(arr[i], reducer, result);
            } else { 
                if (typeof arr[i] !== 'number') throw new Error('Non-numeric value encountered.');
                result = reducer(result, arr[i]);
            }
        }
    } catch (error) {
        return Promise.reject({ error }); // returning an object for better handling of the error.
    } finally {
        console.log('Execution time:', performance.now() - startTime);
    }

    return result;
}

// Example usage with a custom reducer function and fetching data from a DB asynchronously.
fetchFromDB()
  .then(arr => hierarchicalReduce(arr, (a, b) => a + b, 0))
  .then(res => console.log('Final reduced value:', res))
  .catch(({ error }) => console.error('Error during reduction:', error));
```
