class WeatherDataFetcher {
  constructor() {
    this.apiKeys = [];
    this.currentKeyIndex = 0;
    this.rateLimiter = new limiter.RateLimiter(1, 60000); // max 1 call per minute
  }

  async addApiKey(key) {
    this.apiKeys.push({ key: key, lastUpdated: Date.now() });
  }

  getCurrentKey() {
    return this.apiKeys[this.currentKeyIndex].key;
  }

