    // rotate to the next key if it's been more than 12 hours since last update
    const now = Date.now();
    if (now - this.apiKeys[this.currentKeyIndex].lastUpdated >= 43200000) {
      this.currentKeyIndex = (this.currentKeyIndex + 1) % this.apiKeys.length;
      this.apiKeys[this.currentKeyIndex].lastUpdated = now;
    }
  }

  async fetchWeatherData(lat, lon) {
