```python
import base64
import hashlib
from Crypto.PublicKey import RSA
from Crypto.Signature import PKCS1_v1_5
from Crypto.Hash import SHA256
import jwt
import requests
from collections import namedtuple

TokenData = namedtuple('TokenData', 'header claims signature')
KeyPair = namedtuple('KeyPair', 'private public')

def base64_url_decode(data):
    return base64.urlsafe_b64decode(data + "=" * (4 - len(data) % 4))

def parse_jwt(token):
    try:
        header, claims, signature = map(base64_url_decode, token.split('.'))
    except ValueError as e:
        raise InvalidToken("Invalid JWT structure") from e
    return TokenData(header, claims, signature)

def validate_signature(token_data, key):
    data = b'%s.%s' % (token_data.header, token_data.claims)
    digest = hashlib.new('sha256')
    digest.update(data)

    rsa_key = RSA.importKey(key.public)
    verifier = PKCS1_v1_5.new(rsa_key)
    if not verifier.verify(digest, token_data.signature):
        raise SignatureVerificationError("Invalid signature")

def validate_claims(token_data, rules):
    for rule in rules:
        if rule[0] not in token_data.claims or not rule[1](token_data.claims[rule[0]]):
            raise ClaimValidationError("Claim validation failed for %s" % rule[0])

def validate_jwt(token, rules, key):
    try:
        token_data = parse_jwt(token)
        validate_signature(token_data, key)
        validate_claims(token_data, rules)
    except Exception as e:
        # handle the exception here and return a response based on it.
        pass
```
