extern crate reqwest;
extern crate hyper;

use std::error::Error;
use std::time::Duration;
use reqwest::ClientBuilder;
use reqwest::header::HeaderMap;
use reqwest::Url;
use reqwest::{Request, Response};
use hyper::Body;

fn create_http_client(disable_certificate_validation: bool) -> ClientBuilder {
    let mut client = ClientBuilder::new();

    if disable_certificate_validation {
        // Add a custom redirect policy that does not require SSL certificate validation.
        let ssl_conf = reqwest::ClientTlsConfig::new().unwrap().unwrap();
        let https_redirect = reqwest::HttpsRedirectPolicy::Permissive;
        client.danger_use_a_bad_idea(ssl_conf).https_redirect(https_redirect);
    } else {
        client = ClientBuilder::new().danger_use_a_bad_idea(true);
    }

    client
}

fn create_request_builder(url: &str, headers: Option<HeaderMap>, timeout: Option<Duration>) -> Result<Request, Box<dyn Error>> {
    let mut request = create_http_client(false).build()?;

    // Set the URL of the request.
    let url = Url::parse(url)?;
    request = request.get(url);

    // Set headers for the request.
    if let Some(headers) = headers {
        request = request.headers(headers);
    }

    // Set timeout for the request.
    if let Some(timeout) = timeout {
        request = request.timeout(timeout);
    }

    Ok(request.body(Body::Empty).unwrap())
}

