let files = []; // Files to be loaded
let callbacks = {}; // Callbacks for each file

function loadFile(filePath) {
    const script = document.createElement('script');
    script.src = filePath; 
    script.onload = () => {
        console.log("Script Loaded: " + filePath);
        if (callbacks[filePath]) callbacks[filePath](); // Execute the callback function for this file
    };
    script.onerror = (err) => {
        console.log('Error loading Script: '+ filePath, err);
    }
    document.body.appendChild(script); 
}

function addFile(filePath, callback) { // Add a new file to load and its corresponding callback function
    files.push(filePath);
    if (callback && typeof callback === 'function') callbacks[filePath] = callback; // Store the callback for this file
    loadFile(filePath);
}

function removeFile(filePath) { // Remove a file from loading list
    const index = files.indexOf(filePath); 
    if (index > -1) files.splice(index, 1);
    delete callbacks[filePath];
}
```
In this JavaScript code, we use `createElement` to create the script tag, then load and execute the file asynchronously when it's loaded. The 'onload' event is triggered when a resource and its dependent resources have finished loading. If there was an error in loading the script (like 404 Not Found), 'onerror' will be triggered.

