use tokio_postgres::{NoTls, Error};
use clap::Parser;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    dotenv().ok();

    let limit: usize = env::var("CONCURRENT_LIMIT")
        .unwrap_or("10".to_string())
        .parse()
        .unwrap();

    let (mut handle, connections) = tokio_postgres::connect(
        "host=localhost user=user password=password dbname=test",
        NoTls).await?;

    let semaphore = Semaphore::new(limit);

    futures::stream::iter(args.identifiers)
        .map(|id| {
            let id = id.clone();
            tokio::spawn(async move {
                *semaphore.acquire().await;
                get_user(&connections, id).await;
            })
        }).buffered(limit)
        .collect::<Vec<_>>()
        .await?;

    Ok(())
}

