```python
import os
from sqlalchemy import create_engine
from abc import ABC, abstractmethod

# Registry to hold all factory functions for subclasses
factory_registry = {}

class DatabaseConnector(ABC):
    @abstractmethod
    def __init__(self, config: dict):
        self.config = config

    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def close_connection(self):
        pass

    @abstractmethod
    def execute_query(self, query: str):
        pass

    # Factory function registration decorator
    @staticmethod
    def register_factory(name: str):
        def inner_wrapper(func):
            factory_registry[name] = func
            return func
        return inner_wrapper

    @classmethod
    def create_instance(cls, name: str, config: dict):
        if not name in factory_registry:
            raise ValueError("Factory function not found.")

        return factory_registry[name](config)

    @staticmethod
    def discover_subclasses(directory):
        for file in os.listdir(directory):
            if file.endswith('.py'):
                __import__(file[:-3])

class SQLConnector(DatabaseConnector):
    def __init__(self, config: dict):
        self.config = config

    def connect(self):
        engine = create_engine('sqlite:///' + self.config['db'], echo=True)
        return engine.connect()

    def close_connection(self, connection):
        connection.close()

    def execute_query(self, query: str, connection):
        result = connection.execute(query)
        for row in result:
            print(row)

@DatabaseConnector.register_factory("sql")
def create_sql_db(config: dict):
    return SQLConnector(config)
```
