function dynamicClinicManager($clinicData = null, $action = 'create') {
    // Validate and sanitize input data based on predefined rules
    $validatedData = $this->validateAndSanitizeInput($clinicData);

    if ($validatedData['status'] === 'error') {
        return $validatedData;
    }

    switch ($action) {
        case 'create':
            // Validate and sanitize location data using an external geolocation service
            $locationValidationResult = $this->validateLocation($validatedData['location']);

            if (!$locationValidationResult['status']) {
                return ['status' => 'error', 'message' => $locationValidationResult['message']];
            }

            // Create a new clinic record
            $newClinic = $this->createNewClinic($validatedData);

            if ($newClinic) {
                return ['status' => 'success', 'message' => 'Clinic created successfully.'];
            } else {
                return ['status' => 'error', 'message' => 'Failed to create clinic.'];
            }

        case 'update':
            $updatedClinic = $this->updateClinic($validatedData);

            if ($updatedClinic) {
                // If the status is changed to "closed" or "emergency," notify external API and send email notifications
                $this->notifyOnStatusChange();

                return ['status' => 'success', 'message' => 'Clinic updated successfully.'];
            } else {
                return ['status' => 'error', 'message' => 'Failed to update clinic.'];
            }

        case 'delete':
            $deletedClinic = $this->deleteClinic($validatedData);

            if ($deletedClinic) {
                return ['status' => 'success', 'message' => 'Clinic deleted successfully.'];
            } else {
                // If active patients are found, send a notification to the patient scheduling system
                $this->notifyActivePatients();

                return ['status' => 'error', 'message' => 'Failed to delete clinic. Active patients found within 24 hours.'];
            }

        default:
            return ['status' => 'error', 'message' => 'Invalid action.'];
    }
}
