#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <thread>
#include <atomic>
#include <future>
#include <algorithm>
#include <semaphore>

class AdvancedDynamicFileProcessor {
public:
    explicit AdvancedDynamicFileProcessor(std::filesystem::path configPath) : config_file_(configPath) {}

    void processFiles() {
        std::ifstream config_in(config_file_);

        if (!config_in.is_open()) {
            throw std::runtime_error("Failed to open configuration file.");
        }

        // parse the config file and fetch metadata for each file path
        std::string line;
        while (std::getline(config_in, line)) {
            auto splitPos = line.find(' ');
            if (splitPos == std::string::npos) {
                throw std::runtime_error("Invalid configuration format.");
            }

            std::filesystem::path filePath(line.substr(0, splitPos));
            std::vector<std::string> metadataKeys;

            while (splitPos != std::string::npos) {
                auto nextSplitPos = line.find(' ', splitPos + 1);
                if (nextSplitPos == std::string::npos) {
                    metadataKeys.push_back(line.substr(splitPos + 1));
                    break;
                } else {
                    metadataKeys.push_back(line.substr(splitPos + 1, nextSplitPos - splitPos - 1));
                    splitPos = nextSplitPos;
                }
            }

            // call to external API or function that fetches metadata for filePath based on the keys in metadataKeys vector
            std::map<std::string, std::string> metadata = fetchMetadata(filePath, metadataKeys);

            processFileAsync(filePath, metadata).then([this](int res) { this->onOperationCompleted(); });
        }
    }

    // ...
private:
    std::filesystem::path config_file_;
    std::atomic<size_t> filesProcessed_{0};
    std::counting_semaphore<> semaphore_{std::thread::hardware_concurrency() * 4};

    // ...

    void onOperationCompleted() {
        // Increment the counter and print progress
        ++filesProcessed_;
        std::cout << "Files processed: " << filesProcessed_.load() << '\n';
    }

    std::future<int> processFileAsync(std::filesystem::path filePath, const std::map<std::string, std::string>& metadata) {
        // Acquire a semaphore before launching the task to control concurrency
        semaphore_.acquire();

        return std::async(std::launch::async, [this](std::filesystem::path filePath, std::map<std::string, std::string> metadata){
            // ... perform operations and external API call based on the fetched metadata

            semaphore_.release();  // Release semaphore after completing task
            return 0;
        }, filePath, metadata);
    }
};
```
