```java
import java.nio.channels.*;
import java.net.*;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

public class LoadBalancer {
    private final Selector selector;
    private final ServerSocketChannel serverSocketChannel;

    // Assume this is populated with your server connections
    private List<ServerConnection> serverConnections; 

    public LoadBalancer(int port) throws IOException {
        this.selector = Selector.open();
        this.serverSocketChannel = ServerSocketChannel.open();
        InetSocketAddress address = new InetSocketAddress(port);

        serverSocketChannel.bind(address);
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
    }

    public void start() {
        while (true) {
            try {
                if (selector.select() > 0) {
                    for (SelectionKey key : selector.selectedKeys()) {
                        if (key.isAcceptable()) {
                            acceptConnection();
                        } else if (key.isReadable()) {
                            readDataFromClient((SocketChannel) key.channel());
                        }
                    }
                }
            } catch (IOException e) {
                // Handle exceptions...
            }
        }
    }

    private void acceptConnection() throws IOException {
        SocketChannel client = serverSocketChannel.accept();

        if (client != null) {
            ServerConnection connection = selectServerToHandleClient();

            // Add the client to the selected server connection
            connection.addClient(client); 
        }
    }

    private void readDataFromClient(SocketChannel client) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        if (client.read(buffer) == -1) {
            // Client has disconnected, remove them from server's list
            ServerConnection connection = getServerByClient(client);

            if (connection != null) {
                connection.removeClient(client);
            }
        } else {
            // Process client data...
        }
    }

    private ServerConnection selectServerToHandleClient() {
        int serverIndex = ThreadLocalRandom.current().nextInt(serverConnections.size());

        return serverConnections.get(serverIndex);
    }

    // Implement this method that returns the server connection to which the client is connected
    private ServerConnection getServerByClient(SocketChannel client) {
        for (ServerConnection connection : serverConnections) {
            if (connection.containsClient(client)) {
                return connection;
            }
        }

        return null;
    }
}
``` 
