Here is a basic implementation of your requirements in C#. I am assuming that you have RabbitMQ client installed on your system and a queue named 'logQueue' already created. Also, .NET Core 3.1 or above is required to compile the code.

```CSharp
using System;
using System.Text;
using System.Linq;
using System.Security.Cryptography;
using RabbitMQ.Client;

public class MessageProcessor
{
    private readonly string _key, _iv;
    public MessageProcessor(string key, string iv)
    {
        _key = key;
        _iv = iv;
    }

    public void ProcessMessages(IEnumerable<EncryptedMessage> messages)
    {
        var tasks = messages.Select(async m => await DecryptAndValidateAsync(m)).ToArray();
        Task.WaitAll(tasks);
    }

    private async Task DecryptAndValidateAsync(EncryptedMessage message)
    {
        try
        {
            var decrypted = await DecryptMessageAsync(message.Data, _key, _iv);
            if (await ValidateHMACSHA256Async(decrypted, message.Hmac, _key))
            {
                LogMessageToRabbitMQ("Successful decryption", message.Id);
            }
            else
            {
                LogMessageToRabbitMQ("Authentication failure", message.Id);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing message {message.Id}: {ex.Message}");
        }
    }

    private async Task<string> DecryptMessageAsync(string encryptedData, string keyBase64, string ivBase64)
    {
        var cipher = Convert.FromBase64String(encryptedData);
        var key = Convert.FromBase64String(keyBase64);
        var iv = Convert.FromBase64String(ivBase64);

        using (var tripleDes = TripleDES.Create())
        {
            tripleDes.Key = key;
            tripleDes.IV = iv;

            using (var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV))
            {
                var plainTextBytes = await decryptor.TransformFinalBlockAsync(cipher, 0, cipher.Length);
                return Encoding.UTF8.GetString(plainTextBytes);
            }
        }
    }

    private async Task<bool> ValidateHMACSHA256Async(string data, string hmacBase64, string keyBase64)
    {
        var hmac = Convert.FromBase64String(hmacBase64);
        var key = Encoding.UTF8.GetBytes(keyBase64);

        using (var hmacsha256 = new HMACSHA256(key))
        {
            var hash = await hmacsha256.ComputeHashAsync(Encoding.UTF8.GetBytes(data));
            return hash.SequenceEqual(hmac);
        }
    }

    private void LogMessageToRabbitMQ(string status, Guid messageId)
    {
        var factory = new ConnectionFactory() { HostName = "localhost" };
        using (var connection = factory.CreateConnection())
        using (var channel = connection.CreateModel())
        {
            var body = Encoding.UTF8.GetBytes($"{status}:{messageId}");
            channel.BasicPublish("", "logQueue", null, body);
        }
    }
}

public class EncryptedMessage
{
    public Guid Id { get; set; }
    public string Data { get; set; }
    public string Hmac { get; set; }
}
```
