```java
import com.google.gson.Gson;
import io.jsonwebtoken.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import java.io.FileReader;
import java.io.IOException;
import java.security.KeyFactory;
import java.security.NoSuchAlgorithmException;
import java.security.PublicKey;
import java.security.spec.InvalidKeySpecException;
import java.security.spec.X509EncodedKeySpec;
import java.util.*;

@Service
public class JwtValidationService {
    private final RedisTemplate<String, Object> redisTemplate;
    private final ConfigLoader configLoader;

    @Autowired
    public JwtValidationService(RedisTemplate<String, Object> redisTemplate, ConfigLoader configLoader) {
        this.redisTemplate = redisTemplate;
        this.configLoader = configLoader;
    }

    // Loads the key from file
    private PublicKey loadPublicKey() throws IOException, NoSuchAlgorithmException, InvalidKeySpecException {
        byte[] publicBytes = Files.readAllBytes(Paths.get("path_to_public_key"));
        X509EncodedKeySpec spec = new X509EncodedKeySpec(publicBytes);
        KeyFactory kf = KeyFactory.getInstance("RSA");
        return kf.generatePublic(spec);
    }

    // JWT Validation logic with caching and error handling
    public Claims validateAndCacheJwt(String jwt) {
        try {
            if (redisTemplate.hasKey(jwt)) {
                return redisTemplate.opsForValue().get(jwt);
            } else {
                PublicKey key = loadPublicKey();
                Claims claims = Jwts.parserBuilder()
                        .setSigningKey(key)
                        .build()
                        .parseClaimsJws(jwt)
                        .getBody();

                String audience = (String) configLoader.loadConfig("audience");
                if (!claims.getAudience().equals(audience)) {
                    throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Invalid JWT audience.");
                }

                String issuer = (String) configLoader.loadConfig("issuer");
                if (!claims.getIssuer().equals(issuer)) {
                    throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Invalid JWT issuer.");
                }

                // Other validations here...

                redisTemplate.opsForValue().set(jwt, claims);
                return claims;
            }
        } catch (Exception e) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Invalid JWT.");
        }
    }

}
```
