```rust
extern crate futures;
extern crate tokio_postgres;
extern crate clap;
use std::env;
use futures::Future;
use tokio_postgres::{NoTls, Error, Client};
use clap::Parser;

#[derive(Parser, Debug)]
struct Args {
    #[clap(long)]
    id: u32
}

async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    // Build a connection string from environment variables.
    let connect_string = format![ "host={} port={} user={} password={} dbname={}",
        env::var("POSTGRES_HOST")?,
        env::var("POSTGRES_PORT")?,
        env::var("POSTGRES_USER")?,
        env::var("POSTGRES_PASSWORD")?,
        env::var("POSTGRES_DBNAME")?
    ];

    // Create a client.
    let (client, connection) = tokio_postgres::NoTlsConnector::new(connect_string, NoTls)?.connect().await?;

    // Make a query to the database.
    match client
        .query_one(&format![ "SELECT * FROM users WHERE id = $1", args.id ], &[])
        .await
    {
        Ok(row) => println![ "User: {:?}", row ],
        Err(e)  => println![ "Error running query: {}", e ],
    }

    // Close the connection.
    tokio::spawn(connection);

    Ok(())
}
```
