import java.util.*;
import java.net.*;
import java.io.*;

public class PacketFilterModule {
    private static int packetCount = 0;
    private static long totalPacketsSize = 0;

    // Define a Sliding Window to hold the most recent packets, here using ArrayList for simplicity
    private static List<DatagramPacket> slidingWindow = new ArrayList<>();

    public static void main(String[] args) {
        int portNumber = Integer.parseInt("12345"); // you can make this configurable as well
        try {
            DatagramSocket serverSocket = new DatagramSocket(portNumber);

            while (true) {
                byte[] receiveData = new byte[1024];
                DatagramPacket receivePacket = new DatagramPacket(receiveData, receiveData.length);

                // Receiving packet from network
                serverSocket.receive(receivePacket);

                Thread thread = new PacketProcessingThread(receivePacket);
                thread.start();
            }
        } catch (SocketException e) {
            System.out.println("Socket Exception: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("IO Exception: " + e.getMessage());
        }
    }

    public static class PacketProcessingThread extends Thread {
        private DatagramPacket packet;

        public PacketProcessingThread(DatagramPacket packet) {
            this.packet = packet;
        }

        @Override
        public void run() {
            synchronized (slidingWindow) {
                // Add the received packet to the sliding window
                slidingWindow.add(packet);

                // Increment total packets count and size
                packetCount++;
                totalPacketsSize += packet.getLength();

                System.out.println("Current Packet Count: " + packetCount);
                System.out.println("Average Packet Size in Sliding Window: " + totalPacketsSize/slidingWindow.size());
            }

            // Process the received packet based on the filtering criteria here...
        }
    }
}
