                try{
                    // Try another recorder, such as a backup recorder or wait for a moment before trying again.
                    std::this_thread::sleep_for(std::chrono::milliseconds(500));

                    return recordTransaction(std::forward<Args>(args)...);
                }
                catch (const std::exception& e){
                    if(retry == maxRetry - 1){ // If maximum retries are reached, log the final error and return failure code.
