```C
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>

volatile sig_atomic_t quit = 0;
void handle_interrupt(int signal) { quit = 1; }

void printUsage() {
    printf("Usage: ./program --help | -cs [-o output_file] [input_file]\n");
}

int main(int argc, char* argv[]) {

    if (argc < 2 || strcmp(argv[1], "--help") == 0) {
        printUsage();
        return 0;
    }

    // Parse command line arguments
    char *input_file = NULL, *output_file = NULL;
    int verbose = 0, cs = 0;
    for (int i = 1; i < argc; i++) {
        if(strcmp(argv[i], "-cs") == 0) {
            cs = 1;
        } else if(strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else if(strcmp(argv[i], "-o") == 0 && i+1 < argc) {
            output_file = argv[++i];
        } else if(input_file == NULL) {
            input_file = argv[i];
        } 
    }

    // Check if an input file is provided. If not, print usage information and exit.
    if (input_file == NULL) {
        printf("Error: No input file provided.\n");
        return 1;
    }

    FILE *in = fopen(input_file, "r");
    if (!in) {
        perror("Could not open the input file");
        return 2;
    }

    signal(SIGINT, handle_interrupt);
    char line[1024];
    int count = 0;
    while (fgets(line, sizeof line, in) && !quit) {
        if(verbose) printf("%s", line);
        count++;
    }

    fclose(in);

    if(!cs) {
        printf("Number of lines: %d\n", count);

        FILE *out = NULL;
        if (output_file != NULL) {
            out = fopen(output_file, "w");

            // Handle error
            if (!out) {
                perror("Could not open the output file");
                return 3;
            }

            fprintf(out, "%d", count);
            fclose(out);
        }
    }

    return 0;
}
```
