```java
import org.apache.commons.codec.digest.DigestUtils;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.math.BigInteger;
import redis.clients.jedis.Jedis;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class HashService {
    private static final Logger logger = LoggerFactory.getLogger(HashService.class);
    private Jedis jedis;
    private ExecutorService executorService;
    private int cacheSize = 1024; // Default cache size
    private LRUCache<String, HashPair> cache;

    public HashService() {
        this.jedis = new Jedis("localhost"); 
        this.executorService = Executors.newFixedThreadPool(5); // Default thread pool size
        this.cache = new LRUCache<>(cacheSize);
    }

    public void setCacheSize(int cacheSize) {
        this.cacheSize = cacheSize;
        this.cache = new LRUCache<>(cacheSize);
    }

    public void setThreadPoolSize(int threadPoolSize) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
    }

    public Map<String, String> getHashValues(String input, StandardCharsets charset) throws Exception {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Input string is either null or exceeds the maximum length of 1000 characters.");
        }

        String cacheKey = "hash:" + input;
        HashPair hashPair = cache.get(cacheKey);
        if (hashPair == null) {
            Future<HashPair> future = executorService.submit(() -> computeHashes(input, charset));
            try {
                hashPair = future.get(); // This call is blocking when the result isn't ready yet
                cache.put(cacheKey, hashPair);
            } catch (ExecutionException | InterruptedException e) {
                logger.error("Failed to compute hashes", e);
            }
        } else {
            logger.info("Cache hit for key: {}", cacheKey);
        }

        Map<String, String> result = new HashMap<>();
        result.put("md5", hashPair.getMd5());
        result.put("sha256", hashPair.getSha256());
        return result;
    }

    private HashPair computeHashes(String input, StandardCharsets charset) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes(charset));
            BigInteger no = new BigInteger(1, digest);
            String hashtext = no.toString(16);
            while (hashtext.length() < 32) { 
                hashtext = "0" + hashtext; 
            }
            return new HashPair(DigestUtils.sha256Hex(input), hashtext);
        } catch (NoSuchAlgorithmException e) {
            logger.error("Failed to compute hashes", e);
            throw new RuntimeException(e); // Can be replaced by specific exception handling
        }
    }
}
```
