import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Map;
import java.util.HashMap;

public class DynamicServiceManager {

    private Map<String, ServiceFactory> registry = new HashMap<>(); 
    private ObjectMapper mapper = new ObjectMapper();
    private Map<String, Tenant> tenants = new HashMap<>();

    // Register a service factory for the specified tenant and service ID.
    public void register(String tenantId, String serviceId, ServiceFactory factory) {
        if (!tenants.containsKey(tenantId)) {
            tenants.put(tenantId, new Tenant());
        }

        tenants.get(tenantId).register(serviceId, factory);
    }

    // Create a new service instance from the specified JSON configuration string.
    public Service createServiceInstance(String tenantId, String jsonConfig) throws Exception {
        Tenant tenant = tenants.getOrDefault(tenantId, new Tenant());

        ServiceConfiguration config = mapper.readValue(jsonConfig, ServiceConfiguration.class);
        return tenant.createServiceInstance(config);
    }

    // Convert a service configuration to a JSON string.
    public String convertToJsonString(ServiceConfiguration config) throws Exception {
        return mapper.writeValueAsString(config);
    }
}
