app.use(bodyParser.urlencoded({ extended: false }));

// Middleware to handle book names from incoming streams and count occurrences 
const findBooksMiddleware = async (req, res, next) => {
    const textStream = req.body.text;
    let booksFound = {}; // This is where we'll store the counts of each book

    const bookNames = await BookModel.find();
    for(let i=0; i<bookNames.length; i++) {
        let regex = new RegExp('\\b' + bookNames[i].name + '\\b', 'gi');
        booksFound[bookNames[i].name] = (textStream.match(regex) || []).length;
    }

    req.booksFound = booksFound;
    next();
}
app.use(findBooksMiddleware);

// API route to serve the book counts 
app.post('/count-book', (req, res) => {
    const booksFoundCount = req.booksFound;
    cache.set('found_books', booksFoundCount); // Store in cache
    res.send(booksFoundCount);
});

// Handling errors and notifications 
app.use((error, req, res, next) => {
    console.log(error);
    NotificationService.notifyAdmin('Error occurred: ' + error.message);
    res.status(500).send({ message: "An unexpected error has occurred"});
});
```
