Here is a simple C solution following these principles. It may not be as performant as some other languages due to the dynamic memory allocation, but it demonstrates how you can tackle this problem in a modular fashion. This version reads the file line by line and doesn't load all lines into memory at once. The maximum number of decimal places for the sum and average is set to 2.

```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function prototypes
char* readline(FILE *);
double* parsefields(char*, int*);
void calculate_sum_avg(double*, int, double*, double*);
void process_file(const char*);

int main() {
    const char* filename = "input.txt";
    process_file(filename);

    return 0;
}

// Read a line from the file
char* readline(FILE *fp) {
    int c;
    size_t len = 1, i = 0;
    char *buffer = malloc(sizeof(char));

    while ((c = fgetc(fp)) != EOF && c != '\n') {
        buffer[i++] = (char)c;

        if (i >= len) {
            buffer = realloc(buffer, ++len);

            if (!buffer) {
                free(buffer);
                return NULL;  // Out of memory
            }
        }
    }

    buffer[i] = '\0';

    if (c == EOF && i == 0 || !strlen(buffer)) {
        free(buffer);
        return NULL;  // End of file or empty line
    }

    return buffer;
}

// Parse fields from a string, return array of doubles and size of array
double* parsefields(char *line, int *size) {
    double *arr = malloc(10 * sizeof(double));  // Initial capacity
    char *token = strtok(line, " ");

    while (token != NULL) {
        arr[(*size)++] = atof(token);

        if (*size >= (int)(sizeof(arr)/sizeof(double))) {  // If array is full...
            double *new_arr = realloc(arr, 2*(*size)*sizeof(double));  // Double its size

            if (!new_arr) {
                free(arr);
                return NULL;  // Out of memory
            } else {
                arr = new_arr;
            }
        }

        token = strtok(NULL, " ");
    }

    return arr;
}

// Calculate the sum and average of the last three fields in an array
void calculate_sum_avg(double *fields, int size, double *sum, double *avg) {
    if (size < 3) {  // Less than 3 fields
        printf("Error: Line does not contain at least three fields\n");
        return;
    }

    for (int i = size - 3; i < size; ++i) {
        *sum += fields[i];
    }

    *avg = *sum / 3.0;
}

// Process a file line by line, calculate and print sums and averages
void process_file(const char *filename) {
    FILE *fp = fopen(filename, "r");

    if (fp == NULL) {
        printf("Error: Could not open file\n");
        return;
    }

    while (!feof(fp)) {
        char *line = readline(fp);

        if (line != NULL) {  // Not end of file or empty line
            int size = 0;
            double sum = 0.0, avg = 0.0;
            double *fields = parsefields(line, &size);

            calculate_sum_avg(fields, size, &sum, &avg);

            printf("Sum: %.2f, Average: %.2f\n", sum, avg);  // Comma-separated format

            free(line);
            free(fields);
        }
    }

    fclose(fp);
}
```
You can test this program on different files by changing the "filename" variable to a path to your file. The function `process_file()` is where you need to put the name of your input file. You would also want to change the output directory and format according to your specific needs. 

Please note that this code doesn't have any error handling beyond checking if a line read from the file is empty or an end-of-file condition has occurred, which you may want to expand on for a complete solution. Also, you may wish to add additional functions for parsing command line arguments and options as well as for testing performance on large files.

