        // Implement load balancing algorithm here (e.g., round-robin, least connections)...

        if(selectedServer != null) {
            SocketChannel channel = openConnection(selectedServer);

            if(channel != null) {
                serverMap.put(channel, selectedServer);

                // Register the channel with selector for read/write operations...
            }
        }
    }

    private SocketChannel openConnection(ServerData data) {
        try {
            SocketChannel channel = SocketChannel.open();

            channel.configureBlocking(false);
