Python Script - Weather API Integration with Redis caching:
```python
import redis
import requests
from datetime import timedelta

r = redis.Redis()
weather_api_url = 'http://api.openweathermap.org/data/2.5/weather'
params = {
    'q': 'New York, US',  # Location
    'appid': 'your-api-key'  # Replace with your OpenWeatherMap API key
}
cache_ttl = timedelta(minutes=10)  # Redis cache expiration time

def get_weather():
    data = r.get('weather')
    if not data:
        response = requests.get(weather_api_url, params=params)
        data = response.json()
        r.setex('weather', cache_ttl, str(data))  # Store in Redis with expiration time
    else:
        data = eval(data.decode())  # Decode from bytes to dict
    return data
```
