use std::fs;
use std::path::PathBuf;
use tokio::sync::Mutex;
use failure::Error;
use dirs_next::preference_dir;

// Create a global Mutex for concurrency control and resource sharing
static DIRECTORY: Mutex<Option<PathBuf>> = Mutex::new(None);

pub async fn get_directory() -> Result<PathBuf, Error> {
    let mut directory = DIRECTORY.lock().await;

    // Check if the directory already exists
    if let Some(dir) = directory.as_ref() {
        if fs::metadata(&dir).is_ok() {
            return Ok(dir.clone());
        }
    }

    let mut dir: PathBuf; 
    loop {
        // Generate a new local path and try to create it. If fails, generate another one
        dir = preference_dir().expect("Could not find preference directory");

        if fs::create_dir(&dir).is_ok() {
            break;
        } else {
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    // TODO: Call remote config management service to sync directory with remote repository

    *directory = Some(dir);

    Ok(dir)
}
```
