import importlib.util
from abc import ABC, abstractmethod
from typing import Dict

class Registry(type):
    factories = {}

    def __new__(cls, name, bases, attrs):
        cls.factories[name] = super().__new__(cls, name, bases, attrs)

    @classmethod
    def register_factory(cls, factory):
        assert callable(factory), "Factory must be a function"
        cls.factories[factory.__name__] = factory
        return factory

class JSONBase(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @staticmethod
    @abstractmethod
    def from_json(cls, json_str: str):
        pass

def discover_subclasses(directory: str):
    for file in os.listdir(directory):
        if file.endswith('.py'):
            module = importlib.util.spec_from_file_location('module', f"{directory}/{file}")
            module = importlib.util.module_from_spec(module)
            module.loader.exec_module(module)

class JSONSubClassA(JSONBase):
    @Registry.register_factory
    def __init__(self, data: Dict):
        self.data = data

    def to_json(self) -> str:
        return json.dumps(self.data)

    @staticmethod
    def from_json(cls, json_str: str):
        return cls(json.loads(json_str))

class JSONSubClassB(JSONBase):
