const Promise = require("bluebird");
Promise.config({ cancellation: true });

/**
 * Reduce array of numbers and numeric strings asynchronously with error handling,
 * rate limiting, logging, caching and resource management
 * @param {array} arr - Array to be reduced
 * @param {function} fn - The function for reduction
 * @param {number} concurrency - Number of parallel operations allowed
 * @returns Promise that resolves with the final reduced value or an error if encountered
 */
async function reduceAsync(arr, fn, concurrency) {
  // Input validation
  assert.ok(Array.isArray(arr), 'Input is not an array');
  assert.equal(typeof fn, 'function', 'fn should be a function');
  assert.ok(!Number.isNaN(concurrency), 'Concurrency must be a number');

  // Initialize cache for subarray results
  const cache = {};

  return new Promise((resolve, reject) => {
    async.eachLimit(arr, concurrency, (item, callback) => {
      if (!cache[item]) {
        try {
          // Convert string numbers to integers and perform reduction function
          cache[item] = fn(parseInt(item));
          console.log('Processed item:', item);
          callback();
        } catch (error) {
          reject(`Error processing ${item}: ${error}`);
        }
      } else {
        // If result for the subarray is cached, reuse it
        console.log('Cached result used for item:', item);
        callback();
      }
    }, (err) => {
      if(err){
         reject(`Error during iteration ${item}: ${error}`);
      } else {
        // Resolve with final reduced value when all subarrays processed
        const result = cache[0];
        for (let i = 1; i < arr.length; i++) {
          result = fn(result, parseInt(cache[i]));
        }
        resolve(result);
      }
    });
  });
}
