import org.apache.commons.codec.digest.DigestUtils;
import com.google.gson.*;
import redis.clients.jedis.*;
import java.util.*;
import java.util.concurrent.*;
import java.io.*;
import org.slf4j.*;

public class ConfigManager {
    private static final Logger logger = LoggerFactory.getLogger(ConfigManager.class);

    private JedisPool pool;
    private ExecutorService executorService;
    private Map<String, Parser> parsersRegistry = new ConcurrentHashMap<>();
    private LoadingCache<String, String> cache;

    public ConfigManager(int maxThreads, int cacheSize) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        pool = new JedisPool("localhost", 6379); // replace with your redis host and port
        CacheLoader<String, String> loader;
        loader = new CacheLoader<>() {
            @Override
            public String load(String key) throws Exception {
                try (Jedis jedis = pool.getResource()) {
                    byte[] cachedValue = jedis.get(key.getBytes());
                    return new String(cachedValue, "UTF-8");
                } catch (Exception e){
                    logger.error("Error loading from cache", e);
                    throw e;
                }
            }
        };
        this.cache = CacheBuilder.newBuilder().maximumSize(cacheSize).build(loader);
    }

    public void addParser(String type, Parser parser) {
        parsersRegistry.put(type, parser);
    }

    public interface Parser {
        Object parse(String json);
    }

    public void parseConfigFile(String type, String pathToFile){
        Parser parser = parsersRegistry.get(type);
        if (parser == null) throw new IllegalArgumentException("Unsupported config type: " + type);

        try {
            String json = new String(Files.readAllBytes(Paths.get(pathToFile)));

            // Validate input
            if(json == null || json.length() > 1000) {
                throw new IllegalArgumentException("Invalid configuration string");
            }

            Object config = parser.parse(json);

            CompletableFuture.supplyAsync(() -> {
                        String md5Hash = DigestUtils.md5Hex(json);
                        String sha256Hash = DigestUtils.sha256Hex(json);
                        return new Hash[]{md5Hash, sha256Hash};
                    }, executorService)
                .thenAccept(hashes -> { 
                    // Notify connected services about configuration changes
                    // and update cache
                    try (Jedis jedis = pool.getResource()) {
                        String configKey = type + ":" + hashes[0];
                        jedis.set(configKey.getBytes(), json.getBytes());

                        cache.put(configKey, json); // update cache 
                    } catch (Exception e) {
                        logger.error("Error caching configuration", e);
                    }
                });
        } catch(IOException | RuntimeException e){
            logger.error("Error parsing configuration file: " + pathToFile, e);
        }
    }
}
