#include <stdlib.h>
#include <pthread.h>

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int log_level) {
    if (num_structures <= 0 || crc_flag_rules == NULL || nfalist == NULL) {
        printf("Invalid input\n");
        return -1;
    }

    pthread_mutex_lock(&mutex); // Lock to ensure thread safety

    *nfalist = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));  // Allocate memory for structures
    if (*nfalist == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return -1; // Handle allocation failure
    }

    for (int i = 0; i < num_structures; ++i) {
        (*nfalist)[i].RX_UE_INFORMATION_TAG = i + 1;  // Set unique tags and RNTI
        (*nfalist)[i].RNTI = (i % 9000) + 1000;
        (*nfalist)[i].CRC_INDICATION_REL8.CRCFLAG = crc_flag_rules[i]; // Set CRC flag based on rule

        log_structure_creation(log_level, "Structure created", &((*nfalist)[i]));  // Log structure creation
    }

    pthread_mutex_unlock(&mutex); // Unlock to allow other threads to access the list of structures

    return 0;  // Successful execution
}
```
