    [Serializable]
    private class SerializedData
    {
        public int Version { get; set; }
        public byte[] Data { get; set; }
    }

    private static readonly BinaryFormatter Formatter = new BinaryFormatter();

    // Replace with your actual checksum calculation method
    private uint CalculateChecksum(byte[] data) => /* Implementation not provided */;

    public CustomDataStructure LoadAndDeserializeDataFromFile(string filePath, int expectedVersion)
    {
        try
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var serializedObject = (SerializedData)Formatter.Deserialize(fileStream);

                if (serializedObject.Version != expectedVersion)
                    throw new ApplicationException("The version of the data does not match the expected one.");

                uint actualChecksum;
                using (var memoryStream = new MemoryStream(serializedObject.Data))
                {
                    var binaryReader = new BinaryReader(memoryStream);

                    // Read the checksum from the file header
                    actualChecksum = binaryReader.ReadUInt32();

                    // The remaining bytes are for the CustomDataStructure
                    var dataWithoutChecksum = memoryStream.ToArray().AsSpan(sizeof(uint)).ToArray();

                    if (actualChecksum != CalculateChecksum(dataWithoutChecksum))
                        throw new ApplicationException("The checksum of the data does not match the expected one.");

                    // Deserialize the CustomDataStructure and return it
                    memoryStream.Seek(sizeof(uint), SeekOrigin.Begin);
                    using (var objectMemoryStream = new MemoryStream())
                    {
                        memoryStream.CopyTo(objectMemoryStream);
                        objectMemoryStream.Seek(0, SeekOrigin.Begin);

                        return (CustomDataStructure)Formatter.Deserialize(objectMemoryStream);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred while loading and deserializing the data: " + ex.Message);
            return null; // or throw an exception based on your needs
        }
    }
}
