const axios = require('axios');
const pLimit = require('p-limit');

async function loadDynamicContent(contentObjects) {
  const limit = pLimit(3); // Limit the number of simultaneous requests to 3
  let contentHTML = '';

  for (let obj of contentObjects) {
    if ('url' in obj) {
      try {
        const res = await limit(() => axios.get(obj.url, {timeout: 5000})); // Timeout after 5 seconds
        contentHTML += `<script>${res.data}</script>`;
      } catch (err) {
        console.error(`Failed to load script from URL ${obj.url}, reason: ${err}`);
        // Fallback to alternative content source or display a user-friendly message here
      }
    } else if ('code' in obj) {
      try {
        eval(obj.code);  // Inline script
        contentHTML += `<script>${obj.code}</script>`;
      } catch (err) {
        console.error(`Failed to execute inline script with key ${obj.key}, reason: ${err}`);
        // Handle error here, like fallback to alternative content source or display a user-friendly message
      }
    } else {
      console.warn('Skipping invalid object', obj);
    }
  }

  return new Promise((resolve) => {
    resolve(contentHTML); // Resolve the promise with the rendered HTML string
  });
}
