import yaml
from importlib import import_module
import logging

logging.basicConfig(filename='logs.txt', filemode='w', level=logging.INFO, format='%(asctime)s - %(message)s')

def validate_mime(path):
    valid_types = ['application/json', 'text/yaml']
    mime = magic.Magic(mime=True)
    file_type = mime.from_file(path)

    if file_type not in valid_types:
        logging.warning('Invalid MIME type')
        raise ValueError("The configuration file must be either JSON or YAML")

def parse_config(path, format):
    with open(path) as f:
        if format == 'application/json':
            return json.loads(f.read())
        else: # text/yaml
            return yaml.safe_load(f)

class ConfigManager:
    def __init__(self, data):
        self.data = data

def instantiate_manager(config_dict, class_name):
    if not import_module(class_name):
        logging.warning('The configuration manager class does not exist')
        raise ValueError("Invalid configuration manager class")

    return ConfigManager(config_dict)

def get_configuration_manager(path, class_name):
    try:
        validate_mime(path)
        config = parse_config(path, magic.from_file(path))
        cm = instantiate_manager(config, class_name)

        return cm
    except ValueError as ve:
        logging.error(ve)
        raise ve
