            warn="Attempting to create directory";
            for _ in 0..3 {
                if let Err(e) = fs::create_dir_all(&user_config) {
                    error=format_error("Failed to create directory", e);
                    continue;
                }
                break;
            } else {
                return Err("Failed to find or create directory after three attempts");
            }
        }

        Ok(Self { path: PathBuf::from(user_config) })
    }

    pub fn get_path(&self) -> &PathBuf {
        &self.path
    }
}
