const express = require('express');
const redis = require('redis');
const asyncRedis = require("async-redis");
const fetch = require('node-fetch');
const rateLimit = require("express-rate-limit");
const bodyParser = require('body-parser');

// initialize Redis and Express App
let client = redis.createClient();
client.on('connect', function() {
    console.log('Redis client connected');
});

const app = express();
app.use(bodyParser.json());
app.use(rateLimit({ windowMs: 60 * 1000, max: 500 })); // limit to 500 requests per minute from the same IP address

// define middleware for validating permissions and handling cache
async function validatePermissionsAndHandleCache(req, res, next) {
    const id = req.params.id;
    try {
        const authResponse = await fetch('http://auth-service/validate', { headers: req.headers }); // validate user permissions
        if (authResponse.status !== 200) {
            return res.status(401).json({ message: 'Unauthorized' });
        }
        const cachedProduct = await client.getAsync(id); // try to get the product from cache
        if (cachedProduct) {
            req.productFromCache = JSON.parse(cachedProduct);
        } else {
            next(); // product not in cache, fetch from db
        }
    } catch (err) {
        console.error(err);
        return res.status(500).json({ message: 'Internal Server Error' });
    }
}

// define routes
app.put('/product/:id', validatePermissionsAndHandleCache, async function(req, res) {
    try {
        const product = req.body;
        if (req.productFromCache) {
            // perform a partial update on the cached product
            Object.assign(req.productFromCache, product);
            await client.setAsync(id, JSON.stringify(req.productFromCache));
        } else {
            // send update request to external DB service
            const dbResponse = await fetch('http://db-service/update', { method: 'PUT', body: JSON.stringify({ id, product }) }); 
            if (dbResponse.status !== 200) {
                return res.status(500).json({ message: 'Failed to update product' });
            }
        }
        return res.status(200).json({ message: 'Product updated successfully' });
    } catch (err) {
        console.error(err);
        return res.status(500).json({ message: 'Internal Server Error' });
    }
});

app.delete('/product/:id', validatePermissionsAndHandleCache, async function(req, res) {
    try {
        if (req.productFromCache) {
            // mark product as deleted in cache
            req.productFromCache.deleted = true;
            await client.setAsync(id, JSON.stringify(req.productFromCache));
        } else {
            const dbResponse = await fetch('http://db-service/delete', { method: 'DELETE', body: JSON.stringify({ id }) }); 
            if (dbResponse.status !== 200) {
                return res.status(500).json({ message: 'Failed to delete product' });
            }
        }
        return res.status(200).json({ message: 'Product deleted successfully' });
    } catch (err) {
        console.error(err);
        return res.status(500).json({ message: 'Internal Server Error' });
    }
});

// start the server
const port = process.env.PORT || 3000;
app.listen(port, function() {
  console.log('Server listening on', port);
});
```

