```c
#include <stdarg.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// The configuration struct is a singleton, so the 'config' variable can be used globally to access it
typedef struct {
    char* language; // Language selection 
    bool logEnabled; // Whether or not logging is enabled
    size_t maxMessageLength; // Maximum message length for each logged message
} Config;

Config config = {"en", true, 1024}; // Default configuration values

pthread_mutex_t mutexWriteLogFile = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safe file I/O operations

void logConditionalMessage(bool condition, const char *language, const char *format, ...) {
    if (!config.logEnabled || !condition) return; // If logging is disabled or the condition isn't met, do nothing

    pthread_mutex_lock(&mutexWriteLogFile); // Acquire lock for thread-safe file I/O operations

    va_list args;
    char buffer[config.maxMessageLength];
    int formattedLength;

    va_start(args, format);
    formattedLength = vsnprintf(buffer, config.maxMessageLength, format, args); // Format the message using vsnprintf for efficiency
    va_end(args);

    if (formattedLength < 0) { // If there was an error in formatting, handle it gracefully
        pthread_mutex_unlock(&mutexWriteLogFile);
        fprintf(stderr, "Error: Failed to format log message\n");
        return;
    } else if (formattedLength >= config.maxMessageLength) { // If the formatted message is too long, truncate it and inform of potential buffer overflow
        buffer[config.maxMessageLength - 1] = '\0';
        fprintf(stderr, "Warning: Log message was truncated to fit within the maximum length\n");
    }

    // Open the error log file in append mode
    FILE *logFile = fopen("error_log", "a+"); 
    if (logFile == NULL) { // If the log file is not writable, handle it gracefully
        pthread_mutex_unlock(&mutexWriteLogFile);
        fprintf(stderr, "Error: Failed to open error log file\n");
        return;
    }

    // Write the formatted message to the log file
    fputs(buffer, logFile); 

    fclose(logFile); // Close the log file

    pthread_mutex_unlock(&mutexWriteLogFile); // Release lock for thread-safe file I/O operations
}
```
