    // Tries to load a state object from cache first. If not found, loads it from file or service and caches it for future use.
    public byte[] getState(String key) {
        try {
            return cache.get(key); 
        } catch (Exception e) {
            LOG.error("Failed to read state from cache", e);
            throw new RuntimeException(e); 
        }
    }

    // Closes a Closeable without throwing exception.
    private static void closeQuietly(Closeable is) {
        if (is != null ) {
            try { is.close(); } catch (IOException ignored) {}
        }
    }
}
```
