```javascript
const MAX_CONCURRENT_REQUESTS = 4;
const RETRY_ATTEMPTS = 3;
let scriptCache = {}; // In-memory cache for fetched scripts

// Custom HTTP client
async function fetchWithRetries(url, options) {
    let attempt = 0;
    while (attempt < RETRY_ATTEMPTS) {
        try {
            const response = await fetch(url, options);
            if (!response.ok) throw new Error('HTTP error ' + response.status);
            return response.text();
        } catch (err) {
            console.warn("Failed to fetch script: " + url, err);
            attempt++;
        }
    }
    throw new Error("Failed to fetch script after multiple attempts: " + url);
}

// Helper function for fetching and caching scripts
async function fetchScript(src) {
    if (!scriptCache[src]) {
        const content = await fetchWithRetries(src, { timeout: 5000 }); // Timeout after 5 seconds
        scriptCache[src] = content;
    }
    return scriptCache[src];
}

// Function to render scripts based on priority
async function renderScriptsInOrder(scripts) {
    const sortedScripts = [...scripts].sort((a, b) => a.key - b.key); // Sort by key (higher key first)
    let renderedCount = 0;

    for (let script of sortedScripts) {
        if (!script.src || !script.type) throw new Error("Invalid script object: " + JSON.stringify(script));

        const content = await fetchScript(script.src);
        if (!content) continue; // Skip invalid or empty scripts

        if (renderedCount < MAX_CONCURRENT_REQUESTS - 1) {
            renderedCount++;
            renderScriptTag(content, script); // Render immediately
        } else {
            setTimeout(() => renderScriptTag(content, script), renderedCount * 200); // Delayed rendering for rate limiting
            renderedCount = 0;
        }
    }
}

// Helper function to generate a script tag and append it to the footer
function renderScriptTag(content, { type }) {
    const scriptTag = document.createElement("script");
    scriptTag.type = type;
    scriptTag.textContent = content; // Assuming inline scripts

    document.body.appendChild(scriptTag); // Append to footer (or replace with appropriate selector)
}

// Integration with external API for checking script integrity and fetching additional metadata from a configuration service
async function validateScriptsAndFetchMetadata(scripts, apiUrl, configServiceUrl) {
    const validKeys = await fetchWithRetries(apiUrl + '/valid-keys', { method: 'GET' }); // Assuming the API returns an array of valid keys
    for (let script of scripts) {
        if (!validKeys.includes(script.key)) throw new Error("Invalid script key: " + script.key);

        const metadata = await fetchWithRetries(configServiceUrl + '/metadata?scriptKey=' + script.key, { method: 'GET' }); // Assuming the service returns additional metadata for each script
        Object.assign(script, metadata); // Merge fetched metadata into script object
    }
}

// Main function to render scripts in the footer with all functionalities
async function renderFooterScripts(scripts) {
    await validateScriptsAndFetchMetadata(scripts, 'http://example.com/api', 'http://config-service.com'); // Assuming these are the API and config service URLs

    await renderScriptsInOrder(scripts);
}
```
