import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.networknt.schema.JsonSchemaFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.web.bind.annotation.*;

import java.io.IOException;

@RestController
@RequestMapping("/json")
public class JsonController {
    private static final Logger logger = LoggerFactory.getLogger(JsonController.class);
    private ObjectMapper objectMapper = new ObjectMapper();

    @Cacheable(value="parsedData", key="#path")
    @RequestMapping(value = "/parse/{path}", method = RequestMethod.POST)
    public JsonNode parse(@PathVariable("path") String path, @RequestBody String jsonString) throws IOException {
        return objectMapper.readTree(jsonString).at(path);
    }

    @Cacheable(value="validatedData", key="#schemaPath")
    @Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(delay = 5000))
    public boolean validate(@RequestBody String jsonString, @PathVariable("schemaPath") String schemaPath) throws IOException {
        JsonSchemaFactory factory = JsonSchemaFactory.getInstance();
        com.fasterxml.jackson.databind.JsonNode node = objectMapper.readTree(jsonString);
        com.networknt.schema.JsonSchema finalSchema = factory.getSchema(node.at(schemaPath));
        return finalSchema.validate(node).isEmpty();
    }
}
