Here is the ImageProcessor class:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <functional>
#include <dlfcn.h>  // dllib

class ImageProcessor {
    typedef void* (*NewMagickWand_t)(void);
    typedef int  (*SetImageCompressionQuality_t)(void*, size_t);
    typedef int  (*ReadImage_t)(void*, const char *);
    typedef int  (*WriteImage_t)(void*, const char *);
    typedef void (*DestroyMagickWand_t)(void*);

    NewMagickWand_t            NewMagickWand;
    SetImageCompressionQuality_t SetImageCompressionQuality;
    ReadImage_t                ReadImage;
    WriteImage_t               WriteImage;
    DestroyMagickWand_t        DestroyMagickWand;

public:
    ImageProcessor() {
        void* handle = dlopen("path/to/libimage_magick.so", RTLD_LAZY);  // replace this with actual path
        NewMagickWand                = (NewMagickWand_t)             dlsym(handle, "NewMagickWand");
        SetImageCompressionQuality   = (SetImageCompressionQuality_t)dlsym(handle, "SetImageCompressionQuality");
        ReadImage                   = (ReadImage_t)                 dlsym(handle, "ReadImage");
        WriteImage                  = (WriteImage_t)                dlsym(handle, "WriteImage");
        DestroyMagickWand            = (DestroyMagickWand_t)         dlsym(handle, "DestroyMagickWand"); 
    }

    void convertAndSave(std::string inputPath, std::string outputPath, size_t quality){
        auto wand = NewMagickWand();
        if(!ReadImage(wand, inputPath.c_str())) {
            throw std::runtime_error("Failed to read image");
        }

        SetImageCompressionQuality(wand, quality);

        if(!WriteImage(wand, outputPath.c_str())) {
            throw std::runtime_error("Failed to write image");
        }

        DestroyMagickWand(wand); 
    }

    void batchConvertAndSave(std::vector<std::string> inputPaths, std::vector<std::string> outputPaths, std::vector<size_t> qualities){
        if(inputPaths.size() != outputPaths.size() || outputPaths.size() != qualities.size()) {
            throw std::runtime_error("Input sizes mismatch");
        }

        size_t numImages = inputPaths.size();
        std::vector<std::thread> threads(numImages);

        for(int i = 0; i < numImages; ++i) {
            threads[i] = std::thread([this, &inputPaths, &outputPaths, &qualities, i]{  // pass by reference to avoid copies
                try{
                    convertAndSave(inputPaths[i], outputPaths[i], qualities[i]);
                } catch (const std::exception& e) {
                    std::cerr << "Conversion failed for image: " << inputPaths[i] 
                              << " Reason:" << e.what() << "\n";
                }
            });
        }

        for(auto& thread : threads){
            if (thread.joinable()) {
                thread.join();  // wait for all threads to finish
            }
        }
    }
};
```

