const express = require('express');
const jwt = require('jsonwebtoken');
const oauthServer = require('express-oauth-server'); // express-oauth-server is used for OAuth2 server and provider middlewares
const redis = require('redis');
const client = redis.createClient();
const RateLimit = require('express-rate-limit');
let app = express();

app.use(require('body-parser').urlencoded({ extended: false }));

// Authentication Middleware
app.use((req, res, next) => {
    // Implement authentication check here
    jwt.verify(req.headers['authorization'], 'YOUR_SECRET', (err, decoded) => {
        if (err) return res.status(403).send({ success: false, message: 'Invalid Token.' });
        req.decoded = decoded;
        next();
    });
});

// Middleware for Caching Responses
app.use((req, res, next) => {
  let key =  '__express__' + req.originalUrl || req.url;
  client.get(key,function(error,reply){
      if(reply) {
          console.log("Cache Hit!");
          res.send(JSON.parse(reply));
      } else {
          console.log("Cache Miss!");
          res.sendResponse = res.send;
          res.send = (body) => {
              client.setex(key, 60 * 60, JSON.stringify(body)); // Caching for an hour
              res.sendResponse(body)
          };
          next();
      }
  });
});

// Rate Limiter Middleware
const limiter = new RateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    delayMs: 0 // disable delaying - full speed until the max limit is reached
});
app.use(limiter);

// Load balancer for dynamic routing of requests (round robin)
let services = ['http://localhost:3001', 'http://localhost:3002']; // backend service urls
let index = 0;
app.use('/api/*', (req, res) => {
    req.pipe(services[index]).pipe(res);
    index = (index + 1) % services.length;
});

// Health check middleware for fallback mechanisms 
app.use((err, req, res, next) => {
   if (req.xhr) { // Handle only ajax requests
     return res.status(500).send({ error: 'Something failed!' });
   }
   next(err);
});
```
