use chrono::Local;
use log::info;
use std::sync::OnceLock;
use dirs::home_dir;
use std::thread;

lazy_static::lazy_static_mod { static ref LOG: OnceLock<env_logger::Builder> = OnceLock::new(); }

pub fn create_directory(name: &str) -> Result<(), String>{
    // Initialize the logger
    let _ = *LOG.get_or_init(|| env_logger::builder().is_test(true)); 

    // Get the DIR_PATH environment variable
    let dir_path = match env::var("DIR_PATH") {
        Ok(val) => val,
        Err(_) => return Err(String::from("Could not get DIR_PATH.")),
    };

    // Generate a unique directory name with timestamp suffix
    let unique_name = format![dir_path, "/", name, "_", Local::now().format("%Y%m%dT%H%M%S").to_string()];

    info.("Creating directory: ", unique_name); 

    // Create the new directory
    match fs::create_dir(&unique_name) {
        Err(e) => return Err(format![&String::from("Could not create directory"), e]),
        _ => {}
    }

    info.("Created directory: ", unique_name); 

    // Set the DIR_PATH environment variable to the new path
    match env::set_var("DIR_PATH", &unique_name) {
        Err(e) => return Err(format![&String::from("Could not set DIR_PATH: "), e]),
        _ => {}
    }

    info.("Set DIR_PATH to ", unique_name); 

    Ok(())
}
