import asyncio
from collections import defaultdict
from diskcache import Cache
from retrying import retry
from web_interface import WebInterface

class DataAggregator:
    def __init__(self):
        self.data_sources = []
        self.logging_systems = {}
        self.api_clients = defaultdict(list)
        self.cache = Cache("./cachedir")  # Using disk cache for memory and disk efficiency

    def add_source(self, source):
        self.data_sources.append(source)

    def add_logging_system(self, system):
        if isinstance(system, LoggingSystemInterface):
            self.logging_systems[system.name] = system

    def add_api_client(self, client):
        if isinstance(client, APIInterface):
            self.api_clients[client.source].append(client)

    @retry(wait_exponential_multiplier=1000, stop_max_attempt_number=3)  # Retry decorator for network/API failures
    def fetch_data(self):
        loop = asyncio.get_event_loop()

        tasks = []
        for source in self.data_sources:
            client = self.api_clients[source]
            tasks.append(asyncio.ensure_future(client.fetch()))

        responses = loop.run_until_complete(asyncio.gather(*tasks))

        return responses

    def aggregate_data(self):
        data = self.fetch_data()  # Fetch data from API clients asynchronously
        for source, response in zip(self.data_sources, data):
            if isinstance(response, Exception):
                self.logging_systems['error'].log(f"Failed to fetch data from {source}: {str(response)}")
                continue

            self.cache[source] = response  # Cache fetched data

        return "Data aggregation complete."

if __name__ == '__main__':
    da = DataAggregator()
    cli = CommandLineInterface(da)
    wb = WebDashboard(da)

    da.add_logging_system(LoggingSystem('error'))  # Example logging system initialization
    da.add_api_client(APIClient('source1', 'https://example-source.com/api'))  # Example API client initialization
    da.add_source('source1')  # Adding a data source

    cli.run()  # Run command line interface
