void *convert_thread(void *arg) {
    sem_t *sem = (sem_t*) arg;

    sem_wait(sem);  // Wait on semaphore before proceeding

    // Call to convert image to pdf
    char infile[] = "/path/to/image.jpg";
    char outfile[] = "/output/path/report.pdf";
    if (convert_to_pdf(infile, outfile) != 0) {
        printf("Conversion failed\n");
        sem_post(sem);  // Release the semaphore when failed
        return NULL;
    }

    sem_post(sem);  // Release the semaphore when succeeded
    return NULL;
}

int convert_images_to_pdf(char *dir, char *outfile) {
    int concurrency = 5;  // Number of allowed threads to execute at once
    sem_t sem;

    if (sem_init(&sem, 0, concurrency) == -1) {
        printf("Failed to initialize semaphore\n");
        return 1;
    }

    // Get list of images in directory here...

    pthread_t threads[concurrency];
    for (int i = 0; i < concurrency; i++) {
        if (pthread_create(&threads[i], NULL, convert_thread, &sem) != 0) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < concurrency; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            printf("Failed to join thread\n");
            return 1;
        }
    }

    sem_destroy(&sem); // Destroy semaphore after use
    return 0;
}
