    if (!fs::is_directory(inputDirPath)) {
        Logger::error("Input path is not a valid directory.");
        return "Invalid input";
    }

    if (!fs::exists(outputDirPath) && !fs::create_directories(outputDirPath)) {
        Logger::error("Could not create output directory.");
        return "Output creation error";
    }

    // Create sub-directory for optimized images.
    std::string optimizedImgDir = (fs::path(outputDirPath) / "optimized_images").string();
    if (!fs::create_directories(optimizedImgDir)) {
        Logger::error("Could not create optimized image directory.");
        return "Optimized image directory creation error";
    }

    // Initialize zip object.
    int err = 0;
    zip* z = zip_open((outputDirPath + "/reports.zip").c_str(), ZIP_CREATE, &err);
    if (z == nullptr) {
        Logger::error("Could not create zip file.");
        return "Zip creation error";
    }

    ThreadPool pool;
    std::atomic<int> failedOps(0);
    for (const auto& user : userData) {
        // Render template and save as HTML.
        pool.enqueue([&]() {
            try {
                std::string html = renderTemplate(user);  // hypothetical function to generate html report
                zip_source* s = zip_source_buffer(z, html.c_str(), html.size(), 0);
                if (zip_add(z, ("reports/" + user["name"].get<std::string>() + ".html").c_str(), s) < 0) {
                    Logger::error("Could not add report to zip file.");
                    failedOps++;
                }
            } catch (const std::exception& e) {
                Logger::error(e.what());
                failedOps++;
            }
        });
    }

    for (const auto& entry : fs::directory_iterator(inputDirPath)) {
        if (fs::is_regular_file(entry.path()) && isImageFile(entry.path().extension().string())) {
            pool.enqueue([&]() {
                try {
                    // Optimize and resize image using hypothetical library function.
                    auto optimizedImg = optimizeAndResize(entry.path());
                    fs::copy(optimizedImg, optimizedImgDir / entry.path().filename(), fs::copy_options::overwrite_existing);
                } catch (const std::exception& e) {
                    Logger::error(e.what());
                    failedOps++;
                }
            });
        }
    }

    pool.close(); // wait for all tasks to complete

    zip_close(z); // close and save the zip file

    return failedOps == 0 ? (outputDirPath + "/reports.zip") : ("Failed operations: " + std::to_string(failedOps));
}
