```python
import boto3
from botocore.exceptions import BotoCoreError, ClientError
from tenacity import retry, wait_exponential, stop_after_attempt
from concurrent.futures import ThreadPoolExecutor, as_completed
from hashlib import md5
import requests
import logging
from collections import deque
import time

class FileChunkUploader:
    def __init__(self, config):
        self.config = config
        self.session = boto3.Session(**self.config)
        self.s3_client = self.session.client("s3")
        self.uploaded_files = {}
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.queue = deque()
        logging.basicConfig(filename="logfile", filemode='a', level=logging.INFO, format='%(asctime)s - %(message)s')

    @retry(wait=wait_exponential(multiplier=1, min=4, max=10), stop=stop_after_attempt(3))
    def upload_chunk(self, filepath, chunk):
        if self.is_cached(filepath):
            bucket = md5(filepath.encode()).hexdigest()
            return self.s3_client.upload_part(Bucket=bucket, Key=filepath, PartNumber=chunk[0], UploadId=self.uploaded_files[filepath])
        else: 
            response = self.initiate_multipart_upload(filepath)
            self.cache(response['UploadId'], filepath)
            return self.s3_client.upload_part(Bucket=md5(filepath.encode()).hexdigest(), Key=filepath, PartNumber=chunk[0], UploadId=response['UploadId'])

    def initiate_multipart_upload(self, filepath):
        try:
            return self.s3_client.create_multipart_upload(Bucket=md5(filepath.encode()).hexdigest(), Key=filepath)
        except ClientError as e:
            logging.error(e)

    def is_cached(self, filepath):
        return filepath in self.uploaded_files

    def cache(self, uploadId, filepath):
        self.uploaded_files[filepath] = uploadId

    @retry(wait=wait_exponential(multiplier=1, min=4, max=10), stop=stop_after_attempt(3))
    def complete_multipart_upload(self, filepath):
        if self.is_cached(filepath):
            parts = [{'ETag': part[2], 'PartNumber': part[0]} for part in sorted(self.queue[filepath].values(), key=lambda x: x[1])]
            try:
                response = self.s3_client.complete_multipart_upload(Bucket=md5(filepath.encode()).hexdigest(), Key=filepath, UploadId=self.uploaded_files[filepath], MultipartUpload={'Parts': parts})
            except ClientError as e:
                if e.response['Error']['Code'] == "EntityTooSmall":
                    logging.error("The total size of the file is less than 5MB")
                else:
                    raise

    def abort_multipart_upload(self, filepath):
        try:
            self.s3_client.abort_multipart_upload(Bucket=md5(filepath.encode()).hexdigest(), Key=filepath, UploadId=self.uploaded_files[filepath])
        except ClientError as e:
            logging.error(e)

    def upload(self, filepath):
        # Split file into chunks (This depends on how you want to split the files)
        chunks = [(i+1, chunk) for i, chunk in enumerate(chunk_file(filepath))]
        self.queue[filepath] = {}

        futures = []
        for chunk in chunks:
            future = self.executor.submit(self.upload_chunk, filepath, chunk)
            futures.append(future)

        for future in as_completed(futures):
            try: 
                response = future.result()
                self.queue[filepath][response['PartNumber']] = (response['PartNumber'], response['ETag'])
            except Exception as exc:
                logging.error("An error occurred during chunk upload", exc_info=True)

        return self.complete_multipart_upload(filepath)
