```php
class PasswordManager {
    private $hashedPassword;
    private $characterSet = '';
    private $saltRoundCount = 12;

    public function generateRandomString($length, $characterSet) {
        if(!$this->validateCharacterSet($characterSet)) {
            throw new Exception('Invalid character set.');
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $index = random_int(0, strlen($characterSet) - 1);
            $randomString .= $characterSet[$index];
        }

        $this->characterSet = $characterSet;
        return $randomString;
    }

    public function hashPassword($password, $saltRoundCount = null) {
        if(!is_null($saltRoundCount)) {
            $this->setSaltRoundCount($saltRoundCount);
        }

        $hash = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        $this->hashedPassword = $hash;
        return $hash;
    }

    public function checkPassword($providedPassword, $hashedPassword = null) {
        if(!is_null($hashedPassword)) {
            $this->hashedPassword = $hashedPassword;
        }

        return password_verify($providedPassword, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        $uppercase = preg_match('@[A-Z]@', $characterSet);
        $lowercase = preg_match('@[a-z]@', $characterSet);
        $number    = preg_match('@[0-9]@', $characterSet);
        $specialChars = preg_match('@\W@', $characterSet);

        return ($uppercase && $lowercase && $number && $specialChars);
    }

    public function setSaltRoundCount($rounds) {
        $this->saltRoundCount = min(max(8, $rounds), 31);
    }

    // Mock implementation of external service check. Replace with actual call to the service in production code.
    public function externalPolicyCheck($characterSet) {
        return true;
    }

    public function resetPassword() {
        $randomString = $this->generateRandomString(10, $this->characterSet);
        return $this->hashPassword($randomString, $this->saltRoundCount);
    }
}
```
