Below is a C# function that demonstrates how to parse an XML document using XPath. The LINQ to XML (XDocument) namespace is used for parsing the XML, and System.Xml.Linq provides extension methods for querying and manipulating XML trees. 

```csharp
using System;
using System.IO;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;
using Microsoft.Extensions.Configuration;
using System.Runtime.Caching;

public class XmlParser
{
    private readonly IConfiguration _configuration;
    private MemoryCache cache = new MemoryCache("XMLDocumentCache");

    public XmlParser(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    public Dictionary<string, string> ParseXmlWithXPath(string xpathQuery, int limit)
    {
        var xmlFilePath = _configuration.GetSection("AppSettings:XmlDocumentPath").Value;

        if (!File.Exists(xmlFilePath)) throw new FileNotFoundException();

        XmlDocument doc = cache[xpathQuery] as XmlDocument;

        // Check the cache for already parsed XML document. If it's not there, parse the file and add to cache.
        if (doc == null)
        {
            doc = new XmlDocument();
            doc.Load(xmlFilePath);

            var policy = new CacheItemPolicy 
            { 
                AbsoluteExpiration = DateTimeOffset.Now.AddMinutes(10), 
                RemovedCallback = args => Console.WriteLine("XML document removed from cache") 
            };
            cache.Set(xpathQuery, doc, policy);
        }

        XmlNamespaceManager nsmgr = new XmlNamespaceManager(doc.NameTable);
        nsmgr.AddNamespace("ns", "http://www.tempuri.com"); // Replace with your namespace

        Dictionary<string, string> results = new Dictionary<string, string>();
        var nodes = doc.SelectNodes(xpathQuery, nsmgr);

        if (nodes == null || nodes.Count == 0) throw new Exception("No elements found.");
        if (nodes.Count > limit) throw new Exception("Number of matching elements exceeds the specified limit.");

        foreach (XmlNode node in nodes)
        {
            results.Add(node.Name, node.InnerText);
        }

        return results;
    }
}
``` 
Please note that you need to provide the XPath query and the limit as parameters to ParseXmlWithXPath method. Also, replace `http://www.tempuri.com` with your actual XML namespace in XmlNamespaceManager creation line (nsmgr.AddNamespace("ns", "http://www.tempuri.com");).

This is a basic implementation and can be optimized for larger files by streaming the file instead of loading it into memory all at once, which would require additional error handling for corrupt or malformed XML documents. Furthermore, caching strategies need to be designed based on specific requirements like eviction policies, time-to-live etc.

