```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <unistd.h>
#include <fcntl.h>
#define SEM_ID 123456

int createSemaphore(key_t key, int initialValue) {
    int semid = semget(key, 1, IPC_CREAT | 0666);
    if (semid < 0) exit(EXIT_FAILURE);

    union semun arg;
    arg.val = initialValue;
    if (semctl(semid, 0, SETVAL, arg) == -1) {
        perror("Semaphore initialization failed");
        return EXIT_FAILURE;
    }

    printf("Semaphore created with ID: %d\n", semid);
    return semid;
}

void deleteSemaphore(int semid) {
    if (semctl(semid, 0, IPC_RMID) == -1) {
        perror("Semaphore deletion failed");
        exit(EXIT_FAILURE);
    }
}

void acquireSemaphore(int semid) {
    struct sembuf operation;
    operation.sem_num = 0;
    operation.sem_op = -1;
    operation.sem_flg = 0;

    if (semop(semid, &operation, 1) == -1) {
        perror("Semaphore acquire failed");
        exit(EXIT_FAILURE);
    }
}

void releaseSemaphore(int semid) {
    struct sembuf operation;
    operation.sem_num = 0;
    operation.sem_op = 1;
    operation.sem_flg = 0;

    if (semop(semid, &operation, 1) == -1) {
        perror("Semaphore release failed");
        exit(EXIT_FAILURE);
    }
}
```
