```js
import yaml from 'yaml';

const cache = new Map();
let config;
try {
  config = yaml.load('config.yaml'); // load configuration file
} catch (e) {
  console.error("Failed to load or parse the configuration file: ", e);
  process.exit(1);
}

const modulesLoaded = new Set();
let loadingModuleCount = 0;

async function loadModule(moduleName, path) {
  if (cache.has(path)) return cache.get(path); // return cached module if available

  try {
    const startTime = performance.now();
    const loadedModule = await import(path);

    console.log(`Loaded module '${moduleName}' in ${performance.now() - startTime} ms.`)
    cache.set(path, loadedModule); // store module in cache
    modulesLoaded.add(moduleName);
  } catch (e) {
    console.error(`Failed to load '${moduleName}' at path: ${path}. Error message: `, e.message);
  }
}

async function loadModules() {
  loadingModuleCount = config.modules.length;

  for (let module of config.modules) {
    if (!module.dependencies || modulesLoaded.has(module.name)) { // dependencies are already satisfied
      await loadModule(module.name, module.path);
    } else {
      setTimeout(() => loadModule(module.name, module.path), 0) // defer loading if dependencies aren't met
    }
  }
}

async function waitForAllModulesToLoad() {
  return new Promise((resolve) => {
    const intervalId = setInterval(() => {
      if (loadingModuleCount === 0) {
        clearInterval(intervalId);
        resolve();
      }
    }, 100);
  });
}

// Entry point to start loading modules:
loadModules().then(() => waitForAllModulesToLoad()).catch((e) => console.error('Failed to load all modules', e));
```
In this example, the `config.yaml` file would contain configuration for each module to be loaded, like its name and path in the system as well as any dependencies it might have on other modules. The `loadModule()` function dynamically loads a module using the import() function and stores it in a cache if it hasn't been loaded before or the caching is disabled.

