using System;
using System.IO;
using System.Threading;
using System.Collections.Generic;
using PdfSharp.Pdf;
using PdfSharp.Drawing;
using GdSharp.ExtensionMethods;
using ImageMagick;

public class Program
{
    private static readonly SemaphoreSlim semaphore = new SemaphoreSlim(5, 5); // Maximum concurrency level is set to 5 for demonstration purposes

    public async Task convert_images_to_pdf(string directoryPath, string outputFileName, List<string> imageFileNames)
    {
        try
        {
            await semaphore.WaitAsync();

            using (var pdf = new PdfDocument())
            {
                foreach (var fileName in imageFileNames)
                {
                    var path = Path.Combine(directoryPath, fileName);
                    if (!File.Exists(path))
                        continue;

                    var page = pdf.AddPage();
                    using (XGraphics gfx = XGraphics.FromPdfPage(page))
                    {
                        using (var image = MagickImage.FromFile(fileName))
                        {
                            byte[] bytes = image.ToByteArray();
                            var ximg = XImage.FromStream(() => new MemoryStream(bytes));
                            gfx.DrawImage(ximg, 0, 0);
                        }
                    }
                }

                pdf.Save(outputFileName);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message); // Basic error logging for demonstration purposes
        }
        finally
        {
            semaphore.Release();
        }
    }

    static void Main(string[] args)
    {
        var directoryPath = "./images"; // Replace with actual path
        var outputFileName = "output.pdf"; // Replace with actual name
        var imageFileNames = new List<string>() { "image1.jpg", "image2.png" }; // Replace with actual images

        Program p = new Program();
        p.convert_images_to_pdf(directoryPath, outputFileName, imageFileNames).Wait();
    }
}
