class SecurePasswordManager {
    private $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890'; // Character set for password generation 

    public function generateRandomString($length) {
        $password = '';
        for ($i = 0; $i < $length; $i++) {
            $index = mt_rand(0, strlen($this->charset) - 1);
            $password .= $this->charset[$index];
        }
        return $password;
    }

    public function hashPassword($password, $salt){
        // Use a secure hashing algorithm like bcrypt or Argon2 with PHP's password_hash()
        $options = [ 'cost' => 10 ]; // Adjust cost according to your security requirements 
        $hashedPassword = password_hash($password.$salt, PASSWORD_DEFAULT, $options);
        return $hashedPassword;
    }

    public function verifyPassword($hashedPassword, $password, $salt) {
        // Verify the hashed password with PHP's password_verify()
        if (password_verify($password.$salt, $hashedPassword)) return true; 
        else return false;
    }
}
