#include <stdio.h>
#include <semaphore.h>
#include <pthread.h>
#include <unistd.h>

typedef enum { BINARY, COUNTING } sem_type;

// Forward declarations for the library functions
int createSemaphore(sem_t* handle, const char* name, int initialValue, sem_type type);
int deleteSemaphore(sem_t* handle);
int acquireSemaphore(sem_t* handle);
int releaseSemaphore(sem_t* handle);
// Other necessary functions...

int main() {
    // Example usage of the library
    sem_t sem;
    createSemaphore(&sem, "test", 1, BINARY);

    pthread_t thread;
    pthread_create(&thread, NULL, (void* (*)(void*))acquireSemaphore, &sem);

    sleep(1); // Ensure that the other thread has acquired the semaphore before we try to acquire it again.
    acquireSemaphore(&sem);

    pthread_join(thread, NULL);

    releaseSemaphore(&sem);
    deleteSemaphore(&sem);
}
