JavaScript Function:
```javascript
const fetch = require('node-fetch');
let semaphore = require('semaphore')(20); // Maximum parallel requests at a time
let throttle = require('promise-throttle'); // Throttling for rate limits
let cache = {}; // Caching external API calls
let timeout = 5; // Seconds

async function asyncArrayReduce(array, initialValue, callback) {
    let result = initialValue;
    let completedOperations = 0;

    for (let i=0;i<array.length;i++){
        semaphore.take(); // Acquire a slot from the semaphore
        try {
            throttle({
                promise: callback, 
                arguments: [result, array[i]], 
                timeout: timeout * 1000 // Convert seconds to milliseconds
            })
            .then(res => {
                result = res;
                completedOperations++;
                console.log('Completed operations: ' + completedOperations); // Log the progress of the reduction process
                semaphore.leave(); 
            })
        } catch (err) {
            semaphore.leave();
            console.error(err); // Handle error in callback
        }
    }

    return result;
}
```
Note: This code uses `node-fetch` for HTTP requests, `semaphore` and `promise-throttle` libraries for rate limiting and controlling concurrency, and a simple object as a cache. The callback function should be provided by the user of this function. 

