class NetworkDeviceCluster {
public:
    typedef boost::shared_ptr<NetworkDeviceCluster> Ptr;

    static Ptr create(const std::vector<std::string>& filePaths) {
        return Ptr(new NetworkDeviceCluster(filePaths));
    }

    nlohmann::json getSettingByKey(const std::string& key) const {
        boost::lock_guard<boost::mutex> lock(mMutex);

        if (mSettings.contains(key)) {
            return mSettings[key];
        } else {
            throw std::runtime_error("Key not found in settings");
        }
    }

    // ... add methods for saving and registering observers ...

private:
    NetworkDeviceCluster(const std::vector<std::string>& filePaths) : mSettings() {
        for (const auto& path : filePaths) {
            try {
                loadFromFile(path);
            } catch (const std::exception& e) {
                // handle error, log it, etc.
            }
        }
    }

    void loadFromFile(const std::string& path) {
        boost::lock_guard<boost::mutex> lock(mMutex);

        std::ifstream fileStream(path);
        if (!fileStream.is_open()) {
            throw std::runtime_error("Failed to open file: " + path);
        }

        nlohmann::json json;
        fileStream >> json;

        // validate and merge the settings here...
        mSettings.merge(json);
    }

    mutable boost::mutex mMutex;
    nlohmann::json mSettings;
};
