public async Task ProcessFileAndExecuteRemoteCommands(byte[] fileContent, Configuration config, int timeout) {
    var localConfig = await ReadLocalConfigurationAsync(config.PathToLocalConfig);
    if (localConfig == null || !IsValidConfiguration(localConfig)) {
        throw new Exception("Invalid configuration");
    }

