```csharp
public async Task<CommandResult> ExecuteCommandAsync(string command, byte[] fileContent, int timeout) {
    var request = new Request(command, fileContent);

    for (int i = 0; i < MaxRetries; i++) {
        try {
            return await SendRequestWithTimeoutAsync(request, timeout);
        } catch (Exception ex) when (i < MaxRetries - 1) {
            Logger.Warn("Command execution failed, retrying", ex);

            // Back off before retry
            await Task.Delay((int)(Math.Pow(2, i + 1) * 1000));
        }
    }

    throw new Exception("Failed to execute command after multiple attempts");
}
