class OctreeNode {};  // replace with actual implementation of octree node

std::mutex mtx;
bool thread_safe = true; // set to false for testing single-threaded behavior

void log(const std::string& msg) {
    auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    std::cout << std::ctime(&now) << ": " << msg << std::endl;
}

OctreeNode* buildTreeRecursive(const std::vector<Point>& points, float size, unsigned int capacity) {
    if (points.size() <= capacity || size < 0.1) return new OctreeNode(points); // leaf node condition

    std::vector<std::vector<Point>> octants(8);
    for (const auto& point : points) {
        int index = ((point.x > 0 ? 1 : 0) << 2) | ((point.y > 0 ? 1 : 0) << 1) | (point.z > 0 ? 1 : 0); // calculate octant index
        octants[index].push_back(point);
    }

    auto node = new OctreeNode();
    for (int i = 0; i < 8; ++i) {
        if (!octants[i].empty()) {
            std::lock_guard<std::mutex> lock(mtx, std::adopt_lock); // RAII-style locking for thread safety
            node->children[i] = buildTreeRecursive(octants[i], size / 2, capacity);
        } else {
            node->children[i] = nullptr;
        }
    }

    return node;
}

OctreeNode* buildAndManageOctree(const std::string& filename, float featureSize, unsigned int leafCapacity) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        log("Error: Could not open file " + filename);
        return nullptr;
    }

    // Read point cloud data from the file. Replace this with actual implementation for PLY, OBJ or custom binary formats.
    std::vector<Point> points = readPointsFromFile(file); 

    log("Building octree...");
    auto start_time = std::chrono::high_resolution_clock::now();

    OctreeNode* root = buildTreeRecursive(points, featureSize, leafCapacity);

    if (!thread_safe) mtx.unlock(); // release lock in single-threaded environment

    auto end_time = std::chrono::high_resolution_clock::now();
    log("Octree built successfully in " + std::to_string(std::chrono::duration<double, std::milli>(end_time - start_time).count()) + " ms");

    return root;
}
