Here's a simplified version of how such a function could look like in JavaScript using Node.js streams API:

```javascript
const fs = require('fs');

/**
 * Asynchronously copies bytes from source to destination according to the provided byte ranges.
 * @param {Array|Buffer|Stream} sources The list of buffered data chunks or files. 
 * Each element can be a Buffer, a File (Node.js fs module), or a Stream.
 * @param {WritableStream} destination Where to copy the bytes.
 * @param {Array} byteRanges The specified number of bytes ranges for each source. Should be an array 
 * of arrays with 2 elements representing start and end offsets. For example: [[0, 10], [5, 15]] means copy 
 * bytes from position 0 to 10 from the first source and bytes from position 5 to 15 from the second one.
 */
async function copyBytes(sources, destination, byteRanges) {
    return new Promise((resolve, reject) => {
        const streams = [];

        sources.forEach((source, i) => {
            // Check if source is Buffer or File and create Readable stream from it.
            let srcStream;

            if (Buffer.isBuffer(source)) {
                srcStream = fs.createReadStream('', { buffer: source });
            } else if (source instanceof fs.ReadStream) {
                srcStream = source;
            } else {
                reject(new Error('Invalid source type'));
            }

            const [start, end] = byteRanges[i];

            // Validate range and start copying bytes.
            if (start < 0 || end > source.length) {
                reject(new Error('Requested byte range exceeds the available data in the source'));
            } else {
                srcStream.pipe(destination, { end });
                streams.push(srcStream);
            }
        });

        // Clean up resources when all operations finish or an error is thrown.
        Promise.all(streams.map(stream => new Promise((resolve, reject) => {
            stream.on('end', resolve);
            stream.on('error', reject);
        }))).then(() => {
            // All streams have finished reading their source data.
            resolve();
        }, reject).finally(() => {
            for (const stream of streams) {
                stream.destroy();
            }
        });
    });
}
```

This is a basic implementation and doesn't handle all scenarios you might encounter in production, but it provides a good starting point. It also assumes that if multiple sources are provided, they should be read and copied in parallel, which may not always be desirable or efficient depending on the use case. Error handling needs to be enhanced, and functionality for handling overlapping byte ranges could be added as well.

