log.basicConfig(level=log.INFO)

class LoadBalancerAPI:
    def __init__(self):
        self.configs = []
        self._lock = Lock()

    def generate_id(self):
        return random.randint(1000, 9999)

    def assign_weight(self, id, weight):
        if weight < 1 or weight > 100:
            raise ValueError("Weight must be between 1 and 100")

        for config in self.configs:
            if config['ServerID'] == id:
                log.info(f"Updating weight of Server ID {id} to {weight}")
                config['Weight'] = weight
                return

        new_config = {"ServerID": id, "PortNumber": random.randint(1024, 65535), "Weight": weight}
        self.configs.append(new_config)
        log.info(f"New server configuration added: {new_config}")

    def get_config(self, id):
        for config in self.configs:
            if config['ServerID'] == id:
                return config
        raise ValueError("No such Server ID found")

    def delete_config(self, id):
        with self._lock:
            for i, config in enumerate(self.configs):
                if config['ServerID'] == id:
                    log.info(f"Deleting server configuration {id}")
                    del self.configs[i]
                    return
            raise ValueError("No such Server ID found")

    def get_all_configs(self):
        return self.configs
```

