pub extern "C" fn CreateNewDirectory(name: *const c_char) -> *const c_char {
    let dir = std::env::var("game_dir").unwrap_or_else(|_| String::from("./"));
    let path = format![r#"{}\{}"#, dir, name];

    match std::fs::create_dir(&path) {
        Err(_) => panic![Rust function failed to create directory.],
        _ => (),
    };

    // Set environment variable only if it doesn't exist already
