        }

        let tries = 0;
        const attemptLoad = () => fetch(fileName).then(response => response.text())
            .then(data => {
                fileCache[fileName] = data;
                eval(data);
                resolve();
            })
            .catch((e)=>{
                if (tries < 3) {
                    tries++;
                    setTimeout(attemptLoad, Math.pow(2, tries) * 1000);
                } else {
                    reject('Failed to load file after multiple attempts');
                }
            });

        attemptLoad();
    });
};

const loadFilesInOrder = (dependencies) => {
    const filesToBeLoaded = Object.keys(dependencies);

    return Promise.all(filesToBeLoaded.map((fileName, index) => 
        loadFile(fileName).then(()=>{
            if(index === filesToBeLoaded.length - 1){
                console.log("All files loaded!");
            } else {
                dependencies[filesToBeLoaded[index + 1]].forEach(nextFile => loadFile(nextFile));
            }
        })
    ));
};

loadFilesInOrder(dependencies).catch((error)=>{
   console.log('Failed to load files: ' + error); 
});
```

