    /* Implement key distribution logic here */
    pthread_mutex_unlock(&lock);  /* Unlock after modification */
    return NULL;
}

char* hashConfig(const char *config) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)config, strlen(config), digest);    

    char *mdString = malloc(MD5_DIGEST_LENGTH*2+1);
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }

    return mdString;
}

void assignAndHash(const char *jsonConfig, const char **keys) {
    json_t *root = json_loads(jsonConfig, 0, NULL);
    /* Parse JSON and get range */

    int numKeys = 0; while (keys[numKeys++] != NULL); /* Calculate number of keys */

    pthread_t threads[numKeys];
    for(int i = 0; i < numKeys; ++i) {
        if(pthread_create(&threads[i], NULL, assignKeys, (void*)keys[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for(int i = 0; i < numKeys; ++i) {
        if(pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return;
        }
    }

    char* md5 = hashConfig(jsonConfig);
    printf("MD5: %s\n", md5);
}
