```CSharp
using System;
using System.Collections.Concurrent;
using System.Xml;
using System.Xml.Schema;
using System.IO;

public class XmlParserLibrary : IDisposable
{
    private ConcurrentDictionary<string, Tuple<DateTime, XmlDocument>> _cache = new ConcurrentDictionary<string, Tuple<DateTime, XmlDocument>>();
    private TimeSpan _expirationTime = TimeSpan.FromHours(1);
    private int _rateLimit = 10; // per second
    private DateTime _lastRateCheck = DateTime.MinValue;
    private int _currentRateCount = 0;

    public XmlParserLibrary() { }

    public void SetExpirationTime(TimeSpan expirationTime)
    {
        this._expirationTime = expirationTime;
    }

    public void SetRateLimit(int rateLimit)
    {
        this._rateLimit = rateLimit;
    }

    private bool CheckRate()
    {
        var now = DateTime.Now;
        if ((now - _lastRateCheck).TotalSeconds < 1)
        {
            if (_currentRateCount >= _rateLimit) return false;
            _currentRateCount++;
        }
        else
        {
            _lastRateCheck = now;
            _currentRateCount = 0;
        }
        return true;
    }

    public XmlDocument Parse(string path, string schemaPath)
    {
        if (!CheckRate()) throw new Exception("Rate limit exceeded.");

        if (_cache.TryGetValue(path, out var cacheEntry))
        {
            if ((DateTime.Now - cacheEntry.Item1) < _expirationTime) return cacheEntry.Item2;
        }

        var xmlDoc = new XmlDocument();
        try
        {
            xmlDoc.Load(path);

            // validate against schema
            var schemas = new XmlSchemaSet();
            using (var reader = new StreamReader(schemaPath))
            {
                schemas.Add("", XmlReader.Create(reader));
            }
            xmlDoc.Schemas = schemas;

            xmlDoc.Validate((o, e) => throw new Exception($"Validation error: {e.Message}"));
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message); // replace with logger
            return null;
        }

        _cache[path] = Tuple.Create(DateTime.Now, xmlDoc);
        return xmlDoc;
    }

    public XmlNodeList QueryWithXPath(string xpathQuery, XmlDocument document)
    {
        if (!CheckRate()) throw new Exception("Rate limit exceeded.");

        try
        {
            var navigator = document.CreateNavigator();
            return navigator.Select(xpathQuery);
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message); // replace with logger
            return null;
        }
    }

    public void Dispose()
    {
        _cache.Clear();
    }
}
```

