```c
#include <stdio.h>
#include <string.h>
#include <jansson.h> // third-party library for JSON parsing in C
#include <curl/curl.h> // third-party library for HTTP requests in C
#include "uthash.h" // third-party library for hash tables in C
#include "apr_hash.h" // Apache Portable Runtime (APR) library
#include "apr_tables.h" // APR library

struct cache_entry {
    char *key; 
    json_t *value;
    UT_hash_handle hh; 
};

static struct cache_entry *cache = NULL;

void add_to_cache(char* key, json_t* value) {
    struct cache_entry *entry;

    HASH_FIND_STR(cache, key, entry);  
    if (entry==NULL){
        entry = malloc(sizeof(struct cache_entry));
        entry->key = strdup(key); 
        HASH_ADD_KEYPTR(hh, cache, entry->key, strlen(entry->key), entry);
    }

    json_incref(value); // increment reference count for value to ensure it doesn't get garbage collected
    if (entry->value) 
        json_decref(entry->value); // decrement the old reference count
    entry->value = value;
}

json_t* fetch_from_cache(char *key){
    struct cache_entry *entry;

    HASH_FIND_STR(cache, key, entry);  
    if (entry) {
        return json_deep_copy(entry->value); // returns a copy to avoid data corruption
    } else {
        return NULL; 
    }
}

void clear_cache(){
    struct cache_entry *current_entry, *tmp;

    HASH_ITER(hh, cache, current_entry, tmp) {
      HASH_DEL(cache, current_entry);  
      free(current_entry->key);
