```javascript
async function asyncArrayReduce(array, accumulator, initialValue, { maxParallelOps = 1, throttleIntervalMs = 0 } = {}) {
    let result = initialValue;

    const semaphore = new Semaphore(maxParallelOps); // Assume this exists and controls concurrency

    for (const item of array) {
        await semaphore.acquire();

        try {
            result = await accumulator(result, item); // Assuming accumulator returns a Promise

            if (throttleIntervalMs > 0) await new Promise((resolve) => setTimeout(resolve, throttleIntervalMs));
        } finally {
            semaphore.release();
        }
    }

    return result;
}
```

