// Global variables
int verbose = 0;
int case_sensitive = 0;
char *output = NULL;
FILE *logfile = NULL;

struct thread_data {
    int tid;
    char **files;
    int numFiles;
};

void usage() {
    printf("Usage: ./prog [--verbose] [-cs] -o output_file input_files\n");
    exit(EXIT_FAILURE);
}

int parseArguments(int argc, char *argv[]) {
    int i;
    for (i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--verbose")) {
            verbose = 1;
        } else if (!strcmp(argv[i], "-cs")) {
            case_sensitive = 1;
        } else if (!strncmp(argv[i], "-o ", 3)) {
            output = malloc(sizeof(char) * strlen(argv[i] + 2));
            strcpy(output, argv[i] + 3);
        } else if (argv[i][0] == '-' && !strncmp(argv[i], "--help", 6)) {
            usage();
        } else if (!strcmp(argv[i], "-o")) {
            if ((i + 1) < argc) {
                output = malloc(sizeof(char) * strlen(argv[i + 1]));
                strcpy(output, argv[++i]);
            } else {
                usage();
            }
        } else if (strncmp(argv[i], "-", 1)) {
            return i;
        } else {
            printf("Unknown option: %s\n", argv[i]);
            usage();
        }
    }
    return -1;
}

void* processFile(void *thread_arg) {
    struct thread_data *my_data = (struct thread_data *)thread_arg;

    for(int i=0;i<my_data->numFiles;++i){
        // read file, parse patterns, generate report
    }
    pthread_exit(NULL);
}

void signalHandler(int signum) {
    printf("\nInterrupt signal (%d) received.\n", signum);
    fclose(logfile);
    free(output);
    exit(signum);
}

int main(int argc, char *argv[]){
    int start_file = parseArguments(argc, argv);

    if (start_file == -1) {
        printf("No input files provided.\n");
        usage();
    }

    logfile = fopen("log.txt", "w");
    if(!logfile){
        perror("Cannot open output file");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signalHandler);

    int numThreads = sysconf(_SC_NPROCESSORS_ONLN); // get number of cores
    pthread_t threads[numThreads];
    struct thread_data td[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        td[i].tid = i;
        td[i].files = &argv[start_file] + i;
        td[i].numFiles = ((argc - start_file) % numThreads > i ? 1 : 0) + 
                         (argc - start_file) / numThreads;

        if(pthread_create(&threads[i], NULL, processFile, &td[i])){
            fprintf(logfile,"Error creating thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(logfile);
    free(output);

    return EXIT_SUCCESS;
}
```
