void logError(const char* message) {
    printf("Log Error: %s\n", message);
}

typedef struct {
    const char* filename;
    int digitCount;
    const char* fileType;
} FileOptions;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void ParseFilename(const char* filename, char** baseNamePtr, char** extensionPtr) {
    *baseNamePtr = strdup(filename);  // duplicate the original string for manipulation

    char* dotLocation = strrchr(*baseNamePtr, '.');  // find the last occurrence of '.' in the filename

    if (dotLocation != NULL) {  // If a dot is found, set the base name up to the dot and the extension after it
        *dotLocation = '\0';
        *extensionPtr = dotLocation + 1;
    } else {  // If no dot is found, the filename has no extension
        *extensionPtr = "";
    }
}

int DetermineDigits(const char* fileType) {
    if (strcmp(fileType, ".jpg") == 0 || strcmp(fileType, ".png") == 0) {
        return 3;
    } else if (strcmp(fileType, ".txt") == 0 || strcmp(fileType, ".pdf") == 0) {
        return 5;
    }

    // default to 2 for unsupported file types
    logError("Unsupported file type");
    return 2;
}

int ValidateFileType(const char* fileType) {
    const char* supportedTypes[] = {".txt", ".jpg", ".png", ".pdf"};

    for (size_t i = 0; i < sizeof(supportedTypes)/sizeof(char*); ++i) {
        if (strcmp(fileType, supportedTypes[i]) == 0) {
            return 1;  // valid file type
        }
    }

    logError("Invalid or unsupported file type");
    return 0;  // invalid file type
}

void SetFileType(char* baseName, const char* extension, const FileOptions* options) {
    if (strcmp(extension, options->fileType) != 0 && ValidateFileType(options->fileType)) {
        sprintf(baseName, "%s_modified.%s", baseName, options->fileType);
    } else {
        sprintf(baseName, "%s_modified", baseName);  // append "_modified" to the filename if no valid file type is provided
    }
}

char* CreateNewFilename(const FileOptions* options) {
    pthread_mutex_lock(&mutex);  // Lock for thread-safety

    char* baseName;
    const char* extension;
    ParseFilename(options->filename, &baseName, (char**)&extension);

    int digits = DetermineDigits(extension);

    // Allocate memory for the new filename based on the digit count and length of the base name
    size_t requiredLength = strlen(baseName) + strlen(options->fileType) + 13;  // "_modified.txt" is 12 characters long, add one more for null termination '\0'
    char* newFilename = malloc(requiredLength);

    SetFileType(baseName, extension, options);

    sprintf(newFilename, "%s_%0*d.%s", baseName, digits, rand() % (int)pow(10, digits), options->fileType);  // generate a random number with the specified digit count and append it to the new filename

    free((char*)baseName);  // Free dynamically allocated memory

    pthread_mutex_unlock(&mutex);  // Unlock for thread-safety

    return newFilename;
}
```

