        try{
            KafkaProducer<String, String> producer = new KafkaProducer<>();

            ProducerRecord<String, String> record = new ProducerRecord<>("chat-topic", null, chatMessage);

            // Add retry logic for transient failures when sending messages to the broker
            producer.send(record, (metadata, exception) -> {
                if (exception != null){
                    System.err.println("Failed to send message: " + exception);
                } else {
                    System.out.println("Message sent successfully");
                }
            });
        } catch(Exception e){
