class Styler {
    constructor() {
        this.cache = {};
    }

    // 获取元素的方法
    getElement(selector) {
        if (this.cache[selector]) {
            return Promise.resolve(this.cache[selector]);
        }

        return new Promise((resolve, reject) => {
            const element = document.querySelector(selector);

            if (element) {
                this.cache[selector] = element;
                resolve(element);
            } else {
                reject('No element found');
            }
        });
    }

    // 应用样式的方法
    applyStyle(element, style) {
        return new Promise((resolve, reject) => {
            if (window.CSS && window.CSS.supports && window.CSS.supports('background', 'var(--myVariable)')) {
                element.style = style;
                resolve();
            } else {
                reject('Unsupported CSS');
            }
        });
    }

    // 应用动态样式的方法
    applyDynamicStyle(element, property, value) {
        return new Promise((resolve, reject) => {
            if (window.CSS && window.CSS.supports && window.CSS.supports('background', 'var(--myVariable)')) {
                element.style[property] = value;
                resolve();
            } else {
                reject('Unsupported CSS');
            }
        });
    }
}
