#include <pthread.h> // for thread safety
#include <string.h>  // for string manipulation and compression

typedef struct {
    int key;
    long timestamp;
    char* description;
    double value;
} Record;

void fill_random(Record* records, size_t count) {
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % 10001; // key: 0 to 10000
        records[i].timestamp = time(NULL) + (rand() % (365*24*60*60)); // timestamp: current time to 1 year ahead

        size_t desc_length = rand() % 256; // description length: up to 255 characters
        records[i].description = malloc(desc_length + 1);

        if (records[i].description == NULL) {
            printf("Memory allocation error\n");
            exit(EXIT_FAILURE);
        }

        memset(records[i].description, 'A' + rand() % 26, desc_length); // fill with random characters
        records[i].description[desc_length] = '\0';

        records[i].value = -10000.0 + (rand() / (RAND_MAX / (10000.0 - (-10000.0)))); // value: -10000.0 to 10000.0
    }
}

Record* initialize_records(size_t count) {
    Record* records = calloc(count, sizeof(Record)); // allocate memory for an array of record structures

    if (records == NULL) {
        printf("Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    fill_random(records, count);

    return records;
}
