Implementing such a semaphore management system in C would require extensive use of system calls, signal handling, thread synchronization mechanisms (mutexes, condition variables), error handling, data structures (hash tables or trees for named semaphores) and file I/O operations. Given the complexity and requirements of this task, it's impractical to provide a complete solution in one code block.

Here is an example of how you might start implementing a simple version of such a system:

```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t *sem;
    pthread_mutex_t lock; // mutex for synchronization
} named_semaphore;

named_semaphore* createSemaphore(char *name, int value) {
    named_semaphore* sem = malloc(sizeof(named_semaphore));

    if (sem == NULL) {
        return NULL; // failed to allocate memory
    }

    sem->sem = sem_open(name, O_CREAT | O_EXCL, 0644, value);
    pthread_mutex_init(&sem->lock, NULL);

    if (SEM_FAILED == sem->sem) { // failed to create named semaphore
        free(sem);
        return NULL;
    }

    return sem;
}

void deleteSemaphore(named_semaphore *sem) {
    if (sem != NULL && SEM_FAILED != sem->sem) {
        pthread_mutex_lock(&sem->lock); // lock before deleting to prevent race condition
        sem_close(sem->sem);
        sem_unlink(name);
        free(sem);
    }
}

int incrementSemaphore(named_semaphore *sem) {
    if (sem == NULL || SEM_FAILED == sem->sem) {
        return -1; // invalid semaphore
    }

    pthread_mutex_lock(&sem->lock); // lock before modifying to prevent race condition
    int val;
    sem_getvalue(sem->sem, &val);

    if (val < 0) { // non-negative constraint
        pthread_mutex_unlock(&sem->lock);
        return -2; // failed operation
    }

    sem_post(sem->sem);
    pthread_mutex_unlock(&sem->lock);

    return 0; // successful operation
}

int decrementSemaphore(named_semaphore *sem) {
    if (sem == NULL || SEM_FAILED == sem->sem) {
        return -1; // invalid semaphore
    }

    pthread_mutex_lock(&sem->lock); // lock before modifying to prevent race condition
    int val;
    sem_getvalue(sem->sem, &val);

    if (val <= 0) { // non-negative constraint
        pthread_mutex_unlock(&sem->lock);
        return -2; // failed operation
    }

    sem_wait(sem->sem);
    pthread_mutex_unlock(&sem->lock);

    return 0; // successful operation
}
```
The above code snippet creates a named semaphore, deletes it and performs operations on the semaphore. It uses the POSIX semaphore API to create and operate on the semaphore, ensuring that they are system-wide (named) semaphores. Each operation is locked using a mutex before any modification is made to prevent race conditions.

