use actix_web::{get, web, App, HttpResponse, HttpServer, Responder};

static LOGGER: EnvLogger = EnvLogger {
    level_filter: LevelFilter::Info,
    retention_policy: 10,
    last_scan: DateTime::<Local>::from_utc(Utc.ymd(2000, 1, 1).and_hms(0, 0, 0), UtcOffset::UTC),
};

