#[get("/create")]
async fn create(dirname: web::Path<String>) -> impl Responder {
    let dirpath = PathBuf::from(&env::var("HOME").unwrap()).join(dirname);

    match fs::DirBuilder::new().recursive(true).create(dirpath.clone()) {
        Ok(_) => LOGGER.log_info(&format![
            "Directory {} created",
            &dirpath.display()
        ]),
        Err(e) => LOGGER.log_error(&format![
            "Failed to create directory: {}",
            e
        ]),
    };

    env::set_var("DIRPATH", dirpath);
    HttpResponse::Ok().body("Directory created successfully")
}

#[actix_web::main]
