function checkFileAvailability(src, callback) {
    var xhr = new XMLHttpRequest();
    xhr.open('HEAD', src, true);
    xhr.onreadystatechange = function() {
        if (this.readyState == this.DONE) {
            if(this.status == 200){
                callback();
            } else {
                console.log('File not available: ' + src);
            }
        }
    };
    xhr.send();
}
