using System;
using UnityEngine;

public class RandomValueGenerator
{
    private float minFloat, maxFloat;
    private int minInt, maxInt;

    public RandomValueGenerator(float minFloat, float maxFloat)
    {
        if (minFloat > maxFloat) throw new ArgumentException("Min value cannot be greater than Max value");

        this.minFloat = minFloat;
        this.maxFloat = maxFloat;
    }

    public RandomValueGenerator(int minInt, int maxInt)
    {
        if (minInt > maxInt) throw new ArgumentException("Min value cannot be greater than Max value");

        this.minInt = minInt;
        this.maxInt = maxInt;
    }

    public float GenerateFloat()
    {
        return UnityEngine.Random.Range(minFloat, maxFloat);
    }

    public int GenerateInteger()
    {
        return UnityEngine.Random.Range(minInt, maxInt + 1); // UnityEngine.Random.Range does not include the maximum value by default
    }

    public Vector3 GenerateVector3()
    {
        float x = GenerateFloat();
        float y = GenerateFloat();
        float z = GenerateFloat();

        return new Vector3(x, y, z);
    }

    public Quaternion GenerateQuaternion(Vector3 axis)
    {
        float angle = UnityEngine.Random.Range(minFloat, maxFloat);

        return Quaternion.AngleAxis(angle, axis);
    }

    public override string ToString()
    {
        return $"Min Float: {minFloat}, Max Float: {maxFloat}, Min Int: {minInt}, Max Int: {maxInt}";
    }

    // This method could be extended for more complex validation rules, or potentially even moved to another class if it was a lot of logic. 
    public bool ValidateValue(float value)
    {
        float tolerance = 0.1f; // Set your own tolerance level here

        return Math.Abs(value - (minFloat + maxFloat) / 2) <= tolerance;
    }

    // You would need a different method for each supported distribution type, this is just an example of a uniform distribution
    public float GenerateDistributionValue()
    {
        return UnityEngine.Random.Range(minFloat, maxFloat);
    }
}
