class CloudStorageDownloader:
    def __init__(self, config):
        self.config = config
        if config['provider'] == 'AWS':
            self.client = boto3.client('s3')
        elif config['provider'] == 'GoogleCloud':
            self.client = storage.Client()
        elif config['provider'] == 'Azure':
            self.client = azureBlobStorage.BlockBlobService(connection_string=config['azureConnectionString'])

    def download_file(self, file_path):
        bucket_name = self.config['bucketName']
        if self.config['provider'] == 'AWS':
            self.client.download_file(bucket_name, file_path, f"{self.config['outputDir']}/{file_path}")
        elif self.config['provider'] == 'GoogleCloud':
            bucket = self.client.get_bucket(bucket_name)
            blob = storage.Blob(file_path, bucket)
            blob.download_to_filename(f"{self.config['outputDir']}/{file_path}")
        elif self.config['provider'] == 'Azure':
            self.client.get_blob_to_path(bucket_name, file_path, f"{self.config['outputDir']}/{file_path}")

        return self.hash_file(f"{self.config['outputDir']}/{file_path}")

    def hash_file(self, file_path):
        with open(file_path , "rb") as f:
            bytes = f.read()  # read entire file as bytes
            return hashlib.md5(bytes).hexdigest()
