```javascript
const fs = require('fs');
const fetch = require('node-fetch');
const pLimit = require('p-limit');
const logger = console; // Use your logging system here.

class FetchAndProcessFiles {
  constructor(config) {
    this.concurrency = config.concurrency || 5;
    this.retryDelay = config.retryDelay || 1000;
    this.maxRetries = config.maxRetries || Infinity;
  }

  async fetchAndProcessFiles(urls, processFile) {
    const limit = pLimit(this.concurrency);
    for (const url of urls) {
      let retryCount = 0;
      while (retryCount < this.maxRetries) {
        try {
          await limit(() => fetch(url));
          logger.log('Successfully retrieved file:', url);
          const data = fs.readFileSync(url, 'utf8'); // replace with actual processing
          processFile(data);
          break;
        } catch (err) {
          logger.error('Error retrieving file:', err);
          await new Promise((resolve) => setTimeout(resolve, this.retryDelay));
          retryCount++;
        }
      }
    }
  }
}
```

This code uses `fetch` to retrieve files asynchronously and applies a concurrency limit using the `p-limit` library. It also includes a simple retry mechanism that waits for a delay before retrying failed file retrievals. Please note that this is a very simplified example and doesn't handle all of your requirements. 

