const fs = require('fs');
const path = require('path');
const async = require('async');
const util = require('util');

let logger; // you should provide a way to inject a logger object
if (typeof window !== 'undefined') {
  logger = console; // for browser environment, use console as the default logger
} else {
  const winston = require('winston'); // import winston for Node.js logging
  logger = winston.createLogger({ /* configure your logger here */ });
}

const readFilePromise = util.promisify(fs.readFile);

async function readDirectoryFiles(directoryPath, extension, bufferSize, maxConcurrentReads, retries) {
    let contents = '';
    const files = fs.readdirSync(directoryPath).filter(file => path.extname(file) === extension);

    async.mapLimit(files, maxConcurrentReads, async (file) => {
        let tries = 0;
        while (tries < retries) {
            try {
                const data = await readFilePromise(path.join(directoryPath, file), 'utf8');
                logger.info('Reading file:', file);
                contents += data;
                break;
            } catch (error) {
                tries++;
                if (tries === retries) throw error;
            }
        }
    });

    return contents;
}
```
