        fetchPokemon(pokemonData.typeUrl)
            .then(data => {
                let weakness = 'Normal';
                switch (data.name) {
                    case 'Fire':
                        if (pokemonData.level > 50) {
                            weakness = 'Water';
                        }
                        break;
                    // Add additional cases here...
                }
                resolve(callback(null, weakness));
            })
            .catch(error => reject(`Error fetching pokemon data: ${error}`));
    });
}

function reducePokemons(pokemons, callback) {
    let combinedWeaknesses = '';
    return new Promise((resolve, reject) => {
        const reduceFn = (i, acc) => {
            if (i >= pokemons.length) {
                resolve(combinedWeaknesses);
                return;
            }
            determineWeaknesses(pokemons[i], (error, weakness) => {
                if (error) {
                    reject(`Error reducing pokemons: ${error}`);
                    return;
                }
                combinedWeaknesses += weakness;
                setImmediate(() => reduceFn(i + 1, acc));
            });
        };
        reduceFn(0, '');
    });
}
