```java
import java.util.*;
import java.util.concurrent.*;
import org.springframework.cloud.config.server.*;

public class QueryManager {
    private ConfigServer configServer;
    private Map<String, String> cache = new ConcurrentHashMap<>();

    public QueryManager(ConfigServer configServer) {
        this.configServer = configServer;
        loadQueriesFromConfig();
    }

    // Method to load queries from Config Server and add them to the cache
    private void loadQueriesFromConfig() {
        Map<String, String> loadedQueries = configServer.loadConfiguration();

        for (Map.Entry<String, String> entry : loadedQueries.entrySet()) {
            if (!cache.containsKey(entry.getKey())) {
                cache.put(entry.getKey(), entry.getValue());
            } else {
                System.out.println("Duplicate query detected: " + entry.getKey());
            }
        }
    }

    // Method to retrieve the list of currently supported and loaded queries
    public Map<String, String> getQueries() {
        return new HashMap<>(cache);
    }

    // Method to add a query to the cache
    public void addQuery(String name, String query) {
        if (!cache.containsKey(name)) {
            cache.put(name, query);
        } else {
            System.out.println("Query addition unsuccessful: " + name);
        }
    }

