```javascript
const MAX_QUEUE = 3; // Maximum number of simultaneous requests
let queueCount = 0; // Current number of requests in the queue

async function loadScript(url) {
  try {
    if (queueCount >= MAX_QUEUE) {
      await new Promise((resolve, reject) => {
        setTimeout(() => {
          resolve();
        }, 100); // Wait for a bit before retrying
      });
    }

    queueCount++;
    let script = document.createElement('script');
    script.src = url;
    script.async = true;

    const promise = new Promise((resolve, reject) => {
      script.onload = resolve;
      script.onerror = reject;
    });

    document.body.appendChild(script);
    await promise;
  } catch (err) {
    console.log('Error loading script:', url, err);
  } finally {
    queueCount--; // Decrement the count even if there's an error
  }
}

function renderScript(scriptObj) {
  let scriptTag = document.createElement('script');
  scriptTag.innerHTML = scriptObj.code;
  document.body.appendChild(scriptTag);
}

async function renderScriptsFooter(scriptsArr) {
  for (let i = 0; i < scriptsArr.length; i++) {
    if (scriptsArr[i].src) {
      await loadScript(scriptsArr[i].src); // Wait for the script to load before loading the next one
    } else {
      renderScript(scriptsArr[i]);
    }
  }
}
