const q = queue((task, callback) => {
  let valueToAggregate = parseFloat(task);

  // Throttle if necessary
  if (throttle > 0) {
    setTimeout(() => fetchConversionRateAndAggregateValue(), throttle);
    return;
  }

  fetchConversionRateAndAggregateValue();

  function fetchConversionRateAndAggregateValue() {
    if (isNaN(valueToAggregate)) { // If it's not a number, try to convert from string.
      let cacheKey = valueToAggregate;
      if (!LRU.has(cacheKey)) { // Cache results of API calls.
        fetch(`${API_URL}?apikey=${API_KEY}&from=USD&to=EUR`)
          .then(res => res.json())
          .then(data => {
            if (!data.success) throw new Error(`API Call failed: ${JSON.stringify(data)}`);
            let conversionRate = data.result;
            LRU.set(cacheKey, conversionRate); // Cache the result
          })
          .catch((err) => {
            logger.error('Error fetching conversion rate', err);
          });
      }
    } else {
      valueToAggregate = parseFloat(valueToAggregate * LRU.get(task)); 
    }

    // Aggregation logic here...

    callback(); // Callback after aggregating
  }
}, 1); // Limit concurrency to 1 for simplicity, in production this could be configurable

function aggregateData(data) {
  data.forEach((value) => {
    q.push(value);
  });
}
