C Version:
```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    char *key;
    void *value;
} Item;

Item **loadResourceBundle(const char *path, int *numItems) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        perror("Error opening file\n");
        return NULL;
    }

    Item **bundle = malloc(sizeof(Item*));
    if (bundle == NULL) {
        perror("Memory allocation error\n");
        return NULL;
    }

    char line[1024];
    *numItems = 0;
    while (fgets(line, sizeof(line), file)) {
        bundle = realloc(bundle, (*numItems + 1) * sizeof(Item*));
        if (bundle == NULL) {
            perror("Memory allocation error\n");
            return NULL;
        }

        Item *item = malloc(sizeof(Item));
        if (item == NULL) {
            perror("Memory allocation error\n");
            return NULL;
        }

        char *equalsSign = strchr(line, '=');
        if (equalsSign == NULL || equalsSign == line || equalsSign[1] == '\0') {
            fprintf(stderr, "Invalid data format\n");
            return NULL;
        }

        *equalsSign = '\0';  // Replace '=' with '\0' to separate key and value

        item->key = malloc(strlen(line) + 1);
        strcpy(item->key, line);

        equalsSign += 2;  // Move past '=' and a space
        char *endQuote = strchr(equalsSign, '"');
        if (endQuote != NULL) {
            *endQuote = '\0';  // Replace closing quote with '\0'
            item->value = malloc(strlen(equalsSign) + 1);
            strcpy(item->value, equalsSign);
        } else {
            if (strchr(equalsSign, '.') != NULL) {  // Float value
                float *floatValue = malloc(sizeof(float));
                sscanf(equalsSign, "%f", floatValue);
                item->value = floatValue;
            } else {  // Integer value
                int *intValue = malloc(sizeof(int));
                sscanf(equalsSign, "%d", intValue);
                item->value = intValue;
            }
        }

        bundle[(*numItems)++] = item;
    }

    fclose(file);
    return bundle;
}
```

