```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

char* parseAndFormatDate(const char* dateStr, const char* format, 
                        const char* timezone, int logLevel) {
    // Validate input string and format
    if (dateStr == NULL || format == NULL || timezone == NULL) {
        switch(logLevel) {
            case DEBUG: fprintf(stderr, "Invalid input\n"); break;
            case INFO: fprintf(stdout, "Invalid input\n"); break;
            // Log other levels as needed
            default: break;
        }
        return NULL;
    }

    struct tm parsed_time = {0};

    if (strptime(dateStr, "%Y-%m-%d", &parsed_time) == NULL) {
        switch(logLevel) {
            case DEBUG: fprintf(stderr, "Invalid date format\n"); break;
            case INFO: fprintf(stdout, "Invalid date format\n"); break;
            // Log other levels as needed
            default: break;
        }
        return NULL;
    }

    time_t t = mktime(&parsed_time);
    if (t == -1) {
        switch(logLevel) {
            case DEBUG: fprintf(stderr, "Unable to convert date\n"); break;
            case INFO: fprintf(stdout, "Unable to convert date\n"); break;
            // Log other levels as needed
            default: break;
        }
        return NULL;
    }

    setenv("TZ", timezone, 1);
    tzset();
    struct tm* local_time = localtime(&t);
    if (local_time == NULL) {
        switch(logLevel) {
            case DEBUG: fprintf(stderr, "Unable to convert date to specified timezone\n"); break;
            case INFO: fprintf(stdout, "Unable to convert date to specified timezone\n"); break;
            // Log other levels as needed
            default: break;
        }
        return NULL;
    }

    char* formattedDate = NULL;
    if (asprintf(&formattedDate, format, 
                 local_time->tm_year + 1900, 
                 local_time->tm_mon + 1, 
                 local_time->tm_mday) == -1) {
        switch(logLevel) {
            case DEBUG: fprintf(stderr, "Unable to allocate memory for formatted date\n"); break;
            case INFO: fprintf(stdout, "Unable to allocate memory for formatted date\n"); break;
            // Log other levels as needed
            default: break;
        }
    }

    return formattedDate;
}
```

