#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void processLine(char *line) {
    char *token = strtok(line, " ");
    double sum = 0;
    int count = 0;
    while (token != NULL && count < 3) {
        if(isdigit(*token)) { // Check if token is numeric before processing
            double number = atof(token);
            sum += number;
            count++;
        }
        token = strtok(NULL, " ");
    }
    printf("%f\n", sum/3.0);
}

void processFile(FILE *file) {
    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        processLine(line);
    }
    free(line);
}

int main() {
    FILE *file = fopen("largefile.txt", "r");
    if (file == NULL) {
        printf("Unable to open file\n");
        return 1;
    }
    processFile(file);
    fclose(file);
    return 0;
}
