```c
/* crypto_library.c */
#include "crypto_module.h"
#include "crypto_library.h"
#include <stdio.h>
#include <dlfcn.h> /* Dynamic loading */
#include <pthread.h> 

static crypto_module * module = NULL;
static pthread_mutex_t library_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_library() {
  pthread_mutex_lock(&library_lock);

  /* Load the cryptographic module dynamically. Use dlopen to load */
  if (module == NULL)
    module = load_module("AES"); // or any other supported cipher

  pthread_mutex_unlock(&library_lock);
}

void finalize_library() {
  /* Unload the module */
  unload_module(module);
}

int encrypt(char * plaintext, char * key, char ** ciphertext) {
  pthread_mutex_lock(&library_lock);

  int result = aes_encrypt(module, plaintext, key, ciphertext); // Similarly for other supported ciphers

  pthread_mutex_unlock(&library_lock);

  return result;
}

int decrypt(char * ciphertext, char * key, char ** decrypted) {
  pthread_mutex_lock(&library_lock);

  int result = aes_decrypt(module, ciphertext, key, decrypted); // Similarly for other supported ciphers

  pthread_mutex_unlock(&library_lock);

  return result;
}
```

