import requests
from time import sleep
from psycopg2 import connect
from rate_limit import limits
import logging

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.DEBUG)

db_settings = {  # adjust according to your own DB settings
    'host': 'localhost',
    'database': 'mydatabase',
    'user': 'postgres',
    'password': 'secret'
}

@limits(calls=2, period=1)   # rate limit for API calls 
def api_request(url):
    try:
        response = requests.get(url)
        if response.status_code == 429:
            logger.error("Rate limit exceeded")
            sleep(5)
            return api_request(url)
        elif response.status_code != 200:
            logger.error("Unexpected API response status code", response.status_code)
    except Exception as e:
        logger.exception(f"Error occurred while making request to {url}")
        sleep(1)  # wait and retry after a second
        return api_request(url)
    else:
        return response.json()

def process_transaction(transactions, transaction):
    transactions.append((transaction['id'], transaction['weighted_sum']))
    age = max([t[1] for t in transactions])  # calculate the maximum weighted sum and corresponding ID
    max_weighted_sum = max([t[0] for t in transactions])

    return max_weighted_sum, [id for id, ws in transactions if ws == max_weighted_sum]

def process_transactions(url):
    with connect(**db_settings) as conn:
        with conn.cursor() as cur:
            try:
                response = api_request(url)
                # validate transaction and get tokens securely stored in DB 
                cur.execute('INSERT INTO transactions (token) VALUES (%s);', (response['token'],))  

                transactions = []  # list to store transaction IDs and sums
                for transaction in response['transactions']:
                    if valid_transaction(transaction):  # function that verifies transaction age, num, etc.
                        max_weighted_sum, ids = process_transaction(transactions, transaction)

                return max_weighted_sum, ids  # returns weighted sum and corresponding IDs
            except Exception as e:
                logger.exception("Error occurred during processing transactions")
