Below is a basic implementation of the DatabaseConnectionManager class in Java using java.util.concurrent's BlockingQueue for managing the connection pool. Note that the actual implementation would depend on your specific requirements, such as which database you are connecting to and how you want to handle logging, testing, sanitization, etc.

```java
import com.google.common.base.Preconditions;
import org.apache.commons.dbcp2.BasicDataSource;
import java.sql.Connection;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingDeque;
import java.util.logging.*;

public class DatabaseConnectionManager {
    private BasicDataSource dataSource = new BasicDataSource();
    private BlockingQueue<Connection> pool = new LinkedBlockingDeque<>();
    private Logger logger = Logger.getLogger(DatabaseConnectionManager.class.getName());

    public void initializePool(int initialSize, int maxSize, String connectionString) {
        Preconditions.checkArgument(initialSize > 0 && maxSize >= initialSize);

        dataSource.setUrl(connectionString);
        // Additional settings such as driver class name can be set here.

        for (int i = 0; i < initialSize; i++) {
            try {
                pool.put(dataSource.getConnection());
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error while creating connection", e);
            }
        }
    }

    public Connection getConnection() throws InterruptedException {
        return pool.take();
    }

    public void releaseConnection(Connection conn) {
        Preconditions.checkNotNull(conn);

        if (conn != null) {
            try {
                pool.put(conn);
            } catch (InterruptedException e) {
                logger.log(Level.SEVERE, "Error while releasing connection", e);
            }
        }
    }

    public void testConnection(Connection conn) {
        // Implement your own connection testing logic here...
    }

    public void resetPool() {
        pool.clear();
        initializePool(dataSource.getInitialSize(), dataSource.getMaxTotal(), dataSource.getUrl());
    }

    public void setMaxIdleTime(long maxIdleTime) {
        Preconditions.checkArgument(maxIdleTime > 0);

        // Implement your own logic to set max idle time...
    }

    public void setTestOnBorrow(boolean testOnBorrow) {
        // Implement your own logic to enable/disable testing on borrow...
    }

    public void logConnectionUsage(String ipAddress, String action, String databaseName) {
        logger.log(Level.INFO, "IP Address: " + ipAddress + ", Action: " + action + ", Database Name: " + databaseName);
    }

    public void monitorPoolStatus() {
        System.out.println("Active connections: " + dataSource.getNumActive());
        System.out.println("Idle connections: " + dataSource.getNumIdle());
        System.out.println("Total connections: " + (dataSource.getNumActive() + dataSource.getNumIdle()));
    }

    public String sanitizeSQLQuery(String query) {
