Here is a basic version of `asyncArrayReduce` with some considerations for the above requirements (you might need to adjust it according to your needs):

```jsx
const async = require('async'); // For concurrency control, queues etc.
const fetch = require('node-fetch'); // For making API requests
let cache = {}; // Caching mechanism 
class AsyncArrayReduce {
    constructor(options) {
        this.options = options;
        this.token = options.authToken || '';
        this.apiUrl = options.apiUrl || '';
        this.concurrencyLimit = options.concurrency || 10; // Default concurrency level is 10
        this.timeoutDuration = options.timeout || 5000; // Default timeout is 5 seconds
    }

    async fetchWord(url, cb) {
        if (cache[url]) {
            return cache[url];
        }

        const controller = new AbortController();
        const id = setTimeout(() => controller.abort(), this.timeoutDuration);

        try {
            const response = await fetch(url, { signal: controller.signal, headers: {"Authorization": `Bearer ${this.token}`} });

            if (!response.ok) throw new Error('Network response was not ok');

            clearTimeout(id);

            const result = await response.json();

            cache[url] = result; // Store the fetched word in cache
            return result;
        } catch (error) {
            console.log('Error:', error);
            cb(null, 'Error');
        } 
    }

    async reduce(array, cbProgress, customAccumulator) {
        const self = this;

        if (!Array.isArray(array)) {
            console.error('Invalid input: expected an array of URLs')
            return 'Error';
        }

        let accumulatedValue = 0;
        let wordCount = 0;

        const q = async.queue((task, callback) => {
          self.fetchWord(task, (err, result) => {
                if (!err) {
                    // Use the custom accumulator function here
                    accumulatedValue += customAccumulator(result);
                    wordCount++;
                    cbProgress({accumulated: accumulatedValue, count: wordCount});
                } 

                callback();
            });
        }, this.concurrencyLimit);

        for (let i = 0; i < array.length; i++) {
            q.push(array[i]);
        }

        // Wait till queue is drained before returning result
        return new Promise((resolve, reject) => {
          q.drain = () => resolve(accumulatedValue);
        });
    }
}
``` 
This solution uses Node Fetch for API requests and Async library for managing queues and concurrency level. It stores fetched words in a cache to minimize redundant calls, implements configurable timeout and concurrency control and provides progress reporting. However, it does not handle all the exceptions gracefully and doesn't have an optimal way of handling large arrays or heavy loads.

