    int key;
    long timestamp;
    char* description;
    double value;
} Record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // for thread safety

void initialize(Record** records, int recordCount) {
    srand(time(NULL)); 
    *records = (Record*) malloc(recordCount * sizeof(Record));
    assert(*records != NULL);

    pthread_mutex_lock(&mutex); // acquire lock before modifying shared data
    for (int i = 0; i < recordCount; i++) {
        (*records)[i].key = rand() % 10000; // random int key between 0 and 10000
        time_t now = time(NULL);
        (*records)[i].timestamp = (long)(now + i * 3600L * 24 * 30) % ((long)INT_MAX + 1L); // random timestamp, one month ahead

        int descriptionLength = rand() % 255;
        (*records)[i].description = (char*) malloc(sizeof(char) * (descriptionLength+1));
        for (int j = 0; j < descriptionLength; j++) {
            (*records)[i].description[j] = 'a' + rand() % 26; // random string of length up to 255
        }
        (*records)[i].description[descriptionLength] = '\0';

        double f_rand = ((double)rand()) / (RAND_MAX/10000.0);
        (*records)[i].value = -5000 + f_rand; // random double value between -10000 and 10000
    }
    pthread_mutex_unlock(&mutex); // release lock after modifying shared data
}
```
