```c
#include <fcntl.h>
#include <sys/stat.h>
#include <semaphore.h>
#include <stdio.h>

// Create a named semaphore
sem_t *createSemaphore(const char* name, int value) {
    return sem_open(name, O_CREAT | O_EXCL, 0644, value);
}

// Increment the semaphore
void incrementSemaphore(sem_t *sem) {
    sem_post(sem);
}

// Decrement the semaphore
void decrementSemaphore(sem_t *sem) {
    sem_wait(sem);
}

// Delete the semaphore
void deleteSemaphore(const char* name, sem_t *sem) {
    sem_close(sem);
    sem_unlink(name);
}
```
