```python
import json
import yaml
from botocore.exceptions import BotoCoreError, ClientError
import boto3

class ConfigManager:
    def __init__(self, remote_config=True):
        self.remote_config = remote_config
        if remote_config:
            try:
                self.ssm = boto3.client('ssm')
            except BotoCoreError as e:
                print(f"Failed to create AWS SSM client: {e}")
        self.local_cache = {}

    def load_config_file(self, filename):
        try:
            with open(filename, 'r') as f:
                config = json.load(f)
                return config
        except FileNotFoundError:
            print("File not found")
        except json.decoder.JSONDecodeError:
            print("Invalid JSON format")

    def load_config_remote(self, parameter):
        try: 
            response = self.ssm.get_parameter(Name=parameter, WithDecryption=True)
            return json.loads(response['Parameter']['Value'])
        except ClientError as e:
            print(f"Failed to fetch from SSM Parameter Store: {e}")

    def get_config(self, key, filename=None, remote_parameter=None):
        if self.remote_config and remote_parameter is not None:
            # Try to load the config value from AWS SSM Parameter Store
            try: 
                return self.load_config_remote(remote_parameter)[key]
            except (KeyError, TypeError):
                print("Config key not found in remote")
        elif filename is not None:
            # Try to load the config value from a local JSON file
            try: 
                return self.load_config_file(filename)[key]
            except (KeyError, TypeError):
                print("Config key not found in local file")

        if key in self.local_cache:
            # Try to load the config value from local cache
            return self.local_cache[key]

        print("Config not found")

    def set_config(self, key, value):
        if self.remote_config:
            try: 
                # Write the new config value to AWS SSM Parameter Store
                self.ssm.put_parameter(Name=key, Value=json.dumps(value), Type='String', Overwrite=True)
            except ClientError as e:
                print(f"Failed to put in SSM Parameter Store: {e}")
        else:
            # Update the local cache with the new config value
            self.local_cache[key] = value

    def validate_config(self, rules):
        for rule in rules['rules']:
            key = rule['key']
            if 'datatype' in rule and not isinstance(self.get_config(key), rule['datatype']):
                print(f"Invalid data type for {key}")

    def load_validation_rules(self, filename):
        try: 
            with open(filename, 'r') as f:
                return yaml.safe_load(f)
        except FileNotFoundError:
            print("File not found")
```
