import json
from abc import ABCMeta, abstractmethod
from datetime import datetime
from decimal import Decimal
from uuid import UUID, uuid4

class JSONSerializable(metaclass=ABCMeta):
    @abstractmethod
    def to_json(self):
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str):
        pass

    @staticmethod
    def _default(obj):
        if isinstance(obj, UUID) or isinstance(obj, Decimal) or isinstance(obj, datetime):
            return str(obj)
        raise TypeError("Type %s not serializable" % type(obj))

    @staticmethod
    def _object_hook(dct):
        for k, v in dct.items():
            if isinstance(v, str) and UUID_REGEX.match(v):
                dct[k] = UUID(v)
            elif isinstance(v, str) and DECIMAL_REGEX.match(v):
