class EmailValidator:
    def __init__(self):
        self._cache = {}
        self._pattern_map = {'common': r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-a]{2,}\b'}
        self.external_api_url = "https://data.iana.org/TLD/tlds-alpha-by-domain.txt"  # replace with your actual API URL

    def load_valid_domains(self):
        # Implement logic to fetch valid domain names from the external API and update self._pattern_map
        pass  

    async def validate_email(self, email: str) -> dict:
        if not isinstance(email, str):
            raise ValueError("Email must be a string")

        # If we have validated this email before, return from cache
        if email in self._cache:
            return self._cache[email]

        valid_patterns = []
        for name, pattern in self._pattern_map.items():
            match = re.fullmatch(pattern, email)

            # If email matches any of the patterns, append to valid_patterns
            if match:
                valid_patterns.append((name, match))

        # If no pattern matched, email is invalid
        if not valid_patterns:
            return {'email': email, 'valid': False} 

        # Add to cache and return result
        self._cache[email] = {
            'email': email,
            'valid': True,
            'username': valid_patterns[0][1].group(1),
            'domain': valid_patterns[0][1].group(2),
            'tld': valid_patterns[0][1].group(3)
        }
        return self._cache[email]

    def add_pattern(self, name: str, pattern: str):
        # Add new pattern to the map
        self._pattern_map[name] = pattern

    async def validate_emails(self, emails):
        return await asyncio.gather(*[self.validate_email(email) for email in emails])

    def generate_report(self, validated_emails: list):
        # Calculate frequency of each type
        freq = Counter(chain(*[v['tld'] for v in validated_emails if v.get('valid')])) 

        return {'freq': dict(freq)}

    def export_report(self, report:dict, file_path:str, format='csv')->None:
        # Export report as CSV or JSON based on the given format
        if format == 'json':
            with open(file_path + '.json', 'w') as fp:
                json.dump(report, fp)
        elif format =='csv': 
            with open(file_path + '.csv', 'w') as fp:
                writer = csv.writer(fp)
                for key, value in report['freq'].items():
                    writer.writerow([key, value])  

