import com.google.common.cache.*;
import org.slf4j.*;

public class WeatherDataProvider {
    private static final Logger logger = LoggerFactory.getLogger(WeatherDataProvider.class);

    // This should be replaced with the actual implementation to retrieve data from your APIs
    private DataFetcher weatherAPIDataFetcher; 
    private DataFetcher openWeatherMapDataFetcher;

    private LoadingCache<String, String> cache;

    public WeatherDataProvider() {
        cache = CacheBuilder.newBuilder().maximumSize(10_000).build(new CacheLoader<>() {
            @Override
            public String load(String key) throws Exception {
                if (key.startsWith("OpenWeatherMap")) {
                    return openWeatherMapDataFetcher.fetch(key);
                } else if (key.startsWith("WeatherAPI")) {
                    return weatherAPIDataFetcher.fetch(key);
                } else {
                    throw new IllegalArgumentException();
                }
            }
        });
    }

    public String fetchData(String key) {
        try {
           return cache.get(key);
        } catch (ExecutionException e) {
            logger.error("Error fetching data", e);
            throw new RuntimeException(e);
        }
    }

    // Adding a new provider
    public void addDataProvider(String prefix, DataFetcher fetcher){
        cache = CacheBuilder.newBuilder().maximumSize(10_000).build(new CacheLoader<>() {
            @Override
            public String load(String key) throws Exception {
                if (key.startsWith(prefix)){
                    return fetcher.fetch(key);
                } else {
                    return cache.get(key);
                }
            }
        });
    }
}

interface DataFetcher {
    String fetch(String key);
}
