typedef struct {
    char *data;
    size_t len;
} FetchResult;

FetchResult fetchWords(char* url) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        printf("Failed to initialize libcurl\n");
        exit(EXIT_FAILURE);
    }

    FetchResult result;
    result.data = malloc(1); // Start with 1 byte of memory
    result.len = 0;

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, (void *)&writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &result.data);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        printf("Failed to fetch data: %s\n", curl_easy_strerror(res));
        exit(EXIT_FAILURE);
    }

    long responseCode;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
    if (responseCode != 200) {
        printf("Failed to fetch data: HTTP %ld\n", responseCode);
        exit(EXIT_FAILURE);
    }

    curl_easy_cleanup(curl);
    return result;
}
