import os
from abc import ABC, abstractmethod
import requests
import time
import random
import json
from typing import Dict, Any
from sqlalchemy import create_engine, Table, MetaData
from sqlalchemy.orm import sessionmaker
from redis import Redis
import logging
from threading import Lock

# Payment gateway configuration placeholders
stripe_config = {'api_key': os.getenv('STRIPE_API_KEY')}
paypal_config = {'client_id': os.getenv('PAYPAL_CLIENT_ID'), 'secret_key': os.getenv('PAYPAL_SECRET_KEY')}
braintree_config = {'merchant_id': os.getenv('BRAINTREE_MERCHANT_ID'), 'public_key': os.getenv('BRAINTREE_PUBLIC_KEY'), 'private_key': os.getenv('BRAINTREE_PRIVATE_KEY')}

# Setup logging
logging.basicConfig(filename='payments.log', level=logging.INFO)
logger = logging.getLogger(__name__)

# Database setup
engine = create_engine('sqlite:///transactions.db')
metadata = MetaData()
tokens_table = Table('tokens', metadata, autoload_with=engine)
Session = sessionmaker(bind=engine)
session = Session()

# Redis setup for caching responses
redis = Redis(host='localhost', port=6379)

# Lock to ensure data consistency across multiple concurrent transactions
lock = Lock()

class PaymentGateway(ABC):
    def __init__(self, config: Dict[str, Any]):
        self.config = config

    @abstractmethod
    def process_payment(self, amount: float, token: str) -> Dict[str, Any]:
        pass

class StripeGateway(PaymentGateway):
    def process_payment(self, amount: float, token: str) -> Dict[str, Any]:
        # Process payment with Stripe API and handle retries and rate limits.
        pass 

class PayPalGateway(PaymentGateway):
    def process_payment(self, amount: float, token: str) -> Dict[str, Any]:
        # Process payment with PayPal API and handle retries and rate limits.
        pass

class BraintreeGateway(PaymentGateway):
    def process_payment(self, amount: float, token: str) -> Dict[str, Any]:
        # Process payment with Braintree API and handle retries and rate limits.
        pass 

class PaymentsManager():
    def __init__(self):
        self.gateways = {'stripe': StripeGateway(stripe_config), 'paypal': PayPalGateway(paypal_config), 'braintree': BraintreeGateway(braintree_config)}

    def process_transaction(self, gateway: str, amount: float, token: str) -> Dict[str, Any]:
        # Retrieve transaction token from database if available.
        response = redis.get(token)

        if not response: 
            with lock:
                logger.info(f'Processing transaction on {gateway}')

                for i in range(5): 
                    try:
                        payment_response = self.gateways[gateway].process_payment(amount, token)

                        if 'error' not in payment_response:
                            # Cache the response to redis and store the transaction token in database.
                            redis.set(token, json.dumps(payment_response))

                            new_transaction = tokens_table.insert().values(token=token)
                            session.execute(new_transaction)
                            session.commit()
                        else:
                            logger.error(f'Error processing transaction on {gateway}: {payment_response["error"]}')

                        break 
                    except Exception as e:
                        # Log exception and retry with exponential backoff.
                        logger.exception(e)

                        sleep = random.uniform(0, (2 ** i))
                        time.sleep(sleep)
        else:
            payment_response = json.loads(response)

        return payment_response
