```rust
use std::sync::{Arc, Mutex};
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::fs;
use anyhow::Result;
use semver::Version;
use git2::Repository;
use ring::hmac::{Key, HMAC_SHA256};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Config {
    branch: String,
    api_rate_limits: usize,
}

pub struct ConfigurationManager {
    configs: Arc<Mutex<BTreeMap<PathBuf, (Config, Version)>>>,
    crypto: HMAC_SHA256,
}

impl ConfigurationManager {
    pub fn new(config_path: PathBuf, crypto_key: Key) -> Self {
        let configs = Arc::new(Mutex::new(BTreeMap::new()));
        let crypto = HMAC_SHA256.with_key(&crypto_key);

        ConfigurationManager { configs, crypto }
    }

    pub async fn update(&self, url: &str) -> Result<()> {
        let path = PathBuf::from(url);
        let (temp_path, _) = git2::Repository::clone(&url, &path).map_err(anyhow::Error::new)?;

        let config = fs::read_to_string(temp_path.join("config.json"))?;
        let config: Config = serde_json::from_str(&config)?;

        let repo = Repository::open(&temp_path).map_err(anyhow::Error::new)?;
        let version = Version::parse(&repo.head().unwrap()?)?;

        let mut configs = self.configs.lock().unwrap();
        *configs.entry(path).or_insert((config, version)) = (config, version);

        Ok(())
    }
}
```
