```java
import java.util.*;
import java.util.concurrent.*;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.model.*;
import com.google.cloud.storage.*;
import com.microsoft.azure.storage.*;

public class CloudStorageManager {
    private final AmazonS3 amazonS3Client;
    private final StorageAccount azureBlobStorageClient;
    private final Storage googleCloudStorageClient;

    // Constructor to initialize clients based on configurations
    public CloudStorageManager() {
        this.amazonS3Client = AmazonS3ClientBuilder.defaultClient();

        // Assuming you've already set up Azure and Google cloud SDKs properly
        this.azureBlobStorageClient = new CloudStorageAccount();
        this.googleCloudStorageClient = new Storage.Builder().build();
    }

    public void upload(String provider, String bucketName, String key, byte[] data) {
        if (provider.equals("AWS")) {
            amazonS3Client.putObject(bucketName, key, new ByteArrayInputStream(data), new ObjectMetadata());
        } else if (provider.equals("Azure")) {
            CloudBlobContainer container = azureBlobStorageClient.createCloudBlobClient().getContainerReference(bucketName);
            CloudBlockBlob blob = container.getBlockBlobReference(key);
            blob.uploadFromByteArray(data, 0, data.length);
        } else if (provider.equals("Google")) {
            BlobId blobId = BlobId.of(bucketName, key);
            BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build();
            googleCloudStorageClient.create(blobInfo, data);
        }
    }

    public byte[] download(String provider, String bucketName, String key) {
        if (provider.equals("AWS")) {
            S3Object s3object = amazonS3Client.getObject(new GetObjectRequest(bucketName, key));
            S3ObjectInputStream inputStream = s3object.getObjectContent();
            return IOUtils.toByteArray(inputStream);
        } else if (provider.equals("Azure")) {
            CloudBlobContainer container = azureBlobStorageClient.createCloudBlobClient().getContainerReference(bucketName);
            CloudBlockBlob blob = container.getBlockBlobReference(key);
            int fileLength = (int)blob.getProperties().getLength();
            byte[] fileData = new byte[fileLength];
            blob.downloadToByteArr(fileData, 0, fileLength -1 ,true);
            return fileData;
        } else if (provider.equals("Google")) {
            BlobId blobId = BlobId.of(bucketName, key);
            byte[] content = googleCloudStorageClient.readAllBytes(blobId);
            return content;
        }
    }
}
