import time
from threading import Thread
import requests
from queue import Queue
from datetime import datetime, timedelta

class TransactionProcessor:
    def __init__(self, gateways):
        self.gateways = gateways
        self.queue = Queue()
        self.metrics = {}
        self.transactions = {}

    def process_transaction(self, transaction):
        tries = 0
        while tries < 5:  # max retries
            for gateway in self.gateways:
                try:
                    response = requests.post(gateway['url'], data=transaction)

                    if response.status_code == 200:
                        transaction_id = response.json()['transaction_id']

                        # Add transaction to queue for processing
                        self.queue.put((gateway, transaction))

                        return transaction_id
                    else:
                        print(f"Error from {gateway['name']}: {response.status_code}")
                        time.sleep(2 ** tries)  # exponential backoff
                except requests.exceptions.RequestException as e:
                    print(f"Error processing transaction with {gateway['name']}: {str(e)}")

                    if gateway == self.gateways[-1]:  # If primary fails, switch to next one in the list
                        tries += 1
                except Exception as e:
                    print(f"Unexpected error processing transaction with {gateway['name']}: {str(e)}")

            return None

    def process_queue(self):
        while True:  # run forever
            gateway, transaction = self.queue.get()

            if self.is_valid(transaction, gateway):
                try:
                    self.update_metrics(gateway)

                    # Process transaction here...

                    print(f"Transaction processed with {gateway['name']}")
                except Exception as e:
                    print(f"Error processing transaction with {gateway['name']}: {str(e)}")
            else:
                print(f"Invalid transaction with {gateway['name']}")

    def is_valid(self, transaction, gateway):
        # Implement validation logic here...

        return True

    def update_metrics(self, gateway):
        if gateway['name'] in self.metrics:
            self.metrics[gateway['name']] += 1
        else:
            self.metrics[gateway['name']] = 1

# In your main function or where you start processing transactions
if __name__ == "__main__":
    gateways = [{'name': 'Gateway 1', 'url': 'http://gateway1.com/process'},
               {'name': 'Gateway 2', 'url': 'http://gateway2.com/process'}]

    processor = TransactionProcessor(gateways)

    Thread(target=processor.process_queue).start()
