```c
#include <openssl/evp.h>
#include <string.h>
#include <jansson.h>
#include <stdio.h>

void handleErrors(void) { /* Error handling routine */ }

json_t *loadConfig() { 
    json_error_t error;
    json_t *root = json_load_file("config.json", 0, &error);

    if(!root) {
        fprintf(stderr, "Error loading config: on line %d: %s\n", error.line, error.text);
        return NULL;
    }

    return root;
}

EVP_CIPHER_CTX *getEncryptionCipher(json_t *config) { 
    const char *mode = json_string_value(json_object_get(config, "mode"));
    EVP_CIPHER_CTX *ctx;

    if(!strcmp(mode, "ECB")) {
        /* Initialize ctx with ECB mode */
        if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();
        if(1 != EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, NULL, NULL)) handleErrors();
    } else if (!strcmp(mode, "EDE")) {
        /* Initialize ctx with EDE mode */
        if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();
        if(1 != EVP_EncryptInit_ex(ctx, EVP_des_ede(), NULL, NULL, NULL)) handleErrors();
    } else if (!strcmp(mode, "EDE3")) {
        /* Initialize ctx with EDE3 mode */
        if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();
        if(1 != EVP_EncryptInit_ex(ctx, EVP_des_ede3(), NULL, NULL, NULL)) handleErrors();
    } else if (!strcmp(mode, "CFB")) {
        /* Initialize ctx with CFB mode */
        if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();
        if(1 != EVP_EncryptInit_ex(ctx, EVP_des_cfb(), NULL, NULL, NULL)) handleErrors();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return NULL;
    }

    /* Load key from config */
    const char *key = json_string_value(json_object_get(config, "key"));
    if(!EVP_EncryptInit_ex(ctx, NULL, NULL, (const unsigned char *)key, NULL)) handleErrors();

    return ctx;
}
```
This program loads a configuration file with encryption mode and key details. The function `getEncryptionCipher` initializes an `EVP_CIPHER_CTX` object with the chosen cipher settings for encrypting or decrypting data using DES in various modes (ECB, EDE, EDE3, CFB).

