Here is an example of such a function implemented with JavaScript's Async/Await pattern for handling asynchronous operations, along with error handling and comments explaining each part of the code:

```javascript
// Import necessary module for creating buffers
const { Buffer } = require('buffer'); 

/**
 * Function to copy a specified number of bytes from a series of buffered data chunks
 * @param {Object} stream - The external data streaming API object. Must have a `read` method that returns an array of buffer chunks
 * @param {Number} totalBytes - The total number of bytes to be copied
 * @return {Buffer} - A new Buffer containing the copied data
 */
async function copyData(stream, totalBytes) {
    let currentByte = 0; // Track the current byte index we're at
    const buffers = [];  // Store the individual buffer chunks here

    try {
        while (currentByte < totalBytes) {
            // Read data in chunks from the stream
            const dataChunk = await stream.read();

            // Check if we've reached end of file and no more data to read
            if (!dataChunk || !dataChunk.length) { 
                break;
            }

            // Calculate how many bytes can be copied from this chunk without exceeding the total byte limit
            const remainingBytes = totalBytes - currentByte;
            const byteLengthToCopy = Math.min(remainingBytes, dataChunk.length);

            // Create a new buffer slice for the portion of the chunk we're interested in, and add it to our list
            buffers.push(dataChunk.slice(0, byteLengthToCopy));

            // Update the current byte index
            currentByte += byteLengthToCopy;
        }
    } catch (err) { 
        throw new Error("Error occurred while reading data from stream: " + err);
    }

    // If we didn't manage to read enough bytes, throw an error
    if (currentByte < totalBytes) {
      throw new Error(`Attempted to copy ${totalBytes} bytes but only got ${currentByte}. Could be due to EOF or other issues with the stream.`); 
    }

    // Use Buffer.concat to combine our list of buffers into a single buffer and return it
    return Buffer.concat(buffers, totalBytes);
}
```
