    size_t size;
} MemoryStruct;

static void init_userp(struct userpass *up) {
    up->username = NULL;
    up->password = NULL;
}

static int set_userp(char **out, const char *in) {
    free(*out);
    *out = strdup(in);
    return (*out != NULL) ? 0 : -1;
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct userpass *up) {
    FILE *f = (FILE *)up->username;
    char *s = (char *) ptr;
    size_t i;

    for(i = 0; i < nmemb; i++) {
        fputc(*s, f);
        ++s;
    }
    return nmemb;
}

void log_to_server(const char *url, int level, const char *message, va_list args) {
    CURL *curl = curl_easy_init();

    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return;
    }

    FILE* logFile = fopen("log.txt", "a+");  // Open a file for logs

    struct userpass up;
    init_userp(&up);

    char buffer[512];
    vsnprintf(buffer, sizeof(buffer), message, args);  

    switch (level) {
        case 0: fputs("DEBUG: ", logFile); break;
        case 1: fputs("INFO: ", logFile); break;
        case 2: fputs("WARNING: ", logFile); break;
        case 3: fputs("ERROR: ", logFile); break;
        default: fputs("UNKNOWN LOG LEVEL: ", logFile); break;
    }

    fputs(buffer, logFile); // Log the message to file
    fputc('\n', logFile); 

    curl_easy_setopt(curl, CURLOPT_URL, url);

    struct curl_slist *headers = NULL;

    /* Set HTTP Headers here if needed */
    headers = curl_slist_append(headers, "Content-Type: application/json"); 

    // set the callback function and data pointer for writefunc to receive data.
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, logFile);
    curl_easy_perform(curl); // Perform the request.

    fclose(logFile);  // Close the file after writing logs.
    curl_slist_free_all(headers); /* free the header list */ 
    curl_easy_cleanup(curl);
}
